-- 自动生成：跨功能重复中文池；保留原有索引和译文选择。来源见 SOURCES.md。
local D=LegionChineseDB
D.SharedStrings[1]="$C！我差点就神不知鬼不觉地死在这鬼地方了！我在谷里捕猎蝎子的时候，突然看到一只看上去特别凶恶的蝎子。当时我就决定以它为猎物，打算在它那硕大的钳子钳住我的腿以前，先重重地给它来上那么一下子。$b$b但我忘记了它还有根毒刺，毒刺猛扎了下来，一下子就刺进我的胸口。拜托，你一定得替我报仇！只有这样才能留存我的名誉！我是在南边的高地上碰上它的。"
D.SharedStrings[2]="$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉巨魔的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……"
D.SharedStrings[3]="$N!很高兴看见你能安全返回。你对沃科尔提供的帮助使我相信，我们最终可以战胜在黑海岸或是其它任何地方所遇到的一切挑战。"
D.SharedStrings[4]="$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!"
D.SharedStrings[5]="$N―我们冬幕节的礼物如果没有那些货物的话就准备不好了!格拉库就没有机会和这些好孩子们一起分享他的美味肉派了……"
D.SharedStrings[6]="$N，一旦你已在夺取各个堡垒的行动中建功，回来向我回报!"
D.SharedStrings[7]="$N，你和你的盟友帮助联赛免于毁灭性的攻击。虽然我们的天爪骑士非常英勇，但他们的人手几乎都用在维持联赛的地面安全，很难防范诅咒神教来自空中的攻击。银色北伐军和所有在此参与联赛的人都由衷地感谢你。"
D.SharedStrings[8]="$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。"
D.SharedStrings[9]="$N，你想加入我们的会员了吗?我们的福利很好，身为俱乐部的一员，我们一定给你最好的!$B$B每月的第一天会将啤酒寄发给你，想要更多，回来这里，我们保证让你有喝不完的啤酒。"
D.SharedStrings[10]="$N，你拯救了联赛免于毁灭性的攻击。银色北伐军以及在此的所有人都欠你一份情，我们会确保他们记得这件事。那些吹嘘要提供保护的人，保安官和天爪们花了太多时间在应付那些酒后争执，而非对抗天灾军团的威胁。$B$B但不管如何，我们总是能自我保护。"
D.SharedStrings[11]="$N，你接触过聚源虹膜之钥!在你身上吗?$B$B<龙后满是忧虑地望着她的伴侣，克拉苏斯。>$B$B然而你是如何得到的呢?噢，萨菲隆还保有着属于他的那块?"
D.SharedStrings[12]="$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。"
D.SharedStrings[13]="$N，欢迎来到奥格瑞玛。大药剂师普崔司在你来以前先捎了口信过来…你手上有那颗受感染的脑子吗?"
D.SharedStrings[14]="$N，能见到你本人真好。我在你出生之前就认识你了。"
D.SharedStrings[15]="$N，要是没搞错，你发现了关键的装置，可以让我们精确寻找出狩法猎人大军要转至的地方!"
D.SharedStrings[16]="$N，还有什么事吗?我还能为你做些什么?"
D.SharedStrings[17]="$N，高贵的夜向导，欢迎你。愿圣光照耀你，也愿你古老的智慧在必要的时刻守卫我们的大地。"
D.SharedStrings[18]="$c，你已经做出了选择。那么，不管前方的路有多么凶险，你都得走下去。$B$B你要明白，与达拉然的大法师们搞好关系是大有裨益的。为我们服务吧，你的努力不会白费的。"
D.SharedStrings[19]="$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！"
D.SharedStrings[20]="$g嗨，帅哥。有什么是我帮得上忙的吗?:喔，天啊!我能帮你什么呢?;"
D.SharedStrings[21]="$n， 预言者努波顿希望你去见他。是时候让你去了解最后一种元素——空气的奥秘了！$B$B我希望你知道，我对你目前为止所有的表现都非常满意。相信接下去你会做得更好。"
D.SharedStrings[22]="$n，你为银色黎明做出的贡献在这里被广为传颂。作为一种奖励，你将有资格获得我们特殊的多彩黎明衬肩，它可以帮你抵抗各种魔法效果。多彩黎明衬肩只会被授予最强大的英雄！$B$B交给我二十五枚勇气勋章作为你对银色黎明做出贡献的标志，然后我就会把我们最好的衬肩给你。"
D.SharedStrings[23]="$n，你取得的成就已经超越了我的想象。$B$B与青铜龙一样，你能自由地穿行在时空中。你注定会成为一名强者，而我非常乐意帮你达成这一目标。$B$B继续为流沙之鳞效力吧，我将继续在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。"
D.SharedStrings[24]="$n，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。"
D.SharedStrings[25]="$n，你实现了自己的诺言。为此，你获得了青铜龙的赏识。$B$B只要你继续维护发生在海加尔山的历史事件的正常进程，那么我将不断在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。这一天不会太远的。"
D.SharedStrings[26]="$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！$B$B我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。"
D.SharedStrings[27]="$n，你必须想办法确保燃烧军团的这次进攻遭到挫败！去杀死这两只恐惧魔王！没有了他们，剩下的恶魔就会失去领导，变成一群无脑的生物。$B$B你可以在冥火岭正南方的屠魔峡谷中找到戈加农，就在玛诺洛斯那根悬浮在空中的短矛旁边。$B$B搜寻者迪亚索鲁斯住在屠魔山顶部的一处小洞穴里。要到达山顶，你需要从格罗姆·地狱咆哮的纪念碑旁的小径上攀爬上去。"
D.SharedStrings[28]="$n，你必须马上动身前往龙眠神殿，把这封信交给看门人塔里奥斯塔兹。神殿就座落在龙骨荒野的中央。沿着这条路往东一直走到尽头，然后穿过巨龙废土就到了。$B$B我相信塔里奥斯塔兹在了解你的来由后会引荐你拜见阿莱克丝塔萨女王陛下的。我们只能希望一切还不算太晚。$B$B感谢你为我们所做的一切，一路平安！"
D.SharedStrings[29]="$n，你所做的一切大大超出我们的预料。你并不是达拉然的公民，能取得这样的威望实属不易。现在，你在紫罗兰之眼的声望只差一步就达到颠峰了。$B$B继续证明你对我们的忠诚吧，我会将徽记蕴藏的力量全部赐予你。"
D.SharedStrings[30]="$n，你是个值得信赖的$r。我能把另一个任务也托付给你吗？$B$B不久前，我在北边的一个洞穴中挖掘矿石的时候不小心弄丢了我最喜欢的镐。后来当我回去找它的时候，却发现洞穴中住满了邪恶的野兽！到那个被称作火刃集会所的洞穴中去帮我取回我的镐，行吗？$B$B我把它放在一个有瀑布的大厅里了。我的镐附有魔法，你在黑暗中也能看见它，所以你不必担心找不到它……只要小心那些守护它的野兽就是了！"
D.SharedStrings[31]="$n，你没有令我们失望。不过，我们也对你寄予了更大的期望。$B$B继续为紫罗兰之眼效力吧，你会得到满意的回报的。"
D.SharedStrings[32]="$n，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。"
D.SharedStrings[33]="$n，如果没有你的话，燃烧军团的那些强大特工可能还在艾泽拉斯四处游荡，威胁着我们在这场战争中取得的成果。$b$b这样的功绩不能光靠口头表扬。$b$b如果你愿意接受的话，我们会拿出一部分力量，正式表彰你对抗黑暗的英勇事迹。"
D.SharedStrings[34]="$n，对不起，我以为你死了！$B$B太可怕了。我们的船卷进了联盟与部落的混战！$B$B落难的兄弟姐妹们还在等待救援。$B$B<他指着漂浮在附近海面上的逃生舱。>$B$B我得再坐会儿喘口气。你去救他们如何？穿上这双热电液压蛙蹼吧，它可以提升游泳速度。$B$B请转告莎希，我待会就跟她汇合。"
D.SharedStrings[35]="$n，巫妖王的入侵使我们深受其害。为了将他赶回冰封王座，部落和联盟必须坚定地团结在一起。我们在沙塔斯城的圣光广场结成了联军。$B$B为了帮助我们对抗巫妖王，请你到圣光广场的新药剂师营地去，和大药剂师普特雷斯谈一谈，制止亡灵瘟疫的研究就是由他主持的。只有他的研究成果才能拯救我们。$B$B快去吧，$n。每时每刻都有无辜的生命死去。"
D.SharedStrings[36]="$n，庆祝完我们的胜利后，我想你应该返回塞纳里奥树林，跟缚地者塔弗格伦谈谈。$B$B他一定很想知道那场惨剧的真相。"
D.SharedStrings[37]="$n，快！$b$b立即前往洞穴。$b$b我们断后，确保没有敌人跟踪你。"
D.SharedStrings[38]="$n，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。$B$B你要多加小心，这种蘑菇会喷射出有毒的孢子。$B$B帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！"
D.SharedStrings[39]="$n，我要你去召集一支亲友队伍，前往风暴烈酒酿造厂。你要激活那里的挑战者的宝珠，并击败破桶而出的炎诛。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[40]="$n，我要你去召集一支刚毅的队伍前往永茂林地。你要激活那里的挑战者的宝珠，并深入永茂林地阻止雅努的野心。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[41]="$n，我要你去召集一支勇敢的队伍攻入钢铁码头。你要激活那里的挑战者的宝珠，摧毁钢铁部落的训练设施，并击败他们所奴役的德拉诺最强大的怪物，包括斯古洛克，格鲁尔之子。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[42]="$n，我要你去召集一支勇敢的队伍，前往奥金顿的深处。你要激活那里的挑战者的宝珠，并净化塔隆戈尔对那里的渗透。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[43]="$n，我要你去召集一支勇敢的队伍，前往通灵学院。你要激活那里的挑战者的宝珠，并净化黑暗院长加丁。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[44]="$n，我要你去召集一支可靠的队伍返回艾泽拉斯的黑石塔上层。你要激活那里的挑战者的宝珠，并深入黑石兽人的旧居击败铁军先锋和他们的新盟友，督军扎伊拉。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[45]="$n，我要你去召集一支强劲的队伍，前往血槌炉渣矿井的深处。你要激活那里的挑战者的宝珠，并将矿工们从戈洛克的残暴统治下解救出来。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[46]="$n，我要你去召集一支机警的队伍，前往血色大厅。你要激活那里的挑战者的宝珠，并阻止织焰者孔格勒的焚书行为。"
D.SharedStrings[47]="$n，我要你去召集一支果决的队伍前往通天峰。你要激活那里的挑战者的宝珠，并登上峰顶消灭高阶贤者维里克斯和她的超级武器。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[48]="$n，我要你去召集一支目力过人的队伍，参与围攻砮皂寺的战役。你要激活那里的挑战者的宝珠，并击落翼虫首领尼诺洛克。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[49]="$n，我要你去召集一支稳定的队伍，前往影踪禅院。你要激活那里的挑战者的宝珠，并从恨之煞手中救出祝踏岚。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[50]="$n，我要你去召集一支精干队伍，前往残阳关。你要激活那里的挑战者的宝珠，并击败莱公。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[51]="$n，我要你去召集一支精干队伍，前往魔古山宫殿。你要激活那里的挑战者的宝珠，并击败武器大师席恩。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[52]="$n，我要你去召集一支精英队伍渗透进恐轨车站。你要激活那里的挑战者的宝珠，血洗恐轨号，并消灭啸天者托瓦拉的空中支援力量。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[53]="$n，我要你去召集一支顽强的队伍，前往血色修道院。你要激活那里的挑战者的宝珠，并制裁杜兰德。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[54]="$n，我要你去召集一群刚毅的战士前往影月墓地。你要激活那里的挑战者的宝珠，并在耐奥祖让整个德拉诺陪葬之前阻止他与虚空的融合。$B$B完成这个挑战后，你再回来找我。我会好好奖赏你的。"
D.SharedStrings[55]="$n，战争领主加尔顿派我来找你。他说他有件很重要的事情需要你的帮助。\n\n他希望你尽快返回邪能之槌号。"
D.SharedStrings[56]="$n，所谓众人拾柴火焰高，只要你成为“本月美酒”俱乐部的成员，你和你的同胞就能品尝到世间最棒的佳酿。$B$B将“本月美酒”俱乐部会员资料表交给奥格瑞玛的莱玛吧。"
D.SharedStrings[57]="$n，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。$B$B现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。"
D.SharedStrings[58]="$n，看見你真讓人喜極而泣。謝謝你救了我。\r\n\r\n我不知道我被困住多久…但是我感覺到附近有數量龐大的惡魔。\r\n\r\n我在這裡還有很多事要做。要不要幫我一把？"
D.SharedStrings[59]="$n，诺甘农之壳近在咫尺，唾手可得。拿上创世者的圆盘前往图书馆的内部，你应该可以在那里找到一个用来激活圆盘的控制台。我想米米尔储存在那里的东西远比诺甘农之壳更多，甚至可能包括能让铁炉堡的工程师们忙上许多年的结构图！$B$B不管怎样，用圆盘来恢复诺甘农之壳。希望米米尔没有给我们设置什么棘手的障碍。"
D.SharedStrings[60]="$r，你有我需要的東西嗎？時間所剩不多了。"
D.SharedStrings[61]="(兽人语)你好，$C!很高兴看到这么多像你$N一样的部落成员，伸出援手为安其拉之战打好基础。这样的努力一定会让我们胜过异种和他们藏在安其拉里面的邪恶主人。$B$B既然你在这里，记得去和不同的收集者谈谈并提供你的协助，收集你能取得的材料。"
D.SharedStrings[62]="(憤怒之門怪物)被遺忘者荒疫散佈者(防毒面具)"
D.SharedStrings[63]="+{1} 全能。"
D.SharedStrings[64]="+{1} 冰霜抗性。"
D.SharedStrings[65]="+{1} 力量。"
D.SharedStrings[66]="+{1} 奥术抗性。"
D.SharedStrings[67]="+{1} 所有抗性。"
D.SharedStrings[68]="+{1} 所有魔法抗性。"
D.SharedStrings[69]="+{1} 护甲。"
D.SharedStrings[70]="+{1} 护甲值。"
D.SharedStrings[71]="+{1} 敏捷。"
D.SharedStrings[72]="+{1} 智力。"
D.SharedStrings[73]="+{1} 暗影抗性。"
D.SharedStrings[74]="+{1} 武器伤害。"
D.SharedStrings[75]="+{1} 火焰抗性。"
D.SharedStrings[76]="+{1} 耐力。"
D.SharedStrings[77]="+{1} 自然抗性。"
D.SharedStrings[78]="+{1}%比例"
D.SharedStrings[79]="+{1}點PVP韌性。"
D.SharedStrings[80]="1，2，3，你不知道我是谁"
D.SharedStrings[81]="2v2竞技场荣誉杀敌"
D.SharedStrings[82]="3v3竞技场荣誉杀敌"
D.SharedStrings[83]="4份药剂的配方。但是，到底能供应几份还是得看急救技巧。"
D.SharedStrings[84]="4份食物的食谱。但是，到底能供应几份还是得看烹饪技巧。烹饪时可能学会新的食谱。"
D.SharedStrings[85]="4秒后爆炸，造成{2}点火焰伤害。\r\n嘀嗒嘀嗒。"
D.SharedStrings[86]="4秒后爆炸，造成火焰伤害。\r\n嘀嗒嘀嗒。"
D.SharedStrings[87]="5v5竞技场荣誉杀敌"
D.SharedStrings[88]="5秒后对任何停留在暗影裂隙内的敌人造成{1}点暗影伤害。"
D.SharedStrings[89]="5秒后对所有处于暗影裂隙内的敌人造成{1}点暗影伤害。"
D.SharedStrings[90]="5秒后对暮光裂隙内的敌人造成暗影伤害。"
D.SharedStrings[91]="5秒后造成{1}点火焰伤害。"
D.SharedStrings[92]="6秒后爆炸，造成{2}点火焰伤害。\r\n嘀嗒-嘀嗒。"
D.SharedStrings[93]="<一個裝著許多頁技術筆記的袋子。快速翻閱後，你找到克達納茲的最後一篇記錄。>"
D.SharedStrings[94]="<他从架子上翻出一本皮质封面的书。>$b$b如果你想知道更多，就去问阿尔泰娅，她最近正在为摩根·拉迪莫尔的事情头疼……"
D.SharedStrings[95]="<他的袖子上有個小掛牌，上面寫著「16‧瑟倫」。>"
D.SharedStrings[96]="<传送道标并没有激活，但至少完好无损。只要一些远古魔力就能让它重新启动。>"
D.SharedStrings[97]="<你将圆盘置入了控制台。忽然，面板上透出光芒，一阵计算机的仿真语音传了出来。>$B$B发明者圆盘已确认。欢迎回来，守护者弥米尔。"
D.SharedStrings[98]="<你拿走了他们的仪式用品，从而阻止了隐蔽之手的活动，为我们争取了宝贵的时间。>"
D.SharedStrings[99]="<你的线人所言不假，维特雷是邪教的精英，他身上肯定有线索。>"
D.SharedStrings[100]="<你靠近的時候，泰德里斯才從沉思中回神。>\r\n\r\n這樣夠了，$r。\r\n\r\n峭壁荊棘是一種致命的毒藥，正好符合我的需要。"
D.SharedStrings[101]="<信標冰冷而黑暗。>"
D.SharedStrings[102]="<克希利身上发出阵阵淡泊的光芒，而他身边的奥尔多和占星者军队也回应着他的命令。克希利的军团已经完全准备好了，随时可以将伊利丹的军队压制住，并为阿卡玛吸引敌人的注意力。现在，这位纳鲁正等待着你给出进攻开始的信号。>"
D.SharedStrings[103]="<兰特瑞索指着一个没有标志的箱子。>$B$B拿着。这是我送给你的人民的礼物。是你让我的氏族免遭灭顶之灾。$B$B回去告诉你的首领，火刃废墟的兰特瑞索和整个石拳食人魔氏族愿意与你们和平相处。$B$B<兰特瑞索鞠了一躬。>"
D.SharedStrings[104]="<凡席爾劇烈顫抖，眼神空洞地盯著前方。他似乎沒有察覺到你在這裡。>"
D.SharedStrings[105]="<凡席爾的雙手猛然伸出，從你的手裡搶走果實。>"
D.SharedStrings[106]="<古拉鲁克长叹一声……像是解脱……又好像带有悔意？>$B$B曾几何时，我也在这座工厂里，作为一名黑石兽人自豪地工作着。但那是一条错误的道路。自古以来，我们的铁锤该铸造的就是利剑和铁斧……而不是这些由陌生人暗地里授意的机器。$B$B但督军是不会听这些的，我们只有用武力来劝服他。假如你可以从这座铸造厂里最强大的保卫者身上获取精华，我就能为你铸造一枚印记，使你能够直接进入黑手的熔炉。"
D.SharedStrings[107]="<史戴芬仔细端详这些恶心的材料。>$B$B嗯，这算不上完美，不过总是可以用。$B$B现在抱头蹲低吧，$C。这就是好玩的地方……"
D.SharedStrings[108]="<地脈饋流產生輕柔的脈衝。>"
D.SharedStrings[109]="<塞勒斯查看了一下那块龙皮。>$B$B看来你还不是一文不值的。"
D.SharedStrings[110]="<塞勒斯的双眼变成了两颗燃烧的火球。>"
D.SharedStrings[111]="<大勇士从你手上接过德拉克玛之刃。>$B$B真是一把好剑，完美的平衡性。这一定能让我在下一场比赛好好发挥。"
D.SharedStrings[112]="<学者拉安达气若游丝。>$B$B你必须尽快去报告……卡德加。$B$B索克雷萨想要占领沙塔斯。他会不断募集追随者……$B$B谢谢你，陪我走完这最后一程……$B$B离开吧……我想休息了……"
D.SharedStrings[113]="<安格斯一邊擦眼淚一邊說。>\r\n\r\n布蘭伯利，你這傢伙…我保證會給你一場最盛大的葬禮！還有喝也喝不完的麥酒…"
D.SharedStrings[114]="<寇札克裂片嵌入傳送門旁的定位。你可以感覺到無數魔化能量朝著傳送門聚集過來，在你身旁不斷翻滾擾動。>"
D.SharedStrings[115]="<寇札克裂片極力掙脫，似乎想飛向某個地方。>"
D.SharedStrings[116]="<巡察员以一种不信任的眼神看着你。 > $B$B我听说你要来...协助这次的调查。好得很。 $B$B我在废墟使用这些粉尘，来帮助我寻找可能辨认出攻击者的线索。它会让任何与攻击相关的痕迹发光。不要犹豫去检查所有可疑的东西。"
D.SharedStrings[117]="<巫牙因你击败了他的巨鹰敌人而大声嗥叫。>$B$B击杀的荣耀属于你。我真希望最后包复她颈脖的是我的嘴。$B$B我们别浪费了她的牺牲。东西在这，吃了它们!"
D.SharedStrings[118]="<布蘭道夫把配方混合。>\r\n\r\n好吧，我可沒說過這東西會好入口。乾杯。"
D.SharedStrings[119]="<弗喬里克虛弱地看著你。>\r\n\r\n你及時趕回來了…"
D.SharedStrings[120]="<想要找到邪教徒，任何线索都很重要。>"
D.SharedStrings[121]="<戴格吐出一些皮鞋的碎皮。>$B$B呸呸……$B$B<戴格剧烈地咳了起来。>$B$B什么?难道你不知道吗，皮革的蛋白质含量极高，而糖份含量极低!"
D.SharedStrings[122]="<拉格隆德咆哮着。>$B$B他们已经开始传颂你的事迹了，$N。雷矛士兵听到你的名字就会胆战心惊。继续好好干吧!"
D.SharedStrings[123]="<既然已经拿到了林家古老的汤面配方，你决定出发前往半山市集。>$B$B<如果说在潘达利亚有人知道如何破译这个卷轴的话，那一定非孙行·铁掌莫属。>"
D.SharedStrings[124]="<暮光之眼的“声音”在你四周回荡，仿佛它来自四面八方。>$B$B你想借用我的视域，$r？那就得付出代价。暮光教徒一直献祭蛮锤矮人的精华以示诚意，但我还是很饿。或许你可以做得更好。$B$B击败我的旧主子，我的视域就属于你。献上漆黑萨满的精华吧。精华就是精华。"
D.SharedStrings[125]="<有人居住於此的痕跡。這份捲軸上書寫著奇異的文字，發出溫暖的光芒，使你忍不住伸出手觸摸。>"
D.SharedStrings[126]="<沃戈斯裂片嵌入了傳送門旁的位置。漩渦般的魔化能量圍繞在裂片四周，整個房間充滿不祥的黑暗能量。>"
D.SharedStrings[127]="<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……"
D.SharedStrings[128]="<泰德里斯盯著蘇拉瑪爾，似乎陷入沉思。>"
D.SharedStrings[129]="<玛拉纳的海地精和龙虾人从附近的沉船处抓走了被遗忘者水手。>\n\n<水手们似乎受到了毒害，或许他们的境况比这更糟。你应该终结他们的痛苦。>"
D.SharedStrings[130]="<當你注入上古法力時，信標不斷發光。>"
D.SharedStrings[131]="<種子穩穩地落在高台上，卡嗒一聲沉了下去。>"
D.SharedStrings[132]="<第二把圣化长剑，你感受一下这两把宝剑传递给你的力量。>$B$B<还有最后一件事要做。正如神秘的蒙面女子所说，要结束血色十字军的统治，你必须使用两把圣化长剑的力量净化大检察官怀特迈恩。"
D.SharedStrings[133]="<精灵形态的红龙读着你的介绍信，他的脸上渐渐出现了担忧的神情。>$B$B嗯……嗯，我想这应该可以让你立即拜见女王！$B$B等你准备好了之后，就来告诉我一声，我会让这些幼龙把你安全地送到神殿的顶端。你必须亲自把这封信交给阿莱克丝塔萨女王陛下。"
D.SharedStrings[134]="<索隆迪爾氣若游絲勉強吐出幾個字。>\r\n\r\n毒藥…流遍我…全身。"
D.SharedStrings[135]="<結界斷然張開，帶給你些微的痛感。克達納茲一定耗費了無數心力研發這個咒語，既可嚇跑凋萎者，又不會讓他們受傷。>"
D.SharedStrings[136]="<纳萨诺斯大笑了起来。>$B$B太好了!我终于等到了一个可以消灭血色十字军神谕者的机会!"
D.SharedStrings[137]="<聖光之心發出耀眼的光芒，似乎在吞噬靈魂稜石。>"
D.SharedStrings[138]="<艾萊莉說話時眉頭深鎖。>\r\n\r\n你該不會以為部落領袖可以齊聚一地，還不被燃燒軍團注意到吧？"
D.SharedStrings[139]="<菲恩抓住你的肩膀，高興地跳來跳去。>\r\n\r\n莫嚕咕！咕嚕莫嘎咕。"
D.SharedStrings[140]="<蒙托尔神父在你面前做了一个奇怪的手势。>$B$B幸运的$G小伙子:姑娘;，你找到那些阵亡士兵的护甲了吗？这些可怜的英雄在那场战争中咽下了最后一口气，还被天灾士兵脱去了所有护甲，连死亡的尊严都没能保住。$B$B把被玷污的护甲部件和净化所需的材料给我带来，你就会了解信仰的含义。"
D.SharedStrings[141]="<薩莉瑟拉用力握緊法術石，遲遲不肯放手。>\r\n\r\n這是他自找的。\r\n\r\n我不能一直困在過去。失去他，艾莉珊德就少了一大助力，我們離為夏多雷撥亂反正的目標也更近了一步。"
D.SharedStrings[142]="<薩莉瑟拉眼神渙散，身體不斷顫抖。>"
D.SharedStrings[143]="<这个侏儒间谍保护着一份关于被遗忘者部队的详细报告。>"
D.SharedStrings[144]="<这名士兵脸色苍白，身负重伤，显然正承受着巨大的痛苦。>\n\n从突袭……破碎海滩……就一直……被囚禁……\n\n<他战栗了一下。>\n\n恶魔……他们在集结……准备……\n\n必须逃跑……来警告你。一定要……阻止他们！"
D.SharedStrings[145]="<这名士兵脸色苍白，身负重伤，显然正承受着巨大的痛苦。>\n\n从突袭……破碎海滩……就一直……被囚禁……\n\n<此人战栗了一下。>\n\n恶魔……他们在集结……准备……\n\n必须逃跑……来警告你。一定要……阻止他们！"
D.SharedStrings[146]="<這個凋萎者似乎被法術石催眠，徹底平靜下來。>"
D.SharedStrings[147]="<防护盾消失了。直捣黄龙，干掉斡耳朵野牛人的战争使者！>"
D.SharedStrings[148]="<阿卡玛将水晶插入他手中的卡拉波护符里。>$B$B$n，我已经已不再像从前一样强大和自信了，$n。而且这些年来，我一直与真正的邪恶离得那么近，携带这件如此强大的神器的同时，我真不知道自己到时候还能不能再相信自己。$B$B拿去吧，把这个作为我发誓要与你共同对抗伊利丹的信物，拿去吧。你可以把这个卡拉波护符交给沙塔斯城的阿达尔代为保管。"
D.SharedStrings[149]="<阿布撒隆立即吞噬上古法力，看來短時間內似乎說不出話。>"
D.SharedStrings[150]="<阿拉卡呵呵大笑。>$B$B是的，我是在指挥官日志中所提到的背弃者。我一直在等那一天，当其它人感觉到那些我曾经称为兄弟们所造成的威胁。"
D.SharedStrings[151]="<阿达欧问候你。>"
D.SharedStrings[152]="<随着你注入远古魔力，传送道标开始发出光芒。>"
D.SharedStrings[153]="<隨著你將斷裂的部分放到柱子上，並開始注入法力，秘法能量開始修復斷裂處。地脈啟動後，它開始緩慢轉動。>"
D.SharedStrings[154]="<隨著你將碎片重新插入柱子中，秘法能量開始修復裂痕。你對地脈饋流注入上古法力，整個構造體開始復甦。>"
D.SharedStrings[155]="<隨著你對饋流注入更多法力，構造體開始發揮作用。空氣中開始瀰漫著秘法能量，你的皮膚感到刺痛。>"
D.SharedStrings[156]="<隨著狂暴的能量從圓柱的縫隙逸出，地脈饋流也開始劈啪作響。>"
D.SharedStrings[157]="<隨著魔法屏障逐漸消失，你聽見外頭傳來樹葉沙沙的聲響，以及昆蟲喀喀的聲音。>"
D.SharedStrings[158]="<魔网能量似乎是完好无损的，但却毫无反应。或许远古魔力可以让它再次运行？>"
D.SharedStrings[159]="B连战地工具。将其关闭。"
D.SharedStrings[160]="ELM綜合目的兔子(scale x0.01 - Phase I)大型"
D.SharedStrings[161]="ELM綜合目的大型兔子(scale x0.01)－高攻擊性&高等級"
D.SharedStrings[162]="G0-R41-0N型终极坦克"
D.SharedStrings[163]="GM工具，冻结玩家。"
D.SharedStrings[164]="K3的莉吉特要求你前往加姆雷区，使用改进型地雷杀死12个从加姆方向冲过来的敌人。加姆入侵者和雪盲追随者都算数。"
D.SharedStrings[165]="PvP强度提高{1}点。"
D.SharedStrings[166]="PvP韧性提高{1}点。"
D.SharedStrings[167]="P·哈里斯船长"
D.SharedStrings[168]="Throm-Ka，$r！欢迎来到战歌要塞。看到又一个杰出的部落英雄响应使命的召唤来到这里，我深感自豪！$B$B这座固若金汤的堡垒象征着部落的坚定决心。经过艰苦的奋斗，我们在诺森德建起了这座堡垒。我们将从这里出发，最终征服冰封王座。在地狱咆哮之子的领导下，我们必将赢得胜利！$B$B加尔鲁什在下面等着你。$B$BLok'tar ogar！"
D.SharedStrings[169]="X-51虚空火箭"
D.SharedStrings[170]="X-51虚空火箭特别加强版"
D.SharedStrings[171]="X-53型观光火箭"
D.SharedStrings[172]="XD-57“标靶”跟踪导弹"
D.SharedStrings[173]="XE-321爆破机器人"
D.SharedStrings[174]="XS-013废料机器人"
D.SharedStrings[175]="XT-002拆解者的機心受損，移除XT-002拆解者的戰鬥限制。傷害力提高{3}%，生命力提高{4}%。"
D.SharedStrings[176]="ZX-5103动力装甲"
D.SharedStrings[177]="[DND] 任務獎勵 - 貧瘠之地 4.x 河船 - 開始"
D.SharedStrings[178]="[DND]寒冰皇冠飛船(A) - 火砲目標，保護盾"
D.SharedStrings[179]="[DND]寒冰皇冠飛船(H) - 火砲目標，保護盾"
D.SharedStrings[180]="[DND]寒冰皇冠飛行至飛船兔子(A)傳送目標"
D.SharedStrings[181]="[DND]寒冰皇冠飛行至飛船兔子(H)傳送目標"
D.SharedStrings[182]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n使敌人沾上软泥，造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[183]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n使用邪恶能量攻击，造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[184]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n冲向敌人，造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n这个招式总能取得先手。"
D.SharedStrings[185]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n对敌人的宠物造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n摧毁由双方队伍制造出的物体。"
D.SharedStrings[186]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n对敌人的激活宠物造成[StandardDamage(1,1)]点[School()]伤害，并对敌人的后排宠物造成[StandardDamage(1,2)]点[School()]伤害。"
D.SharedStrings[187]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n对敌人造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[188]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n对敌方队伍造成[StandardDamage(1,1)]点[School()]伤害，但会消耗你[points(1,4)]%的最大生命值。"
D.SharedStrings[189]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n朝目标射出电能箭，造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[190]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n猛击敌人，造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[191]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n猛咬敌人，造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[192]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n猛抓敌人，造成[StandardDamage(1, 1)]点[petTypeName(abilityPetType())]伤害。"
D.SharedStrings[193]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n猛撞敌人，造成[StandardDamage(1,1)]点[School()]伤害，并对自身造成[SimpleDamage(1,3)]点[School()]伤害。"
D.SharedStrings[194]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n用龙之吐息席卷敌人，造成[StandardDamage(1, 1)]点[School()]伤害。"
D.SharedStrings[195]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n第一次使用：装填炮弹。\r\n\r\n第二次使用：发射炮弹，造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[196]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n粉碎敌人，造成[StandardDamage(1, 1)]点[School()]伤害。"
D.SharedStrings[197]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n连击敌人1-2次，每1击造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n如果使用者率先攻击，则可额外攻击1次。"
D.SharedStrings[198]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1, 1)]点[School()]伤害，并移除战场上的所有对象。"
D.SharedStrings[199]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[200]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n为使用者回复相当于所造成伤害[points(1,3)]%的生命值。"
D.SharedStrings[201]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n如果使用者率先发起攻击，则可使对手的攻击轮中断。"
D.SharedStrings[202]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n该技能总能取得先手。"
D.SharedStrings[203]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害。每击中一次伤害提高[FormatDamage (pointsincreaseperuse(1,1)*AttackBonus())]点。最高可造成[FormatDamage (pointsmax(1,1)*AttackBonus())]点[School()]伤害。"
D.SharedStrings[204]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害并迫使对手将生命值最高的宠物换入战斗。"
D.SharedStrings[205]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害，并有25%的几率使目标昏迷。"
D.SharedStrings[206]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害，并迫使对手的另一只宠物出战。"
D.SharedStrings[207]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害，并迫使敌人生命值最低的宠物出战。"
D.SharedStrings[208]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害，并迫使敌人生命值最高的宠物出战。"
D.SharedStrings[209]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害，由所有敌人分摊，并将天气转变为奥术之风，持续[duration(1,2)]轮。如果奥术之风已经激活，则造成额外伤害。\r\n\r\n在奥术之风期间，宠物不会陷入昏迷或被定身。"
D.SharedStrings[210]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n造成[StandardDamage(1,1)]点[School()]伤害，由敌人的队伍成员均摊。"
D.SharedStrings[211]="[StandardAccuracy(1,1)] 命中几率\r\n\r\n鞭笞敌人1-2次，每一击造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n如果使用者率先攻击，则可额外攻击1次。"
D.SharedStrings[212]="[StandardAccuracy(2,1)] 命中几率\r\n\r\n在首轮积聚力量。\r\n\r\n使用者会在下一轮以势不可挡之力朝敌人发起冲锋，造成[StandardDamage(2,1)]点[School()]伤害。"
D.SharedStrings[213]="[StandardAccuracy(2,1)] 命中几率\r\n\r\n高高跃起，在1轮内无法攻击。\r\n\r\n在下一轮，你发动攻击，造成[StandardDamage(2, 1)]点[School()]伤害。"
D.SharedStrings[214]="[UNUSED]短距離哥布林探測器"
D.SharedStrings[215]="{1}点神圣伤害。"
D.SharedStrings[216]="——已发现创造者。警报！警报！——"
