D.SharedStrings[228]="“小刀”希格尔·格希尔"
D.SharedStrings[229]="“就此开始，自然之父塞纳留斯。就此开始。”$B$B德迪利特伸手在空中迅速地作了几个手势，一道微弱的光环罩住了他。$B$B“你要领悟的第一种自然的力量就是熊的力量。我将指引你理解这种力量对德鲁伊所具有的意义，但是从现在起，你必须信奉并宣扬这一信条，永不改变!”$B$B"
D.SharedStrings[230]="“巧手”雷尼·麦考伊"
D.SharedStrings[231]="“巨兽”乔莫格"
D.SharedStrings[232]="“急浪船帮”"
