D.SharedStrings[263]="“鳐鱼”塞德里克·菲克曼塔"
D.SharedStrings[264]="“鸩酒”是古代上层精灵所用的一种毒药。讽刺的是，在地下埋藏了一万年之后，这种酒已经失去了致命的毒性，变成了一种温和的麻醉品。"
D.SharedStrings[265]="“黑拳”海默尔"
D.SharedStrings[266]="“齿轮眼”艾米波特"
D.SharedStrings[267]="《大地的裂变》团队副本完成次数（杀死最终首领）"
D.SharedStrings[268]="《大地的裂变》地下城完成次数（杀死最终首领）"
D.SharedStrings[269]="《大地的裂变》给艾泽拉斯带来了更多小动物。你必须也对它们献上你的/爱。"
D.SharedStrings[270]="《大地的裂变》美食家"
D.SharedStrings[271]="《巫妖王之怒》10人团队副本完成次数（杀死最终首领）"
D.SharedStrings[272]="《巫妖王之怒》25人团队副本完成次数（杀死最终首领）"
D.SharedStrings[273]="《巫妖王之怒》5人副本完成次数（杀死最终首领）"
D.SharedStrings[274]="《德拉诺之王》团队副本完成次数（击败最终首领）"
D.SharedStrings[275]="《德拉诺之王》地下城完成次数（击败最终首领）"
D.SharedStrings[276]="《熊猫人之谜》团队副本完成次数（杀死最终首领）"
D.SharedStrings[277]="《熊猫人之谜》地下城完成次数（杀死最终首领）"
D.SharedStrings[278]="「潛力無窮」被抓走的俾格米擊殺獎勵"
D.SharedStrings[279]="『兜風』酷炫改裝車鑰匙已使用擊殺獎勵"
D.SharedStrings[280]="『汝當歸於塵土』擊殺獎勵"
D.SharedStrings[281]="『測試龍』奧瑪"
D.SharedStrings[282]="『表演一定要繼續!』火枝大砲A擊殺獎勵"
D.SharedStrings[283]="『表演一定要繼續!』火枝大砲B擊殺獎勵"
D.SharedStrings[284]="『表演一定要繼續!』火枝大砲C擊殺獎勵"
D.SharedStrings[285]="一个也不能少"
D.SharedStrings[286]="一个利用纯净法力可以毁掉我们城镇的炸弹!但是为什么?为什么血精灵要制造这样一个东西还用来对付我们?塞纳里奥灌木林曾是一个和平宁静的地方。$B$B不管理由是什么，它一定被锁在守望者崔洛斯的头里，我不知道该怎么解救他。或许他的心智会随着时间被治愈?$B$B不论如何，我要谢谢你帮助我厘清发生的事。我只希望这个悲剧永远不会再降临在任何人身上!"
D.SharedStrings[287]="一个刺客凝视着一个目标。额外受到15%的伤害。"
D.SharedStrings[288]="一个名叫维利塔恩的萨特正在玷污玛拉顿的洞穴，使那里的许多植物无法生长。$B$B拿着这个瓶子，$n。用洞穴里面橙色水晶池中的水装满这个瓶子；瓶中所包含的物质可以中和毒药，将它变成一种治疗药剂。$B$B你可以在橙色的洞穴中找到维利斯塔姆藤蔓，然后对它们使用净化过的液体。这样，附着在植物上的堕落物质就会被净化，但是你要知道维利塔恩仍然控制着这些植物。他会利用它来对付你……"
D.SharedStrings[289]="一个地精伐木工？看着挺不错。但那可是佩妮。"
D.SharedStrings[290]="一个奥术构造体的能量核心，散发着狂野的能量。"
D.SharedStrings[291]="一个强壮的幻影，会周期性地被激怒。"
D.SharedStrings[292]="一个愤怒的橡树之魂冒出来，为被你杀死的晶歌橡树复仇！"
D.SharedStrings[293]="一个施法型幻影，会周期性投掷火球，将地面变成火海。"
D.SharedStrings[294]="一个普通的幻影，没什么特殊技能。"
D.SharedStrings[295]="一个极其结实的柜子立在你面前，柜子的门被一个内建的锁牢牢地锁着。柜子的前面有深深的划痕与刻痕，看起来好像是在无数次想要解开其中秘密的粗暴失败尝试所导致的结果。$B$B如果你想要打开这个柜子，就得先找到钥匙。"
D.SharedStrings[296]="一个火焰鞭笞者跟随着你。"
D.SharedStrings[297]="一个精密的陷阱，可以捉住巨大的老虎。"
D.SharedStrings[298]="一个精心编织的陷阱，可以套住巨型仙鹤的腿。"
D.SharedStrings[299]="一个食人魔流浪汉偷走了你的一些装备。"
D.SharedStrings[300]="一件大口径武器，已经预装了测试弹药。警告：使用者后果自负。"
D.SharedStrings[301]="一件来自光辉年代的，未使用的圣物。"
D.SharedStrings[302]="一件来自无尽之海深处的神秘纳迦神器。国王姆嘎姆嘎正在上古海滩寻找这种东西。"
D.SharedStrings[303]="一件纤毫毕现的精美复制品。它会随着时间的流逝逐渐磨损。"
D.SharedStrings[304]="一件非常昂贵的服装。"
D.SharedStrings[305]="一份来自赞加红土的古怪植物样本。"
D.SharedStrings[306]="一位守护法师将你传送到了夺日者圣殿外面。"
D.SharedStrings[307]="一位守护法师将你传送到了银色领地外面。"
D.SharedStrings[308]="一位艺术家从赫达沙尔的最高点捕捉到的景象。"
D.SharedStrings[309]="一切安排妥当。所有系统运转正常，并且我们拥有充足的燃料。邪能之槌号的迁跃引擎也已就绪。\n\n凯丽娅和瓦雷迪斯知道你在找他们。根据贝拉斯的情报，他们已经躲到一个叫做尼斯卡拉的恶魔世界里了。\n\n我们要发动入侵，彻底做个了结。"
D.SharedStrings[310]="一剂特制毒药，可以削弱最健壮的猢狲。"
D.SharedStrings[311]="一只四壁厚实的笼子，专门用来装超大型的螃蟹。"
D.SharedStrings[312]="一只巨大的虫子身上的一小块碎片。"
D.SharedStrings[313]="一只巨大的食人魔之手，被切下来并拴在一根长长的绳子上。"
D.SharedStrings[314]="一只恐惧渡鸦正专注攻击你。恐惧渡鸦受到的{1}%伤害会复制给你。"
D.SharedStrings[315]="一只恶魔蜘蛛马上要从卵中孵化出来了！"
D.SharedStrings[316]="一只枭兽宝宝正跟着你，想从你的冒险中学习经验。"
D.SharedStrings[317]="一只特别结实、卑鄙的猢狲。可能还有别的办法，但是……"
D.SharedStrings[318]="一只角鹰兽宝宝正蹲在你肩膀上。"
D.SharedStrings[319]="一只讨厌的欺诈者小鬼抓住你了！\r\n移动速度降低{1}%。"
D.SharedStrings[320]="一只逃脱的小鬼正在攻击你。"
D.SharedStrings[321]="一只逃脱的魔犬正在攻击你。"
D.SharedStrings[322]="一只饥饿的巢鸟以为你是它的妈妈！\r\n对这只巢鸟造成的伤害提高{1}%。"
D.SharedStrings[323]="一台大口径火炮，可以将大量小动物发射到空中。"
D.SharedStrings[324]="一名狙击手发现了你。你很快将被击中。"
D.SharedStrings[325]="一名被遗忘者法师将你传送出了灰牙之地。"
D.SharedStrings[326]="一名被遗忘者法师将你传送出了风行者圣殿。"
D.SharedStrings[327]="一名贵宾室保镖将你从比兹莫贵宾室里扔了出来。"
D.SharedStrings[328]="一团团烈焰在龙的周围突涌，使其获得施放火球弹幕的力量。"
D.SharedStrings[329]="一团火焰在龙的周围快速来回旋转，使其获得能量以施放火球弹幕。"
D.SharedStrings[330]="一团硕大、凝结且不停颤动的污泥。"
D.SharedStrings[331]="一团艰涩思维之云，阻断所有攻击和法术施放。"
D.SharedStrings[332]="一场战斗无法决定整场战争，指挥官。\n\n那艘运输舰抵挡不了钢铁部落的海军多久。我们还需要一艘舰船。幸运的是，一个本地的走私贩子向我们提供了建造驱逐舰所需的图纸。我们得立即建造一艘驱逐舰！"
D.SharedStrings[333]="一块发热发光的岩石。"
D.SharedStrings[334]="一块恶魔碎片，可以打开邪魂堡垒中的恶魔传送门。"
D.SharedStrings[335]="一块武器的碎片，上面似乎附有足以对抗伊利丹麾下恶魔的魔法。"
D.SharedStrings[336]="一块法罗迪斯之戒的碎片。"
D.SharedStrings[337]="一块精心雕刻着蛮沼部族所膜拜的动物图腾的木头。"
D.SharedStrings[338]="一声尖锐的呼号，加速附近的雏龙孵化，并令它们来协助主母。"
D.SharedStrings[339]="一大袋代币"
D.SharedStrings[340]="一头掠食龙注意到你了。跳跃以甩掉肉片。"
D.SharedStrings[341]="一套“链式”胸甲，全部由恶魔猎犬的牙齿连缀而成。牙齿的齿尖在胸甲的内侧，整齐地朝上排列着，只要一穿上就绝不可能脱下来——准确地说，不把穿它的人撕扯得血肉模糊，绝不可能脱下来。"
D.SharedStrings[342]="一定有人通報了大博學者，她們才會知道凡席爾也參與了這場反叛行動。如此殘暴的行為…\r\n\r\n艾莉珊德…為什麼？"
D.SharedStrings[343]="一定有办法让他动起来……"
D.SharedStrings[344]="一客南瓜馅饼已经上桌了。"
D.SharedStrings[345]="一客火鸡已经上桌了。"
D.SharedStrings[346]="一客玉米馅料已经上桌了。"
D.SharedStrings[347]="一客甜薯已经上桌了。"
D.SharedStrings[348]="一客酸果蔓已经上桌了。"
D.SharedStrings[349]="一对木质雕像，分别代表乌索尔和乌索克。"
D.SharedStrings[350]="一封谒见龙后的介绍信函?让我看看。$B$B无论你的来意为何，我希望事关要紧。今日的天空满是蓝龙的攻击!"
D.SharedStrings[351]="一小包代币"
D.SharedStrings[352]="一小块泰坦圆盘的碎片。"
D.SharedStrings[353]="一层大地之盾保护目标，受到近战攻击可以为其恢复生命值。该效果几秒内只能出现一次。"
D.SharedStrings[354]="一层大地之盾保护目标，被大地之盾笼罩的目标在受到近战攻击时可以恢复生命值。该效果数秒内只能出现一次。"
D.SharedStrings[355]="一层苔藓之皮，使施法者在受到伤害时有一定几率吸收伤害。"
D.SharedStrings[356]="一层薄薄的软泥覆盖在你身上，保护你免受岩浆的炙烤。"
D.SharedStrings[357]="一层魔法护盾包裹施法者，有{1}%的几率反射法术。"
D.SharedStrings[358]="一座巨型熔炉，可以超负荷供应动力。"
D.SharedStrings[359]="一座栩栩如生的雕像！"
D.SharedStrings[360]="一张龙皮卷轴，上面描绘着某种神秘的维库人仪式。"
D.SharedStrings[361]="一支强大的军队，能够与追随者一起执行任务，提高成功率。"
D.SharedStrings[362]="一支长长的望远镜，但你透过它却什么都看不到，或许会派上用场。"
D.SharedStrings[363]="一整天的训练没什么害处。很高兴看见你持续锻炼。"
D.SharedStrings[364]="一旦我们的部队开始动身穿越奥尔杜萨，他们就很容易遭到来自铁墙壁垒和广袤的冰川平原地区的攻击。$B$B我们没有时间和资源去建造防御工事，但可以搭建一些临时性的路障，抵御天灾军团的远程火力和突击，以保护我们的士兵。$B$B带着这只工具箱到奥尔杜萨西面的陨落英雄之谷去。按照我在那里做好的记号，用这只工具箱制造一些路障。"
D.SharedStrings[365]="一旦甲虫的召唤活动结束，其拉虫族就会返回它们的地穴。"
D.SharedStrings[366]="一旦那几座哨塔被做上了标记，它们就将成为我们在安多哈尔的首要攻击目标。我预计在攻占那些哨塔塔之后就要和安多哈尔城中的主力部队交锋了。那时，我们要进行一场痛快淋漓的战斗，一举夺取城市的控制权!$B$B我希望你凯旋而归，另外别忘了把信号火炬也带回来，我们可不能浪费资源。"
D.SharedStrings[367]="一束伊利丹的魔法灼过地表，大地开始燃烧，对行进路线上所有目标造成{1}点暗影伤害。"
D.SharedStrings[368]="一条小小的吊坠，拴着一条纤细的坠链。"
D.SharedStrings[369]="一条怪鱼。它没有嘴巴，还长着一条不分叉的尾巴，主要靠植物的生命能量存活。只有老练的渔夫在纳特·帕格的帮助下才有可能抓到它。"
D.SharedStrings[370]="一条神奇的“鱼”，生活在熔岩中，看起来就像一条长着锥形甲壳的鱿鱼。只有老练的渔夫在纳特·帕格的帮助下才有可能抓到它。"
D.SharedStrings[371]="一枚奖章，只授予勇敢坚定的老战士。"
D.SharedStrings[372]="一枚奖章，只授予在战场上最勇猛、最所向披靡的参赛者。"
D.SharedStrings[373]="一枚奖章，只授予野蛮残酷、能够一次又一次杀出一条血路，赢得胜利的战士。"
D.SharedStrings[374]="一枚小小的水晶护符，可以和能量发生共鸣。"
D.SharedStrings[375]="一枚恶魔印记，只授予被萨格拉斯选中的极少数信徒，能够让人进入阿古斯的核心。"
D.SharedStrings[376]="一枚沉重、制作精良的手镯。外圈上有许多刮痕，似乎经历过一场大战。"
D.SharedStrings[377]="一枚炸弹，命中后爆炸，对范围内的目标造成暗影伤害。"
D.SharedStrings[378]="一枚荣誉徽章"
D.SharedStrings[379]="一枚被蓟叶林精偷走的、未孵化的月翼龙蛋。他们是打算吃掉它吗？"
D.SharedStrings[380]="一桶易爆的烈酒，造成{1}点火焰伤害。"
D.SharedStrings[381]="一桶陈年达拉然红葡萄酒"
D.SharedStrings[382]="一桶风暴蜜酒"
D.SharedStrings[383]="一次凶猛的横扫攻击，对目标和最多三名邻近的敌人造成伤害。"
D.SharedStrings[384]="一次凶猛的横扫攻击，对目标和最多两名邻近的敌人造成伤害。"
D.SharedStrings[385]="一次大规模地震，造成物理伤害并使附近敌人减速。"
D.SharedStrings[386]="一次对目标的惩罚打击，使其受到的治疗效果减少{1}%。"
D.SharedStrings[387]="一次快速攻击，对目标造成中等的物理伤害。"
D.SharedStrings[388]="一次恶毒的猛击，造成{1}点物理伤害。"
D.SharedStrings[389]="一次有力的攻击，近战伤害提高10%。"
D.SharedStrings[390]="一次有力的攻击，近战伤害提高10%，并产生大量的威胁值。"
D.SharedStrings[391]="一次有力的攻击，近战伤害提高100%。"
D.SharedStrings[392]="一次有力的攻击，造成{1}%的武器伤害。"
D.SharedStrings[393]="一次横扫攻击，攻击你前方的所有敌人，造成{1}点物理伤害。"
D.SharedStrings[394]="一次稳固的射击，对目标造成相当于{1}%武器伤害的物理伤害。"
D.SharedStrings[395]="一次稳固的射击，造成相当于{1}%武器伤害的物理伤害。"
D.SharedStrings[396]="一次野蛮的攻击，造成{1}%的武器伤害。"
D.SharedStrings[397]="一波混沌能量的爆炸冲击施法者前方的敌人，造成{1}点暗影伤害。"
D.SharedStrings[398]="一片染血的羊皮纸，一侧有米葛的潦草字迹。"
D.SharedStrings[399]="一片疫病之云弥漫在施法者周围，对范围内所有敌人造成自然伤害。"
D.SharedStrings[400]="一瓶陈年达拉然红葡萄酒"
D.SharedStrings[401]="一生中最棒的是什么？"
D.SharedStrings[402]="一直以來，你對部落貢獻良多，$n。\r\n\r\n你的責任會變得越來越重…越來越重。"
D.SharedStrings[403]="一瞬千击刘刚拳"
D.SharedStrings[404]="一种当代铭文师不再使用的过时材料。但有些人会收集它们，所以你还是能够收回本钱的。"
D.SharedStrings[405]="一种特殊的酒精类饮料。"
D.SharedStrings[406]="一种瓦解性的魔法力量已经破坏了这种秘药，令其完全失去了效果。"
D.SharedStrings[407]="一笔小钱，以表彰你的事迹。"
D.SharedStrings[408]="一管采自瓦古心脏中的疫病病菌。用以折磨敌人。"
D.SharedStrings[409]="一箱摆放整齐的、加工过的原料。"
D.SharedStrings[410]="一篇被破译的《真正的信徒》上的文章。"
D.SharedStrings[411]="一簇金色风暴乌鸦的羽绒，能将追随者的移动速度提升到史诗级别。"
D.SharedStrings[412]="一群蜘蛛攻击附近玩家，对所有附近敌人造成暗影伤害。"
D.SharedStrings[413]="一股力量逼迫着你……"
D.SharedStrings[414]="一股奇怪的力量从你体内穿过，然后渐渐退去……"
D.SharedStrings[415]="一股强风将目标吹到空中，造成{1}点自然伤害。"
D.SharedStrings[416]="一股猛烈的强风，对敌人造成自然伤害。"
D.SharedStrings[417]="一股痛苦波浪碾过施法者面前的敌人，造成{1}点暗影伤害并将其击退。"
D.SharedStrings[418]="一股神秘的力量正探索魔古神器上的信息。"
D.SharedStrings[419]="一股被腐蚀的生命能量发生毁灭性的爆炸，对周围的所有玩家造成{1}点暗影伤害。"
D.SharedStrings[420]="一股高能光束在图腾周围画上一个圈，灼烧触碰到的敌人。"
D.SharedStrings[421]="一股黑暗的力量在奎尔德拉中涌动，似乎它要把你扯向冰冠堡垒的映像大厅。"
D.SharedStrings[422]="一般兔子"
D.SharedStrings[423]="一般控制器LAB－多重階段(非無柄巨型AOI)"
D.SharedStrings[424]="一般用途兔子JMF (Look 2)"
D.SharedStrings[425]="一艘军团战舰正在轰炸此目标。"
D.SharedStrings[426]="一艘拥有强化装甲的快速舰船，可用于海军行动。"
D.SharedStrings[427]="一艘搭载了大口径火炮的舰船，可用于海军行动。"
D.SharedStrings[428]="一艘毁灭性的潜水舰艇，可用于海军行动。"
D.SharedStrings[429]="一艘运输部队和给养的大型舰船，可用于海军行动。"
D.SharedStrings[430]="一袋好东西"
D.SharedStrings[431]="一记由上至下的猛砍对施法者面前的所有敌人造成{1}点物理伤害。"
D.SharedStrings[432]="一道煞染情绪仿佛护盾般围绕着这只生物。那些试图逼近它的家伙们会发现自己被纯粹情感所侵蚀了。"
D.SharedStrings[433]="一道猛烈喷发的熔岩烈焰，可以用来扫清冰封路障。"
D.SharedStrings[434]="一道空气漩涡，击退过于靠近的敌人。"
D.SharedStrings[435]="一道魔法訊息，居然能夠從燃燒軍團的監視下傳出…非常聰明。"
D.SharedStrings[436]="一部催人泪下的言情小说：《北地柔情》"
D.SharedStrings[437]="一部催人泪下的言情小说：《大号铜弹》"
D.SharedStrings[438]="一部催人泪下的言情小说：《机器情缘》"
D.SharedStrings[439]="一部催人泪下的言情小说：《热与雾》"
D.SharedStrings[440]="一部催人泪下的言情小说：《狂野基情》"
D.SharedStrings[441]="一部催人泪下的言情小说：《禁断之爱》"
D.SharedStrings[442]="一部纳斯雷兹姆书籍，但艾泽拉斯的凡人种族完全无法将其破译。"
D.SharedStrings[443]="一阵强劲的烈焰疾风对施法者前方锥形区域内的敌人造成火焰伤害，并将其击退。"
D.SharedStrings[444]="一阵强烈的眩光对目标造成奥术伤害。"
D.SharedStrings[445]="一阵强烈的眩光对目标造成暗影伤害。"
D.SharedStrings[446]="一阵强风将目标卷上空中，造成{1}点自然伤害。"
D.SharedStrings[447]="一面邪焰护盾包围施法者，对附近敌人造成火焰伤害。"
D.SharedStrings[448]="一颗虚空之星锁定了你！"
D.SharedStrings[449]="一颗黑曜石陨星坠落到地面。"
D.SharedStrings[450]="万千之主祖尔坦"
D.SharedStrings[451]="万桩丛中过，片叶不沾身"
D.SharedStrings[452]="三个控制阀门都处于打开状态。根据控制面板上的指示说明，在拆卸零件之前必须要把这三个阀门关闭。"
D.SharedStrings[453]="三人执政团"
D.SharedStrings[454]="三分之一块圆形符印。"
D.SharedStrings[455]="三次快速的噬咬，对前方的所有敌人造成{1}点物理伤害。"
D.SharedStrings[456]="上传攻城数据。"
D.SharedStrings[457]="上位者的蔑视"
D.SharedStrings[458]="上升暖气流可以使你比一般情况下跳得更远。"
D.SharedStrings[459]="上古之梦对玩家进行了治疗，并被移除。"
D.SharedStrings[460]="上古之神和艾泽拉斯的秩序"
D.SharedStrings[461]="上古之神的触须"
D.SharedStrings[462]="上古巢穴守卫"
D.SharedStrings[463]="上古水晶的元素之力充满你的全身，使用这股力量来对付暮光之锤元素仆从。"
D.SharedStrings[464]="上古水灵"
D.SharedStrings[465]="上周，有位暗夜精灵乘坐着虚空幼龙来到镇上。他说自己名叫奥图里斯，然后向城民们询问了一些关于纳格兰的问题。$B$B最夸张的是，他宣称还自己的职责是追杀燃烧军团。你听听这癫狂的言语，你能想象吗？居然还有人愿意猎杀恶魔？$B$B奥图里斯临走之前让我们告诉那些想要成为英雄的人，说什么如果人愿意做点有意义的事，就尽管去找他。他会一直在纳格兰西部恭候诸位的大驾。"
D.SharedStrings[466]="上层精灵"
D.SharedStrings[467]="上层精灵对一切紫色物品的嗜好可以追溯到上古之战之前。玻璃碗是很常见的器具，从谷粒到金锭都可以用它来盛装。"
D.SharedStrings[468]="上次我一时头脑发热，跟一个死亡骑士打了一架，结果……唉。$B$B前往晶歌森林的南部，你可以在水晶裂痕的出口上方找到恒焰领主。杀死他，拿到他身上的恒焰灰烬。$B$B带着恒焰灰烬前往嚎风峡湾北部的冬息湖中心，解救一位被寒冰困在那里的女士。她守护着一把古代宝剑，能够解救她的人就可以获得那把宝剑作为奖励。$B$B证明你的能力，拿到她守护了许久的宝剑吧，$n。"
D.SharedStrings[469]="上面不完整的文字似乎记载着某种戒严令之类的律令，并暗示人们警惕邻居和朋友中施行诅咒的迹象。"
D.SharedStrings[470]="上面有你的名字！"
D.SharedStrings[471]="上面的时间刻度十分模糊，仔细看还会让人眼睛发疼。"
D.SharedStrings[472]="上面的跳蚤毫无防御作用。"
D.SharedStrings[473]="上面绘着一只渡鸦的轮廓。"
D.SharedStrings[474]="下一个抓钩的伤害提高{1}%。"
D.SharedStrings[475]="下一个持续时间超过{1}秒的、使你完全失去控制的效果在施放后会很快被移除。"
D.SharedStrings[476]="下一个闪电箭、闪电链、次级治疗波、治疗波或治疗链的施法时间缩短{1}%。"
D.SharedStrings[477]="下一次对你进行的近战或远程攻击将由前来援护的战士承担。"
D.SharedStrings[478]="下一次快速治疗成为瞬发技能并且不消耗法力值。"
D.SharedStrings[479]="下一次攻击的伤害提高{1}点。"
D.SharedStrings[480]="下一次攻击的伤害提高。"
D.SharedStrings[481]="下一次攻击造成的伤害降低{1}%。"
D.SharedStrings[482]="下一次致命攻击会触发诅咒，为你恢复最大生命值的{1}%并使诅咒寻找新的主人。"
D.SharedStrings[483]="下一次近战攻击的爆击几率提高{1}%。"
D.SharedStrings[484]="下一次远程攻击会对该目标额外造成{1}%的伤害。"
D.SharedStrings[485]="下一轮，将为你的激活宠物回复50%的最大生命值。"
D.SharedStrings[486]="下列所有熊猫人职业都达到最高等级。"
D.SharedStrings[487]="下列所有职业均获得“决斗者”头衔。"
D.SharedStrings[488]="下列所有职业均获得“大元帅”头衔。"
D.SharedStrings[489]="下列所有职业均获得“战斗大师”头衔。"
D.SharedStrings[490]="下列所有职业均获得“挑战者”头衔。"
D.SharedStrings[491]="下列所有职业均获得“竞争者”头衔。"
D.SharedStrings[492]="下列所有职业均获得“角斗士”头衔。"
D.SharedStrings[493]="下列所有职业均获得“高阶督军”头衔。"
D.SharedStrings[494]="下次有雞會，我一定確保他得到妥善的照顧。我們今天大有斬獲，$n。\r\n\r\n艾莉珊德一定會記住，我們不會輕易丟下自己人。"
D.SharedStrings[495]="下水道传送门"
D.SharedStrings[496]="下水道怪兽兰希德斯"
D.SharedStrings[497]="下界地狱的恶魔"
D.SharedStrings[498]="下达一份破碎命运印记订单。"
D.SharedStrings[499]="下达订单，订购一批勇士武器和装备。"
D.SharedStrings[500]="下面的敌人"
D.SharedStrings[501]="不会受到任何伤害，但也无法做出任何动作。"
D.SharedStrings[502]="不会受到任何物理和法术伤害，但是在这期间你也无法攻击、移动或施法。"
D.SharedStrings[503]="不会吧！又坏了一个垫圈……$B$B每次有垫圈坏掉，润滑剂都会流得到处都是。如果没有溶解剂的话，就得折腾好几个小时才能清理干净。$B$B我跟你说啊，在风险投资公司闯入的那个港口里有一种奇特的火箭燃料——我想他们把它称为“115号元素”。那东西可是很猛的溶解剂哦。$B$B帮我弄些过来，我不会让你白辛苦的。"
D.SharedStrings[504]="不会和其他食人魔发生争斗。"
D.SharedStrings[505]="不停地挥砍敌人，造成{1}%的武器伤害。"
