D.SharedStrings[562]="不需要为了这些年幼雏龙的命运感到良心不安，$r。玛里苟斯才应该要为此负责。$B$B我努力不懈地研究想揭开这些符文的奥秘。$B$B我向你保证，除非必要我们不会再夺取更多的生命了。"
