D.SharedStrings[647]="与联盟作战是为部落效劳的莫大荣耀！那些在各条战线上和联盟作战的士兵是我们最伟大的成员。我们要消灭我们的对手，而不是仅仅进行小规模的遭遇战，我们要打精心准备的大战。$B$B去每一条战线上消灭联盟吧！为了荣耀！为了部落！"
