D.SharedStrings[808]="专注地引导以琥珀为源动力的卡拉克西心灵能量。"
D.SharedStrings[809]="专用于那些普通朗姆酒不足以应付的场合。"
D.SharedStrings[810]="世界事件：儿童周"
D.SharedStrings[811]="世界事件：冬幕节"
D.SharedStrings[812]="世界击碎者的风暴之镰"
D.SharedStrings[813]="世界啟動器(不是免疫的玩家)"
D.SharedStrings[814]="世界製皮龍麟訓練師(NO LONGER IMPLEMENTED)"
D.SharedStrings[815]="世间流传着许多关于塔隆·血魔的故事，但是大多数都只是传说。人们并不知道塔隆·血魔返回德拉诺世界后发生的事。$B$B我们只能确定一件事，那就是他已经死了。$B$B我曾听这儿的斥候说，在遥远的东南方，跨越灵翼平原，穿过灵翼小径就能到达暗影祭坛，有位远古的兽人灵魂居住在那儿。戴上幽灵眼镜搜寻这位兽人。他应该知道更多关于塔隆·血魔的事。"
D.SharedStrings[816]="业报之触激活期间受到的伤害会治疗你。"
D.SharedStrings[817]="丛林守护者"
D.SharedStrings[818]="东尼利·顿沃德"
D.SharedStrings[819]="东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯会免费为你施放奥术遮罩的咒语。你在银色黎明中的声望必须达到崇拜。"
D.SharedStrings[820]="东瘟疫之地圣光之愿礼拜堂的愤怒者玛塔乌斯需要10枚十字军徽记和30金币。"
D.SharedStrings[821]="东部王国灭火"
D.SharedStrings[822]="东部王国的糖果"
D.SharedStrings[823]="丝瓦什荣誉卫士"
D.SharedStrings[824]="丝黛拉苟萨"
D.SharedStrings[825]="丢掷一桶水，浇灭焰须巡逻营的大火。"
D.SharedStrings[826]="严重受伤。\r\n这条幼龙很快就会失去飞行能力。"
D.SharedStrings[827]="严阵以待……呃，水阵"
D.SharedStrings[828]="中了邪能灌注酒的毒。"
D.SharedStrings[829]="中型火焰"
D.SharedStrings[830]="中断的束缚引发混乱喷涌，造成{1}点混乱伤害。"
D.SharedStrings[831]="中毒发疯的白鬼"
D.SharedStrings[832]="丰富的材料回来了!你把我要的东西都带来了吗?"
D.SharedStrings[833]="丰收女巫塞莱斯廷"
D.SharedStrings[834]="丹塔利纳克斯"
D.SharedStrings[835]="丹莫罗巡山人"
D.SharedStrings[836]="丹莫罗熊宝宝"
D.SharedStrings[837]="丹莫罗雪橇手"
D.SharedStrings[838]="为一个友方单位恢复{1}点生命值。"
D.SharedStrings[839]="为一个友方目标恢复{1}点生命值。"
D.SharedStrings[840]="为一个友方目标恢复{1}点生命值。你施放在目标身上的回春术、愈合或生命绽放效果可以使治疗效果提高20%。"
D.SharedStrings[841]="为一个友方目标恢复{1}点生命值。你施放在目标身上的回春术、愈合或生命绽放效果可以使该治疗效果提高20%。"
D.SharedStrings[842]="为一个被冻结的生物解冻。"
D.SharedStrings[843]="为一件《军团再临》的传说物品注入强大的力量，使其物品等级提升，最高可达到{1}。"
D.SharedStrings[844]="为一位追随者装备一件物品等级为{1}的武器。"
D.SharedStrings[845]="为一名友方目标移除所有诅咒和魔法效果。"
D.SharedStrings[846]="为一名盟友恢复其最大生命值的{1}%。"
D.SharedStrings[847]="为一名追随者装备全套物品等级为{1}的护甲。"
D.SharedStrings[848]="为一把煞染武器或雷电神兵增加一个棱彩插槽。"
D.SharedStrings[849]="为了冲破凯尔娜拉的奥术护盾，我们需要一块具有罕见力量和品质的聚焦水晶。$b$b在矿场里有个水晶巨人，德莱尼人管它叫安杜尔。那个巨人已经在地下岩层间沉睡多年，但现在已经被凯尔娜拉的鲁莽行动惊醒了。$b$b水晶巨人的心脏绝对是强大的神器。击败安杜尔，把水晶巨人之心给我带回来。等我拿到它之后，打造聚焦水晶的准备工作就完成了！"
D.SharedStrings[850]="为了参加鲜血竞技场而战。"
D.SharedStrings[851]="为了夺取要塞，我们得消灭巫师领主莫库克才行，可我不认为应该就这么径直去找他。$B$B他的三位副官——沃戈什、祖尔莫克和克罗矛格都是强大的法师，而且都对莫库克无比忠诚。$B$B一旦我们跟巫师领主交上手，他们恐怕就会立刻赶来助战。让我们先干掉他们，防止那种情况出现吧。"
D.SharedStrings[852]="为了打发时间，商人们通常会喝点小酒来提提神，你懂的吧。\n\n但有时候，有些人会喝得太多。你的商人可能刚迈出门就倒在树下睡过去了。这种事情也是时有发生。\n\n幸运的是，我这有一种专门用来弄醒这些酒醉商人的饮料。只要泼上一点，他们就会更愿意起来干活。"
D.SharedStrings[853]="为了满足燃烧军团的地狱火兵力需求，暗影议会必定挑选了一处隐蔽之地，在那里召唤堕落的元素生物来构成地狱火的核心部分。$B$B召唤室通常在地下，附近会有被污染的水池或熔岩。前往死亡熔炉寻找召唤大厅，并设法破坏他们的召唤仪式。一些莫尔葛恶魔也参与了制造地狱火，他们身上携带的某种工具或许能打断召唤师的魔法。"
D.SharedStrings[854]="为了联盟！"
D.SharedStrings[855]="为了能在霜狼氏族内获得承认，每一位氏族成员都必须独自完成一个任务，那就是驯服一头野生霜狼并与之结下友谊。不是所有的氏族成员都能通过这项试炼，但成功的人都将获得一位终生的伙伴。"
D.SharedStrings[856]="为了能够在PTR上测试地下城内容，你的装备等级修改至{1}。"
D.SharedStrings[857]="为了诺莫瑞根！"
D.SharedStrings[858]="为了部落！"
D.SharedStrings[859]="为了防止被偷走，这辆载具中安装了自爆系统。当它离开规定区域之后，自爆系统就会自动开启。"
D.SharedStrings[860]="为了阻止钢铁部落，我们必须克服成见，进行必要的合作。\n\n部落，联盟，过去，现在……在这样的强敌面前，一切都变得毫无意义。\n\n我们将合力重新夺回沙塔斯……至死方休。"
D.SharedStrings[861]="为什么我的运气总是烂到家了呢？我的比赛用剑无影无踪了！$B$B在吟游诗人的传说里，如果哪位旅人能给一位孤独的女士带去几朵冬水仙，就可以获得她的礼物。那些花只生长在铁墙大坝下游的浮冰上，就在晶歌森林的西北部，与冰冠冰川交界的地方。去摘些这种花，然后把花带到龙骨荒野东北部的达克玛尔湖去，就在该地区与祖达克、灰熊丘陵交界处的灯环中找到那位孤独女士。把花献给她，她会回赠你一把优秀的利剑。"
D.SharedStrings[862]="为你历经战火的神器解锁一种新的配色。"
D.SharedStrings[863]="为你恢复{1}点生命值。"
D.SharedStrings[864]="为你的武器附加一条武器链，使缴械效果的持续时间缩短{1}%，急速提高{2}点。不与其它同类效果叠加。\r\n\r\n附加武器链的武器会与你绑定。不能对物品等级高于600的物品使用。"
D.SharedStrings[865]="为你的要塞添加一名追随者。"
D.SharedStrings[866]="为使用者回复[StandardDamage(1,1)]点生命值。"
D.SharedStrings[867]="为北郡骑士麦斯米兰完成任务来获得经验并提升等级。"
D.SharedStrings[868]="为友方目标恢复{1}点生命值。"
D.SharedStrings[869]="为友方目标恢复生命值。"
D.SharedStrings[870]="为友方目标治疗{1}点伤害。"
D.SharedStrings[871]="为受保护的目标恢复{1}%的最大生命值。"
D.SharedStrings[872]="为塞达斯获取充能的塑魔法杖和不稳定的构造体核心。"
D.SharedStrings[873]="为废料堆中的一个机器人充能，使其重新运作起来。"
D.SharedStrings[874]="为影锋注入其主人的鲜血。每秒造成{1}点伤害并使目标衰弱，使其造成的伤害降低{2}%。"
D.SharedStrings[875]="为施法者前方所有盟友治疗{1}点生命值。"
D.SharedStrings[876]="为施法者恢复{1}%的最大生命值。"
D.SharedStrings[877]="为施法者恢复{1}点生命值。"
D.SharedStrings[878]="为施法者恢复其最大生命值的{1}%。"
D.SharedStrings[879]="为施法者每秒恢复{1}点生命值，并在效果结束时使其恢复{2}%的生命值。"
D.SharedStrings[880]="为施法者注入青龙的能量，允许技能有附加效果。"
D.SharedStrings[881]="为施法者的武器注入水的能量，使近战攻击命中后有一定几率造成自然伤害"
D.SharedStrings[882]="为施法者的武器注入闪电的能量，使近战攻击命中后有一定的几率造成自然伤害。"
D.SharedStrings[883]="为施法者的武器注入黑暗能量，使近战攻击命中后有一定几率造成暗影伤害。"
D.SharedStrings[884]="为施法者祛除{1}点腐蚀值。"
D.SharedStrings[885]="为月神之光内受伤最严重的小队成员恢复{1}点生命值。"
D.SharedStrings[886]="为游学者周卓画一幅画。使这幅画可以说话！"
D.SharedStrings[887]="为焦躁的海魂收集活水。叠加到10层时回去与海魂交谈。落水则会失去已经叠加的层数！"
D.SharedStrings[888]="为狂心氏族阵营完成下列8个日常任务。"
D.SharedStrings[889]="为生命值低于5%的玩家包扎厚霜纹布绷带、烬丝绷带或风绒绷带。"
D.SharedStrings[890]="为盟友恢复{1}%的生命值。受到伤害会打断施法。"
D.SharedStrings[891]="为盟友施加护盾，使其受到的所有伤害降低{1}%。"
D.SharedStrings[892]="为盟友设定攻击位置。"
D.SharedStrings[893]="为目标恢复{1}%的最大生命值。"
D.SharedStrings[894]="为目标恢复{1}点生命值。"
D.SharedStrings[895]="为目标治疗{1}点伤害。"
D.SharedStrings[896]="为目标的灵魂充能，使他们获得额外的技能资源以对抗他们的敌人。"
D.SharedStrings[897]="为碎地者发出信号攻击目标位置。"
D.SharedStrings[898]="为神谕者阵营完成下列8个日常任务。"
D.SharedStrings[899]="为自己恢复{1}点生命值。"
D.SharedStrings[900]="为萨鲁法尔大王准备的礼物"
D.SharedStrings[901]="为长矛钉刺和召唤兽群灌以元素火焰之力。\r\n\r\n非骑乘状态时可以使用高热弹片。"
D.SharedStrings[902]="为阿穆纳伊充能。"
D.SharedStrings[903]="为附近的所有盟友恢复{1}%最大生命值。"
D.SharedStrings[904]="为附近的所有盟友恢复{1}%的生命值，并提高{2}%的伤害。该效果可叠加。"
D.SharedStrings[905]="为附近的盟友恢复{1}点生命值。"
D.SharedStrings[906]="为青铜幼龙标记要摧毁的投石车。"
D.SharedStrings[907]="主城宠物格斗家（联盟）"
D.SharedStrings[908]="主城宠物格斗家（部落）"
D.SharedStrings[909]="主母玛沃伦丝"
D.SharedStrings[910]="主母萨丝琳"
D.SharedStrings[911]="主管索戈尔"
D.SharedStrings[912]="主管索戈尔（史诗难度）"
D.SharedStrings[913]="主要過場動畫載具"
D.SharedStrings[914]="丽丽·风暴烈酒"
D.SharedStrings[915]="丽丽的风筝"
D.SharedStrings[916]="举行你的个人赛。"
D.SharedStrings[917]="举行致命的仪式，随机召唤一只恶魔。需要至少3名参与者。"
D.SharedStrings[918]="举起休战旗。拥护沃金的暗矛巨魔将不会攻击你。"
D.SharedStrings[919]="举起旗帜代表你的阵营。"
D.SharedStrings[920]="举起盾牌，偏转所有远程攻击和法术，并格挡来自前方的所有近战攻击。"
D.SharedStrings[921]="乌克兹·沙顶"
D.SharedStrings[922]="乌克头领没有拿到橘子。"
D.SharedStrings[923]="乌克头领猛击他的目标，将其打翻在地。哎呦！"
D.SharedStrings[924]="乌尔的暗影魔法研究论文"
D.SharedStrings[925]="乌拉罗格·塑山"
D.SharedStrings[926]="乌比斯将军向一个敌人的位置冲锋，如果成功则造成物理伤害并将其击飞。"
D.SharedStrings[927]="乌特加德之巅"
D.SharedStrings[928]="乌特加德之巅奖励任务"
D.SharedStrings[929]="乌特加德城堡"
D.SharedStrings[930]="乌瑞恩堡步兵"
D.SharedStrings[931]="乌瑞恩堡火枪手"
D.SharedStrings[932]="乌瑞恩堡魔导师"
D.SharedStrings[933]="乌瑞恩的开荒团"
D.SharedStrings[934]="乌瑟尔·光明使者"
D.SharedStrings[935]="乌祖尔死亡时在附近制造一个酸性水滴。"
D.SharedStrings[936]="乌索克之爪"
D.SharedStrings[937]="乌索克，巨熊之神"
D.SharedStrings[938]="乌苏雷的最终抉择"
D.SharedStrings[939]="乌萨勒斯，逆风收割者"
D.SharedStrings[940]="乍看之下，这个蛋和其他彩蛋没有什么不同。"
D.SharedStrings[941]="乔乔·铁眉"
D.SharedStrings[942]="乔恩·铁枷"
D.SharedStrings[943]="乔拉齐·拉文霍德公爵"
D.SharedStrings[944]="乘着维瑟尔飞行，在赫达沙尔消灭150名神王的部下。"
D.SharedStrings[945]="九头蛇卵的铭文袋"
D.SharedStrings[946]="也许我们终于能做点什么了。不过不要被蒙蔽了，巫妖王还是能通过天灾军的爪牙“窥探”。$B$B那就是你来此的理由。"
D.SharedStrings[947]="也许我们能晃晕他……"
D.SharedStrings[948]="书籍研究"
D.SharedStrings[949]="书记员赫拉斯·怀特斯蒂德"
D.SharedStrings[950]="买家注意：这是一件在先前的拍卖中售出的物品，但竞价胜出者一直没来领取。"
D.SharedStrings[951]="事实上，我们在多线作战，$g小子:小姑娘;，而且我们不能把军队部署得太过分散，否则我们可能会全盘皆输！$b$b我们需要以天为单位来部署最关键的部队，今天，奥特兰克山谷的战斗最需要勇敢的士兵们！$b$b现在就出发吧，$n，去帮助雷矛远征军。我们不能就这么看着霜狼氏族逃脱他们应受的惩罚。"
D.SharedStrings[952]="事实上，我们在多线作战，$g小子:小姑娘;，而且我们不能把军队部署得太过分散，否则我们可能会全盘皆输！$b$b我们需要以天为单位来部署最关键的部队，今天，阿拉希盆地的战斗最需要勇敢的士兵！$b$b带着胜利的消息回来吧，$n。我们不允许部落狗来威胁属于我们的资源！"
D.SharedStrings[953]="事情的結局可能沒我希望的這般明朗。"
D.SharedStrings[954]="云游节是安宁祥和的节日，这里不允许打斗。"
D.SharedStrings[955]="云端翔龙"
D.SharedStrings[956]="云端翔龙骑士团"
D.SharedStrings[957]="云端翔龙骑士团一直在寻找天赋异禀的骑手。$B$B如果你希望追寻我们的道路，你应该去翡翠林的百木园和天荆教头谈一谈。$B$B祝你好运，$r。"
D.SharedStrings[958]="亚勒伯龙攻击计划"
D.SharedStrings[959]="亚煞极之启迪"
D.SharedStrings[960]="亚煞极之触会控制目标的心灵，使其搜索附近的盟友，并试图传播给他们。对受到心灵控制的玩家造成足够多的伤害后，会打破该效果。"
D.SharedStrings[961]="亚煞极的仆从"
D.SharedStrings[962]="亚煞极的力量从亵渎武器上渗出，随着其生命值的下降，亵渎之地的影响范围也会逐渐缩小。"
D.SharedStrings[963]="亚煞极的爪牙"
D.SharedStrings[964]="亚煞极的锐利凝视"
D.SharedStrings[965]="亚煞极的黑暗之血"
D.SharedStrings[966]="亚考罗克的精华"
D.SharedStrings[967]="亚萨·袭月上尉"
D.SharedStrings[968]="亡灵卫兵亚当斯"
D.SharedStrings[969]="亡灵卫兵亨伯特"
D.SharedStrings[970]="亡灵卫兵战地队长"
D.SharedStrings[971]="亡灵卫兵沙穆萨"
D.SharedStrings[972]="亡灵卫兵达内尔"
D.SharedStrings[973]="亡灵舰长伊丽扎"
D.SharedStrings[974]="亡灵骑兵库伦"
D.SharedStrings[975]="亡灵骑兵疫病使者"
D.SharedStrings[976]="亡灵骑兵马尔维克"
D.SharedStrings[977]="亡者的传说"
D.SharedStrings[978]="亡语者布莱克松"
D.SharedStrings[979]="亡语者贾格巴"
D.SharedStrings[980]="交给畜棚开始装运。"
D.SharedStrings[981]="产品订单"
D.SharedStrings[982]="产品订单：至高岭鲑鱼"
D.SharedStrings[983]="产品订单：魔石"
D.SharedStrings[984]="产生一个治疗气泡。盟友可以激活气泡，恢复{1}点生命。"
D.SharedStrings[985]="产生一个被折磨的灵魂。"
D.SharedStrings[986]="产生一块方尖碑，阻挡植物攻击。"
D.SharedStrings[987]="产生一道闪电攻击敌人，造成{1}点自然伤害。这套设备完全由金属制成……"
D.SharedStrings[988]="产生弹片，并击退前方锥形区域内的敌人。"
D.SharedStrings[989]="产生电能火花跳跃到随机位置，伤害所有邻近敌人。"
D.SharedStrings[990]="亲手对下列职业中的一种进行荣誉击杀。"
D.SharedStrings[991]="亲爱的$n，巫妖王在用疾病和侵略折磨着我们——部落和联盟都深受其害。只有艾泽拉斯的这两个伟大文明联手，才有可能击败他。$B$B我们在沙塔斯城的圣光广场结成了联军。为了帮助我们对抗巫妖王，请你到圣光广场的新联盟营地去，和拉莎莉尔主教谈一谈。$B$B愿圣光保佑你，$n。"
D.SharedStrings[992]="亲爱的，我恐怕终于要为自己的罪行偿命了。我将永远被困在冥界，在海拉的操纵下航行于海上。不要忘了我。"
D.SharedStrings[993]="亵渎大地护腕"
D.SharedStrings[994]="亵渎施法者脚下的土地，对进入其中的敌人造成暗影伤害。"
D.SharedStrings[995]="亵渎武器蕴含着亚煞极的力量，武器的生命值越低，其亵渎能够影响的半径就越小。"
D.SharedStrings[996]="亵渎联盟在大灾变后出现的地区中的篝火。"
D.SharedStrings[997]="亵渎这团火焰！"
D.SharedStrings[998]="亵渎部落在大灾变后出现的地区中的篝火。"
D.SharedStrings[999]="亵渎部落的银松营火!"
D.SharedStrings[1000]="人如其名，碎手氏族的战士会通过某种仪式砸碎自己的手，然后再将它砍下来。他们会用火烧灼残肢使其结疤，然后装上各种不同的武器。这把武器看似只是普通的屠夫砍刀，其实极其沉重，能够干脆利落地砍断你的手。"
D.SharedStrings[1001]="人类保卫者 狙击战斗光束 虚拟"
D.SharedStrings[1002]="什么?!$B$B<你眼前的影像扭曲了一会儿，大法师试图保持镇定。>$B$B当然，我们早该想到这是他们的企图。快，不要浪费时间。$B$B要有人去警告龙眠神殿!"
D.SharedStrings[1003]="什么?!一杯免费啤酒?好吧，好吧。我猜我们决定今年要这么做了。"
D.SharedStrings[1004]="什么事吗?你手里拿着的是什么?"
D.SharedStrings[1005]="什么什么平衡器"
D.SharedStrings[1006]="什么他们被逼疯了?什么他们脑海里的声音?$B$B你脑海里的声音?!$B$B我要你先静下来把杂念从心中排去$g孩子:女孩l;。$B$B等明天你充分的休息以后，我们再试试把其馀的受害者从那地方救出来。"
D.SharedStrings[1007]="什锦汤面餐车"
D.SharedStrings[1008]="什麼？我聽到熟悉的聲音…但不可能。"
D.SharedStrings[1009]="仁德会营地的大德鲁伊拉索留斯许诺，若你能带回15只奈辛瓦里同党的耳环，他就会给予你丰厚的奖赏。"
D.SharedStrings[1010]="仅仅一小块矿石的光芒也散发着深不可测的力量。"
D.SharedStrings[1011]="仅供在苏拉玛练习裁缝图样时使用，不准偷。"
D.SharedStrings[1012]="仅供在达拉然练习裁缝图样时使用，不准偷。"
D.SharedStrings[1013]="仅限英雄难度"
D.SharedStrings[1014]="仇恨使者格劳迪奥"
D.SharedStrings[1015]="今天你通过完成一个日常任务的方式参与了夺日者的作战行动。\r\n坐骑施法时间减少{1}%。\r\n坐骑移动速度提高{2}%。"
D.SharedStrings[1016]="今天你通过完成一个日常任务的方式参与了肯瑞托的作战行动。\r\n坐骑施法时间减少{1}%。\r\n坐骑移动速度提高{2}%。"
D.SharedStrings[1017]="今天就到这里吧，孩子。明天如果你还活着再来找我。"
D.SharedStrings[1018]="今天，黑騎兵嘗到有史以來最大的敗績，也是暮色森林人民的一大勝利。\r\n\r\n他們欠你一份恩情，我也是。"
D.SharedStrings[1019]="从65码的高度掉落下来，但是不摔死。"
D.SharedStrings[1020]="从“高个子”巴克身上找到“高个子”巴克的尾巴。"
D.SharedStrings[1021]="从一个敌人身上吸取{1}点生命值，将其转移给施法者。"
D.SharedStrings[1022]="从一个死亡的石油软泥怪身上虹吸油。"
D.SharedStrings[1023]="从一个沥青元素的尸体上刮掉粘稠的沥青。"
D.SharedStrings[1024]="从一个狂怒的鬼灵身上虹吸精质。这个狂怒的鬼灵生命值不能高于50%。"
D.SharedStrings[1025]="从一个随机敌对目标身上迸出鲜血，对附近的敌人造成{1}点物理伤害。"
D.SharedStrings[1026]="从一名戈杜尼术士手里获得戈杜尼宝珠。"
D.SharedStrings[1027]="从一名敌人处吸取{1}点生命值和{2}%的耐力，并转移给施法者。"
D.SharedStrings[1028]="从一名敌人身上吸取{1}点生命值和{2}%的属性值，并转移到施法者身上。"
D.SharedStrings[1029]="从一名敌人身上吸取{1}点生命值，并转移给施法者。"
D.SharedStrings[1030]="从一名死去的艾露恩的信徒身上吸取灵魂能量。"
D.SharedStrings[1031]="从一扇无人保护的虚空传送门中吸取能量，切断其与鲁拉之间的联系，并将其永久关闭。"
D.SharedStrings[1032]="从一道暗影之门传动到另一道暗影之门，随后，伤害和移动速度在短时间内获得很大提升。"
D.SharedStrings[1033]="从任意一座旅店的糖罐里获取一把糖果。"
D.SharedStrings[1034]="从你上次接受测验到现在已经有很长的时间了，$n。迄今为止，你展示了足够的耐心，不过现在你应该学到更多的东西，应该去了解水的纯洁。$B$B去贫瘠之地找到水之先知伊斯伦，沿着怒水河的东岸向棘齿城的南方走，你可以在一间小渔屋里找到她。祝你好运，$n。"
D.SharedStrings[1035]="从你的帽子中抓出可施放嘲讽技能的兔子。"
D.SharedStrings[1036]="从元素生物体内分离出元素的灵魂。只有在灵魂图腾的附近才能生效。"
D.SharedStrings[1037]="从关押所里的光脊收割者身上收集7株蜷草苗芽。"
D.SharedStrings[1038]="从农夫达尔松那已经成为食尸鬼的遗体中拿到的钥匙完全与锁孔吻合。柜子的门转开了，展现在你面前的是数样完整无缺的物品，而且它们看起来都非常珍贵。"
D.SharedStrings[1039]="从冬泉谷的两处冬泉熊怪营地中取得6块熏肉，把它们喂给你的冬泉豹幼崽。"
D.SharedStrings[1040]="从冰斧巨魔洞穴中找到雷尔松的全视之眼，然后回到指挥官雷尔松那里。$B$B要当心，据说雷尔松的全视之眼带有可怕的诅咒！"
D.SharedStrings[1041]="从凯丽娅·邪魂的手中夺走奥达奇战刃。"
D.SharedStrings[1042]="从北荆棘谷丛林捕猎者身上获得5根丛林捕猎者的羽毛。"
D.SharedStrings[1043]="从南海火枪手和南海勇夫身上获得20份金料。"
D.SharedStrings[1044]="从卡拉赞的猎手阿图门那里获取炽热战马的缰绳。"
D.SharedStrings[1045]="从卡桑琅河的污鳞打击者身上收集6颗污鳞蛇头。"
D.SharedStrings[1046]="从古拉巴什竞技场拾取竞技场高手饰物。"
D.SharedStrings[1047]="从地下钻出来。你的冰虫会固定在原地，但是可以攻击。"
D.SharedStrings[1048]="从地面上召唤冰川尖刺，向前突进，对喷发点附近的敌人造成{1}点冰霜伤害。"
D.SharedStrings[1049]="从地面唤起一块巨石并向目标位置丢去，对附近的单位造成物理伤害。"
D.SharedStrings[1050]="从地面喷出一道水柱，造成伤害和击退效果。"
D.SharedStrings[1051]="从埃鲁纳克的手上释放出闪电箭，对附近的敌人造成大量伤害。"
D.SharedStrings[1052]="从塔拉多库洛的领地上方的艾默松身上取得一根嗡鸣的德拉诺晶刺。"
D.SharedStrings[1053]="从塔拉多沙塔斯城沙塔尔灯塔那里的赫尔默大使处夺回埃索达斯之光。"
D.SharedStrings[1054]="从塔纳安丛林的多名斥候那里听取报告。"
D.SharedStrings[1055]="从塞泰克大厅的安苏那里获取乌鸦之神的缰绳。"
D.SharedStrings[1056]="从天空中引导邪能流星风暴。"
D.SharedStrings[1057]="从天而“降”"
D.SharedStrings[1058]="从失落希望海角的船只残骸中取回6桶南海朗姆酒。失落希望海角位于此地以北的海边。"
D.SharedStrings[1059]="从奈瑟匹拉里面的埃卓凯丝督军和埃卓凯丝先知手中夺取5颗神秘的珍珠。"
D.SharedStrings[1060]="从奈瑟匹拉里面的武器架上收集4支被盗的长矛。"
D.SharedStrings[1061]="从奥术之柱内吸取能量，对所有敌人造成{1}点奥术伤害。"
D.SharedStrings[1062]="从奥术畸变体或奥术能量裂隙中吸收能量。"
D.SharedStrings[1063]="从奥格瑞姆之锤斥候身上截获6份奥格瑞姆之锤急件，把它们交给破天号上的高级指挥官加斯汀·巴雷特。"
D.SharedStrings[1064]="从奸商街的“大金牙”盖比那里购买一些亮闪闪的珠宝，从苏扎博那里购买一套潮人装束，从“软糖”米萨那里购买一副清爽遮阳镜。"
D.SharedStrings[1065]="从安其拉深处召唤出一群范克瑞斯的爪牙。"
D.SharedStrings[1066]="从山上来的结晶粉末充满着这个区域的地心。"
D.SharedStrings[1067]="从山迪·格罗斯那里取得“借来的战袍”。"
D.SharedStrings[1068]="从工匠斯尼格斯那里拿到控制台的钥匙。"
D.SharedStrings[1069]="从巫妖王之怒的竞技场第8季取得暴怒角斗士的冰霜巨龙。"
D.SharedStrings[1070]="从当前目标跳开。"
D.SharedStrings[1071]="从影月谷影月飞地的乌娜·黑尺身上取得乌娜的测量杖。"
D.SharedStrings[1072]="从征服者平台偷取7把灌注神力的利刃。"
D.SharedStrings[1073]="从德拉诺各地收集10份木料，然后在你要塞的伐木场里下达一份产品订单。"
D.SharedStrings[1074]="从怒火余烬或神圣能量裂隙中吸收能量。"
D.SharedStrings[1075]="从恐怖图腾长者身上收集4份恐怖图腾便笺，将它们组合成恐怖图腾作战计划。"
D.SharedStrings[1076]="从恐轨号上跳下。"
D.SharedStrings[1077]="从戈尔隆德永茂丛林的阿坎瑟斯身上取得被感染的兽人遗骸。"
D.SharedStrings[1078]="从托比准备好的讲稿中选出一篇来进行演讲。"
D.SharedStrings[1079]="从扭曲虚空中引导邪能时处于无敌状态。"
D.SharedStrings[1080]="从护锅领主身上找到的钥匙很容易地滑入锁孔并随即消失，而瘟疫之锅的控制板也一下子打开了，粘稠的腐液在瘟疫之锅里涌动沸腾。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为冰风岗的高阶牧师玛多妮尔带回一份样品。"
D.SharedStrings[1081]="从拉希奥背后发动的攻击会造成{1}%的额外伤害。"
D.SharedStrings[1082]="从敌人背后发动，对其造成普通武器伤害再加上{1}点额外伤害。"
D.SharedStrings[1083]="从敌人身上吸取{1}点生命值，并使施法者恢复最多相当于该数值两倍的生命值。"
D.SharedStrings[1084]="从敌人身上吸取{1}点生命值，并将其转移给施法者。"
D.SharedStrings[1085]="从敌人身上吸取生命值，并将其转移给施法者。"
D.SharedStrings[1086]="从敌人身边跳开。"
D.SharedStrings[1087]="从敌对阵营的主城中窃取烈焰，并完成“盗贼的奖励”任务。"
D.SharedStrings[1088]="从教头朗克身上找回兰特瑞索的长剑。"
D.SharedStrings[1089]="从断断续续的梦境中醒来。"
D.SharedStrings[1090]="从斯克提斯的风舞者奇洛克斯身上获得利奥拉的念珠。"
D.SharedStrings[1091]="从施法圣骑士的攻击中受到的神圣伤害提高{1}%。"
D.SharedStrings[1092]="从施法者位置召唤一组光线四射的水晶刺。一小段时间后，它们将从地面钻出，对其附近的所有敌人造成{1}点伤害，并将它们击飞。"
D.SharedStrings[1093]="从施法者脚下召唤一个蛮拳雕像，猛地将其弹射到空中。"
D.SharedStrings[1094]="从昆莱山的表叔大口袋那里购买一头雄壮远足牦牛。"
D.SharedStrings[1095]="从暗影中跃出，造成物理伤害。"
D.SharedStrings[1096]="从暮光闪电通道里收集一个充能的冷凝瓶。"
D.SharedStrings[1097]="从有记忆开始，这是我第一次感受到了安静。"
D.SharedStrings[1098]="从杀死第一个算起，在60秒内连续击杀所有敌方英雄（10人）。"
D.SharedStrings[1099]="从档案员麦卡顿那里拿到诺甘农之壳。"
D.SharedStrings[1100]="从森林中收集一块玛洛恩的灵魂碎片。"
D.SharedStrings[1101]="从死去的巨魔身上召唤一个骷髅。"
D.SharedStrings[1102]="从每株狐尾花植物上收集更多的材料。"
D.SharedStrings[1103]="从汽痕高地的浓烟之主咆吼身上取得凋零之蕾。"
D.SharedStrings[1104]="从没有人能进入纳克萨玛斯还活着讲他的故事。"
D.SharedStrings[1105]="从泰罗克的黑暗时代流传下来的法术焦镜。"
D.SharedStrings[1106]="从洛斯贝格村取回22条洛斯贝格黑鲈鱼。你可以在村后礁石群的鱼线上找到这种鱼。洛斯贝格村位于营地正北方，就在右边。"
D.SharedStrings[1107]="从涡流蒸汽中吸取能量。"
D.SharedStrings[1108]="从涡流蒸汽中吸取能量。冷……凝……"
D.SharedStrings[1109]="从潘达利亚大地的深处冒出根须，形成一道屏障。"
D.SharedStrings[1110]="从潘达利亚的钓鱼场所钓到25,000条鱼。"
D.SharedStrings[1111]="从激流堡的托尔贝恩墓室中取回托卡拉尔剑。"
D.SharedStrings[1112]="从濒死状态恢复过来……"
D.SharedStrings[1113]="从火车上跳下。"
D.SharedStrings[1114]="从盎迦猴岛的盎迦村民处获得30条恶臭烂鱼。"
D.SharedStrings[1115]="从目标的灵魂分裂出一部分，对目标玩家施放灵魂碎片。"
D.SharedStrings[1116]="从目标身上吸取{1}点生命值。"
D.SharedStrings[1117]="从目标身上吸取生命。"
D.SharedStrings[1118]="从石板上翻译过来的文献，详细记载了一场古代维库战争。"
D.SharedStrings[1119]="从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。"
D.SharedStrings[1120]="从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。"
D.SharedStrings[1121]="从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。"
D.SharedStrings[1122]="从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。"
D.SharedStrings[1123]="从祖尔格拉布的血领主曼多基尔那里获取拉扎什迅猛龙。"
D.SharedStrings[1124]="从祖尔格拉布的高阶祭司塞卡尔那里获取迅捷祖利安猛虎。"
D.SharedStrings[1125]="从祖玛维的布拉多克那里获得他的魔精。"
D.SharedStrings[1126]="从祖阿曼里面带出来的布片缝制而成的袋子。"
D.SharedStrings[1127]="从种子生长为花朵，小小的恐惧在滋长。"
D.SharedStrings[1128]="从移动的潭泥身上收集10份充满活力的淤泥样本。"
D.SharedStrings[1129]="从空中召唤一块燃烧的巨石，造成火焰伤害。"
D.SharedStrings[1130]="从空中召唤燃烧的巨石，造成{1}点火焰伤害。"
D.SharedStrings[1131]="从空中召唤燃烧的巨石，造成火焰伤害。"
D.SharedStrings[1132]="从符咒的木刻中散发出淡淡的气味。令你感到周身不适。"
D.SharedStrings[1133]="从纳克萨玛斯收集一套任意职业的套装。"
D.SharedStrings[1134]="从纳格兰破碎悬崖的宰相达古德身上取回托莫克心爱的佩剑。"
D.SharedStrings[1135]="从纳特西斯·冰刃那里取得勒斯平的胸针。"
D.SharedStrings[1136]="从纳迦探险者身上获得6捆海蛇草。"
D.SharedStrings[1137]="从背后攻击拉希奥可提高{1}%的伤害。"
D.SharedStrings[1138]="从艾泽拉斯的各个种族手中找回下列权杖。"
D.SharedStrings[1139]="从苏拉玛的瓦雷迪斯·邪魂手里取得欺诈者的双刃。"
D.SharedStrings[1140]="从荆棘谷海角南野人海岸获得6尊纳迦雕像。"
D.SharedStrings[1141]="从荆棘谷海角纳克迈尼圣泉里打上澄澈圣水。"
D.SharedStrings[1142]="从荆棘谷的尤亚姆巴岛的水晶之脊主母身上收集一个原生水晶碎片。"
D.SharedStrings[1143]="从莫什奥格食人魔山后的废墟里获得莫什奥格的馈赠。"
D.SharedStrings[1144]="从莫纳斯那里找到并取回勒斯平的“作品”。"
D.SharedStrings[1145]="从萨菲隆的爪中掉下了一枚眼球形状的珠宝，里面发出了魔法能量的震荡，你可以听到并感觉到这种声音。对凡人的耳朵来说，这块石头发出的声音甚至可以说是令人感到痛楚难当的。$B$B如此重要的物品显然只能交给红龙女王阿莱克丝塔萨，生命的缚誓者。前往龙骨荒野的龙眠神殿去请求她的指点吧。"
D.SharedStrings[1146]="从藏宝海湾坐船去棘齿城，然后跟加兹鲁维谈一谈。"
D.SharedStrings[1147]="从虚空灌注的土地中吸取力量，造成的伤害提高{1}%。"
D.SharedStrings[1148]="从血槌炉渣矿井拿一颗巨大的食人魔脑袋。"
D.SharedStrings[1149]="从血环之心的2个血环牢笼里救出奴隶。"
D.SharedStrings[1150]="从裁缝桌上拿取适当数量的材料，交给凿握据点的萨拉隆·巨钉。"
D.SharedStrings[1151]="从裂钳诱捕蟹那里收集6块多汁的蟹肉。"
D.SharedStrings[1152]="从要你命3000的各种武器中选一种出来，扔向目标。"
D.SharedStrings[1153]="从诅咒之地的灰鬃野猪身上收集5块灰鬃肉排。"
D.SharedStrings[1154]="从诅咒之地破碎海滩附近的盐腮手中夺取瑟温妮的护符。"
D.SharedStrings[1155]="从赞加沼泽的塞纳里奥远征队那里购买一头塞纳里奥作战角鹰兽。"
D.SharedStrings[1156]="从赫达沙尔的风暴之翼幼龙身上收集鳞片。"
D.SharedStrings[1157]="从达拉然下水道中钓起巨型下水道老鼠。"
D.SharedStrings[1158]="从达拉然的梅尔·弗兰希斯那里获得一头装甲棕熊。"
D.SharedStrings[1159]="从达拉然的梅尔·弗兰希斯那里获得一头长毛猛犸象。"
D.SharedStrings[1160]="从达拉然的梅尔·弗兰希斯那里购买一头旅行者的苔原猛犸象。"
D.SharedStrings[1161]="从这个记录着恐怖生物的典籍中召唤一个奥术恐魔。"
D.SharedStrings[1162]="从远处的墓穴召唤出一个幽魂，来为施法者而战。"
D.SharedStrings[1163]="从逐日岛上的任意使用魔法的生物身上收集6块奥术薄片，把它们交给奥术师伊塔纳斯。"
D.SharedStrings[1164]="从野蛮的基霍身上获得基霍的断裂之爪。"
D.SharedStrings[1165]="从钢铁码头获得一桶可怕的酸性溶液。"
D.SharedStrings[1166]="从钢铁部落成员的尸体上找到的，可在你要塞的战争工坊或矮人地堡中使用。"
D.SharedStrings[1167]="从阿博拉兹废墟赞吉尔的追随者手里获得赞吉尔的配方。"
D.SharedStrings[1168]="从阿古拉克之骨的雷神驯兽师身上收集5卷结实的绳索。"
D.SharedStrings[1169]="从附近的尸体身上拾取物品。"
D.SharedStrings[1170]="从附近的敌人身上吸取{1}点生命值，并使施法者恢复最多相当于该数值三倍的生命值。"
D.SharedStrings[1171]="从附近的敌人身上吸取魔法，使造成的伤害提高{1}%，附近敌人造成的伤害和治疗降低{2}点。"
D.SharedStrings[1172]="从霜火岭南风崖的领巢者伊里克斯身上取得碎冰甲壳。"
D.SharedStrings[1173]="从风暴要塞的凯尔萨斯·逐日者那里获取奥的灰烬。"
D.SharedStrings[1174]="从风险投资公司的某个监督或者执行者那里夺取猫眼翡翠。"
D.SharedStrings[1175]="从骆驼驭手多尔穆斯身上获得一匹灰色骑乘骆驼。"
D.SharedStrings[1176]="从高地四处召唤生命的神圣能量。死亡之翼一定会注意到如此明显的破坏行为……以及谁才是始作俑者。"
D.SharedStrings[1177]="从高处猛扑下来，对小范围内的敌人造成物理伤害。"
D.SharedStrings[1178]="从高处猛扑向你的敌人。"
D.SharedStrings[1179]="从高处猛扑向你的敌人，对其造成{1}点伤害。"
D.SharedStrings[1180]="从鬼灵工人的身上获得布莱恩·费恩的图纸。"
D.SharedStrings[1181]="从魔导师平台的凯尔萨斯·逐日者那里获取迅捷白色陆行鸟。"
D.SharedStrings[1182]="从黑暗森林的黑暗森林蛛母身上收集4个粘性丝囊。黑暗森林位于此地以西，穿过岛屿中心的桥梁就到。"
D.SharedStrings[1183]="从黑石深渊制造厂获得5个元素模组，并且拿回元素傀儡蓝图。"
D.SharedStrings[1184]="从黑石深渊找到6块元素束缚之石。你可以在暗炉城、住宅区、索瑞森神殿、东区兵营，以及西区兵营这些地方找到它们。"
D.SharedStrings[1185]="从黑石深渊的铁怒矮人身上缴获5把元素灌能武器，然后在暗炉城的黑铁砧上将它们敲断。"
D.SharedStrings[1186]="仔细地检查孢芽之后，你发现许多可能曾被用来容纳某种东西的凹痕。这枚怪异的蘑菇是一个谜团，它完全不健康，但是你找不到任何线索来了解它可能曾经派作什么用场。$B$B也许熟悉赞加沼泽生态的人应该可以告诉你更多有关这种孢芽的情况。"
D.SharedStrings[1187]="他们丝毫不感到羞愧吗？"
D.SharedStrings[1188]="他们为探油权可真是花了血本，可他们哪来那么多钱？"
D.SharedStrings[1189]="他们叫他兰特瑞索·火刃"
D.SharedStrings[1190]="他们可能会派艘舢板过来，多半会花点时间。我留在这里同他们接触。$B$B你要马上返回洞穴，让他们知道救兵来了。只能但愿纳迦还没有发现他们。$B$B去吧。快些游，$n。"
D.SharedStrings[1191]="他们干嘛非要派我来武装弓箭手呢？我是个吟游诗人，不是游侠！唉，抱怨是没有用的。$n，我需要一些制作箭头用的龙骨。$B$B你可以到冬拥湖西边的阴影森林去找。自从上次战斗过后，联盟就在那里搜集龙骨。杀了他们，夺走他们手中的龙骨。$B$B如果这招不管用，你或许可以从那里的幽灵身上得到一些。我听说他们喜欢用龙骨把猎物穿起来。"
D.SharedStrings[1192]="他们来了……"
D.SharedStrings[1193]="他们派来了刺客"
D.SharedStrings[1194]="他們現在知道暮色百合不好惹，做得很好。"
D.SharedStrings[1195]="他只告诉我的就是卷款离开此地。然后他就抛弃我了，难道不是吗？$B$B哦，$N，真是傻子才会爱上他，但我又能怎么办？他太迷人了！"
D.SharedStrings[1196]="他好像在种什么东西。看上去不太像是好的。"
D.SharedStrings[1197]="他實在太熱情、太奔放。我看到他的幻想，完全按照他的規格製作作品。美麗的鑲鈿和瓷釉共同構成令人生畏的成品…"
D.SharedStrings[1198]="他沒有受到傷害！我欠你和黎利斯一份大人情。"
D.SharedStrings[1199]="他的双眼紧锁着一个敌人，瞬即消失。5秒后再次出现，造成{2}点物理伤害，由目标周围的所有敌人分摊。"
D.SharedStrings[1200]="他知道你是不是乖孩子"
D.SharedStrings[1201]="他蛰伏在我的思想里。等待我崩溃的那一刻……要我屈服于他的意志。$B$B他的死期到了。我要呼唤他，告诉他我愿意俯首听令。你必须趁他现身之际杀掉这个家伙，拿到钥匙！$B$B祖鲁希德是位兽人长者，拥有深不可测的强大力量，他必定得到了伊利丹的力量。你是在用生命做赌注，你真的愿意做这样大的牺牲吗？"
D.SharedStrings[1202]="他锁定一个敌人，然后消失。5秒后再次出现，造成{2}点物理伤害，由目标周围的所有敌人分摊。"
D.SharedStrings[1203]="代理人亚希克斯的映像"
D.SharedStrings[1204]="代表你的阵营！"
D.SharedStrings[1205]="代表河鬃、天角和鲜血图腾的木偶围着太阳慢慢旋转着。"
D.SharedStrings[1206]="令人不安的绿光散发出恶毒诡谲的生命流。"
D.SharedStrings[1207]="令人印象深刻，骁士。我会尽快安排你的考验。"
D.SharedStrings[1208]="令迦顿男爵虚弱，让大德鲁伊能够打败他。"
D.SharedStrings[1209]="以一道闪电打击敌人，造成{1}点自然伤害。闪电会跳跃到附近的敌人身上，每次跳跃会再造成50%的自然伤害。"
D.SharedStrings[1210]="以下列方式击败入侵海加尔山的精英怪物。"
D.SharedStrings[1211]="以刺骨的寒风冲击目标，对周围半径10码范围内的所有敌人造成冰霜伤害。对被冻结的目标造成三倍伤害。"
D.SharedStrings[1212]="以博學者之名啊，我已經忘記那個東西有多醜了。工藝技術絕對無懈可擊，只是…呃。我應該把那個東西整個熔掉。"
D.SharedStrings[1213]="以地精小队成员的身份见证过往的事件。"
D.SharedStrings[1214]="以太焦镜会引导来自纳拉克煞引擎的能量。"
D.SharedStrings[1215]="以奥术魔法冲击敌人，将其击退并造成普通伤害外加{1}点伤害。"
D.SharedStrings[1216]="以少于21人的阵容击败玛里苟斯（25人）。"
D.SharedStrings[1217]="以少于21人的阵容击败纳克萨玛斯的塔迪乌斯（25人）。"
D.SharedStrings[1218]="以少于21人的阵容击败纳克萨玛斯的所有首领（25人）。"
D.SharedStrings[1219]="以少于21人的阵容击败黑岩守护者萨塔里奥和其它暮光幼龙（25人）。"
D.SharedStrings[1220]="以少于9人的阵容击败玛里苟斯（10人）。"
D.SharedStrings[1221]="以少于9人的阵容击败纳克萨玛斯的塔迪乌斯（10人）。"
D.SharedStrings[1222]="以少于9人的阵容击败纳克萨玛斯的所有首领（10人）。"
D.SharedStrings[1223]="以少于9人的阵容击败黑岩守护者萨塔里奥以及其它暮光幼龙（10人）。"
D.SharedStrings[1224]="以尖刺之拳将一个敌人举离地面，造成{1}点物理伤害。"
D.SharedStrings[1225]="以巨大的手臂发动横扫，产生一道冲击波，对其行进路上的所有敌人造成{1}点伤害。"
D.SharedStrings[1226]="以帕雷斯之眼诅咒敌人。"
D.SharedStrings[1227]="以强大的热能冲击附近的所有铁铸像，使它们的移动速度提高{1}，急速提高{2}。这个效果可以叠加最多10次。叠加到10次之后，铁铸像会熔化。"
D.SharedStrings[1228]="以极强的力量撼动大地，造成{1}点物理伤害，并将所有被击中的敌人击飞。"
D.SharedStrings[1229]="以火焰吞噬施法者的双手，使其进行近战攻击时造成额外的火焰伤害。"
D.SharedStrings[1230]="以目标的视角观察世界。"
D.SharedStrings[1231]="以神圣能量冲击目标，对一个敌人造成{1}点神圣伤害，或者为一个盟友目标恢复{2}点生命值。"
D.SharedStrings[1232]="以神圣能量冲击目标，对一个敌人造成神圣伤害。"
D.SharedStrings[1233]="以血写成的魔典。"
