D.SharedStrings[1282]="以邪能魔法轰击目标，造成火焰伤害。"
D.SharedStrings[1283]="以锯齿利刃攻击目标，对其造成物理伤害，并在随后8秒内造成额外伤害。"
D.SharedStrings[1284]="以闪电充能之拳猛击地面，在施法者面前形成一道律动的冲击波。"
D.SharedStrings[1285]="以闪电攻击敌人，造成自然伤害。"
D.SharedStrings[1286]="以闪电的力量攻击一个敌人，造成自然伤害。"
D.SharedStrings[1287]="以雷霆万钧之力近距离攻击敌人，将其击退稍许，并造成{1}点奥术伤害。"
D.SharedStrings[1288]="仲夏就要来了！$b$b每一年，按照传统，各大城市里都会选出护火者来照看我们城中的篝火。当火焰燃烧在艾泽拉斯世界的各处时，我们就可以通过这种世上最热诚也最明亮的事物向夏天这个季节表示敬意。$b$b事实上，若你不介意的话，我有个任务要交给你。我还不知道是否所有城市里的火焰都已经点起了。到各大城市去吧，让那里的火焰温暖你的身躯，当然，首先要确认它们已经被点燃了！"
D.SharedStrings[1289]="仲夏火焰节是敬拜元素的时刻。火焰元素会在我们所有人心中点燃激情。在许多时候，这种激情会喷发出来，演变成侵略性的行动。但在这个地方，我们将心中的激情变为虔诚的祭拜。$b$b我们会遵循传统，为火焰举行庆典。你愿意和我们一同敬拜火焰吗，$n？"
D.SharedStrings[1290]="任何美食，就算是我煮的，也都比不上勝利的滋味。"
D.SharedStrings[1291]="任务专员"
D.SharedStrings[1292]="任务：中毒的兔子"
D.SharedStrings[1293]="任务：寓言之兽\n"
D.SharedStrings[1294]="任务：德拉诺宠物博览"
D.SharedStrings[1295]="任务：熊猫人驭灵师\n地区：锦绣谷\n"
D.SharedStrings[1296]="任务：穆尔凯斯和沙德拉兹之门"
D.SharedStrings[1297]="仿佛现在的局势还不够疯狂一样，我们又要在两条战线上作战了！我们面前是天灾军团，而那些该死的部落却在偷袭我们的后方！$B$B我们在这里的任务是为我们的飞艇清理出一片安全的着陆点，但在那道城垒的另一侧，一个大家伙正在向所有靠近的东西投掷弹药。这让我们的小型船只根本无法着陆。$B$B说实话，它对于我们来说的确是有些太大了。但你和你的朋友们似乎能够对付它。"
D.SharedStrings[1298]="仿制的影踪派头盔"
D.SharedStrings[1299]="仿真机械霜鬃野猪"
D.SharedStrings[1300]="伊丝拉米·轻风"
D.SharedStrings[1301]="伊克提克屠杀者"
D.SharedStrings[1302]="伊克提克巨像"
D.SharedStrings[1303]="伊克提克恐虫"
D.SharedStrings[1304]="伊克提克战士"
D.SharedStrings[1305]="伊兰尼库斯的阴影"
D.SharedStrings[1306]="伊兰尼库斯精华"
D.SharedStrings[1307]="伊兰尼库斯，梦境之暴君"
D.SharedStrings[1308]="伊利丹·怒风"
D.SharedStrings[1309]="伊利丹从永恒之井中取出了七瓶水。他将其中三瓶倒入海加尔山颠的湖泊中，由此形成了第二口永恒之井。岁月流逝，剩下的四瓶水已不知去向。$B$B黑暗之门开启后，我们得知伊利丹将两瓶水交给了他的副官凯尔萨斯和瓦丝琪。取回残余的永恒之水，我们可以利用它打开通往近代或是远古时期的海加尔山的时光通道。我们必须维持海加尔圣战的事件不被改变。"
D.SharedStrings[1310]="伊利丹包裹在魔法火焰之中，对周围的敌人造成火焰伤害。"
D.SharedStrings[1311]="伊利丹在黑暗神殿溃败之后，我们把他的遗体带到了这里，想将他永远埋葬在守望者地窟之中。\n\n古尔丹突破了我们的防线，企图夺走背叛者的遗体。\n\n就算失去了生命，伊利丹的躯体还能被燃烧军团所利用。绝不能让古尔丹得逞。"
D.SharedStrings[1312]="伊利丹对敌人释放出坍缩之星的能量。"
D.SharedStrings[1313]="伊利丹的仆从"
D.SharedStrings[1314]="伊利丹追尋真相，眼前所見卻使他變得一意孤行。他開始認識到自己的命運，但他還必須做出最後一項犧牲。"
D.SharedStrings[1315]="伊利丹遭受到了一次野蛮的打击，正在恢复。"
D.SharedStrings[1316]="伊利达雷"
D.SharedStrings[1317]="伊利达雷之怒"
D.SharedStrings[1318]="伊利达雷后勤官"
D.SharedStrings[1319]="伊利达雷恶魔猎手"
