D.SharedStrings[1324]="伊利达雷斩除碎片"
D.SharedStrings[1325]="伊利达雷最近帮助了你。"
D.SharedStrings[1326]="伊利达雷狂热者"
D.SharedStrings[1327]="伊利达雷的灵魂棱镜"
D.SharedStrings[1328]="伊利达雷精锐"
D.SharedStrings[1329]="伊利达雷萨特"
