D.SharedStrings[1335]="伊利达雷飞行管理员"
D.SharedStrings[1336]="伊利达雷魔犬"
D.SharedStrings[1337]="伊利达雷魔蝠"
D.SharedStrings[1338]="伊利達瑞的靈魂稜石可以使用了。$B$B有人將伊利丹的靈魂從虛空之中抽離…或者是說竊取…然後帶往冥界了。在一個叫做黑爾海姆的地方。"
D.SharedStrings[1339]="伊墨瑞尔·影卫"
D.SharedStrings[1340]="伊墨瑞尔的伙伴"
D.SharedStrings[1341]="伊墨纳尔是扭曲虚空中有史以来最致命的赏金猎人。找个地方把他解决掉。"
D.SharedStrings[1342]="伊墨苏斯使被煞能腐蚀的水流从地面喷涌而出！"
D.SharedStrings[1343]="伊墨苏斯的净化之缚"
D.SharedStrings[1344]="伊墨苏斯的晶化之泪"
D.SharedStrings[1345]="伊崔格"
D.SharedStrings[1346]="伊崔格有几率出现并施放剑刃风暴，对附近的所有敌人造成大量伤害。"
D.SharedStrings[1347]="伊扎尔·白月"
D.SharedStrings[1348]="伊斯多弗的冰冷之心"
D.SharedStrings[1349]="伊曼蒂尔·锋歌"
D.SharedStrings[1350]="伊桑·那提斯"
D.SharedStrings[1351]="伊欧因·顿沃德"
D.SharedStrings[1352]="伊瑞尔"
D.SharedStrings[1353]="伊瑟拉"
D.SharedStrings[1354]="伊瑟拉开始将所有精力专注于对抗死亡之翼，使她无法使用自己的气息或是梦境帮助她的勇士们。"
D.SharedStrings[1355]="伊瑟拉开始将所有精力专注于死亡之翼，使她无法使用自己的气息或是梦境帮助她的勇士们。"
D.SharedStrings[1356]="伊瑟拉的影像"
D.SharedStrings[1357]="伊瑟拉，觉醒者"
D.SharedStrings[1358]="伊米亚之王战甲"
D.SharedStrings[1359]="伊米隆国王"
D.SharedStrings[1360]="伊约库克的世袭印戒"
D.SharedStrings[1361]="伊维·考伯斯宾"
D.SharedStrings[1362]="伊莉萨娜·拉文凯斯"
D.SharedStrings[1363]="伊莫塔尔之眼"
D.SharedStrings[1364]="伊萨里奥斯勋爵"
D.SharedStrings[1365]="伊鲁伦·图布雷勋爵"
D.SharedStrings[1366]="休眠的守卫之熊"
D.SharedStrings[1367]="优质竞技场装备"
D.SharedStrings[1368]="会员总是享有特权的。只要你成为“本月美酒”俱乐部的成员，就能在第一时间品尝到世间最棒的佳酿。$B$B将“本月美酒”俱乐部会员资料表交给铁炉堡石火旅店的拉尔金·雷酒吧。"
D.SharedStrings[1369]="会杀死你的攻击反而会为你恢复{1}%的最大生命值。"
D.SharedStrings[1370]="会杀死你的攻击反而会使其获得{1}%的最大生命值。"
D.SharedStrings[1371]="会追逐最近的玩家并且试图扑向他，令他受到寄生镣铐影响。一旦寄生镣铐再度被驱散，会重新生成一个寄生生物，其生命值与它用寄生镣铐影响目标时相同。"
D.SharedStrings[1372]="伟大事业的第二个盟友"
D.SharedStrings[1373]="伟大的天神正拯救你的灵魂。\r\n你将无法释放灵魂。"
D.SharedStrings[1374]="伟大的阿卡扎曼扎拉克"
D.SharedStrings[1375]="伟大的阿卡扎曼扎拉克有几率出现，对附近的所有敌人造成大量伤害。"
D.SharedStrings[1376]="传令官基尔图诺斯"
D.SharedStrings[1377]="传令官沃拉兹"
D.SharedStrings[1378]="传令官瓦兹德"
D.SharedStrings[1379]="传承大德鲁伊"
D.SharedStrings[1380]="传承正义军需官"
D.SharedStrings[1381]="传染的恐惧猎犬"
D.SharedStrings[1382]="传说中的伊格纳乌斯·托尔贝恩之剑。"
D.SharedStrings[1383]="传送你到达未知地区。"
D.SharedStrings[1384]="传送到一个目标的位置，并发动迅疾的打击，造成{1}%的武器伤害"
D.SharedStrings[1385]="传送到一个附近的地点，移除所有威胁值，在原地留下一个暗影幻象。"
D.SharedStrings[1386]="传送到登陆场：灾难。只能在军团要塞传送器中使用。"
