D.SharedStrings[1406]="传送门：奥格瑞玛"
D.SharedStrings[1407]="传送门：暴风城"
D.SharedStrings[1408]="传送门：纳斯雷萨"
D.SharedStrings[1409]="伤害与治疗提高{1}%。\r\n最大生命值提高{2}%。"
D.SharedStrings[1410]="伤害会打破虫茧，将困住猎物的丝网撕成碎片。"
D.SharedStrings[1411]="伤害和攻击速度提高{1}%。"
D.SharedStrings[1412]="伤害和治疗效果提高{1}%。\r\n不稳定爆炸会取消不稳定的太阳光束效果。"
D.SharedStrings[1413]="伤害和生命值上限提高{1}%。"
D.SharedStrings[1414]="伤害性法术或技能命中敌人后有一定几率恢复1%的最大生命值。"
D.SharedStrings[1415]="伤害提高[abs(abilityStateMod( STATE_Mod_DamageDealtPercent, 207 ))]%。"
D.SharedStrings[1416]="伤害提高[abs(abilityStateMod( STATE_Mod_DamageDealtPercent, 613 ))]%。"
D.SharedStrings[1417]="伤害提高{1}%"
D.SharedStrings[1418]="伤害提高{1}%\r\n急速提高{2}%\r\n\r\n免疫群体控制效果。"
D.SharedStrings[1419]="伤害提高{1}%。"
D.SharedStrings[1420]="伤害提高{1}%。\r\n单位生命值越高，造成的伤害越高。"
