D.SharedStrings[1440]="伦德尔·火舌"
D.SharedStrings[1441]="伪装成一个邪刃蜥蜴人。"
D.SharedStrings[1442]="伪装成一名夜之子。"
D.SharedStrings[1443]="伪装成一名布伦希尔达挑战者。"
D.SharedStrings[1444]="伪装成影月兽人的模样。\r\n沙兹古尔的影月兽人变为友好了。\r\n\r\n只能在影月谷的暮光林地或沙兹古尔使用。"
D.SharedStrings[1445]="伪装成滑刃纳迦，游泳速度提高{1}%，并能够在水下呼吸。"
D.SharedStrings[1446]="伪装成蝙蝠时不能施法。\r\n右键点击这个图标可以解除此效果。"
D.SharedStrings[1447]="伯德里克·格雷"
D.SharedStrings[1448]="伯拉克，欧鲁诺克之子"
D.SharedStrings[1449]="伯瓦尔·弗塔根公爵"
D.SharedStrings[1450]="伯里尔基抢劫者"
D.SharedStrings[1451]="伴随着赞达拉神灵的出现，这只生物被注入了神力，获得额外的生命值和护甲。"
D.SharedStrings[1452]="似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……"
D.SharedStrings[1453]="位于区域中时，偶尔会召唤奥丁之力，对目标释放闪电，造成大量伤害。[NYI]"
D.SharedStrings[1454]="位于堡垒下层时，移动速度提高{1}%。"
D.SharedStrings[1455]="位于苏拉玛城中时，你可以将自己伪装成一名夜之子。"
D.SharedStrings[1456]="位于蓝风海湾时获得水下呼吸能力，并且在海底的移动速度提高80%。"
D.SharedStrings[1457]="位移的奥术畸兽"
D.SharedStrings[1458]="位置擊殺獎勵"
D.SharedStrings[1459]="低于{1}点的伤害都被降低至1点。\r\n当有攻击能够穿透屏障时，此效果消失。"
D.SharedStrings[1460]="低能耗的特点使得这门中远程火炮在战场上极具实用价值。瞄准目标，然后让它发出怒吼吧！"
D.SharedStrings[1461]="佐伊德的熔岩手甲"
D.SharedStrings[1462]="佐克·托齐维克"
D.SharedStrings[1463]="佐奥拉克的闪电冲击击中地面上的所有敌人，造成{1}点自然伤害。"
D.SharedStrings[1464]="佐姆·波克"
D.SharedStrings[1465]="佐尔洛克将信息素吸入自己体内，强化自己的能量。"
D.SharedStrings[1466]="佐尔洛克提高声音赞美女皇，对所有能听到歌声的非螳螂妖目标造成伤害。"
D.SharedStrings[1467]="佐尔洛克提高声音赞美女皇，对所有能听到歌声的非螳螂妖目标造成伤害，直到其展开近身战斗为止。"
D.SharedStrings[1468]="佐德的机括长弓"
D.SharedStrings[1469]="佐治亚的纯心羽杖"
D.SharedStrings[1470]="体型变大并获得力量增强，生命值和造成的伤害提高30%。"
D.SharedStrings[1471]="体型增大{1}%。"
D.SharedStrings[1472]="余烬之墙束腰"
D.SharedStrings[1473]="作为一个道德沦丧的狡猾侏儒，米尔豪斯稍一生气就会把某人烧成灰。"
D.SharedStrings[1474]="作为一位勇敢而强大的元素萨满，可敬的卡尔戈经过无数艰苦的战斗才赢得了如今的称号。"
D.SharedStrings[1475]="作为一名新晋的武器锻造师，纳什拉无疑是一位强大的战士和武器大师。"
D.SharedStrings[1476]="作为一名杂草清理者实在是令人头晕目眩！"
D.SharedStrings[1477]="作为一名生存大师，游侠卡尔娅是一名擅长猎杀原兽的老道女猎手。"
D.SharedStrings[1478]="作为一名精英斥候，莱拉总是能在敌后来去自由，游刃有余。"
D.SharedStrings[1479]="作为一名自然的守护者，德鲁伊奇娅娜在野性方面的天赋无人能及。"
D.SharedStrings[1480]="作为成年仪式的一部分，每个霜狼兽人都要杀死一头霜鬃野猪并将他们的族谱尽可能完整地刻在野猪最大的獠牙上。家族历史和传统对霜狼氏族非常重要，所以每一季他们都会猎取最大的霜鬃野猪，以记载氏族的谱系。"
D.SharedStrings[1481]="作为烈日行者中资格最老的圣骑士，奥伯妮·亮鬃将她那些渴求知识的族人紧密地团结在自己的周围。圣光的真义究竟是什么？为什么它会将力量赐予我们？这些问题如火焰一般在奥伯妮心中燃烧，一切阻挡她追寻答案的人或事，都会被她毫不犹豫地扫除。"
D.SharedStrings[1482]="作为狂风与战争的大师，穆维里克是少数掌握了双头飞龙骑术的霜狼兽人。"
D.SharedStrings[1483]="作废的试验样本"
D.SharedStrings[1484]="作战大师"
D.SharedStrings[1485]="作战车辆的生命值和伤害根据装备水平获得提升。"
D.SharedStrings[1486]="作战雄鹰"
D.SharedStrings[1487]="作者不明，来历不明的作品。如果被燃烧军团发现，一定会被他们烧毁。"
D.SharedStrings[1488]="作茧缚命现在将对目标施放复苏之雾和氤氲之雾。"
D.SharedStrings[1489]="你……你不是他们的人？快！快把我放出来！$B$B我们必须马上逃往琥珀松木营地！一旦杜蒙特中尉发现这些家伙的真面目，就会夷平这个镇子！"
D.SharedStrings[1490]="你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。"
D.SharedStrings[1491]="你一直在证明你自己，$N。收下这个，并不是礼物，是对抗天灾的利器。"
D.SharedStrings[1492]="你一直对我们很有贡献，$N。"
D.SharedStrings[1493]="你下一次射击或杀戮命令不会消耗集中值。"
D.SharedStrings[1494]="你不展示肌肉是不会有糖果的，$N……"
D.SharedStrings[1495]="你不是僵尸……$b$b你在找一个巨魔？我确实看到过一个，就在战斗爆发之前……他警告了我们，督促我们提高警惕……但一切都太晚了。$b$b你的巨魔朋友已经赶往藏宝海湾去警告那里的人了……"
D.SharedStrings[1496]="你不能控制行动的方向，直到逃脱为止。"
D.SharedStrings[1497]="你不能用它做巨型蛋卷……"
D.SharedStrings[1498]="你不该来这里……"
D.SharedStrings[1499]="你不该看见我"
D.SharedStrings[1500]="你不该碰它的。但你已经碰过了，他很快就会来找你。$B$B他一定会找到你，除非你能躲藏起来，不让他发现。$B$B如果你还想活下去，就去弄一些无面者的鲜血回来！"
D.SharedStrings[1501]="你与时光同在，$N。你与我们同在。$B$B瞧!即使属于永恒之井中微小的遗迹都能释放出超越凡人所能理解的力量。$B$B收下这个礼物，这样大家才知道你是流沙之鳞的盟友……这样大家才知道你是时间本身的盟友!"
D.SharedStrings[1502]="你与梦魇合而为一，所有思想都被吞噬。"
D.SharedStrings[1503]="你中途离开了你的团队，必须过一段时间才能再次使用地下城或者团队查找器。"
D.SharedStrings[1504]="你为部落带来了莫大的荣耀，$N。你今日的胜利将可确保明日无数的胜利!"
D.SharedStrings[1505]="你为黑暗女王作出了卓越的贡献，$C。我给你的任务可不是一件鸡毛蒜皮的小事。$B$B我们将永远铭记你对被遗忘者的绝对忠诚和你在战斗中表现出来的坚毅不拔。"
D.SharedStrings[1506]="你之前告诉我关于纳迦的事情一直萦绕在我的脑海里。他们召唤的盟友到底是谁？他们真的认为自己可以击败猎潮者吗？$B$B逃出洞穴让人松了一口气，但我们在这里还有未竟的事情。我希望你能最后一次从女武士那里寻得答案。$B$B我想他们只可能把神器带到一个地方去——废墟顶部的神殿。显然那里会有重兵把守。小心行事。"
D.SharedStrings[1507]="你乘着一朵冥想之云在空中快速飞行。"
D.SharedStrings[1508]="你也许认为我在马绍尔探险队里当挖掘工是因为我喜欢这活儿，好吧，世上可能的确有比这更糟糕的差事……但是我还真没见过。$B$B我们本应是在恐惧小道那个鬼地方进行剑龙和双帆龙化石的挖掘工作——顺便提一句，那地名可真古怪。呃，那儿也有许多活着的恐龙！威利和霍莱坚持要研究这些东西，所以我们还是得弄些恐龙骨头来。咱们私下里说说，其实你只要从活着的恐龙身上给我取些骨头回来就行了。"
D.SharedStrings[1509]="你今天做的很好。随着士兵们释放和熔炉入口的打开，不用多久我就可以协助大家一起通过天灾领主泰兰努斯和这个肮脏的矿坑了。"
D.SharedStrings[1510]="你今天已证明了自己的能力，$N。$B$B我没有什么东西可给你，我只有这个王冠;是个适合胜利者的礼物。愿它照亮你的路。$B"
D.SharedStrings[1511]="你从前线带来了什么消息，$N?"
D.SharedStrings[1512]="你从无头骑士的南瓜灯笼中找到的?这是个古老的圣光徽记。在他受到诅咒变成今天这样的怪物之前，这一定曾属于无头骑士。感谢你，$N。这个徽记应该属于圣骑士。我会确保他们收到这个。$B$B喔，我差点忘了!你有个秘密的仰慕者……$g她:他;太害羞，不敢把这个亲自交给你。"
D.SharedStrings[1513]="你从皇冠药剂公司的许多优质假日产品中选择一种作为试用。免责声明：不保证整个试用期内完全满意。"
D.SharedStrings[1514]="你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。"
D.SharedStrings[1515]="你代表你的公会而战。公会声望提升速度提高{1}%。"
D.SharedStrings[1516]="你以你的行动荣耀我们，$N。看我将蕴含在你的徽记里的力量解放出来!"
D.SharedStrings[1517]="你们到底喂雪人吃什么？"
D.SharedStrings[1518]="你们在奥特莱克山脉大举交战对辛迪加来说没什么意义，$c。我们会按照惯例来做，等待时机，直到看见你们分出胜负，然后趁势发起攻击。$B$B但是，那并不是我们现在留在这里的原因。我的全视之眼不见了，它被这里的冰斧巨魔给拿走了。$B$B找到全视之眼，然后我们就会为你效力——直到分出胜负。$B$B当你拿到全视之眼后就回到我这里来，然后我就可以好好看看你了。$B$B<指挥官雷尔松咧嘴笑着。>"
D.SharedStrings[1519]="你会周期性变成一个强大的霜火食人魔，使你对疾病效果的抗性提高{1}%。"
D.SharedStrings[1520]="你会感到一点刺痛，$N。那种感觉就表示它发挥作用了。完成之后，你就能踏上病木林里的符文传送门进入纳克萨玛斯。"
D.SharedStrings[1521]="你会跳舞吧?先伸你的右脚…再缩你的右脚…伸你的右脚…扭扭身子…"
D.SharedStrings[1522]="你伪装成库卡隆士兵。"
D.SharedStrings[1523]="你伪装成影月兽人。\r\n\r\n附近的影月幽灵狼会识破你的伪装。"
D.SharedStrings[1524]="你佩带了更多我们敌人的徽记了吗，$C?燃烧军团仍是一个威胁，我们将继续在任何我们找到他们的地方追捕他们。"
D.SharedStrings[1525]="你做了什么?愚蠢!$B$B你必须纠正你犯下的错。毕竟，这是你的责任。从这里挑一顶盔帽去吧。每一顶盔帽都灌注了你帮我取得的永燃灰烬。更重要的是，他们会赋予你看见影月谷鬼魂的能力，包含泰朗.血魔。$B$B当你找到泰朗.血魔的时候，杀死他。"
D.SharedStrings[1526]="你做了正確的決定。\r\n\r\n希望你的本事就和名氣一樣響亮。"
D.SharedStrings[1527]="你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。"
D.SharedStrings[1528]="你做得很好，$C。$B$B信差已经回报了一些非常有价值的资讯。"
D.SharedStrings[1529]="你做的很好，$C。这是把杰作之剑……它的平衡非常完美。$B$B拿着你的武器，$N。带着无比的自信使用它并消灭我们的敌人吧!"
D.SharedStrings[1530]="你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信你可以帮助我们击败万恶的其拉虫人。"
D.SharedStrings[1531]="你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。"
D.SharedStrings[1532]="你停止了呼吸……"
D.SharedStrings[1533]="你偶尔能在潘达利亚的怪物身上找到额外的宝物。这种效果在死亡后仍可继续存在。"
D.SharedStrings[1534]="你像旋风一般挥舞手中的武器，攻击近战范围内的所有敌人，对每个敌人造成{1}%的武器伤害。"
D.SharedStrings[1535]="你决定违背先前的选择?我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$B$B它索费不低。当然，我需要你把旧的戒指交回来。"
D.SharedStrings[1536]="你准备好射击目标了！"
D.SharedStrings[1537]="你准备好要交换了吗?"
D.SharedStrings[1538]="你准备好要交易了吗?"
D.SharedStrings[1539]="你准备好要证明你身为骁士的技巧?"
D.SharedStrings[1540]="你几乎在发着光芒，$r。你带了什么来?"
D.SharedStrings[1541]="你凯旋归来了吗?"
D.SharedStrings[1542]="你击败了诅咒神教的突袭队吗?"
D.SharedStrings[1543]="你刚刚穿越过的传送门还在微微闪着光芒。"
D.SharedStrings[1544]="你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有熏木牧场免于疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!"
D.SharedStrings[1545]="你办到了!我不知道你怎么做到的，但你居然成功了!"
D.SharedStrings[1546]="你协助沃金彻底击败了扎拉赞恩，为暗矛巨魔光复了回音群岛。"
D.SharedStrings[1547]="你協助的受訓員一直在讚美你的戰鬥技巧。他們已經開始把自身所學教給其他人了。\r\n\r\n我很感激你在這方面的幫忙。"
D.SharedStrings[1548]="你去过北面的灰谷没有？部落最近在那里的佐拉姆海岸旁设立了哨所，我们经常派一些刚刚招募的新兵来协助防守前线。$B$B如果你愿意的话，就到贫瘠之地北部的哨塔里找卡德拉克。他正要去灰谷进行战斗，应该可以给你进一步的指示。"
D.SharedStrings[1549]="你去过恶魔监狱了吗，$n？每次我们差不多把那些牢房里的恶魔清理干净的时候，他们都会很快卷土重来。我们发现他们是从散布在该地区的被诅咒的镣铐中钻出来的。这就是我要交给你的任务了，$n。$B$B我要你去尽可能收集那些镣铐，把它们带回来交给我。我们会立即摧毁这些东西。"
D.SharedStrings[1550]="你去过水晶塔了吗，$N?"
D.SharedStrings[1551]="你去过维尔松船坞吗，$n？除非你有充分的理由，否则别轻易涉足。不幸的是，我正需要你去那里跑一趟。$b$b自从我们夺回岛屿以来，供给就一直处于短缺状态。那座满是鬼魂的船坞储有很多木料，我们曾经派了好些人去收集木料，但是他们都没能回来。$b$b你能帮帮我们吗？"
D.SharedStrings[1552]="你又一次完美地完成了我交给你的任务。也许有一天，我会要向你学些什么东西，不是吗，$N?$B$B这是给你的护腿图样，另外我还要对你表示感谢。学会这个图样，让你高超的技艺体现在你制作出的装备中吧!"
D.SharedStrings[1553]="你发现了什么?"
D.SharedStrings[1554]="你发现了什么，$N?"
D.SharedStrings[1555]="你发现的碎片看来源自纳迦。我一直希望能找到像这样一件具有强大聚焦能力的物体，好将我一直钻研的法术释放出来，以便窥视不远的过去。$B$B我已经将这片利刃附魔，但你还是要把它带到其主人曾经所在之地。我想让你回到发现它的地方，使用这片利刃。$B$B也许我们能明白纳迦究竟在这里干什么，或许运气好的话，还能找到他们的弱点，给我们一线生机。"
D.SharedStrings[1556]="你取回了塔隆·血魔的所有物件，离谜底仅剩一步之遥：寄主。$B$B<上古影月之魂邪恶地咧嘴一笑。>$B$B你显然不相信我之前告诉你的故事。暗影祭坛便是我的牢狱。没有你的帮助，我大概会永世被禁锢在这座祭坛中。现在，我要寄宿在你体内。杀死上古看守者卡修斯，让我摆脱束缚。如果你拒绝的话，那咱俩就永远留在这儿好了。$B$B塔隆·血魔就要重获自由了！"
D.SharedStrings[1557]="你取回的碎片只能拼凑出半块卡拉波勋章。另一半必定在灰舌破碎者的首领阿卡玛手中。$B$B派你去执行这项任务令我心中隐隐有些不安，因为阿卡玛是个邪恶而狡诈的家伙。$B$B据说，他甚至还和氏族中那些最卑劣残忍的成员——灰舌死誓者一起在守望者牢笼中设立了刑讯室。$B$B现在，我要你立刻前往刑讯室寻找阿卡玛的下落。如果有必要的话，你可以将他的副官萨诺鲁抓来审问。"
D.SharedStrings[1558]="你受到卡拉的祝福。有一定几率使你的爆击几率提高至最大值，持续20秒。"
D.SharedStrings[1559]="你受到的伤害中{1}%会被转移至附近的一只刺背野猪身上。"
D.SharedStrings[1560]="你受到的伤害降低了[abs(abilityStateMod(24,391))]%。"
D.SharedStrings[1561]="你受到的圣光的强化，倒下后仍然可以继续战斗。免疫一切群体控制技能。"
D.SharedStrings[1562]="你变成了一个雪人！"
D.SharedStrings[1563]="你口鼻上叛徒的血腥味让我很舒爽，兄弟之间是不应该彼此攻击的。"
D.SharedStrings[1564]="你只能看清上面有一个古老的艾瑞达符文。"
D.SharedStrings[1565]="你召唤一道猛烈的台风，对它接触到的敌对目标造成{1}点自然伤害，并将其击退5码。"
D.SharedStrings[1566]="你可以告诉你的朋友，能拯救她是我们的荣幸，也是我们的职责。$B$B她所遭遇的情况就我来看，是巨大谜团的一小部分。$B$B达拉然在尽一切的努力来解开这个谜团，但老实说，我们需要更多的协助……"
D.SharedStrings[1567]="你可以回到职业大厅查看侦察地图，选择进入各个区域完成突袭点任务。"
D.SharedStrings[1568]="你可以在图书馆的楼梯下方找到一只古老的箱子，从中拿取你所需的东西吧。"
D.SharedStrings[1569]="你可以在水上行走。"
D.SharedStrings[1570]="你可以在水上行走。任何伤害都会取消这个效果。"
D.SharedStrings[1571]="你可以在水面上行走。"
D.SharedStrings[1572]="你可以选择与一名随机的搏击俱乐部首领作战。"
D.SharedStrings[1573]="你可能已经在马车这边见过我的马驹贝贝了。她拉的马车把一些动物运送到珍奇馆里。$B$B她干活可卖力了，你可能不会相信她的蹄铁损耗得多么快。现在是时候给她换双新鞋了。我已经把所有的原材料购齐了。$B$B你需要做的就是把它们在铁砧上定型，然后安在贝贝的蹄子上。这事不会用掉你太多时间，还能换取一些奖券，何乐而不为呢？"
D.SharedStrings[1574]="你可能觉得自己已经很强大了，足以横扫这些亡灵，驾驶你的战争机器轻易地击败它们。$B$B但是创造出这些亡灵生物的力量更为强大，与之相比，你的力量不值一提。$B$B我见过那位王子本人这样做过。我可以营造一个幻境，向你演示他是怎么做到这一点的……如果你愿意领略一下的话。"
D.SharedStrings[1575]="你吃一口，我吃一口……"
D.SharedStrings[1576]="你向地狱的深渊望去，看到了极端恐怖的景象。被恐惧。"
D.SharedStrings[1577]="你向我们证明了你的实力，$N。作为奖励，请收下这只背包!你可以在里面发现一些补给品和绷带，这些东西只有在战歌峡谷中才能使用。$B$B当你在战歌峡谷的战场上不断证明自己的价值之后，就能找到更多可以购买的东西。当你在我们这里的声望达到友好的程度之后，你就能购买这些补给品，而当你的声望达到尊敬的程度之后，就可以购买绷带。"
D.SharedStrings[1578]="你向我们证明了自己的实力，$N。作为奖励，请收下这个包裹!里面装满了仅可在阿拉希盆地使用的补给物品和绷带。$B$B随着你在阿拉希盆地取得的进展，你会发现你可以购买这些物品。当你在我们当中的声望达到尊敬时，你即可购买补给物品;达到崇敬时即可购买绷带。"
D.SharedStrings[1579]="你向目标抛掷熔岩，造成{1}点火焰伤害。"
D.SharedStrings[1580]="你向目标抛掷熔岩，造成{1}点火焰伤害。如果目标身上有你的烈焰震击效果，熔岩喷溅会造成爆击。"
D.SharedStrings[1581]="你听到了远处传来的声音……"
D.SharedStrings[1582]="你听到墓穴中央的房间中传来一阵隆隆声。那两尊大雕像看样子确实很可疑。"
D.SharedStrings[1583]="你听到消息了吗，旅行者？有人对我们最为神圣的锦绣谷发起了攻击！$b$b即使是现在，一位人类王子仍在白虎寺中争论着你们和其他来自迷雾另一端的种族是否应该获准进入。$b$b那个寺庙就在昆莱的东北方。也许你能说服白虎放你进去？$b$b我只希望山谷还没有被彻底摧毁……"
D.SharedStrings[1584]="你吸引了古代魔网的力量，使魔网裂痕在战斗中出现。\r\n\r\n你站在魔网裂痕中会获得远古魔力。\r\n\r\n在魔网裂痕中的敌人会周期性受到伤害。\r\n\r\n只能在苏拉玛生效。"
D.SharedStrings[1585]="你周围曾经发生过一场激烈的战斗。纳迦骷髅不稀奇，但这些武器和他们对手留下的痕迹却出人意料。$B$B在骸骨中间，你发现一块奇怪得惹眼的金属从其中一个颅骨中扎出来。很难说它曾经是什么武器上的，不过它是如此地惹人注意，你无法不把它作为证据带走。$B$B洞里肯定会有人对这一发现感兴趣的。"
D.SharedStrings[1586]="你周围的空气正在因为声波的能量而震荡……"
D.SharedStrings[1587]="你和你的宠物共享群体控制递减效果。"
D.SharedStrings[1588]="你和你的宠物获得5%伤害、治疗和吸收。"
D.SharedStrings[1589]="你和你的宠物获得{1}%伤害、治疗和吸收。"
D.SharedStrings[1590]="你和你的寄生客体进化了！"
D.SharedStrings[1591]="你和玛尔拉德正在护送工人。跟紧了！"
D.SharedStrings[1592]="你和生锈的猎鱼枪扳机绑在了一起，可以随意开火！"
D.SharedStrings[1593]="你和白骨之廷的十字军并肩作战了吗?"
D.SharedStrings[1594]="你回来了!你带来了胜利的消息吗?"
D.SharedStrings[1595]="你回来了。想要跟我谈谈吗?"
D.SharedStrings[1596]="你回来了！还想跟我打一场吗？"
D.SharedStrings[1597]="你回来了，$N。"
D.SharedStrings[1598]="你回来了，$N。你一定要告诉我你发现的所有事情。但是首先让我们先来看看你的奖励。"
D.SharedStrings[1599]="你回来了，做的好。如你所见，我们在这里忙到无暇分身。"
D.SharedStrings[1600]="你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。"
D.SharedStrings[1601]="你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?"
D.SharedStrings[1602]="你回来得真快啊，在离开的这段时间中，你做了怎样的祷告?$B$B你有没有完成什么高尚的事业?也许你已经了解了慈善的真正价值，或者更多你对艾泽拉斯居民的责任。告诉我，你都帮了谁，怎么帮的……你的所做所为令人印象深刻，$N，你的行为毫无疑问证明你在坚定不移地追随圣光的指引。$B$B这样的牺牲一定会得到及时的奖赏。"
D.SharedStrings[1603]="你在占领这座岛的过程中表现得很出色，$c。现在，我们既然已经占领了岛屿，就要用这些牢房关押囚犯。恶魔监狱是个特别难以清理的地方，不幸的是，这里到处都是形形色色的恶魔。$B$B我们成功地削减了恶魔的数量，但是有一只巨大的熔火犬冲出了牢笼，正在那里大肆破坏。我要你去干掉它，把它的颈环拿回来。"
D.SharedStrings[1604]="你在圣坛找到了内在平静吗?你的骚动消除了吗?"
D.SharedStrings[1605]="你在完整的迁跃时空中撕开一个缺口。\r\n\r\n哎哟。"
D.SharedStrings[1606]="你在布瑞尔周围努力寻找狼人的足印。"
D.SharedStrings[1607]="你在战场上的英勇已经向十字军证明了一件众所皆知的事 -- 我们的战士绝不仅只是节庆游行的装饰品而已。"
D.SharedStrings[1608]="你在敌后可以获得额外{1}%的神器碎片。"
D.SharedStrings[1609]="你在暮光之中！"
D.SharedStrings[1610]="你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……"
D.SharedStrings[1611]="你在燃烧！"
D.SharedStrings[1612]="你在猎豹形态下所进行的近战攻击有一定几率为你恢复{1}点能量值。"
D.SharedStrings[1613]="你在箱子中找到了一件圆形的小设备，放在一张垫子上。$b$b如果说这座墓穴中确实有泰坦圣物，那肯定就是它无疑了。你决定将它带回去交给布拉姆博士。"
D.SharedStrings[1614]="你在船上！我们来开派对吧！"
D.SharedStrings[1615]="你在这儿。希望这样行得通吧。我们全都靠它了。"
D.SharedStrings[1616]="你在这山谷中的针对火刃氏族的试炼……如今就算是完成了。但我希望你能去向其他人报告一下你的发现。$B$B到森金村去找加德林大师吧。先从山谷的东侧出去，在岔路口转向右一直走到底就能抵达森金村了。$B$B我们必须把火刃氏族的势力出现在试炼谷的事告诉加德林大师。$B$B去吧，$n，动作要快。恐怕我们在火刃集会所中找到的东西只是更可怕的威胁的预兆而已……"
D.SharedStrings[1617]="你在这里帮了我们很多忙，但是时候让你回去塔莉萨身边了。\n\n附近有个传送板，近年来一直无人使用。你试试能否重新定向，用它回到塔莉萨身边。\n\n哦，你出发之前：\n\n<凡瑟尔交给你一瓶包装好的魔力酒。>\n\n请把这个交给她，感谢她送你来帮忙。请告诉她，你帮助我们补满了魔力酒的存货，还令一位母亲得以和她的孩子团聚。\n\n我们的感激之情难以言表。让我们暂且告别吧。"
D.SharedStrings[1618]="你在重新体验最近发生的事情。"
D.SharedStrings[1619]="你在阿什兰的每个转角处都会遇到危险。但别担心，$n，我已经想出了完美的解决办法。就是这瓶我自制的大受欢迎的隐形药水。$B$B现在所有材料都齐了，只少洞穴蘑菇。$B$B幸好在阿什兰当地就有一种。"
D.SharedStrings[1620]="你填妥会员表格了吗?"
D.SharedStrings[1621]="你夺得了虚空风暴军旗。\r\n将这面旗帜带到任何一个本方控制的据点以获得胜利点数。"
D.SharedStrings[1622]="你好。你来学习操控火焰的新技巧吗?"
D.SharedStrings[1623]="你好你好，$N。船长大人跟我说你要去找奈古拉什的晦气，呵呵，是真的吗?"
D.SharedStrings[1624]="你好啊!如果你是来跟我说导航机器人坠毁在你家房顶上之类的事情，那么请去找我的律师。如果不是，请问找我有什么事?"
D.SharedStrings[1625]="你好啊，$N!你找到高拉什了吗?那箱子是我最喜欢的，里面有个小夹层，我最值钱的宝贝都藏在里面!"
D.SharedStrings[1626]="你好，$C……我一眼就看出你和我一样是制皮师。你是来向我学手艺的吗?又或者是你想和我做生意?"
D.SharedStrings[1627]="你好，$C。$B$B我很高兴看到像你这样的勇士对大自然保持着兴趣。我已经听说过你的事迹了，欢迎你。看见你站在这里，我相信塞纳里奥议会已经得到了我们所需的帮助。$B$B我们与月光林地的塞纳里奥议会之间的联系已经超越了种族和政治的界限。请记住，你是在为议会效力，你会干得很出色的。"
D.SharedStrings[1628]="你好，$C。很高兴你愿意帮助我们进行研究。你要做的事情很多，如果是我告诉你这工作并不危险，也许会伤害到你的感情。希望你不会因此受惊……但是，从你的表情看来，你已经经历过不少危险了。"
D.SharedStrings[1629]="你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。"
D.SharedStrings[1630]="你好，$N。你是否磨练了你的救火技巧了呢?别忘了演练区就在南边!"
D.SharedStrings[1631]="你好，$N，你有没有发现什么被冲到海岸上的尸体?"
D.SharedStrings[1632]="你好，$c。$B$B最近我们一直在对伊米海姆发动猛攻，但是这些维库人比我们之前遇到过的要凶残得多。每次部队试图向伊米海姆推进时都会遭到伏击，我们的人员损失非常惨重。$B$B如果你愿意参战，帮助我的小分队安全抵达伊米海姆的大门，我们会好好奖励你的。抵达大门之后，我们就会挖掘壕沟，等待后援部队。"
D.SharedStrings[1633]="你好，$c。我这里有一些你可能会很感兴趣的东西。$B$B它跟你们这个职业的人平常穿着的那些护甲有点类似，但质量上远远好于你们现在所拥有的。要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通的套装组件。$B$B栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我目前很需要的特性。给我带来一批样本，再把普通套装的手腕部分拿来，当然了，你还得支付一些金币。你会发现这其实是笔很划算的交易。"
D.SharedStrings[1634]="你好，$n。$B$B你截获了古尔丹给斯科瓦尔德的信息了吗？"
D.SharedStrings[1635]="你好，$n。我们肯瑞托议会已经将达拉然城邦整体移动到了诺森德，你或许已经知道了，不知道也没有关系。$B$B总之，现在达拉然不再坐落于洛丹米尔湖南岸的保护罩内，而是使用魔法能源飘浮在晶歌森林上空。$B$B我们相信你已经具备拜访这座城市的资格了。做好准备之后就告诉我，我将施展魔法，直接把你传送过去。$B$B等你到了那边以后，去找大法师塞琳德拉，并将这枚戒指作为我们会面的证明交给她。"
D.SharedStrings[1636]="你好，$r。$B$B你该不是碰巧有空可以进行一个有点重要的修复任务吧?"
D.SharedStrings[1637]="你好，尊贵的$C。我是科尔丹，魔法和某些“神秘艺术”的学徒。$B$B那帮懦弱的商人让你到这里来和我接触，想要与我进行更加微妙的接触，但这并不意味着你就不能再帮助我们了。$B$B请不要紧张，我会告诉你为什么大酋长那么需要我的帮助……还有你的。$B$B首先这是一个形象问题，$N。部落是怎样看自己的，我们的盟友是怎样看我们的，以及最重要的，我们的敌人是怎样看我们的。"
D.SharedStrings[1638]="你好，年轻的德鲁伊。现在是让你了解我们的水栖形态的时候了。这种形态能让你在水中活动自如，你将发现它是一种非常实用的形态，是神对我们的恩赐……但你必须要通过自己的努力去获得它。$B$B你将面对两个考验。首先要测试你在水中压力下的作业能力，并掌握它。$B$B做好准备吧，试炼就要开始了。"
D.SharedStrings[1639]="你好，年轻的德鲁伊，很高兴见到你来学习解毒知识。$B$B大多数的德鲁伊都是通过事先准备好的试炼来完成学习的，而你则会有些不同。在贫瘠之地的十字路口出现了许多起动物中毒事件，那里的居民已经没法控制局面了。最终，他们派了一个代表来我这里，要求月光林地为他们提供帮助，我们准备派你去。这不是练习―你要做的是拯救许多生命的严肃工作。你要牢记这一点。"
D.SharedStrings[1640]="你好，年轻的猎人。看起来你已经准备好要驯服一头野兽，并将其训练成自己的同伴了。$B$B你必须去见一见多兰纳尔的达扎拉，他可以帮助你驯服自己的第一头宠物。"
D.SharedStrings[1641]="你好，我们又见面了，$N。你对圣洁之书的研究进展如何?$B$B那么你应该准备好接受考验了。我们的城市和国家到处都有等着我们去完成的任务，给予他人同情和理解;援助需要帮助的人;击杀凶恶的生物。$B$B只要证明你可以秉持耐心去帮助别人―特别是那些不幸的人，你就能证明自己是圣光的侍从，正直心灵的表率。"
D.SharedStrings[1642]="你好，我很高兴你愿意听我说话。联盟需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，$n！$B$B你应该和负责此事的大元帅斯诺·落雪谈一谈。你觉得怎么样？你是否愿意帮助联盟做好战争的准备？"
D.SharedStrings[1643]="你好，我很高兴你愿意听我说话。部落需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，$n！$B$B你应该和负责此事的督军格尔库克谈一谈。你觉得怎么样？你是否愿意帮助部落做好战争的准备？"
D.SharedStrings[1644]="你好，暗影之刃。\n\n我没有等你就自己先开始了，希望你别生气。面对无脑亡灵时，我就控制不了自己。\n\n对，你没听错。泰利尔，就是那个在暗影大厅里站了好多个月的泰利尔，是一个恐惧魔王的亡灵走狗。\n\n像他那样的人还有很多——他们混迹在我们的主城里，隐藏在贵族中间，不断扩大自己的权力和影响力，而且几乎没法察觉。"
D.SharedStrings[1645]="你安抚了被杀的托利克村民的灵魂了吗?"
D.SharedStrings[1646]="你完成“不给糖就捣蛋”了吗?我很遗憾我生病了不能去，不过你的帮忙让我感觉好多了…"
D.SharedStrings[1647]="你完成了你的任务吗，$N?"
D.SharedStrings[1648]="你完成了我要你去做的任务吗，$N?"
D.SharedStrings[1649]="你完成了技击大赛的训练吗?"
D.SharedStrings[1650]="你完成任务了吗，$N?"
D.SharedStrings[1651]="你完成你的任务了吗，$N?"
D.SharedStrings[1652]="你完成必要的任务了吗，$N?"
D.SharedStrings[1653]="你对你的决定有把握吗，$N?这可不是你可以随便决定的事喔。$B$B紫罗兰徽记会随着力量而成长，只要你继续对紫罗兰之眼证明你自己。"
D.SharedStrings[1654]="你对冬天爷爷真是太好了，$N。祝你冬幕节快乐。$B$B这些小东西……就当作给你的奖励吧。"
D.SharedStrings[1655]="你对抗天灾军团的能力大幅度提升了！在旗帜附近守卫时的法力值和生命值恢复速度提高。"
D.SharedStrings[1656]="你对抗白骨之廷的敌人了吗?"
D.SharedStrings[1657]="你对暮光之眼的控制使伽格尔食人魔深信你是友好的。"
D.SharedStrings[1658]="你对银色黎明所做出的贡献将受到表彰，$n。你在我们的组织中有着很高的声誉，因此我授权你可以购买我们最宝贵的装备——我们的魔法抗性护肩。$B$B只要把它加在你现有的护肩上，你就可以抵抗五种魔法的力量。作为对我们的事业继续做出贡献的标志，我要求你拿至少10枚银色黎明勇气勋章来换取这些护肩。"
D.SharedStrings[1659]="你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。"
D.SharedStrings[1660]="你将三份塞纳里奥植物药膏涂在了这株鞭根草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。"
D.SharedStrings[1661]="你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。"
D.SharedStrings[1662]="你将四份塞纳里奥植物药膏涂在了这株夜龙草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。"
D.SharedStrings[1663]="你将学会如何打开一道通往阿彻鲁斯：黑锋要塞的传送门。"
D.SharedStrings[1664]="你将熔岩的能量灌注在副手武器中，立即对目标造成{1}%的副手武器伤害。如果你的副手武器附加了火舌效果，这个伤害值还可以提高{2}%。"
D.SharedStrings[1665]="你将自己伪装成一个被无悯者控制的奴仆。拉葛雷克身体中的敌对生物不会对你进行攻击。找到通往拉葛雷克脑室的路线。"
D.SharedStrings[1666]="你将荣耀带给了我们大家，$N。我们一定会让敌人知道无论我们在何处发现他们都将会战斗到底。"
D.SharedStrings[1667]="你将角鹰兽的蛋放入机器，随后里面传来了一些奇怪的机械声响和嘟嘟声。$B$B似乎测蛋器正在为这颗蛋称重、测量和包装。真是快捷又完善的服务!"
D.SharedStrings[1668]="你将赢得各种有趣的奖励，如宠物和时令服装！"
D.SharedStrings[1669]="你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到亡靈壁壘的暗影牧師范蒂絲那裡去了。"
D.SharedStrings[1670]="你尝试摆脱目标，向后方跳跃。必须面对目标。"
D.SharedStrings[1671]="你就是来自暴风城的新兵？我是治安官玛克布莱德，这支驻防部队的指挥官。欢迎你前来报到……$B$B<玛克布莱德翻阅着文件。>$B$B$n。你是$n吧？$B$B来得正是时候。黑石兽人从山脉断口处潜入了北郡。驻防部队的士兵们正在竭力奋战，一次次地击退敌人的进攻，但是我担心他们支持不了多久了。$B$B前往西北方的森林，杀死入侵的黑石座狼！帮帮我们吧！"
D.SharedStrings[1672]="你就是来自暴风城的新兵？我是治安官玛克布莱德，这支驻防部队的指挥官。欢迎你前来报到……$B$B<玛克布莱德翻阅着文件。>$B$B$n。你是$n吧？$B$B来得正是时候。黑石兽人从山脉断口处潜入了北郡。驻防部队的士兵们正在竭力奋战，一次次地击退敌人的进攻，但是我担心他们支持不了多久了。$B$B前往西北方的森林，杀死入侵的黑石战狼！帮帮我们吧！"
D.SharedStrings[1673]="你已拿到所有你需要的零件了…有些部位甚至還雙倍有餘。"
D.SharedStrings[1674]="你已经从暮光之锤的闪电攻击中吸收了足够的能量，并开始为你的风暴战锤充能。充能3次以后，你下一次投出风暴战锤将对一片区域造成大量伤害。"
D.SharedStrings[1675]="你已经完成我要求的工作了吗，$N?"
D.SharedStrings[1676]="你已经很久没有接受试炼了，$n。到目前为止，你已经证明了自己有足够的耐心，现在是时候让你学习更多东西，是时候让你了解毁灭…和混乱了。只要你明白自己即将为此付出的代价，火焰的元素就会与你建立连接。$B$B到贫瘠之地去找卡纳尔·菲斯，他就住在十字路口北部的一间小房子里。路上小心点，走太远的话，你就会进入精灵的领地。"
D.SharedStrings[1677]="你已经标记了一个目标。"
D.SharedStrings[1678]="你已经证明了你是拥有强大力量的人。纳鲁赞同你……"
D.SharedStrings[1679]="你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。"
D.SharedStrings[1680]="你已经证明了自己有资格获得更多的信任。$B$B现在立刻返回龙眠神殿去，再一次与塔里奥斯塔兹执事谈谈吧，亲爱的$n。"
D.SharedStrings[1681]="你已经证明你是虚空之翼的盟友。我的母亲已经被释放而我的兄弟姐妹们也都得救了!$B$B也许某一天，我们会再呼唤你前来。当那天来临的时候，你知道你会受到热烈的欢迎-一个虚空之翼龙军团的$g兄弟:姐妹;。"
D.SharedStrings[1682]="你已经达到了可以和兄弟会进行合作的层次了，$r。我们开始对你另眼相看。干得很不错!$B$B如果你希望能赢得我们更多的尊敬，那就听好了。$B$B我们可以通过在炽热助熔剂中添加黑铁残油的方式来进一步提炼它，到黑石深渊去收集黑铁残油吧。$B$B把你找到的所有黑铁残油都交给我!"
D.SharedStrings[1683]="你已经重铸了这把剑，并对它进行了锻造，但它仍然只是静静地躺在剑鞘里，丝毫没有显示出它应有的力量。你说这把剑在吸引你，就好象它拥有自己的意志？$B$B你敢把它带到它想去的地方吗？这把剑不应该如此沉默，但如果你不把它带去那个地方，也许我们将永远不知道这是为什么。把它带进冰冠堡垒的映像大厅。在那里一定要万分小心！我会在冰封大殿等你。"
D.SharedStrings[1684]="你已被发现！迅速着陆避免遭到击落！"
D.SharedStrings[1685]="你已达成交易，我也会保留我的。$B$B记住，我会保留最好的部份，就等你完成任务了。"
D.SharedStrings[1686]="你已非吴下阿蒙，我忠实的骑士。$B$B<大领主达瑞安.莫格莱尼盯着你。>$B$B复仇就要展开，$g兄弟:姐妹;。寇尔提拉以炮艇和奥格林之锤为部落助战，而萨沙理安则为联盟提供了破天号的帮助。黑锋骑士团就要横扫冰冠冰川，让巫妖王的军队在战场上永久地毁灭。"
D.SharedStrings[1687]="你带了我要的材料来吗，$N?"
D.SharedStrings[1688]="你带来了什么消息，$N?"
D.SharedStrings[1689]="你带来了最好的贡献，大自然会顺应你的要求。在我向你传授了部族制皮的技艺之后，你的作品将成为自然本身力量的体现。$B$B要学会部族制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。"
D.SharedStrings[1690]="你带着我要你收集的东西回来了吗，$C?"
D.SharedStrings[1691]="你帮了我一个大忙。我的剑将为你所用。$b$b我在此发下血誓：我将辅佐于你，用我的剑术和采矿技术为你的部队效劳。$b$B你愿意接受我的效忠吗？"
D.SharedStrings[1692]="你帮了我一个大忙。这柄利刃既是你的也是我的。$b$b我要为你送上这个血誓：我愿助你一臂之力，把我掌握的利刃和采矿方面的知识都贡献给你的军队。$b$B你愿意接受吗？"
D.SharedStrings[1693]="你帮我带来了披风的材料吗，$N?"
D.SharedStrings[1694]="你帮我把戒指和材料带来了吗，$N?"
D.SharedStrings[1695]="你帮我把试剂带来了吗，孩子?"
D.SharedStrings[1696]="你帶了什麼關於『吞噬者』恐翼的消息來？"
D.SharedStrings[1697]="你干得很不错，$c。我还可以再教你一些手段，但我不会再让你对着假人浪费时间了。$B$B现在我给你安排最后一项考验吧，伙计。到这个区域中间的试炼场去，跟一个真正的敌人交手——对方对你可是毫不留情的哟。等你准备好了，告诉那边的狱卒一声就行了。"
D.SharedStrings[1698]="你应该好学习有关德鲁伊的解毒能力的知识了，$n。塞纳留斯赐予了我们特殊的能力，让我们只需施展一个简单的法术就能净化世间最邪恶的剧毒。但是这份礼物可不是随便就可以送给你的……为了保证你能深刻地理解这门新的课程，你要像个刚刚入行的新手那样，逐一了解各种毒药的特点。$B$B到月光林地去跟德迪利特·星焰谈谈吧，他会在那里向你传授这些知识的。"
D.SharedStrings[1699]="你建造了一艘能够进攻塔纳安丛林的舰船。快去征服那片土地吧！"
D.SharedStrings[1700]="你弄到了一个专业技能建筑的图纸！快用建筑设计桌选一块小空地来建造它吧。"
D.SharedStrings[1701]="你弄到治疗水晶必要的飞蛾血清了吗?溪谷里到处都是生还者，时间紧迫!"
D.SharedStrings[1702]="你弄到龟鳞头盔和护腕了吗?另外不要忘记我还要两株野葡萄。$B$B现在，你已经开始意识到蛮皮护胫潜在的能量了。一件拥有无穷应用潜力的护甲对于一个皮革匠来说是无价的，唯一的瓶颈是制作这些护甲所需要的原料―而不是成品的品质!"
D.SharedStrings[1703]="你引起了暗夜游魂的注意。最好别让他发现太多次。"
D.SharedStrings[1704]="你当前阵营的3v3胜利"
D.SharedStrings[1705]="你往瓶子里装满了天灾之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。"
D.SharedStrings[1706]="你很善戰。\r\n\r\n我想應該是時候正式的向你自我介紹。"
D.SharedStrings[1707]="你很快就可以完成训练，参加总决赛了。为了证明你有资格拥有这种荣誉，你必须击败银色北伐军的一名冠军。$B$B到大帐外面的兽栏旁去，拿上一把长枪，跨上你的坐骑。然后到场地西侧的银色勇士赛场去找侍从丹尼。当你做好战斗的准备之后，他会为你召来对手。$B$B这场战斗结束之后，我们再好好谈谈。"
D.SharedStrings[1708]="你很想尝尝小动物的滋味，尽管周围一只都找不到。"
D.SharedStrings[1709]="你很有本事，我能理解瑞特辛為什麼喜歡派你辦事。"
D.SharedStrings[1710]="你得去杀掉赞吉尔。希里克的翅膀带你飞翔，希里克的双眼为你所及。去把他杀掉。$b$b哦，对了$r：要是我们走散了，你可以使用这尊神像。它只在荆棘谷有效，不过却可以迅速把你传送到我这里来。$b$b祝你好运，$r。赞吉尔可不是一般的对手。"
D.SharedStrings[1711]="你從不讓人失望，$n。\r\n\r\n這個早已遭到遺忘的靈魂，現在可以更有貢獻。"
D.SharedStrings[1712]="你必须使用显灵镜才能看见影月谷的灵魂。"
D.SharedStrings[1713]="你必须在野外活过一个晚上，才能赢得雷克萨的尊敬。"
D.SharedStrings[1714]="你必须明白，$N―只有摧毁『召唤者』阿拉基的肉身才能拿到完成钥匙所必需的材料。把阿拉基的圣甲虫交给我，我会将它制成钥匙的头部。"
D.SharedStrings[1715]="你必须杀死巴拉丁监狱东边的咒怨地牢中的大法师加鲁斯，然后取回他的法杖。"
D.SharedStrings[1716]="你必须杀死恶魔监狱中的斯瓦诺斯，并带回它的诅咒颈环。斯瓦诺斯就在巴拉丁监狱西北边的恶魔监狱中。"
D.SharedStrings[1717]="你必须杀死矿渣洞的典狱官席尔瓦，并拿到他的钥匙。矿渣洞就在巴拉丁监狱的西南边。"
D.SharedStrings[1718]="你快速搜查了带锁箱，找到一只带锁的小带锁箱!似乎你已经找到财宝了!"
D.SharedStrings[1719]="你怎么也想不到竟会有这么大个儿的鱼卵。"
D.SharedStrings[1720]="你急切渴望着加入战斗，为此神经都已紧绷。"
D.SharedStrings[1721]="你总是叫人叹为观止，$N。$B$B你跟我一定得在这一切结束之后好好喝一杯，知道吗?"
D.SharedStrings[1722]="你总是听别人说这里是“法师之城”，不过这也太夸张了吧！"
D.SharedStrings[1723]="你想成为一名玩火炬的艺人？你具备相应的素质吗？比如机敏？灵活？……勇气？如果你有信心的话，不妨来试试身手！$B$B带上火炬去篝火堆附近吧。当你看见某只火盆上方显现标记时，就将火炬扔过去。动作要快！在标记消失前扔出火炬才能得分！$B$B这是一项限时游戏，你要击中规定数量的带有标记的火盆，然后回到我这儿来……准备接受新的挑战。"
D.SharedStrings[1724]="你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。"
D.SharedStrings[1725]="你感到与世无争。"
D.SharedStrings[1726]="你感到很平静。"
D.SharedStrings[1727]="你感到神志不清……\r\n耐力降低{1}点。\r\n全能提高{2}。"
D.SharedStrings[1728]="你感到窒息，每秒受到一次物理伤害！"
D.SharedStrings[1729]="你感到自己变小了……"
D.SharedStrings[1730]="你感受到了一个逝去灵魂的感情。"
D.SharedStrings[1731]="你感染了月羽疫病。如果不能及时治好，可能会造成可怕的后果。"
D.SharedStrings[1732]="你感染了毒性孢子！你会爆炸并感染附近的所有友方玩家，造成{1}点暗影伤害，并提高他们对毒气的抗性。"
D.SharedStrings[1733]="你感觉不太好……"
D.SharedStrings[1734]="你感觉到速度与激情了吗？"
D.SharedStrings[1735]="你感觉变轻了……\r\n每秒造成{1}点奥术伤害。"
D.SharedStrings[1736]="你感觉整个世界一片宁静。"
D.SharedStrings[1737]="你愿意帮助我们的孤儿院？太感谢你了，我的朋友。感谢你愿意在儿童周的这段时间内为我们提供帮助。$B$B拿着这只哨子，你只能在儿童周的这7天内使用它。当你使用它的时候，就可以和那些由你负责照看的孩子进行对话，再次使用就可以解散那个孩子。$B$B不管怎么样，$n——使用这个口哨，见一见你的小朋友！我相信孩子们一定很想见到你。"
D.SharedStrings[1738]="你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧……这会让他们想起死去的领导者还有杀死他们的人类。"
D.SharedStrings[1739]="你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。"
D.SharedStrings[1740]="你成功了，$n。把这些徽记拿到档案馆的控制台那里去，看看你能否进入天文台。$B$B你最好快一点，$g伙计:小丫头;，时间紧迫。"
D.SharedStrings[1741]="你成功击败了卡利姆多和东部王国的驯宠大师，但你的下一项挑战将更为艰难。$B$B你必须在外域击败这四名训练师：地狱火半岛的尼基·微技、赞加沼泽的拉斯安、纳格兰的纳洛克和沙塔斯城的莫勒鲁长老。$B$B要想在成功之路上继续前进，就必须先击败他们。"
D.SharedStrings[1742]="你戒指里的力量是可塑的，虽然改变你的选择不容易。你确定你想替换它现在的形态吗?"
D.SharedStrings[1743]="你或許會想先清滌一下味覺，我們釀的酒味道可都很濃郁！"
D.SharedStrings[1744]="你所造成的伤害提高{1}%。"
D.SharedStrings[1745]="你所造成的伤害提高{1}点。"
D.SharedStrings[1746]="你所造成的伤害降低{1}%。"
D.SharedStrings[1747]="你所造成的暗影伤害提高{1}%。\r\n受到的近战伤害降低{2}%。"
D.SharedStrings[1748]="你所造成的法术伤害提高{1}点。\r\n你所受到的法术伤害提高{2}点。"
D.SharedStrings[1749]="你所造成的物理伤害提高{1}%。\r\n攻击速度提高{2}%。"
D.SharedStrings[1750]="你所造成的物理伤害提高{1}点。\r\n体型增大。"
D.SharedStrings[1751]="你手里正拿着蛛丝。将蛛丝扔到目标位置可以设置蛛网陷阱。"
D.SharedStrings[1752]="你打败了古尔丹的手下，他对这座邪能堡垒的控制被削弱了，我可以将你和你的盟军们一起传送到这座黑暗大厅的更深处。如果你能给我一些灵魂残片——比如说，就四块吧——就没有必要进行这些繁琐的步骤了，我可以掌控残片中的力量，将你们直接送到堡垒的上层。"
D.SharedStrings[1753]="你打败了银白勇士吗?"
D.SharedStrings[1754]="你打造出我要的那些东西了吗，$N?"
D.SharedStrings[1755]="你找到一具海龟的尸体，它显然是不久之前搁浅在黑海岸的，而且早已被住在周围的灰雾鱼人吃得一干二净了。不过，剩下的残骸也足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去了。"
D.SharedStrings[1756]="你找到了!?哦是的，东西都在这儿了。$B$B请容我表达谢意。如果可以的话，贝瑞那德最好别知道这件事。"
D.SharedStrings[1757]="你找到了一张发霉的卷轴。"
D.SharedStrings[1758]="你找到了一本书!"
D.SharedStrings[1759]="你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。"
D.SharedStrings[1760]="你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。"
D.SharedStrings[1761]="你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。"
D.SharedStrings[1762]="你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。"
D.SharedStrings[1763]="你找到了什么?"
D.SharedStrings[1764]="你找到了新朋友！"
D.SharedStrings[1765]="你找到它了!你拯救了熏木牧场冬幕节的礼物!$B$B可怜的萨克斯……我们会派一支队伍去找他并想办法帮他解冻的。希望他能够及时回来和我们一起欢度这个节日;虽然他要补上这段时间没有干的活。这些都是因为你的功劳才能够实现的啊!"
D.SharedStrings[1766]="你找到它啦!啊，今天我太高兴啦!谢谢你，$N。得到这个箱子之后，我内心里的愤懑也就平息了。$B$B但我还是要复仇……"
D.SharedStrings[1767]="你找到我需要的东西了吗?除非你帮我弄来那些东西，否则你得不到任何报酬。"
D.SharedStrings[1768]="你找到摧毁军团囤积炼狱火的方法了吗?"
D.SharedStrings[1769]="你找到深渊之核了吗?没有它的话，我们就无法得知暮光之锤究竟在那里做什么。"
D.SharedStrings[1770]="你找到鑰匙了！快點，看看合不合…\r\n\r\n沒錯，就是這支！你找到了！"
D.SharedStrings[1771]="你把他们粉碎在你脚下了吗，指挥官?"
D.SharedStrings[1772]="你把我所要求的材料都带回来了吗， $N?"
D.SharedStrings[1773]="你把我的弯剑从奈古拉什那儿抢回来啦!我简直不敢相信这是真的，$N!自从见到你之后，我似乎就时来运转了呀，没错，肯定是这样的!$B$B谢谢你!以后，要是我能再搞到一条新船的话，你要出海就尽管来找我，我让你随便坐，你永远都是我最欢迎的客人!"
D.SharedStrings[1774]="你把我的束带找回来了?这么说……你一定已经把海巨人摩卡什干掉了!万岁!$B$B摩卡什正是那些把我的船搞沉、把我的船员们都杀光的三个海巨人之一。$B$B那已经是第三次了。$B$B你确实是一位优秀的$C，$N。"
D.SharedStrings[1775]="你把我要的东西带来了吗?"
D.SharedStrings[1776]="你把我要的东西带来了吗，$N?"
D.SharedStrings[1777]="你把我要的东西都带来了吗，$N?"
D.SharedStrings[1778]="你把我要的材料带来了吗，$N?"
D.SharedStrings[1779]="你把我需要的材料带来了吗，$N?"
D.SharedStrings[1780]="你把符石放进对应的凹槽之中，大地随即猛烈地震动起来，发出了巨大的轰鸣声，与此同时封印也破碎了。"
D.SharedStrings[1781]="你把药剂倒入了锅中的混合物中，不断喷涌的水汽的颜色和成分很快就发生了变化。面对大量散入空气中的新物质，即使是那些离锅炉较远的天灾军团爪牙也显出了畏惧之色。"
D.SharedStrings[1782]="你抓住友方小队或团队目标的灵魂，使其立即移动到你身边。"
D.SharedStrings[1783]="你抓到了一個希爾斯布萊德人類。"
D.SharedStrings[1784]="你拥抱过圣光吗，$g兄弟:姐妹;？是圣光拯救了我们！是圣光让我有能力治疗这些饱受战火摧残的士兵！如今，圣光也将赋予你踏进北面的战区，营救我们倒下的兄弟的能力和勇气！$B$B带着这本祷言之书，对受伤的士兵施放圣光的治疗之触。"
D.SharedStrings[1785]="你拿到我所需要的东西了吗，$N?"
D.SharedStrings[1786]="你拿到我的項鍊了嗎？戴在那些…生物的脖子上，對我一點好處也沒有。"
D.SharedStrings[1787]="你拿到我需要的紫色蘑菇了吗?找不到我要的东西，我可不会付给你报酬的!"
D.SharedStrings[1788]="你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。"
D.SharedStrings[1789]="你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，履行这样的任务将是赢得最终胜利的关键要素。"
D.SharedStrings[1790]="你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……"
D.SharedStrings[1791]="你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……"
D.SharedStrings[1792]="你拿到马了，快回去把它交给萨拉纳尔！"
D.SharedStrings[1793]="你挥舞一桶酒，对目标造成相当于{1}%武器伤害的物理伤害。"
D.SharedStrings[1794]="你捉住了一个希尔斯布莱德人类。"
D.SharedStrings[1795]="你捕到了一条罕见的鱼……带翅膀的。或许应该咨询一下渔人码头的纳特·帕格，听取他的专业意见。"
D.SharedStrings[1796]="你掌握了最后一条黑龙的力量。"
D.SharedStrings[1797]="你搬运了太多的盎迦丛林酒。返回酿酒大锅处。"
D.SharedStrings[1798]="你携带着联盟旗帜。将它带回你的基地即可将其占据。"
D.SharedStrings[1799]="你携带着能量宝珠。\r\n携带这种宝珠将使你的团队获得胜利点数。\r\n受到的伤害提高。\r\n造成的伤害提高。\r\n受到的治疗效果降低。"
D.SharedStrings[1800]="你携带着部落旗帜。将它带回你的基地即可将其占据。"
D.SharedStrings[1801]="你收集好我要的材料了吗?"
D.SharedStrings[1802]="你教他们如何做人了吗？"
D.SharedStrings[1803]="你施放的每个审判法术都有一定几率为你身边的所有小队成员恢复{1}点生命值。"
D.SharedStrings[1804]="你施放的每个攻击法术都有一定几率使你的下一个法术所消耗的法力值减少{1}点。"
D.SharedStrings[1805]="你无法再控制自己的行动了。"
D.SharedStrings[1806]="你是一个杂草清理者。清理出一条穿越山谷的通道！"
D.SharedStrings[1807]="你是一只绵羊。不能在绵羊形态下施法。右键点击这个图标可以取消这个效果。"
D.SharedStrings[1808]="你是一名卧底侍者。用盘里的饮料来使顾客酒后乱言。"
D.SharedStrings[1809]="你是个派对狂热者！用你特有的派对方式去取悦每个参与者。"
D.SharedStrings[1810]="你是个真正的勇士，$N，不论是在战场或是竞技场中都一样。我们应该要更谨慎地与天灾军作战，而你对我们的同袍或你的同胞来说都是个伟大的榜样。"
D.SharedStrings[1811]="你是克苏恩的奴仆，凡人。"
D.SharedStrings[1812]="你是想改变自己吗，$N？"
D.SharedStrings[1813]="你是来学习地精工程学的?好吧，你算是找对地精了。虽然诺姆瑞根当局可以用政治的手段来放逐那些智商比他们高的天才，但是他们也知道，知识是他们无法控制的!$B$B他们和我都很清楚，自从我离开诺姆瑞根之后，他们就失去了一个有史以来最伟大的工程师!如果你是个合格的学生，那么我会将我的知识倾囊相传。"
D.SharedStrings[1814]="你是来领取奖励的吗?"
D.SharedStrings[1815]="你是第一个亲眼看到巨龙议会的凡人，$n，也是整个艾泽拉斯唯一能够参与守护巨龙选举的生物。$b$b我晋升之后，获得了不可思议的力量。我已经擅自强化了你与泰蕾苟萨之间的融合，尽管她需要的是一个更加……稳定的家。$b$b我要你再闯一次火元素位面，给我带来拉格纳罗斯的心脏。$b$b当我们下次再会时，我会好好褒奖你所做的一切。"
D.SharedStrings[1816]="你替暴风城所做出的贡献应该得到表扬，$N。如果范克里夫成功地实行了他的计画，无疑将会给王国带来巨大的灾难，我们必须避免这种事发生。$B$B收下这个吧，$C，它代表了我的谢意。"
D.SharedStrings[1817]="你最好一次就聽懂，我很討厭同一件事要說兩遍。"
D.SharedStrings[1818]="你最好立刻前往北风苔原的考达拉，$n。到那以后，我建议你对一些关键地点进行侦察，然后向我汇报情况。\n\n我很了解那片地区，应该可以给你行动建议。\n\n快去吧！"
D.SharedStrings[1819]="你最好给我确定，这回炖菜里面没有任何和地精有关的东西!"
D.SharedStrings[1820]="你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?"
D.SharedStrings[1821]="你最近刚刚从墓地复活，因此获得了暂时性的防护。"
D.SharedStrings[1822]="你有4分钟时间驾驭赛羊，让它保持三种不同的速度各8秒。"
D.SharedStrings[1823]="你有东西要给我吗?"
D.SharedStrings[1824]="你有东西要给我吗，$N?"
D.SharedStrings[1825]="你有亡者面包吗?"
D.SharedStrings[1826]="你有什么事吗，$N?"
D.SharedStrings[1827]="你有什么要和我说的，$C?"
D.SharedStrings[1828]="你有什么要报告的，士兵?"
D.SharedStrings[1829]="你有什么要给我的吗，$N?"
D.SharedStrings[1830]="你有几率拾取额外的肉类和鱼。"
D.SharedStrings[1831]="你有在对抗天灾军的战斗中自我磨练吗?"
D.SharedStrings[1832]="你有带我要的材料吗，$N?"
D.SharedStrings[1833]="你有带材料来吗?"
D.SharedStrings[1834]="你有很多疑问，$n。你是唯一能看见我的人，因为你碰过那件曾经属于他的东西……你不记得了吗？$B$B你还不知道那是什么吗？嗯……我可不能就这么告诉你……那样会让他变得非常愤怒。他已经不再只是个王子了……他是国王！$B$B到冰冠堡垒北边的白骨之庭来找我吧，你可以自己搞明白这一切。"
D.SharedStrings[1835]="你有我要的物品了吗，$C?"
D.SharedStrings[1836]="你有战歌峡谷的消息吗，$N?"
D.SharedStrings[1837]="你有找到任何东西能证实黑骑士的故事吗?"
D.SharedStrings[1838]="你有看到应该送起司和酒来给我的外送小弟吗?我超饿的!"
D.SharedStrings[1839]="你有着善良的灵魂，$N。人们很容易在战争的混乱与胜利的兴奋中遗忘了那些牺牲者。我代死者的亲友感谢你。"
D.SharedStrings[1840]="你有采回药草吗?伤兵与病人又增加了。"
D.SharedStrings[1841]="你杀掉执旗者并阻止它们一再尝试利用逝往的英魂来对付我们了吗?"
D.SharedStrings[1842]="你来得可真是时候啊，$n。我们已经占领了托尔巴拉德，但战斗才刚刚开始。$B$B我们在这里的东边发现了一座监狱，得靠你去清理一下。那地方塞满了不知被关押了多久的幽灵。$b$b尽可能多地清理那里的幽灵，然后回来向我报告。"
D.SharedStrings[1843]="你来找我们是件好事。或许我们可以利用这次攻击扭转对龙喉的情势。"
D.SharedStrings[1844]="你来这里做什么，$C?我没有太多的访客。"
D.SharedStrings[1845]="你正在帮助赞吉吉钻研德鲁伊的能力。"
D.SharedStrings[1846]="你正在控制一挺防空炮。"
D.SharedStrings[1847]="你正在搬运一桶盎迦丛林陈酿。搬运25桶以上将获得阻滞效果。"
D.SharedStrings[1848]="你正在搬运一桶盎迦丛林陈酿。搬运30桶以上将造成溢出。"
D.SharedStrings[1849]="你正在放置冲击波发射器为抵抗巴塔里入侵做准备！"
D.SharedStrings[1850]="你正在放置卡桑琅荒原啤为抵抗巴塔里入侵做准备！"
D.SharedStrings[1851]="你正在放置烟花炸药桶为抵抗巴塔里入侵做准备！"
D.SharedStrings[1852]="你正在爬树。抓紧了！"
D.SharedStrings[1853]="你正在瑞林的射击场里玩。瞄准被标记的目标，射击！"
D.SharedStrings[1854]="你正在练习扔火炬。把火炬扔向被标记的火盆！"
D.SharedStrings[1855]="你正在运球。将它灌进敌方基地的篮筐中来赢得分数。"
D.SharedStrings[1856]="你正在追踪一条霜狼血迹。"
D.SharedStrings[1857]="你正在逐漸了解我們的現實世界。我能從你的表情中看出來。很好。"
D.SharedStrings[1858]="你正在骑着艾维娜的守卫飞行。扇动双翼来飞得更高！"
D.SharedStrings[1859]="你正在骑着艾维娜的守卫飞行。扇动双翼！"
D.SharedStrings[1860]="你正处在被邪能魔法感染的区域中，从而周期性受到伤害。"
D.SharedStrings[1861]="你正把一头钢鬃野猪人拽在你的身后。"
D.SharedStrings[1862]="你正控制着大老爸。"
D.SharedStrings[1863]="你正穿着暮光之锤的衣物，以愚弄黏肠食人魔。"
D.SharedStrings[1864]="你正窥探基尔罗格的所见所闻！"
D.SharedStrings[1865]="你正面对玉珑的挑战。离开寺庙将无法进行挑战。"
D.SharedStrings[1866]="你正面对砮皂的挑战。离开寺庙将无法进行挑战。"
D.SharedStrings[1867]="你正面对赤精的挑战。离开寺庙将无法进行挑战。"
D.SharedStrings[1868]="你正面对雪怒的挑战。离开寺庙将无法进行挑战。"
D.SharedStrings[1869]="你每次攻击敌人，都可以获得{1}点攻击强度加成。"
D.SharedStrings[1870]="你每次施放审判法术，你的小队成员都获得{1}点法力值。"
D.SharedStrings[1871]="你每次施放攻击法术都有一定几率使你的下一个治疗涌动所消耗的法力值减少{1}点。"
D.SharedStrings[1872]="你每走一步都是连蹦带跳的，但对周围的白鹤来说，你是可口的美餐。"
D.SharedStrings[1873]="你没有让我失望，$N!你所学到的东西已经超越了奖章和表扬所能达到的范畴，它只有通过经验积累和在战场上的磨练才可以获得。$B$B你干得很好，$C。你是联盟真正的英雄!"
D.SharedStrings[1874]="你沾上了粘液！移动速度降低{1}%。在你被感染之前赶快躲开！"
D.SharedStrings[1875]="你浑身都是蜂蜜，并且吸引到了一些“朋友”……"
D.SharedStrings[1876]="你现在已经收集到了套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说每个月暗月马戏团的入口都会出现在莫高雷和闪金镇。"
D.SharedStrings[1877]="你现在感觉如何?"
D.SharedStrings[1878]="你现在拿的徽章就像议会里任何一个大法师的徽章一样的强大。配戴着它，无论你走那里，这样子学习员就能认知到你的忠诚。配戴着它，无论你走那里，如此它的力量就可如你为我们效劳般地为你效劳!"
D.SharedStrings[1879]="你现在真觉得绳子是个不可或缺的添头。"
D.SharedStrings[1880]="你甚至不知道该从哪里开始读起……"
D.SharedStrings[1881]="你的VLD降落伞成功地打开了。享受余下的旅程吧。"
D.SharedStrings[1882]="你的上一次射击打在了目标区域附近，再接再厉吧！和弗兹尔巴布交谈可以使你快速传送回去。"
D.SharedStrings[1883]="你的上一次射击正中靶心！和弗兹尔巴布交谈可以使你快速传送回去。"
D.SharedStrings[1884]="你的下一个凿击、肾击、脚踢或毒刃的冷却时间缩短为0.5秒。"
D.SharedStrings[1885]="你的下一个嗜血的伤害和治疗量提高{1}%。"
D.SharedStrings[1886]="你的下一个奥术弹幕、火焰冲击、炼狱冲击、冰锥术或冰霜新星的冷却时间缩短为0.5秒。"
D.SharedStrings[1887]="你的下一个愈合的施法时间缩短{1}%。"
D.SharedStrings[1888]="你的下一个施法时间低于10秒的法师法术会成为瞬发法术。"
D.SharedStrings[1889]="你的下一个星涌术、猛虎之怒、裂伤（熊形态）或迅捷治愈的冷却时间缩短为0.5秒。"
D.SharedStrings[1890]="你的下一个杀戮命令、奇美拉射击、黑箭或陷阱的冷却时间缩短为0.5秒。"
D.SharedStrings[1891]="你的下一个死亡之握、心灵冰冻、反魔法护罩或爆发的冷却时间缩短为0.5秒。"
D.SharedStrings[1892]="你的下一个治疗之触或复生法术变为瞬发，不消耗法力值，并且在任何形态下都可以使用。"
D.SharedStrings[1893]="你的下一个治疗法术所消耗的法力值减少{1}点。"
D.SharedStrings[1894]="你的下一个治疗法术消耗的法力值减少{1}点。"
D.SharedStrings[1895]="你的下一个活血酒所消耗的真气降低{1}%。"
D.SharedStrings[1896]="你的下一个炎爆术或烈焰风暴变成瞬发，并且会造成正常点燃伤害的双倍伤害。"
D.SharedStrings[1897]="你的下一个熔岩爆裂变为瞬发。"
D.SharedStrings[1898]="你的下一个神圣震击、复仇者之盾或审判的冷却时间缩短为0.5秒。"
D.SharedStrings[1899]="你的下一个致死打击、嗜血、盾牌猛击或雷霆一击的冷却时间缩短为0.5秒。"
D.SharedStrings[1900]="你的下一个苦修、心灵震爆或圣言术的冷却时间缩短为0.5秒。"
D.SharedStrings[1901]="你的下一个醉酿投、复苏之雾或旭日东升踢的冷却时间缩短为0.5秒。"
D.SharedStrings[1902]="你的下一个铁鬃的怒气消耗降低{1}%。"
D.SharedStrings[1903]="你的下一个风暴打击、激流、震击术或元素释放的冷却时间缩短为0.5秒。"
D.SharedStrings[1904]="你的下一个黑暗灵魂、恶魔法阵：传送或暮光结界的冷却时间缩短为0.5秒。"
D.SharedStrings[1905]="你的下一次凛风冲击不会消耗符文，也不会产生符文能量，造成的伤害提高{1}%。"
D.SharedStrings[1906]="你的下一次影袭、背刺、斩击或出血的爆击几率提高{1}%。"
D.SharedStrings[1907]="你的下一次攻击造成的伤害提高{1}%。"
D.SharedStrings[1908]="你的下一次物理攻击可以造成{1}点额外伤害。"
D.SharedStrings[1909]="你的下一次物理攻击造成{1}点额外伤害。"
D.SharedStrings[1910]="你的专注使你更擅长肢解敌人。你现在可以获得双倍的破碎骨骼。"
D.SharedStrings[1911]="你的任务完成了吗，$N?"
D.SharedStrings[1912]="你的任务是从巴拉丁监狱西北边的恶魔监狱取回8条被诅咒的镣铐。"
D.SharedStrings[1913]="你的任务是从托尔巴拉德的巴拉丁鳄鱼身上收集8张鳄鱼皮。你可以在巴拉丁监狱西边的沼泽中找到鳄鱼。"
D.SharedStrings[1914]="你的任务是去巴拉丁监狱西南边的矿渣洞杀死任意10名囚犯。"
D.SharedStrings[1915]="你的任务是在巴拉丁监狱东边的咒怨地牢中收集4本满是灰尘的狱中日记。"
D.SharedStrings[1916]="你的任务是在巴拉丁监狱东边的咒怨地牢中杀死任意9个幽灵。"
D.SharedStrings[1917]="你的任务是在巴拉丁监狱西北边的恶魔监狱中杀死任意10个恶魔。"
D.SharedStrings[1918]="你的任务是在巴拉丁监狱西南边的矿渣洞中收集12份囚犯的口粮。"
D.SharedStrings[1919]="你的任务是杀死普罗布里姆，一只在托尔巴拉德的路上游荡的巨型双头魔。"
D.SharedStrings[1920]="你的伤害性法术和技能会周期性地对一名敌方目标造成{1}点暗影烈焰伤害。"
D.SharedStrings[1921]="你的低温肠道为小蜘蛛提供了一个理想的寄生场所。"
D.SharedStrings[1922]="你的入侵已经惊动了瑞文戴尔男爵。他的囚犯活不了多久了。"
D.SharedStrings[1923]="你的兴起是所有人之中最出色的，$N。愿你永远不会在征服者之路上迷失!"
D.SharedStrings[1924]="你的前任行政助理"
D.SharedStrings[1925]="你的前方涌现出一条坡道，通向城市众多平台之一。前面蝙蝠形状的图腾表明这是的追随者，高阶祭司耶克里克的领域。$b$b耶克里克是众多崇拜哈卡的祭司之一，赞吉尔正打算复活他。假如你动作快，或许可以阻止他的复活！"
D.SharedStrings[1926]="你的努力获得很大的赞赏，$N。我要立刻显示这些侦察报告，去接你的下一个任务吧。"
D.SharedStrings[1927]="你的協助讓這一切得以實現。謝謝你。"
D.SharedStrings[1928]="你的双眼充满血色阴霾，造成的伤害提高{1}%。"
D.SharedStrings[1929]="你的变形术法术现在有20秒的冷却时间，持续时间缩短15秒，但不再导致目标恢复生命值。"
D.SharedStrings[1930]="你的同伴们在我们的土地上可真是一点也不客气，一到这里就大打出手。$b$b我们还尚未了解他们造成的全部破坏。目前所知的情况……已经是难以言喻。$b$b然而，出于报复而遗弃你的朋友有悖于我们的处世之道。毫无疑问，所有幸存者都已经身负重伤，并需要紧急救护。$b$b这些烟火原本准备用于庆祝雕像的完工。请在你的同伴附近使用它们以便给米师发信号，她会把他们运到安全的地点。"
D.SharedStrings[1931]="你的周期性伤害将累积烈焰宝珠。烈焰宝珠存在时，你的炎爆术将被凤凰烈焰代替。"
D.SharedStrings[1932]="你的圣骑士职业专属坐骑散发着璀璨的圣光。"
D.SharedStrings[1933]="你的坐骑看起来更具节日气息。"
D.SharedStrings[1934]="你的复仇技能可以令你的下一次伤害技能所造成的伤害提高{1}%。"
D.SharedStrings[1935]="你的天怒图腾提供的法术强度加成提高{1}%。"
D.SharedStrings[1936]="你的奉献会在原地留下一个灰烬使者的影像。当你使用技能时，灰烬使者的影像会将此技能造成的伤害的{1}%分布到奉献范围内的敌方目标身上。"
D.SharedStrings[1937]="你的奥术法术有几率召唤出艾格文的影像协助你。"
D.SharedStrings[1938]="你的宠物吃了零食之后变得非常开心！"
D.SharedStrings[1939]="你的宠物的攻击有一定几率为其恢复{1}点生命值。"
D.SharedStrings[1940]="你的宠物造成的伤害提高{1}%。"
D.SharedStrings[1941]="你的寒冰宝珠会在10秒后返回到你身边。"
D.SharedStrings[1942]="你的幼崽期待地看着你。它想要什么？$B$B这只小猫舔着嘴唇。一定是又到它的吃饭时间了！作为它的代理$g父亲:母亲;，你有责任为它提供肉食，直到它能够自己狩猎。$B$B不过你也可以让其他人完成狩猎工作。冬泉谷的两座冬泉熊怪营地里，冬泉熊怪们通常都会在手边准备许多熏肉。当然，他们不会在乎少几块肉。而你的幼崽也可以尝试一下新食物。"
D.SharedStrings[1943]="你的憎恶伙伴"
D.SharedStrings[1944]="你的战斗怒吼技能所提供的攻击强度加成提高{1}点。"
D.SharedStrings[1945]="你的战旗，带着鲜明的联盟色彩，由你的追随者手工缝制。"
D.SharedStrings[1946]="你的战旗，带着鲜明的部落色彩，由你的追随者手工缝制。"
D.SharedStrings[1947]="你的所有经验都被移除了。衣服也是。"
D.SharedStrings[1948]="你的招架提高{1}点。"
D.SharedStrings[1949]="你的拳头捏得劈啪作响，可以开始了！"
D.SharedStrings[1950]="你的搜索技能可以从敌对玩家身上偷取最多5块神器碎片。"
D.SharedStrings[1951]="你的搜索技能可以从敌对玩家身上偷取最多5块神器碎片，但依然有{2}秒的冷却时间。只能在阿什兰使用。"
D.SharedStrings[1952]="你的攻击可以引发爆炸造成{1}点伤害。"
D.SharedStrings[1953]="你的攻击性法术可以造成额外的该系伤害。每个法术消耗一次使用次数。"
D.SharedStrings[1954]="你的攻击无视目标的{1}点护甲值。"
D.SharedStrings[1955]="你的攻击有几率召唤亡者大军中的一名成员。"
D.SharedStrings[1956]="你的攻击法术爆击之后有一定几率令你的下一个法术所消耗的基础法力值减少{1}点。"
D.SharedStrings[1957]="你的攻击被铸炉之主索朗格斯的盾牌格挡了！"
D.SharedStrings[1958]="你的数据看起来没有问题，$N，欢迎成为俱乐部的一员!$B$B每个月的第一天你会收到我们的邮件，如果你喜欢我们邮寄给你的酒，请来俱乐部，我们可以卖你更多。我们是很大方的俱乐部。"
D.SharedStrings[1959]="你的斥候报告说命运之柱还有敌人活动的迹象。"
D.SharedStrings[1960]="你的斥候报告说失落的安苏鸦巢还有敌人活动的迹象。"
D.SharedStrings[1961]="你的斥候报告说戈尔隆德的沙塔斯城还有敌人活动的迹象。"
D.SharedStrings[1962]="你的斥候报告说戈尔隆德的黑石矿坑还有敌人活动的迹象。"
D.SharedStrings[1963]="你的斥候报告说斯克提斯还有敌人活动的迹象。"
D.SharedStrings[1964]="你的斥候报告说永茂丛林还有敌人活动的迹象。"
D.SharedStrings[1965]="你的斥候报告说沙塔斯港口还有敌人活动的迹象。"
D.SharedStrings[1966]="你的斥候报告说玛戈纳洛克还有敌人活动的迹象。"
D.SharedStrings[1967]="你的斥候报告说石怒崖还有敌人活动的迹象。"
D.SharedStrings[1968]="你的斥候报告说破碎悬崖还有敌人活动的迹象。"
D.SharedStrings[1969]="你的斥候报告说索克雷萨高地还有敌人活动的迹象。"
D.SharedStrings[1970]="你的斥候报告说莫高尔岗哨还有敌人活动的迹象。"
D.SharedStrings[1971]="你的斥候报告说钢铁军工厂还有敌人活动的迹象。"
D.SharedStrings[1972]="你的斥候报告说高里亚试炼场还有敌人活动的迹象。"
D.SharedStrings[1973]="你的斥候报告说黑潮栖木还有敌人活动的迹象。"
D.SharedStrings[1974]="你的本质和你所找到的火焰能量共鸣着，$N。你找到的火焰相当强大，只需要正确地处理，就能增强它的力量……$B$B<老者对着空气中低语，然后拿出一个发光的瓶子。>$B$B啊!好了。不管你往何处去，愿它照亮你的道路。"
D.SharedStrings[1975]="你的正义盾击额外造成{1}%的火焰伤害。"
D.SharedStrings[1976]="你的武器和护甲浸润在艾露恩圣水中，使你对纳迦的伤害提高{1}%。\r\n\r\n只有当你处于潮汐王座的时候才会生效。"
D.SharedStrings[1977]="你的武器掉在地上了！下一次科林喝酒的时候记得离他远一点。"
D.SharedStrings[1978]="你的毒皮暴掠龙幼崽想要你喂它10块异种蝎肉。"
D.SharedStrings[1979]="你的毒皮暴掠龙幼崽想要你喂它12枚异种蝎卵。"
D.SharedStrings[1980]="你的毒皮暴掠龙幼崽想要你喂它15片鲜嫩的恐龙肉。"
D.SharedStrings[1981]="你的毒皮暴掠龙幼崽想要你给它弄来5根炎鹏的羽毛。"
D.SharedStrings[1982]="你的治疗法术产生爆击后，有一定几率立即为附近受伤最严重的团队成员恢复{1}点生命值。"
D.SharedStrings[1983]="你的治疗法术所消耗的法力值减少{1}点。"
D.SharedStrings[1984]="你的治疗法术所造成的治疗效果提高{1}%。"
D.SharedStrings[1985]="你的治疗法术有一定几率使你获得{1}点法力值。"
D.SharedStrings[1986]="你的治疗法术有一定几率激活这条项链中蕴含的奥术能量（若你在占星者阵营的声望达到崇拜）或圣光能量（若你在奥尔多阵营的声望达到崇拜）。"
D.SharedStrings[1987]="你的治疗法术有一定几率立即为附近受伤最严重的团队成员恢复{1}点生命值。"
D.SharedStrings[1988]="你的治疗法术有一定几率触发净化烈焰效果，治疗你前方所有靠近的友方目标{1}点生命值。"
D.SharedStrings[1989]="你的法术、技能和近战攻击有50%的几率额外造成{2}点暗影伤害。"
D.SharedStrings[1990]="你的法术可以在时空之墙上打穿孔洞，开启传送门。"
D.SharedStrings[1991]="你的法术可以在移动中施放。"
D.SharedStrings[1992]="你的法术有一定几率激活这条项链中蕴含的奥术能量（若你在占星者阵营的声望达到崇拜）或圣光能量（若你在奥尔多阵营的声望达到崇拜）。"
D.SharedStrings[1993]="你的法术有几率唤醒圣光之心，在6秒内向8码内的敌人辐射500000点神圣伤害。\r\n\r\n圣光之心会为附近的盟友恢复生命，数值相当于其造成伤害的25%."
D.SharedStrings[1994]="你的法术有时会造成额外的暗影伤害。"
D.SharedStrings[1995]="你的法术消耗降低{1}%。"
D.SharedStrings[1996]="你的法术爆击时造成的伤害提高{1}%。"
D.SharedStrings[1997]="你的注意力再次集中了起来。在破碎群岛时自然伤害提高{1}%。"
D.SharedStrings[1998]="你的消息還沒傳來這裡，琪拉就先來了。她不久前剛來到這裡，但她顯然有意避開我的目光。\r\n\r\n你居然能夠得到她的信任，這是我辦不到的。有了她的幫忙，我們應該就可以召喚傳送門了。"
D.SharedStrings[1999]="你的火球术的施法时间缩短{1}%，造成的伤害提高{2}%。"
D.SharedStrings[2000]="你的灵魂前往潘达利亚的晴日峰，将你的肉身留在原地。"
D.SharedStrings[2001]="你的灵魂正在堕落，叠加5层之后便会碎裂。"
D.SharedStrings[2002]="你的灵魂生气蓬勃，年轻的$C。我接受你的致敬并回敬你这个硬币……"
D.SharedStrings[2003]="你的熔岩图腾攻击时有几率重置熔岩爆裂的冷却时间，并使你的下一个熔岩爆裂变为瞬发。"
D.SharedStrings[2004]="你的燃烧和凤凰之箭会生成凤凰卵。激活燃烧会使凤凰卵复生，对敌人造成伤害，并治疗盟友。"
D.SharedStrings[2005]="你的爆击提高{1}点。"
D.SharedStrings[2006]="你的狂暴情绪被红龙女王的气息消除了。"
D.SharedStrings[2007]="你的猎鹰已经蓄势待发了。"
D.SharedStrings[2008]="你的生命值低于{1}！芬克的混合剂无法治疗重伤。"
D.SharedStrings[2009]="你的生存本能使你的肾上腺素急速分泌！记住，变得越大越好，想做什么就做什么，不要跑！"
D.SharedStrings[2010]="你的盟友和我马上就会清除这些障碍，不过这会消耗我们很大一部分力量。不管前面是什么，都不是那么容易对付的。\n\n古尔丹利用密码强化了一个元素领主，让它变得疯狂了。他想要用它来破坏元素与德拉诺之间的联系。如果你能摧毁那个元素，我们就能收回密码了。"
D.SharedStrings[2011]="你的直接性治疗法术有一定几率触发灼烧治疗。你的直接性伤害法术有一定几率触发灼烧烈焰。"
D.SharedStrings[2012]="你的相对时间减慢了{1}%，施法速度、移动速度、攻击速度、冷却回复速度减慢，周期性法术效果的触发频率降低。"
D.SharedStrings[2013]="你的确是个值得的盟友。随着你力量的成长，永恒指环也随着增强!"
D.SharedStrings[2014]="你的移动速度提高{1}%，急速提高{2}%。"
D.SharedStrings[2015]="你的第一份工程学订单"
D.SharedStrings[2016]="你的第一份珠宝加工订单"
D.SharedStrings[2017]="你的第一份锻造订单"
D.SharedStrings[2018]="你的精华被烧尽了！在一处引火烈焰附近重新充能。"
D.SharedStrings[2019]="你的老师凯德莫斯要你前往埃索达与他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。"
D.SharedStrings[2020]="你的老师奥德兰要你前往银月城跟他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。"
D.SharedStrings[2021]="你的肌肉已经充分伸展，可以开始了！"
D.SharedStrings[2022]="你的脑袋被扳手狠狠打了一下，肯定已经肿了个大包……"
D.SharedStrings[2023]="你的脚步变得快了一点，而且身上散发着非常刺鼻的气味。"
D.SharedStrings[2024]="你的腐蚀术或献祭法术每一跳都可以为你恢复{1}点生命值。"
D.SharedStrings[2025]="你的自动射击有几率让你的下一次奥术射击或多重射击施放猎人印记，猎人印记会激活标记射击。"
D.SharedStrings[2026]="你的英勇事迹已经传遍了艾泽拉斯内外。其他地方也需要你的高超身手。\n\n你愿意穿过黑暗之门，去外域的破碎世界与燃烧军团战斗吗？\n\n或者是飞往北方的诺森德，参加对抗巫妖王的战争。\n\n做出你的选择吧，冒险者。"
D.SharedStrings[2027]="你的行动变得缓慢，而且对周围的白鹤来说，你是一道美餐。"
D.SharedStrings[2028]="你的表现到目前为止都很不错，$n。你在不知不觉中已经成了一个宠物方面的专家，现在是时候去抓一个属于你自己的宠物了！$b$b去外面找一个战斗宠物并与其交战，当它体力不支时抛出你的陷阱。一旦你完成后，记得把捕获的宠物带给我瞧瞧。$b$b记住，你至少要有一个宠物达到了3级才能使用陷阱！"
D.SharedStrings[2029]="你的试炼不会很轻松，但是你的勇气没有丧失，你的力量将会永存。和过去的辉煌告别吧，$C。没有人需要它们来证明自己的价值。向前进，$N。今天你将以英雄的姿态昂首向前!"
D.SharedStrings[2030]="你的贡献并非无人注意，$N。你的印记或许看来没有改变，但它的力量会随着你持续证明自己的忠诚而获得强化。"
D.SharedStrings[2031]="你的贡献被接受了。你获得了我们的好感，继续做下去，你就可以接触到那些历史悠久的生意了。"
D.SharedStrings[2032]="你的身体僵硬起来，并开始转化为青玉。"
D.SharedStrings[2033]="你的躲闪提高{1}点。"
D.SharedStrings[2034]="你的近战和远程攻击有一定几率激活这条项链中蕴含的奥术能量（若你在占星者阵营的声望达到崇拜）或圣光能量（若你在奥尔多阵营的声望达到崇拜）。"
D.SharedStrings[2035]="你的近战和远程攻击有一定的几率使你的爆击、急速或精通提高{1}点，提高当前数值最高的一项属性。持续30秒。"
D.SharedStrings[2036]="你的近战攻击会造成{1}%的额外伤害（视为暗影伤害）。"
D.SharedStrings[2037]="你的近战攻击可以从目标身上吸取生命值。"
D.SharedStrings[2038]="你的近战攻击有一定几率使你获得{1}点法力值。"
D.SharedStrings[2039]="你的近战攻击有一定几率使用火焰、暗影或者冰霜的力量冲击敌人，造成{1}点伤害。"
D.SharedStrings[2040]="你的近战攻击有一定几率使目标受伤，造成{1}点物理伤害。"
D.SharedStrings[2041]="你的近战攻击有几率从目标敌人身上吸取{1}点生命值。\r\n"
D.SharedStrings[2042]="你的近战攻击有几率冲击目标，造成{1}点火焰伤害。\r\n"
D.SharedStrings[2043]="你的近战攻击有几率对目标造成流血伤害。"
D.SharedStrings[2044]="你的远古列王守卫在为你而战！你的每一次攻击都会为你注入远古能量，使你的力量提升{1}。"
D.SharedStrings[2045]="你的远古列王守卫在为你而战！它的每一次攻击都会为你注入远古能量，使你的力量提升{1}。"
D.SharedStrings[2046]="你的速度受到限制。\r\n将强化矿石带回队伍的矿车可以获得分数。"
D.SharedStrings[2047]="你的那份“赢利”和其他东西都被丢在拳台上了。"
D.SharedStrings[2048]="你的部隊做得很好。我們擁有的靈魂裂片已經足以強化定位器。"
D.SharedStrings[2049]="你的队友已经举报了你的懒散行为！如果你不投入PvP战斗的话，就会被标记为消极的玩家，并且无法获得荣誉值和征服点数。"
D.SharedStrings[2050]="你的阵营以你的英勇事迹为傲！"
D.SharedStrings[2051]="你的阵营需要更多的士兵！\r\n\r\n荣誉击杀、战场获胜或完成战场目标后获得的荣誉点数提高{1}%。"
D.SharedStrings[2052]="你的风暴打击技能还会使你的火焰新星，烈焰震击，火舌武器，熔岩爆裂，熔岩猛击，以及火焰释放对目标造成{1}%的额外伤害。"
D.SharedStrings[2053]="你的鱼漂变成了一个可爱的鱼人脑袋。"
D.SharedStrings[2054]="你看上去像是……死了。任务完成之后，最好和灵魂医者安娜拉谈谈。"
D.SharedStrings[2055]="你看上去死了……好像是的。当你任务完成后，最好与灵魂医者安娜拉交谈。"
D.SharedStrings[2056]="你看到了吗?你懂它的力量了吗?净化……真是笨蛋……$B$B<麦特斯不以为意地摇了摇头。>$B$B拿去吧，离开我的视线。"
D.SharedStrings[2057]="你看到这尊雕像分裂成了两座，然后是四座，然后是八座一模一样的雕像，以方阵排列。$b$b你听到了一个声音，不是从你的耳朵传进来的，而是直接传入你的心灵：$b$b   “真正的戒卫不会面向外界，寻求危机的迹象。$b  真正的戒卫总是检视自己，专注于保护他的内心。”$b$b也许这是一道谜题？"
D.SharedStrings[2058]="你看見菈塔娜了？怎麼回事？\r\n\r\n…我知道了。對不起讓妳失望了，吾愛。"
D.SharedStrings[2059]="你看见地上那个发光的发声装置了吗？就在伊莎的小屋外。"
D.SharedStrings[2060]="你看见岛屿北端的要塞了吗，$n？那里是要塞领主法尔森的老巢。$b$b法尔森有一帮忠心耿耿的追随者，自从我们来到这里，他们就一直找我们的麻烦。我们曾经派出侦查小队潜入要塞，探明了法尔森的具体位置。$b$b你能帮我们除掉他吗？"
D.SharedStrings[2061]="你看见那些在坟场中徘徊的鬼魂了吗？$B$B他们是复生的先祖，是被重新召唤到这个世界上来的，魔古族死者的灵魂。$B$B当被激怒时，他们会迅捷无声地发起攻击，他们的数量也在日增夜长。$B$B他们不属于这里。去消灭他们，把他们送回坟墓里去。"
D.SharedStrings[2062]="你看起來已經做好戰鬥的準備。到了那裡，別讓嗜血的慾望支配你。\r\n\r\n大酋長希望在你前往戰場之前，先贈與你這枚戒指，願你能帶著無數惡魔的頭顱凱旋。"
D.SharedStrings[2063]="你看起来，闻起来都不一样…你不是我的狼群中的一员。跟我说你的故事;我被困在这里什么也没有，但我有的是时间。"
D.SharedStrings[2064]="你真是个既完整又有效的样本。我们有许多的实验要做，而我们自愿者样本的存量又近乎见底。我们最欢迎新鲜的血液，而你的原始血液可以作为我们数小时研究的原料。"
D.SharedStrings[2065]="你真是了不起，哈哈!做的好，你真是个有趣的人。这是你的糖果。$B$B万鬼节快乐，$N!"
D.SharedStrings[2066]="你真是令我们喜出望外，伙计。我敢说，你的天赋对我们肯定是大有帮助。你不用再跟这些新兵蛋子混在一起啦。$B$B到东南边的村子里去吧，闯出你自己的天地来。到处帮帮忙，我相信你很快就会出人头地的。"
D.SharedStrings[2067]="你真是太厉害了!谢谢你救了我!$B$B我就知道，我命中注定不会成为巨魔的开胃菜!"
D.SharedStrings[2068]="你真的要喝它吗？这种药剂只能在达拉然城中生效。"
D.SharedStrings[2069]="你着火了！"
D.SharedStrings[2070]="你知道的，我还没有丧失对往昔的故乡与人民的爱。我曾为了银月城能在幽暗城与奥格瑞玛的谈判桌上有一席之地而与兽人针锋相对。$B$B你带来的消息可以让任何反对者闭上嘴。立刻将这封信送给奥格瑞玛的萨鲁法尔。身为兽人的领袖，他会最终接受辛多雷的效忠宣誓。$B$B我已经在信上盖了自己的印章，表明了我个人的认可。到城市的西北方去，你就可以找到地精飞艇的空港，搭乘飞艇可以很快到达杜隆塔尔。"
D.SharedStrings[2071]="你知道规矩的。击败要塞中的宠物，我或许有一些奖励给你。"
D.SharedStrings[2072]="你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。"
D.SharedStrings[2073]="你確定要這麼做嗎？"
D.SharedStrings[2074]="你离开了艾萨拉战斗区域。你很快将会被传送回去。"
D.SharedStrings[2075]="你离战场太远了……"
D.SharedStrings[2076]="你端起盛有淤泥样本的培养皿。要查看样本是否纯净的唯一方法就是打开培养皿，检查里面的物质成分。在理想状态下，你应该可以找到符合化学家弗雷要求的样本。"
D.SharedStrings[2077]="你粗心大意地亲吻青蛙，结果嘴上长疣了。"
D.SharedStrings[2078]="你终于大步迈进了一个更加广阔的世界，$N。我感觉到你已经掌握了巨熊之灵所传授的知识，还有月爪枭兽曾经拥有的力量。$B$B在你的面前没有其它的障碍了……现在，让我告诉你成为一个利爪德鲁伊意味着什么吧!"
D.SharedStrings[2079]="你给我的是什么东西？纳特叫你请求我把这玩意儿做成鱼竿？$B$B<玛西娅接过你手中切断的鱼饵。她将鱼饵挨到珍珠跟前，发现它们产生了共鸣。>$B$B有点意思。看来这东西和珍珠之间存在某种联系。也许把这东西做成鱼竿确实能得出有趣的结果……"
D.SharedStrings[2080]="你肯来帮忙真是太好了，$r。我们有很多事情要做。"
D.SharedStrings[2081]="你能做的，我能做得更好……"
D.SharedStrings[2082]="你能想像萊斯賓的真跡埋藏在一堆樹葉中嗎？真是糟蹋。"
D.SharedStrings[2083]="你能感觉到瓶中的液体所散发出的能量，但却无法触摸到它。"
D.SharedStrings[2084]="你能感觉到里面的暗影也在回望着你。"
D.SharedStrings[2085]="你能拿到那柄剑吗?"
D.SharedStrings[2086]="你能理解你盟友的外族语言。"
D.SharedStrings[2087]="你能闻到它的味道！就在你前面的什么地方。把你手里的家伙扔过去，看看能不能砸到它吧。"
D.SharedStrings[2088]="你脚下有一枚闪光的符文，4秒后会对周围的敌人造成{2}点火焰伤害。"
D.SharedStrings[2089]="你获得了法力炸弹。\r\n将炸弹带到敌方控制的据点放置。"
D.SharedStrings[2090]="你获得了碎石之锤。有了它你就能穿过塌方了。"
D.SharedStrings[2091]="你融汇月亮和太阳的能量，对目标发出一股毁灭性的能量冲击波。对目标造成{1}点法术风暴伤害。"
D.SharedStrings[2092]="你衣角的碎片告诉我你是一名裁缝师，而且可以轻易地学会我要教你的技术。$B$B北方的人型生物所穿着的衣服，可以很容易地转化成布料，只要你知道诀窍的话。$B$B只需要一点点的费用，我就会教你布料搜掠的技巧，如此一来，你就可以从诺森德的人型生物那儿搜刮一些布料来。"
D.SharedStrings[2093]="你被一股强大的邪能法术给击退了。"
D.SharedStrings[2094]="你被催泪毒气熏的头晕目眩，完全无法移动！"
D.SharedStrings[2095]="你被军团打上了死亡的标记。\r\n\r\n触碰其他玩家可以传递标记。"
D.SharedStrings[2096]="你被发现了！"
D.SharedStrings[2097]="你被变成了一个饥饿的海象人。钓鱼技能提高{1}点。"
D.SharedStrings[2098]="你被变成了一只飞行的巨蜂。这个效果只能在达拉然城中生效。"
D.SharedStrings[2099]="你被巴德盯上了……至少现在是这样。"
D.SharedStrings[2100]="你被敲了脑袋。下次记得把酒喝光！\r\n昏迷。"
D.SharedStrings[2101]="你被标记为可以进行PvP战斗，对你的小队以外的所有玩家呈敌对状态。"
D.SharedStrings[2102]="你被沙拉斯鸦巢的防御结界发现并标记了。"
D.SharedStrings[2103]="你被迷雾所排斥。"
D.SharedStrings[2104]="你被限速。\r\n将矿车送回基地以获取胜利点数。"
D.SharedStrings[2105]="你被黄昏使者塞尔赞施加了死亡的印记。在你被杀死之前，将这本书交给骑兵杜尔库！"
D.SharedStrings[2106]="你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。"
D.SharedStrings[2107]="你要从萨格隆邪恶的萨特身上收集10枚萨特魔印，将它们放进艾露恩的火盆。"
D.SharedStrings[2108]="你要在祖格卡的祭坛使用地狱动力核心控制魔王阿兹雷索克，用它的力量消灭祖格卡。"
D.SharedStrings[2109]="你要找的地精的名字叫做克林科·古德斯迪尔。他在塔纳利斯的加基森镇里生活，为出价最高的顾客效力。看来他是唯一个可以帮我们完成融合工序的铁匠，不过他的标价会非常高，所以你来解决他的工钱。$B$B我是个炼金师，不是个银行家。如果我有一堆金子的话，还待在这里干什么？$B$B我相信我已经把事情说得很直白了，咳咳。$B$B加基森在等待你！祝你好运！"
D.SharedStrings[2110]="你要放下阴郁蜡烛，从无头骑士受阻咒的永眠中召唤他吗?"
D.SharedStrings[2111]="你要用这台机器去对付天灾军团？你这样是无法胜过他们的。$B$B你或许可以消灭几百个敌人……甚至几千个，但你无法取得胜利。这样不行。$B$B等你摆弄够了这台机器，可以到北边来找我。那里有一座旧军营。我会让你认识到，你要面对的是怎样的敌人。"
D.SharedStrings[2112]="你见过地精吗，$n？这些邪恶的绿皮小怪物只喜欢两件东西：金币和他们自己。$B$B黑石兽人招募了一批地精刺客，屠杀我们的士兵。他们就潜伏在北面的草丛中，肉眼很难察觉。$B$B我要你去那里，杀死你撞见的所有地精。得给他们上一课，联盟不是好惹的！"
D.SharedStrings[2113]="你觉得很有趣。"
D.SharedStrings[2114]="你觉得斯科瓦尔德不希望你发现这颗水晶，是吗？我来瞧瞧。$B$B<卡德加眯着眼睛检查邪能水晶碎片，寻找其中流淌的能量痕迹。>$B$B我见过这种水晶，它们是用来传达燃烧军团最高阶指挥官的命令的。$B$B这可不妙。"
D.SharedStrings[2115]="你解决掉了陆地和天空的敌人，甚至还有雷雨。接下来你将面对你脚底下的动物。$B$B岩虫是一种狡猾的捕食者，它们喜欢从沙土底下钻出来袭击敌人。在纳格兰，很多野兽都学会了注意脚底下的动静。带你的座狼去那边的沙滩，尝试干掉那里的老岩虫：铁钻。"
D.SharedStrings[2116]="你說得也有道理，$n。但我的決心不會動搖。"
D.SharedStrings[2117]="你讓他們離開了？我好高興。我也不喜歡被關在籠裡…"
D.SharedStrings[2118]="你证明了我们对抗天灾军团的承诺，不管我们在哪，也不管我们在做什么。"
D.SharedStrings[2119]="你说什么，$r?安努尼亚克派你来的?$B$B很好，很好……有很多事情等着处理。我们用得上所有的帮手!"
D.SharedStrings[2120]="你说过交叉光是不好的"
D.SharedStrings[2121]="你说，是一颗珍珠？好吧，让我仔细瞧瞧……"
D.SharedStrings[2122]="你调查过入侵行动了吗?没有时间可以浪费了!"
D.SharedStrings[2123]="你赢得了我要找的剑吗?"
D.SharedStrings[2124]="你赢得了那把剑吗?"
D.SharedStrings[2125]="你距离活体流星太近，引发它爆炸了！"
D.SharedStrings[2126]="你身上全给烟灰弄脏了!你想必已经扑灭了那些火焰!$B$B干得好!身为一个救火队的荣誉成员，我请求你在村庄需要你的时候回来帮助我们!"
D.SharedStrings[2127]="你身处攻击盲区中。\r\n命中和被击中的几率降低{1}%。"
D.SharedStrings[2128]="你轻松地将从护锅领主拜尔摩那里拿来的钥匙插进控制板里，但是随即它就消失了。尽管如此，你却已经可以不用钥匙就打开控制板了。随着一种未知的浓缩混合剂在瘟疫之锅中翻腾，腐烂的恶臭气息从打开的控制板里散发了出来。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为冰风岗的高阶牧师玛多妮尔带回一份样品。"
D.SharedStrings[2129]="你辦到了，$n。你成功殺死了海潮祭司並從沙許塔爾納迦手中拯救了詹德維克。"
D.SharedStrings[2130]="你辨认出来，这是一个被召唤的恶魔的精华。$b$b难以理解的危险能量在它的表面吐纳。$b$b你瞧着它，脑子里出现了一幅影像——你自己控制着恶魔的影像。一想象要使用这样的力量，激动之情就掠过你的全身。$b$b你四下看了看，试图找到能够用来对付这名恶魔敌人的宝贝……"
D.SharedStrings[2131]="你还等什么?快擦在身子上!$B$B快呀!不然他就要看到你了!"
D.SharedStrings[2132]="你进入了PvP混乱区域。如果不离开这片区域，很快你将被标记为可以进行PvP战斗。"
D.SharedStrings[2133]="你进入了先知加德拉的幻象。"
D.SharedStrings[2134]="你进入了星界位面！"
D.SharedStrings[2135]="你造成的所有伤害提高{1}%。"
D.SharedStrings[2136]="你遭受了猛烈的射击火力！"
D.SharedStrings[2137]="你钩住了什么东西。"
D.SharedStrings[2138]="你铸造出骷髅钥匙的主体部分了吗?很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天灾军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最后一件物品了。$B$B虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。"
D.SharedStrings[2139]="你闻起来真是恶臭无比。"
D.SharedStrings[2140]="你防护大锅行为使盎迦猴岛的猢狲不得不背水一战。近战攻击、远程攻击和施法速度提高{1}%。"
D.SharedStrings[2141]="你阻止蓝龙军团与复仇军的协议了吗?"
D.SharedStrings[2142]="你除掉了天灾执旗者与它们的爪牙?很好，我们的战备必须立刻重新进行。"
D.SharedStrings[2143]="你顺利地中和了一批瘟疫样本了吗，$C?"
D.SharedStrings[2144]="你领着一小群涂了油的牦牛。"
D.SharedStrings[2145]="佩妮·殴底"
D.SharedStrings[2146]="佩妮洛普·希斯罗"
D.SharedStrings[2147]="佩戴一个狗头人颅骨，表明你是他们的一名指挥官。"
D.SharedStrings[2148]="佩罗萨恩之眼"
D.SharedStrings[2149]="佳莉娅·米奈希尔"
D.SharedStrings[2150]="使30码范围内的盟友获得吸血光环的效果。"
D.SharedStrings[2151]="使一个卓格巴尔奴隶的灵魂得以解脱。"
D.SharedStrings[2152]="使一个技巧娴熟的工程师在采矿、剥皮或采集草药时有一定几率可以收集到动燃空气。"
D.SharedStrings[2153]="使一个敌人变形为琥珀巨兽，生命值大幅度提高，并使目标攻击其盟友。"
D.SharedStrings[2154]="使一个敌人锁定施法者。在施法者被目标锁定期间，施法者会很不愿意攻击其他的目标。"
D.SharedStrings[2155]="使一具尸体爆炸，对所有尸体附近的敌人造成{1}点暗影伤害。"
D.SharedStrings[2156]="使一名敌人凝视着施法者。在目标被施法者凝视的期间内，目标会很不愿意攻击其他的目标。"
D.SharedStrings[2157]="使一名敌人定身，每秒造成{1}点自然伤害。"
D.SharedStrings[2158]="使一名敌人的命中几率降低{1}%。\r\n使一名敌人的法术命中几率降低{2}%。"
D.SharedStrings[2159]="使一名敌方目标昏迷。"
D.SharedStrings[2160]="使一名正在攻击的敌人中毒，同时可能在其武器上喷洒毒液。"
D.SharedStrings[2161]="使一名玩家可以学习每日熊猫人烹饪。"
D.SharedStrings[2162]="使一条游荡的冰虫进入灵体状态，供安格里姆吞食。"
D.SharedStrings[2163]="使下一次近战攻击造成{1}点额外的自然伤害。"
D.SharedStrings[2164]="使主人发送事件的讯息。"
D.SharedStrings[2165]="使任何沉默或打断效果对装备者的影响时间缩短{1}%。"
D.SharedStrings[2166]="使任何沉默或打断效果对装备者的影响时间缩短{1}%。这个效果不与其它同类效果叠加。"
D.SharedStrings[2167]="使任何腐蚀信徒的血液化脓，导致古神之血从凝固的血液中形成，并使腐蚀信徒的血液开始沸腾。"
D.SharedStrings[2168]="使伊利达雷议会成员之间的能量达到平衡。议会成员互相分享生命值。"
D.SharedStrings[2169]="使你不会被圣城恩其拉中的大部分天灾士兵发现。只能在圣城恩其拉中使用。"
D.SharedStrings[2170]="使你伪装成熔火爬行者。\r\n\r\n只能在德拉诺使用。"
D.SharedStrings[2171]="使你伪装成熔火爬行者。\r\n\r\n只能在格罗姆加尔使用。"
D.SharedStrings[2172]="使你免疫霜风戈壁的住民所施放的毒素。"
D.SharedStrings[2173]="使你受到的伤害降低{1}%。"
D.SharedStrings[2174]="使你变成座狼的外形。除了血齿座狼以外的其它生物都可以看穿这种伪装。许多行动，包括战斗和施放增益法术，都会取消伪装效果。"
D.SharedStrings[2175]="使你可以从奥尔杜萨的诅咒教徒的尸体上收集被污染的精华。"
D.SharedStrings[2176]="使你可以在德拉诺从不同的树木上收集木材。"
D.SharedStrings[2177]="使你可以在水上行走。"
D.SharedStrings[2178]="使你可以在水下呼吸，并且在海底的移动速度提高{1}%。只能在悲伤沼泽使用。"
D.SharedStrings[2179]="使你可以在萨格隆看到幽灵状态下艾露恩的信徒。"
D.SharedStrings[2180]="使你可以看得更远。"
D.SharedStrings[2181]="使你可以看得更远。右键点击增益图标以在千里眼和普通视野之间切换。"
D.SharedStrings[2182]="使你可以训练战斗宠物，进行宠物对战，并且可以在地图上追踪战斗宠物。"
D.SharedStrings[2183]="使你可以通过猎鹰的眼睛来观察世界，并控制猎鹰的行动。"
D.SharedStrings[2184]="使你在咒法师马戈斯处的声望提高{1}点。"
D.SharedStrings[2185]="使你在珍珠湖或蓝玉号船骸处可以进行水下呼吸。"
D.SharedStrings[2186]="使你在瓦丝琪尔可以进行水下呼吸，且移动速度提高{1}%。"
D.SharedStrings[2187]="使你在破碎群岛可以进行水下呼吸，且在水下的移动速度提高{1}%。"
D.SharedStrings[2188]="使你在翡翠林可以进行水下呼吸，且游泳速度提高{1}%。"
D.SharedStrings[2189]="使你在翡翠林可以进行水下呼吸，且移动速度提高{1}%。"
D.SharedStrings[2190]="使你对目标施放毒药的几率提高{1}%。"
D.SharedStrings[2191]="使你抵抗恐惧效果的几率提高{1}%。"
D.SharedStrings[2192]="使你抵抗沉默和打断效果的几率提高{1}%。"
D.SharedStrings[2193]="使你抵抗移动限制效果的几率提高{1}%。"
D.SharedStrings[2194]="使你拆卸技能的冷却时间缩短。"
D.SharedStrings[2195]="使你消失并进入强化潜行模式，持续3秒。消失后的最初3秒内，受到的伤害和有害效果都不会取消潜行。同时解除一切移动限制效果。"
D.SharedStrings[2196]="使你的PvP强度提高{1}点（唯一）。"
D.SharedStrings[2197]="使你的下一个氤氲之雾的消耗降低{1}%。"
D.SharedStrings[2198]="使你的下一次嗜血或暴怒额外击中最多{1}个目标，造成{2}%的伤害。"
D.SharedStrings[2199]="使你的下次攻击获得{1}次额外的攻击机会。"
D.SharedStrings[2200]="使你的全能提高{1}。"
D.SharedStrings[2201]="使你的切割技能的加速效果提高{1}%。"
D.SharedStrings[2202]="使你的圣光道标转移的治疗效果提高{1}%。"
D.SharedStrings[2203]="使你的坐骑更具节日气氛。"
D.SharedStrings[2204]="使你的奔跑速度提高{1}%。"
D.SharedStrings[2205]="使你的宠物的伤害提高{1}%。"
