D.SharedStrings[2223]="使你的真言术：盾能将所吸收的部分伤害反射给攻击者。该伤害不会产生威胁。"
D.SharedStrings[2224]="使你的神圣法术的爆击几率提高{1}%。"
D.SharedStrings[2225]="使你的腐蚀术和献祭造成的伤害提高{1}%。"
D.SharedStrings[2226]="使你能挖掘最远30码距离的矿物。只能在潘达利亚使用。"
D.SharedStrings[2227]="使你获取的黑王子阵营声望提高{1}%。使黑王子的死敌有更高的几率掉落帝国秘史、智慧印记、力量印记或泰坦符文石。"
D.SharedStrings[2228]="使你获得{1}%的基础法力值。"
D.SharedStrings[2229]="使你获得{1}点法力值。"
D.SharedStrings[2230]="使你获得恶魔的能量，所有近战攻击都可以从目标身上吸取生命值。"
D.SharedStrings[2231]="使你获得能够随波漂流的能力。\r\n\r\n在漂流过程中跳跃可以划动筏子，使你的移动速度最多提高130%。"
D.SharedStrings[2232]="使你躲闪攻击的几率提高100%。"
