D.SharedStrings[2235]="使你造成的伤害提高[abilityStateMod(23, 1391)]%，受到的伤害提高[abilityStateMod(24, 1391)]%。"
D.SharedStrings[2236]="使你造成的伤害提高[abilityStateMod(23, 970)]%，受到的伤害提高[abilityStateMod(24, 970)]%。"
D.SharedStrings[2237]="使你造成的伤害提高{1}%。"
D.SharedStrings[2238]="使你避开攻击的几率提高[abs(abilityStateMod( 73, 311 ))]%。"
D.SharedStrings[2239]="使你飞向空中，展开魔法之翼。只能在德拉诺使用。"
D.SharedStrings[2240]="使使用者免受坠落伤害。"
D.SharedStrings[2241]="使勇士的物品等级提高{1}级，最高可以达到900级。"
D.SharedStrings[2242]="使勇士的物品等级提高{1}级，最高可达到850。"
D.SharedStrings[2243]="使半径10码范围内的所有敌人受到{2}点伤害！"
D.SharedStrings[2244]="使受到伤害的敌人身边另一个目标分担{1}%火焰武器伤害。"
D.SharedStrings[2245]="使受到伤害的敌人身边的另一个目标也受到{1}%的火焰武器伤害。"
D.SharedStrings[2246]="使周围全部单位的生命值减少最大生命值的5%。"
D.SharedStrings[2247]="使周围盟友获得微光血的效果。\r\n技能的冷却时间缩短为标准时间的一半。\r\n攻击速度提高{1}%。"
D.SharedStrings[2248]="使坎雷萨德·埃伯洛克成为你的勇士。"
D.SharedStrings[2249]="使埃里戈尔·黎明使者成为你的勇士。"
D.SharedStrings[2250]="使塔尔达斯承受巨大的痛苦，削弱他的抵抗意志。"
