D.SharedStrings[2253]="使宠物造成的伤害提高{1}点。"
D.SharedStrings[2254]="使对联结目标造成的{1}%伤害反射到你身上，且该伤害类型为暗影伤害。"
D.SharedStrings[2255]="使小鳄鱼造成持续型伤害，并降低目标的移动速度。"
D.SharedStrings[2256]="使强大的旋风造成自然伤害，并将玩家击退。"
D.SharedStrings[2257]="使当前目标复制施法者。"
D.SharedStrings[2258]="使徒德瑞纳萨"
D.SharedStrings[2259]="使总体地面移动速度增加{1}。"
D.SharedStrings[2260]="使憎恶爆炸，杀死周围的所有达卡莱裂颅者。"
D.SharedStrings[2261]="使憎恶爆炸，杀死莫德雷萨下面的天灾单位。"
D.SharedStrings[2262]="使所有攻击命中你的几率降低{1}%。"
D.SharedStrings[2263]="使所有盟友单位的生命值、伤害和治疗效果提高{1}%。"
D.SharedStrings[2264]="使所有邻近敌人的移动速度降低{1}%。"
D.SharedStrings[2265]="使所有附近敌人所造成的伤害和治疗效果降低{1}%。"
D.SharedStrings[2266]="使护甲值提高{1}点，冰霜抗性提高{2}点，并可令攻击者减速。"
D.SharedStrings[2267]="使接地场偏转指向其内部单位的任何法术。"
D.SharedStrings[2268]="使携带者可以看到最近死去的人的灵魂。"
D.SharedStrings[2269]="使携带者能在空中飞行。着陆后对所有敌人造成伤害，并使其攻击和移动速度降低。效果随飞行时间而提升。"
D.SharedStrings[2270]="使敌人体内的噩梦毒素爆发，造成自然伤害并使目标产生蜘蛛幻觉。大蜘蛛。"
D.SharedStrings[2271]="使敌人包围在钢铁旋风之中。对附近所有单位造成物理伤害。"
D.SharedStrings[2272]="使施法者受到伤害，对周围的敌人造成火焰伤害，将其击退。"
D.SharedStrings[2273]="使施法者可以漂浮在地面上，漂浮时下落速度减缓并且可以在水面行走。"
D.SharedStrings[2274]="使施法者注视当前目标，令施法者只攻击该目标。"
D.SharedStrings[2275]="使施法者的攻击和施法速度提高{1}%并使其造成的物理伤害提高{2}%。"
D.SharedStrings[2276]="使施法者的攻击和施法速度提高{1}%，造成的伤害提高{2}%。"
D.SharedStrings[2277]="使施法者的攻击和移动速度提高{1}%，对敌人造成的所有伤害提高{2}%。并且免疫嘲讽。"
D.SharedStrings[2278]="使施法者的攻击获得狂怒效果，攻击速度提高{1}%。"
D.SharedStrings[2279]="使施法者的武器神圣化，下一次攻击会造成额外伤害。所有造成的伤害都被视作神圣法术。"
D.SharedStrings[2280]="使施法者的躲闪几率提高{1}%。"
D.SharedStrings[2281]="使施法者的躲闪几率提高{1}%。效果一直持续，直到取消。"
D.SharedStrings[2282]="使施法者的近战攻击有一定几率降低目标受到的治疗效果。"
D.SharedStrings[2283]="使施法者的近战攻击速度和施法速度提高{1}%，最多叠加20次。"
D.SharedStrings[2284]="使施法者看起来像是一只小动物。"
D.SharedStrings[2285]="使施法者获得{1}次额外的攻击机会。"
D.SharedStrings[2286]="使施法者被一层岩石地幔包围，吸收所受伤害。地幔包围时，提高造成的伤害。"
D.SharedStrings[2287]="使施法者被强风包围，熄灭火焰并抵御敌人。"
D.SharedStrings[2288]="使施法者躲闪的几率提高{1}%。"
D.SharedStrings[2289]="使施法者进入潜行状态。"
D.SharedStrings[2290]="使施法者进入潜行状态。持续直到取消。"
D.SharedStrings[2291]="使施法者进入潜行状态。效果一直持续到取消为止。"
D.SharedStrings[2292]="使施法者进入潜行状态。效果将一直持续直到取消。"
D.SharedStrings[2293]="使施法者进入潜行状态。直至取消。"
D.SharedStrings[2294]="使施法者进入潜行状态，但是移动速度降低{1}%，效果一直持续到取消为止。"
D.SharedStrings[2295]="使施法者进入潜行状态，但是移动速度降低到普通速度的{1}%，效果一直持续到取消为止。"
D.SharedStrings[2296]="使施法者造成的物理伤害降低{1}点，近战攻击速度提高{2}%。"
D.SharedStrings[2297]="使施法者面前的大地裂开，2秒后突现出一根冰霜尖刺。"
D.SharedStrings[2298]="使施法者高高跃起，着陆时对附近所有敌人造成物理伤害。"
D.SharedStrings[2299]="使智力提高{1}点。"
D.SharedStrings[2300]="使灵魂回到躯体中，让已死的目标起死回生，并为其恢复{1}%的生命值和{2}%的法力值。"
D.SharedStrings[2301]="使灵魂回归肉体，复活一名死去的目标恢复其最大生命值和法力值的35%。无法在战斗中施放。"
