D.SharedStrings[2304]="使爆裂熔炉的热能提高{1}点。"
D.SharedStrings[2305]="使玩家可以通过雷松之眼从空中观察联盟的要塞，需与占卜之球配合使用。"
D.SharedStrings[2306]="使玩家可以通过雷松之眼从空中观察部落的要塞，需与占卜之球配合使用。"
D.SharedStrings[2307]="使珠宝匠有一定几率将优秀品质的诺森德宝石切割成完美宝石。"
D.SharedStrings[2308]="使用2份莫克纳萨肋排和1份香脆蛇来烹制一些恶魔烧烤。"
D.SharedStrings[2309]="使用SGM-3摧毁6架破天号侦查机，然后向奥格瑞姆之锤的掠天者考尔姆·黑痕复命。"
D.SharedStrings[2310]="使用XE-321爆破机器人，在12秒内击败20个XS-013废料机器人（10人）。"
D.SharedStrings[2311]="使用XE-321爆破机器人，在12秒内击败20个XS-013废料机器人（25人）。"
D.SharedStrings[2312]="使用一个箭靶作为盾牌。\r\n不能施法或攻击。\r\n移动速度降低{1}%。"
D.SharedStrings[2313]="使用一阵猛烈的强风打击敌人，对其造成自然伤害。"
D.SharedStrings[2314]="使用不同的法力药水"
D.SharedStrings[2315]="使用两把圣化长剑净化大检察官怀特迈恩，令她永远安息。"
D.SharedStrings[2316]="使用之后会制作出骨质雕像，用来召唤千面吞噬者。"
D.SharedStrings[2317]="使用传送门前往黑暗神殿并与阿卡玛对战。"
D.SharedStrings[2318]="使用你的孤儿哨召唤德莱尼孤儿。"
D.SharedStrings[2319]="使用你的攻城撞锤进行攻击，对附近的敌人造成21000到35000点物理伤害。"
D.SharedStrings[2320]="使用你的赛车上的撞锤去摧毁其他人的打架赛车。"
D.SharedStrings[2321]="使用你的铁钩和锁链抓住已锁定为目标的箱子。"
D.SharedStrings[2322]="使用你的银色宝典中蕴含着的神圣智慧力量攻击敌人。"
D.SharedStrings[2323]="使用侦察地图，完成“加尔顿的需求”任务。"
D.SharedStrings[2324]="使用侦察地图，完成“部队出勤”任务。"
D.SharedStrings[2325]="使用侦察地图，完成任务“破碎海滩的威胁”。"
D.SharedStrings[2326]="使用储备铁块制造4块马蹄铁，然后给暗月马戏团的贝贝安上马蹄铁。"
D.SharedStrings[2327]="使用先祖硬币购买一件节日裤装或者节日裙装。"
D.SharedStrings[2328]="使用凯旋石板，获得奈萨里奥的巢穴内所有有名字蜗牛的足迹。"
D.SharedStrings[2329]="使用创世者的图书馆中的原型机控制台。"
D.SharedStrings[2330]="使用创世者的圆盘，从数据库中获得7条秘密数据。"
D.SharedStrings[2331]="使用刽子手的精华强化逆风收割者。"
D.SharedStrings[2332]="使用副本工具组织野队来完成随机的英雄难度地下城，累积组到的随机玩家数量达到100名。"
D.SharedStrings[2333]="使用副本工具组织野队来完成随机的英雄难度地下城，累积组到的随机玩家数量达到10名。"
D.SharedStrings[2334]="使用副本工具组织野队来完成随机的英雄难度地下城，累积组到的随机玩家数量达到50名。"
D.SharedStrings[2335]="使用动作条上的技能来攻击其它遥控玩具。"
D.SharedStrings[2336]="使用动力贩子，在钟响20下之前完成铁人拉力赛。"
D.SharedStrings[2337]="使用动力贩子，在钟响25下之前完成铁人拉力赛。"
D.SharedStrings[2338]="使用动力贩子，在钟响30下之前完成铁人拉力赛。"
D.SharedStrings[2339]="使用动力贩子，在钟响40下之前完成铁人拉力赛。"
D.SharedStrings[2340]="使用发射器发射烟花。"
D.SharedStrings[2341]="使用召唤法阵召唤一只虚空行者。"
D.SharedStrings[2342]="使用召唤法阵召唤一只魅魔。"
D.SharedStrings[2343]="使用召唤者号角召唤7匹黑石作战科多兽返回营地。如果哪只科多兽怀有敌意，就迫使它屈服。"
D.SharedStrings[2344]="使用呼啸的气旋的力量消灭元素勋爵玛格玛萨。"
D.SharedStrings[2345]="使用嘲颅药剂找到割颅者，并取得寂静之颅。"
D.SharedStrings[2346]="使用塔贝萨的火炬烧毁恐角岗哨的北部帐篷、东部帐篷和东北部帐篷。"
D.SharedStrings[2347]="使用大地之盾保护目标。当受保护的目标受到伤害时，为其恢复{1}%的最大生命值。"
D.SharedStrings[2348]="使用天空卫队炸弹炸毁15堆邪能炮弹。"
D.SharedStrings[2349]="使用奥术魔法冲击一名敌人，造成{1}点奥术伤害。"
D.SharedStrings[2350]="使用奥术魔法冲击一名敌人，造成普通伤害再加上{1}点伤害，并将其击退。"
D.SharedStrings[2351]="使用女王的优雅织布机，将你收集的丝线和布料缝合在一起。"
D.SharedStrings[2352]="使用小动物的零食，在3分钟内诱使10只小动物成为你的宠物。"
D.SharedStrings[2353]="使用巨大的木桩敲击前方地面，对附近的敌人造成{1}%武器伤害。"
D.SharedStrings[2354]="使用建筑设计桌选择议政厅，并将你的要塞升至2级。"
D.SharedStrings[2355]="使用引爆器炸开监狱列车，说服拉克加入你们。"
D.SharedStrings[2356]="使用强劲的奥术能量猛击地面。"
D.SharedStrings[2357]="使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。$B$B一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。"
D.SharedStrings[2358]="使用整修过的攻城车，在失落希望之谷里消灭150只腐朽的食尸鬼、20个霜颅大法师和2个白骨巨人。完成任务之后前往第一军团前线营地，与米斯希尔萨·阿奈尔谈一谈。"
D.SharedStrings[2359]="使用春季花朵，为不低于18级的女性戴上兔耳朵。"
D.SharedStrings[2360]="使用春季长袍，在下列沙漠地区种植花朵。"
D.SharedStrings[2361]="使用暗影魔法攻击敌人，对其造成暗影伤害。"
D.SharedStrings[2362]="使用暗影魔法攻击附近的敌人，造成暗影伤害。"
D.SharedStrings[2363]="使用月神镰刀，从一个有意志的灵魂上移除古老的诅咒。"
D.SharedStrings[2364]="使用机枪攻击。\r\n命中几率降低{1}%。"
D.SharedStrings[2365]="使用死亡一指攻击一名敌人，对该敌人及其祖宗八辈都造成{1}点暗影伤害。"
D.SharedStrings[2366]="使用法师传送门"
D.SharedStrings[2367]="使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。"
D.SharedStrings[2368]="使用泡沫冲击一个敌人，造成冰霜伤害。"
D.SharedStrings[2369]="使用混乱能量腐蚀并控制目标。"
D.SharedStrings[2370]="使用源质之斧砍断禁锢莉拉斯塔萨的镣铐。"
D.SharedStrings[2371]="使用漫游专家滑翔机在空中停留超过10秒。"
D.SharedStrings[2372]="使用漫游专家，在钟响20下之前完成铁人拉力赛。"
