D.SharedStrings[2400]="使用自然的力量治疗一名盟友。"
D.SharedStrings[2401]="使用自然的力量治疗盟友。"
D.SharedStrings[2402]="使用致命的钢铁陷阱捕捉一只铁皮公牛、恐牙头狼或湿地践踏者。"
D.SharedStrings[2403]="使用血色火炮的能量释放强大的全方位电磁脉冲，消灭附近的所有敌人。"
