D.SharedStrings[2429]="使用黑暗魔法立即鞭笞一个敌人，造成暗影伤害。"
D.SharedStrings[2430]="使用黑石炮台。"
D.SharedStrings[2431]="使用黑石爪钩抵达纳尔的碉堡。杀死他并夺取拉克的船坞图纸。"
D.SharedStrings[2432]="使用黑石训诫棒杀死5名黑石中士。速战速决，在你暴露身份之前杀死他们。"
