D.SharedStrings[2435]="使用龙喉哨站的传送门前往奥格瑞玛，向萨鲁法尔大王报告。"
D.SharedStrings[2436]="使用：为你的《魔兽世界》账号添加30天游戏时间。"
D.SharedStrings[2437]="使目标使用近战武器攻击所造成的伤害降低{1}%。"
D.SharedStrings[2438]="使目标充满力量，施法速度提高{1}%，移动速度提高{2}%。"
