D.SharedStrings[2461]="使祖阿曼所有的妖术受害者恢复原形（英雄难度）。"
D.SharedStrings[2462]="使移动速度提高{1}%，并且免疫暗影伤害和移动限制效果。"
D.SharedStrings[2463]="使移动速度降低{1}%。\r\n每2秒造成{2}点暗影伤害。"
