D.SharedStrings[2465]="使绽放的冰霜对一片区域造成冰霜伤害，并使敌人的攻击和移动速度降低。"
D.SharedStrings[2466]="使萨满祭司可以看到元素之灵。"
D.SharedStrings[2467]="使蒸汽发动机在短时间内超速运转，向前冲锋。"
D.SharedStrings[2468]="使蒸汽发动机在短时间内超速运转，向前冲锋，对敌人造成攻城伤害，并将它们击退。"
D.SharedStrings[2469]="使装备者可以在水下呼吸。必须在匕鞘湾的浮筒有效范围内。"
D.SharedStrings[2470]="使装备者可以在水下呼吸，并提高{1}%的游泳速度。头盔已经破了，坚持不了太久。"
