D.SharedStrings[2475]="使近战攻击可以造成额外的物理伤害，由有效范围内的所有目标平均分摊伤害。"
D.SharedStrings[2476]="使造成的伤害提高{1}%。"
D.SharedStrings[2477]="使造成的所有伤害提高{1}%，受到的伤害提高{2}%。"
D.SharedStrings[2478]="使造成的物理伤害提高{1}点。"
D.SharedStrings[2479]="使铁匠可以制造基本的武器和护甲，技能上限为75点。需要通过采矿得到的石块和金属。"
D.SharedStrings[2480]="使附近所有迷雾化身消散。"
