D.SharedStrings[2501]="侦察地图"
D.SharedStrings[2502]="侦查圆形平台的西北边缘，以及北部主台阶下的隧道。这两个地点都在废墟的中层。"
D.SharedStrings[2503]="侦查暮光海滩的滩头控制点。你不必占领控制点，但是成功占领的话，你会被标记为开启PvP状态，且你所在的营地可以获得作战优势。"
D.SharedStrings[2504]="侦测元素之魂。"
D.SharedStrings[2505]="侦测次级隐形药剂"
D.SharedStrings[2506]="侵入点：博尼克"
D.SharedStrings[2507]="侵入点：奈格塔尔"
D.SharedStrings[2508]="侵入点：奥雷诺"
D.SharedStrings[2509]="侵入点：萨古亚"
D.SharedStrings[2510]="侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。"
D.SharedStrings[2511]="便携式世界毁灭者"
D.SharedStrings[2512]="便携式洒弹器"
D.SharedStrings[2513]="便携式的降落伞，在施法者开始降落时自动打开。"
D.SharedStrings[2514]="便携式邪能散播器"
D.SharedStrings[2515]="俄瑞斯忒斯对一个目标施以死亡标记，使其受到15%的额外伤害。"
D.SharedStrings[2516]="保卫国王的领土"
D.SharedStrings[2517]="保卫艾欧娜尔（史诗安托鲁斯，燃烧王座）"
D.SharedStrings[2518]="保卫艾欧娜尔（普通安托鲁斯，燃烧王座）"
D.SharedStrings[2519]="保卫艾欧娜尔（英雄安托鲁斯，燃烧王座）"
D.SharedStrings[2520]="保卫艾欧娜尔（随机安托鲁斯，燃烧王座）"
D.SharedStrings[2521]="保护一位友方目标，使最多3个正在攻击该目标的敌人转而攻击圣骑士。"
D.SharedStrings[2522]="保护使用者不会受到跌落伤害，直到使用者着陆。"
D.SharedStrings[2523]="保护它的幼崽，使其受到的所有伤害降低{1}%。"
D.SharedStrings[2524]="保护施法者不受任何物理和魔法伤害。"
D.SharedStrings[2525]="保护施法者免受一切伤害和效果影响。"
D.SharedStrings[2526]="保护施法者免遭所有物理和魔法伤害，直到取消为止。"
D.SharedStrings[2527]="保护符石作用范围内的玩家免于承受一切敌对火焰效果。摧毁符石会让附近的敌人暂时昏迷。"
D.SharedStrings[2528]="保护者之路"
D.SharedStrings[2529]="保护预言者努波顿，抵御燃烧军团的袭击。"
D.SharedStrings[2530]="保持船体的稳定端正，使其能够轻松地穿越漩涡乱流。"
D.SharedStrings[2531]="保证内有一件贵重物品！"
D.SharedStrings[2532]="信徒刀翼战士"
D.SharedStrings[2533]="修复并展示所有古朴的德拉诺氏族遗物。"
D.SharedStrings[2534]="修复并展示所有古朴的熊猫人和魔古族遗物。"
D.SharedStrings[2535]="修理商"
D.SharedStrings[2536]="修理机器人74A型"
D.SharedStrings[2537]="俾格米伏击者"
D.SharedStrings[2538]="倒下的月之守卫的精华大幅度强化了伊利丹。\r\n所有伤害提高{1}%。"
D.SharedStrings[2539]="倒转时光之眼沙漏。"
D.SharedStrings[2540]="倒霉的迪菲亚强盗"
D.SharedStrings[2541]="倾听晓和他同伴们的谈话。"
D.SharedStrings[2542]="倾泻出徽记的力量吧，让敌人听到你的声音，让他们被你震慑。部落的力量不容蔑视!"
D.SharedStrings[2543]="假如你带来的作战计划是真的，那么除钢铁部落外，巨槌食人魔同样要为这场惨剧负责。是该给这些食人魔提个醒了。$B$B这些食人魔和钢铁部落的主要联络人似乎是巨槌要塞里面一个叫碎牙的食人魔。$B$B杀了他就能给他们的作战计划带来巨大的打击。"
D.SharedStrings[2544]="假日活动：时空漫游"
D.SharedStrings[2545]="假面狸猫幼崽"
D.SharedStrings[2546]="偏转对三角龙正面所施放的所有法术。"
D.SharedStrings[2547]="偏转并格挡所有正面攻击。\r\n无法移动或转动。"
D.SharedStrings[2548]="偏转来自前方的攻击。"
D.SharedStrings[2549]="做得好!你很快就可以成为一名火焰杂耍师了!下一次的考验就是来真的了……"
D.SharedStrings[2550]="做得好。在他們把援軍找來之前我們趕快離開吧。"
D.SharedStrings[2551]="做得好。有時候一場簡單的勝利就能把軍隊團結起來。接下來，這些新兵就會開始訓練其他人，我們軍隊的規模就會越來越大。"
D.SharedStrings[2552]="做得好，$C。$B$B也许透过些适当地调查，我们便能发现他们如何让这样的生物来到世上。"
D.SharedStrings[2553]="做得好，$C。那个通道是我们通往那片沼泽的重要路线。$B"
D.SharedStrings[2554]="做得好，$N。这应该会让港口有一阵子不会出现援军。"
D.SharedStrings[2555]="做得好，$r。但别太志得意满了。他们随时会派人取代这些监督者…"
D.SharedStrings[2556]="做得很好，我的朋友。$B$B就在我们的对谈期间，信差又进来回报信息了。"
D.SharedStrings[2557]="做得非常好。他們不尊重狩獵，所以必須藉此提醒他們自己的定位。"
D.SharedStrings[2558]="做的好，$N。我们不用再担心阿拉卡什么时候又会引诱我们的商人和信差了。"
D.SharedStrings[2559]="做的好，$N。请接受这个代表塞纳里奥议会的象征。这是你应得的，朋友!"
D.SharedStrings[2560]="做的好，$N。这是你的下一个任务。"
D.SharedStrings[2561]="健壮的风暴幼龙"
D.SharedStrings[2562]="健忘的勘察员"
D.SharedStrings[2563]="偷来的维库武器"
D.SharedStrings[2564]="傀儡统帅阿格曼奇"
D.SharedStrings[2565]="催人泪下的言情小说全集"
D.SharedStrings[2566]="催促毒心者夏克里尔去卡拉克西维斯。"
D.SharedStrings[2567]="傲之煞令最多5名玩家反省自身的行为，在其位置制造出一个本我具象。随着本我具象的每一跳，傲之煞都将锁定傲气值更高一级的玩家。傲之煞只锁定傲气值达到25、50和75点的目标。"
D.SharedStrings[2568]="傲慢之凝视"
D.SharedStrings[2569]="傲慢之棱光囚笼"
D.SharedStrings[2570]="像旋风一样对周围敌人释放寒冰箭，造成{1}点冰霜伤害并使其移动速度降低{2}%。"
D.SharedStrings[2571]="像旋风一般挥舞手中的武器，对身旁的敌人造成{1}%武器伤害。"
D.SharedStrings[2572]="像旋风一般挥舞手中的武器，对近战范围内的所有敌人造成{1}%的武器伤害。"
D.SharedStrings[2573]="像旋风一般挥舞手中的武器，攻击半径8码范围内的所有敌人，对每个目标都造成伤害，数值为你手持的所有近战武器的伤害之和。"
D.SharedStrings[2574]="像旋风一般挥舞手中的武器，攻击半径8码范围内的所有敌人，用两把近战武器对每个敌人都造成武器伤害。"
