D.SharedStrings[2587]="允许你前往被钢铁部落入侵之前的诅咒之地。"
D.SharedStrings[2588]="允许附近的玩家调整天赋。"
D.SharedStrings[2589]="允许骑乘战斗。"
D.SharedStrings[2590]="元水之珠接觸枯木或生命力歸零時爆發，對所有玩家造成{1}點冰霜傷害。"
