D.SharedStrings[2592]="元素愤怒号角"
D.SharedStrings[2593]="元素生物有时候也会对野兽构成威胁。即使是最强大座狼也常会被远处的雷声所惊吓。$B$B在纳格兰的海岸，有一处迎风而立的峭壁。在那峭壁上有一只由纯粹的雷雨构成的生物，它的名字叫雷鸣。骑上你的坐骑去那儿对付它，让我们瞧瞧结果如何。"
D.SharedStrings[2594]="元素的祝福"
D.SharedStrings[2595]="元素能量萃取器"
D.SharedStrings[2596]="元素萨满祭司"
D.SharedStrings[2597]="元素萨满祭司：莱维娅·劳伦斯的窘境"
D.SharedStrings[2598]="元素赋予你水上行走的能力，生命值和生命值回复速度提高。"
D.SharedStrings[2599]="元素需要你的帮助，$r！影月谷曾遭受过一场难以言喻的灾难。元素之灵至今仍在痛苦中挣扎，现在，这些被激怒的元素之灵已经不愿再继续与大地之环沟通了。$B$B朋友，帮助影月谷恢复原貌吧。$B$B蛮锤要塞东北方便是诅咒祭坛，到那里去，与大地治愈者托洛克谈谈。"
