D.SharedStrings[2631]="光靠我们自己是抵挡不了巫妖王的。分裂只会让我们全部灭亡！$B$B我请求你响应这个号召，我的$g兄弟:姐妹;。银色北伐军接受所有愿意对天灾军团作战的勇士。大领主提里奥·弗丁正在银色前线基地等待着你！跨上你的坐骑，火速飞往冰冠冰川的东南边界吧。你可以在那里找到弗丁大人和银色北伐军的部队。$B$B现在就出发吧，$c，审判日就要降临了！"
