D.SharedStrings[2710]="入侵地图标记"
D.SharedStrings[2711]="入侵的兽人可不傻。他们密切关注着我们的动向，想要抓住有利的时机发起进攻。$B$B黑石间谍就躲藏在西北方的森林里。他们利用望远镜偷窥我们的一举一动，耐心地等待着。我要你除掉他们！$B$B杀死黑石间谍！让这帮家伙明白，我们知道他们在打什么如意算盘，而且我们做好了准备！"
