D.SharedStrings[2763]="六人议会的礼物"
D.SharedStrings[2764]="兰克拉尔公爵"
D.SharedStrings[2765]="兰图克·格里姆托"
D.SharedStrings[2766]="兰多菲·摩洛克"
D.SharedStrings[2767]="兰德鲁的小巫妖"
D.SharedStrings[2768]="兰德鲁的小拆"
D.SharedStrings[2769]="兰提克的子嗣"
D.SharedStrings[2770]="兰特瑞索·火刃"
D.SharedStrings[2771]="兰达洛克的书真是让人醍醐灌顶。它记载了一个方法，可以让我们不费吹灰之力就绕过黑暗神殿的神圣屏障。\n\n我需要一点时间召唤传送门。请退后。"
D.SharedStrings[2772]="共鸣水晶"
D.SharedStrings[2773]="关于月亮井和泰达希尔的点点滴滴实在是太多了，我无法一一告知给你，这需要你自己去探索。科瑞萨斯·月怒正在等着你。我已经把你所带回来的水倒入了这个容器中，把它送到科瑞萨斯那里去吧。$b$b出发吧，科瑞萨斯就在多兰纳尔的月亮井旁。你只需要沿着奥达希尔南边的小路走出幽影谷，沿着鹅卵石铺成的小路一直走，然后向西转就行了。$b$b注意，你要一直沿着路走，$n。最近路旁的森林里出现了许多危险的野兽。"
D.SharedStrings[2774]="关于艾泽拉斯诸多荒野之神及目击情况的记录，跨越有史可考的数千载时间。"
D.SharedStrings[2775]="关闭法力熔炉：布纳尔"
D.SharedStrings[2776]="关闭法力熔炉：库鲁恩"
D.SharedStrings[2777]="关闭燃油控制阀、调节阀和主控制阀，然后再使用控制台。"
D.SharedStrings[2778]="关闭的月之守卫传送门"
D.SharedStrings[2779]="关闭设备后就可以开启控制面板，从控制台中移出主动式负载平衡器。一切准备就绪，现在你需要做的就是取得可以打开控制台的钥匙。"
D.SharedStrings[2780]="兴奋的萤火虫"
D.SharedStrings[2781]="兴盛之夜披风"
D.SharedStrings[2782]="兵临城下"
D.SharedStrings[2783]="其拉虫人和他们的奴仆所使用的装备是由最珍稀宝贵的物品制作而成的，包括古代巨兽的骨头，大地最深处的宝石，以及最坚硬纯净的金属。$B$B这些其拉神器让我有一种冲动，想要用一些这样的材料来锻炼我的技艺。向塞纳里奥议会证明你的忠诚吧，$n，我会用最好的其拉虫人材料帮你制作一把强大的武器。"
D.SharedStrings[2784]="其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。"
