D.SharedStrings[3017]="准备大干一场！\r\n受到的治疗效果降低100%。"
D.SharedStrings[3018]="准备好在明媚的阳光下大玩一场吧！"
D.SharedStrings[3019]="准备确认。$B$B准许进入星穹浑天仪。请取出你的钥匙。"
D.SharedStrings[3020]="凋萎者…對夜井的迫切渴望使他們生不如死，同時他們本身的記憶也在折磨他們。\r\n\r\n確實是比死亡更悲慘的命運…"
D.SharedStrings[3021]="凋零投掷者"
D.SharedStrings[3022]="凋零毒气对附近的所有玩家造成{1}点暗影伤害。"
