D.SharedStrings[3026]="减速。每0.5秒受到一次伤害。"
D.SharedStrings[3027]="凝结足够的琥珀会形成一个陷阱。"
D.SharedStrings[3028]="凝聚腐蚀胸甲"
D.SharedStrings[3029]="凝视者通过凝视他的对手找到了他们的弱点，使其造成的伤害提高{1}%。"
D.SharedStrings[3030]="几千年来，这种植物上深浅两色铃铛花之间的和谐共生一直是熊猫人创作诗与歌的灵感之源。"
D.SharedStrings[3031]="几年前，一个名叫卡里尔·温萨鲁斯的精灵领主独自带着几件上古精灵的神器逃离了他那饱经战乱的家乡。$B$B为了寻找这位失踪的领主，我们离开了奎尔萨拉斯的废墟，穿过燃烧平原以及广阔的海洋，最终来到了菲拉斯。$B$B我们认为他就躲在埃雷萨拉斯（现在被称为厄运之槌）的大厅里。$B$B你必须找到他，冒险者。无论他是死是活，我们必须拿回那些他所带走的东西！"
