D.SharedStrings[3214]="出列，$n！别耽误时间了，去找这些家伙谈谈，他们会向你说明一切的。"
D.SharedStrings[3215]="出大事啦！驯鹿梅森被绑架了！$B$B梅森是冬天爷爷的八头驯鹿之一，也是烟林牧场的财产。我们相信，是那个讨厌的格林奇绑架了梅森，并把它藏在了希尔斯布莱德丘陵里。由于冬幕节正在进行中，我们完全脱不开身！拜托了——请你找到梅森，击败绑匪并把它带回来！"
D.SharedStrings[3216]="出现在目标敌人身后，发动快速打击，造成{1}%的武器伤害。"
D.SharedStrings[3217]="出现在目标身后，迅速使用飞踢将其击退，并使其昏迷2秒。"
D.SharedStrings[3218]="出现在目标身后，迅速使用飞踢将其击退，并使其昏迷。"
D.SharedStrings[3219]="出纳员奥尔米达"
D.SharedStrings[3220]="出纳员普莱施尼尔"
D.SharedStrings[3221]="击中后有一定几率造成额外的神圣伤害。"
D.SharedStrings[3222]="击中敌方单位后爆炸，造成范围伤害效果。"
D.SharedStrings[3223]="击中目标的几率降低{1}%。"
D.SharedStrings[3224]="击倒。"
D.SharedStrings[3225]="击倒一名对手，造成{1}点伤害。\r\n\r\n如果目标使用细剑来招架，则该攻击将被招架，且不会造成任何伤害。"
D.SharedStrings[3226]="击杀一个目标会使神圣马驹的冷却时间缩短25%。"
D.SharedStrings[3227]="击杀一个目标可以使英勇飞跃的冷却时间降低25%。"
D.SharedStrings[3228]="击杀一名可以提供经验值的敌人会触发德欧里的祝福，持续10秒。伤害性法术或技能成功击中敌人后有一定几率恢复1%的最大生命值。"
D.SharedStrings[3229]="击杀主母萨丝琳（史诗萨格拉斯之墓）"
D.SharedStrings[3230]="击杀主母萨丝琳（普通萨格拉斯之墓）"
D.SharedStrings[3231]="击杀主母萨丝琳（英雄萨格拉斯之墓）"
D.SharedStrings[3232]="击杀主母萨丝琳（随机萨格拉斯之墓）"
D.SharedStrings[3233]="击杀会在15秒内使移动速度提高50%。\r\n\r\n只能在苏拉玛生效。"
D.SharedStrings[3234]="击杀传送门守护者哈萨贝尔（史诗安托鲁斯，燃烧王座）"
