D.SharedStrings[3566]="分裂会导致伊墨苏斯喷出邪煞软泥怪和被污染的软泥怪，并试图在房间中央重塑形体。每击杀一个邪煞软泥怪或将一个被污染的软泥怪的生命值回满，伊墨苏斯的腐蚀值就会减少1点。"
D.SharedStrings[3567]="分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$B$B我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。"
D.SharedStrings[3568]="分选者泰瑞克"
