D.SharedStrings[3591]="初级炼金师"
D.SharedStrings[3592]="初级裁缝"
D.SharedStrings[3593]="初级铁匠"
D.SharedStrings[3594]="初级附魔师"
D.SharedStrings[3595]="判决声明"
D.SharedStrings[3596]="利亚姆·格雷迈恩王子"
D.SharedStrings[3597]="利亚索斯·黑林"
D.SharedStrings[3598]="利刃翻滚效果达到10层时，对附近所有敌人造成伤害并使其昏迷。"
D.SharedStrings[3599]="利刃铁丝弹出，使目标无法移动并对其造成伤害。"
D.SharedStrings[3600]="利奥拉在战斗中被击败了。你可以在他痊愈后在兵营里重新招募他。"
D.SharedStrings[3601]="利奥拉是一个流亡的刃牙虎人萨满，他得到过埃匹希斯神器的强化。而今他在寻找新的盟友，来一展自己强大的治疗之术。"
D.SharedStrings[3602]="利尔·夜风"
D.SharedStrings[3603]="利爪之王艾吉斯"
D.SharedStrings[3604]="利爪卫士库雷克"
D.SharedStrings[3605]="利爪大德鲁伊"
D.SharedStrings[3606]="利爪德鲁伊"
D.SharedStrings[3607]="利用恶魔之力踩踏地面，对施法者前方锥形区域内的所有目标造成{1}点物理伤害，并将其击退。"
D.SharedStrings[3608]="利用星尘尾迹来召唤出赤精！"
D.SharedStrings[3609]="利维特·急刹"
D.SharedStrings[3610]="别以为我已经忘了你在纳格兰为我的族人所做的一切，$N。地狱咆哮什么都记得。$B$B为此我亏欠你许多，所以我给你一个机会:滚。离开这个地方，永远不要回头。$B$B回到你的老家去，作临死前的祷告。"
D.SharedStrings[3611]="别忘了未受抑制的力量和未被使用的力量具有一样的毁灭性，$C。穿上霜火护甲时要谨慎使用。"
D.SharedStrings[3612]="别忘了那馅料！"
D.SharedStrings[3613]="别想夺走我的天空"
D.SharedStrings[3614]="别畏惧邪恶"
D.SharedStrings[3615]="到你在影月谷的要塞与伯德里克·格雷谈一谈。"
D.SharedStrings[3616]="到你在影月谷的要塞与巴隆斯·阿历克斯顿谈一谈。"
D.SharedStrings[3617]="到你在霜火岭的要塞与战争大师佐格谈一谈。"
D.SharedStrings[3618]="到你在霜火岭的要塞与洛坎交谈。"
D.SharedStrings[3619]="到剑圣洞穴里与兰特瑞索·火刃见面。"
D.SharedStrings[3620]="到加尼罗哨站的雕像下取得你的奖赏。"
D.SharedStrings[3621]="到堕落之座找大主教玛拉达尔谈一谈。"
D.SharedStrings[3622]="到塔拉多的圣光之墓找女伯爵莉亚德琳。"
D.SharedStrings[3623]="到塔拉多的莉亚德琳哨所找女伯爵莉亚德琳谈一谈。"
D.SharedStrings[3624]="到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。"
D.SharedStrings[3625]="到奥格瑞玛的传送门"
D.SharedStrings[3626]="到奧格瑪外面的野豬農場找監督者金塔克。"
D.SharedStrings[3627]="到奧格瑪的力量谷找血衛士托雷克。"
D.SharedStrings[3628]="到奧格瑪的智慧谷和卡德里斯·尋夢者談話。"
D.SharedStrings[3629]="到奧特蘭克山脈的達拉然陷坑找博學者萊德羅斯。"
D.SharedStrings[3630]="到希尔斯布莱德丘陵去，在拉文霍德庄园后面找到药剂师斯塔弗隆·雷伦特。"
D.SharedStrings[3631]="到幽暗城的传送门"
D.SharedStrings[3632]="到戈尔隆德你的车队处，将恐惧之心交还给尖啸者卡兹。"
D.SharedStrings[3633]="到戈尔隆德的石槌奴隶营地与杜隆坦交谈。"
D.SharedStrings[3634]="到提瑞斯法林地去，将洛瑟玛·塞隆的信交给被遗忘者的首都幽暗城中的希尔瓦娜斯·风行者。"
D.SharedStrings[3635]="到提瑞斯法林地的亡灵壁垒去，向高级执行官德灵顿报到。"
D.SharedStrings[3636]="到暮光之门中的某座哨塔顶部去，发出攻击信号。"
D.SharedStrings[3637]="到暴風城的暴風要塞向安東上尉回報。"
D.SharedStrings[3638]="到暴風城的貿易區找加斯汀·德瑪利。"
D.SharedStrings[3639]="到月光林地去，与永夜港的德迪利特·星焰谈一谈。"
D.SharedStrings[3640]="到杜洛塔的野豬農場找監督者金塔克。"
D.SharedStrings[3641]="到梣谷的戰歌伐木營地找復仇者維達。"
D.SharedStrings[3642]="到沙塔斯城的圣光广场去，与新联盟营地中的拉莎莉尔主教谈一谈。"
D.SharedStrings[3643]="到沙塔斯城的圣光广场去，与新药剂师营地中的大药剂师普特雷斯谈一谈。"
D.SharedStrings[3644]="到泰達希爾的達納蘇斯墓園找興奮的夜精靈靈魂。"
D.SharedStrings[3645]="到熔岩前線上的熔爐北端找亞索·風歌。"
D.SharedStrings[3646]="到白虎寺与试炼教头罗敦交谈，然后进入试炼场。"
D.SharedStrings[3647]="到石爪山脈的蛛網小徑找加克希姆·塵鏈。"
D.SharedStrings[3648]="到纳格兰的迷时林地与大法师卡德加谈一谈。"
D.SharedStrings[3649]="到翠玉林的落英園找水墨大師老魏。"
D.SharedStrings[3650]="到艾爾文森林的明鏡湖果園找監督者賽倫德拉。"
D.SharedStrings[3651]="到苏拉玛与卡德加见面。"
D.SharedStrings[3652]="到菲拉斯的羽月要塞找學者盧索恩·紋角。"
D.SharedStrings[3653]="到藍謎島找女獵人凱拉·夜弓。"
D.SharedStrings[3654]="到虚空风暴去，与52区的虚空猎手卡尔伊谈一谈。"
D.SharedStrings[3655]="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开天灾之锅。你必须随身携带嚎哭鬼屋的空瓶来采集天灾之锅中的毒药样本。"
D.SharedStrings[3656]="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开天灾之锅。你必须随身携带盖罗恩农场的空瓶来采集天灾之锅中的毒药样本。"
D.SharedStrings[3657]="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开天灾之锅。你必须随身携带费尔斯通农场的空瓶来采集天灾之锅中的毒药样本。"
D.SharedStrings[3658]="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开天灾之锅。你必须随身携带达尔松之泪的空瓶来采集天灾之锅中的毒药样本。"
D.SharedStrings[3659]="到诅咒之地的黑暗之门下方与大法师卡德加谈一谈。"
D.SharedStrings[3660]="到贫瘠之地北部的卡德拉克那里报到。"
D.SharedStrings[3661]="到金色黎明营地向女伯爵莉亚德琳报告。"
D.SharedStrings[3662]="到锦绣谷的闻道之座外面与克罗米交谈。"
D.SharedStrings[3663]="到黑石深渊去取得10份元素精华。你应该在那些作战傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了一些有关元素生物的话题……"
D.SharedStrings[3664]="制作500件史诗物品，物品等级不得低于359。"
D.SharedStrings[3665]="制作500件史诗物品，物品等级不得低于476。"
D.SharedStrings[3666]="制作50件史诗物品，物品等级不得低于600。"
D.SharedStrings[3667]="制作一件神秘饰品。"
D.SharedStrings[3668]="制海权仍在我们的掌握之中！$b$b然而，我们需要更多的经验和资源才能继续提升这座船坞的等级。达到目标之后，我们就能提升船坞的容量，拥有更多舰船了！"
D.SharedStrings[3669]="制皮供应商"
D.SharedStrings[3670]="制皮和剥皮供应商"
D.SharedStrings[3671]="制皮训练师"
D.SharedStrings[3672]="制造{1}枚可以食用的幽暗孢子壳。"
D.SharedStrings[3673]="制造一个传送门，将使用传送门的85级或以上的队伍成员传送到托尔巴拉德。"
D.SharedStrings[3674]="制造一个传送门，将使用传送门的队伍成员传送到你的要塞。"
D.SharedStrings[3675]="制造一个传送门，将使用传送门的队伍成员传送到卡拉赞。"
D.SharedStrings[3676]="制造一个传送门，将使用传送门的队伍成员传送到奥格瑞玛。"
D.SharedStrings[3677]="制造一个传送门，将使用传送门的队伍成员传送到幽暗城。"
D.SharedStrings[3678]="制造一个传送门，将使用传送门的队伍成员传送到暴风城。"
D.SharedStrings[3679]="制造一个传送门，将使用传送门的队伍成员传送到沙塔斯城。"
D.SharedStrings[3680]="制造一个传送门，将使用传送门的队伍成员传送到破碎群岛的达拉然。"
D.SharedStrings[3681]="制造一个传送门，将使用传送门的队伍成员传送到达拉然。"
D.SharedStrings[3682]="制造一个传送门，将使用传送门的队伍成员传送到达纳苏斯。"
D.SharedStrings[3683]="制造一个传送门，将使用传送门的队伍成员传送到锦绣谷城。"
D.SharedStrings[3684]="制造一个大锅，以供公会成员制作各种合剂。\r\n\r\n如果持有魔法合成物品的玩家退出游戏超过15分钟，则该物品就会消失。"
D.SharedStrings[3685]="制造一个奥术能量源，莎拉苟萨无法抵挡这种能量的诱惑。"
D.SharedStrings[3686]="制造一个宝箱可使你远程进入公会银行。"
D.SharedStrings[3687]="制造一个强大的壁垒，保护盟友免疫任何伤害。"
D.SharedStrings[3688]="制造一个树脂之壳，所受伤害降低{1}%。"
D.SharedStrings[3689]="制造一个沙砾陷阱。它将在几秒钟后爆炸，造成自然伤害，并使受害者的命中几率在5秒钟内降低25%。"
D.SharedStrings[3690]="制造一个流沙陷阱，可造成自然伤害，并随时间扩大。"
D.SharedStrings[3691]="制造一个灵魂能量之球飞向随机敌人，轰击后造成法术暗影伤害。"
D.SharedStrings[3692]="制造一个目标NPC，如果食尸鬼碰到他，就会吃掉你的脑子。"
D.SharedStrings[3693]="制造一件优秀、精良或史诗品质的勇士护甲强化徽记。"
D.SharedStrings[3694]="制造一件适用于你职业的T17灵魂绑定物品。"
D.SharedStrings[3695]="制造一件适用于你职业的T18灵魂绑定物品。"
D.SharedStrings[3696]="制造一件适用于你职业的T19灵魂绑定物品。"
D.SharedStrings[3697]="制造一件适用于你职业的T20灵魂绑定物品。"
D.SharedStrings[3698]="制造一件适用于你职业的T21灵魂绑定物品。"
D.SharedStrings[3699]="制造一团催眠气体的云雾，使任何进入其中的敌人昏睡。受到伤害或离开云雾都会移除该效果。"
D.SharedStrings[3700]="制造一座火山。"
D.SharedStrings[3701]="制造一株喷酸草，它会向逼近的僵尸喷吐酸液。"
D.SharedStrings[3702]="制造一次以施法者为中心的魔法爆炸，对附近的敌人造成{1}点奥术伤害。"
D.SharedStrings[3703]="制造一次以施法者为中心的魔法爆炸，对附近的敌人造成{1}点奥术伤害，并将他们击退。"
D.SharedStrings[3704]="制造一次以施法者为中心的魔法爆炸，对附近的敌人造成奥术伤害。"
D.SharedStrings[3705]="制造一次圣光能量爆炸，对邻近的敌人造成{1}点神圣伤害。"
D.SharedStrings[3706]="制造一次强大的地震，对附近所有敌人造成物理伤害。"
D.SharedStrings[3707]="制造一次魔法爆炸，对附近的敌人造成{1}点奥术伤害。"
D.SharedStrings[3708]="制造一次魔法爆炸，对附近的敌人造成奥术伤害。"
D.SharedStrings[3709]="制造一次魔法爆炸，对附近的敌人造成自然伤害。"
D.SharedStrings[3710]="制造一波奔涌的潮汐。"
D.SharedStrings[3711]="制造一滩黑暗软泥，对该区域内的所有敌人造成暗影伤害。"
D.SharedStrings[3712]="制造一片声波能量场，每秒造成一次物理伤害。"
D.SharedStrings[3713]="制造一片抑制魔法的区域。在该区域内的单位受到的法术伤害降低{1}%，但是施法速度降低{2}%。"
D.SharedStrings[3714]="制造一片治愈之风气息。"
D.SharedStrings[3715]="制造一片电解之地，对区域内的所有敌人造成自然伤害。"
D.SharedStrings[3716]="制造一片痛苦泪池，造成自然伤害并随时间而变大。"
D.SharedStrings[3717]="制造一片邪焰之地。站在邪焰之地里的玩家会受到火焰伤害。"
D.SharedStrings[3718]="制造一连串冰刺。"
D.SharedStrings[3719]="制造一道通往纳克萨纳尔上层的传送门。"
D.SharedStrings[3720]="制造一道邪能灼烧光束，造成{1}点火焰伤害。"
D.SharedStrings[3721]="制造伤害的能力提高{1}%，直到光束的能量消失。"
D.SharedStrings[3722]="制造出一片恶臭的气态云雾，对附近的敌人造成自然伤害。"
D.SharedStrings[3723]="制造合成德拉诺最为强大的炼金物品所需的试剂。每天只能制作一次。与其它炼金师的大锅共享冷却时间。"
D.SharedStrings[3724]="制造有毒的混合剂"
D.SharedStrings[3725]="制造灼热的邪能能量光束，造成火焰伤害。"
D.SharedStrings[3726]="制造皮甲需要耐心和热情。一旦你投身元素制皮工作，就不能退出了。让我看看你是否能胜任这项工作，然后我们就可以开始了。"
D.SharedStrings[3727]="制造虚无行者的传送门发生器"
D.SharedStrings[3728]="制造许多小型震动，使附近的地面来回晃动，对附近所有敌人造成物理伤害。"
D.SharedStrings[3729]="制造越烧越烈的火焰，对前方弧形区域内的敌人造成{1}点火焰伤害。"
D.SharedStrings[3730]="制造邪能软泥怪。"
D.SharedStrings[3731]="制造黑暗物质之云包围目标，使其受到的伤害增加{1}%，移动速度降低{2}%并对周围所有敌方目标造成{3}暗影伤害。"
D.SharedStrings[3732]="刷成橙色的芜菁"
D.SharedStrings[3733]="刺入玛诺洛斯体内的刀刃与暗夜精灵魔法产生共振，对玛诺洛斯造成{1}点伤害。"
D.SharedStrings[3734]="刺客可能还在风暴峡湾搜寻希格林。小心行事。"
D.SharedStrings[3735]="刺客联盟"
D.SharedStrings[3736]="刺着字母的腰带"
D.SharedStrings[3737]="刺耳唳鸣束带"
D.SharedStrings[3738]="刺芒小径里种植着年轻的凯帕圣树。女皇很早就开始吸收这些树苗了，外来者。在其琥珀能够被采摘之前，它们必须要继续生长。$b$b卡拉克西瓦要求对这一罪行进行惩罚！如果你能杀死那些琥珀收割者们，卡拉克西瓦会非常满意的。"
D.SharedStrings[3739]="刺骨的寒风吹得你节节后退。"
D.SharedStrings[3740]="刻意之力护肩"
D.SharedStrings[3741]="刻有银色黎明的徽记。"
D.SharedStrings[3742]="剃刀沼泽启蒙者"
D.SharedStrings[3743]="剃刀沼泽狩猎大师"
D.SharedStrings[3744]="剃刀沼泽狩猎者"
D.SharedStrings[3745]="剃刀沼泽血纹卫士"
D.SharedStrings[3746]="剃刀沼泽颂石者"
D.SharedStrings[3747]="削减蜘蛛的数量"
D.SharedStrings[3748]="前几天我的花园又被搞得一塌糊涂，不过现在我已经知道是哪个混蛋干的了。就是那只被治安官马瑞斯先生称作“贝利格拉布”的野猪。$b$b你瞧，我在下一季来临之前都没法种我的水仙花了。全毁了！一切都被那只混蛋野猪给毁了！把那祸害给我干掉！把它的獠牙给我带回来，我会付给你酬劳的。它一般就在湖畔镇西南的田边闲逛，但有时候也会跑进我的花园里来。"
D.SharedStrings[3749]="前往东瘟疫之地，进入圣光之愿礼拜堂地下的圣光之愿大殿，和其他圣骑士会合。"
D.SharedStrings[3750]="前往伊瓜鲁克峭壁并消灭一名邪刃蜥蜴人。"
D.SharedStrings[3751]="前往俯瞰索尔莫丹的丘陵地带，在那里找到库伦。"
D.SharedStrings[3752]="前往冰冠冰川的银色前线基地，向大领主提里奥·弗丁报到。"
D.SharedStrings[3753]="前往刀锋山的希尔瓦纳与莉娜·月泉谈一谈。"
D.SharedStrings[3754]="前往刀锋山的铸魔营地：天罚或是铸魔营地：恐怖，利用放逐水晶放逐15个恶魔。"
D.SharedStrings[3755]="前往刀锋山的雷神要塞，与高德雷克谈一谈。"
D.SharedStrings[3756]="前往刀锋山，找到食人魔位于外域的要塞和他们的戈隆主子。"
