D.SharedStrings[3810]="前有鸦后有虎"
D.SharedStrings[3811]="前线基地很安全，朋友。我们再次掌握了回音谷的控制权，并摧毁了封住突破口的层层蛛网。现在，是时候攻下天灾城，在冰冠冰川内建起我们的营地了。战线正在向前推进！$B$B我已经向黑锋观察者发出请求，让他协助我们攻打天灾城。他对天灾军团非常了解，这对战事是至关重要的。$B$B往西北方走，到突破口外面的帐篷处向他报到吧。"
D.SharedStrings[3812]="前锋军指挥官昂斯洛特"
D.SharedStrings[3813]="剑刃漩涡每秒对15码范围内的所有目标造成{1}点物理伤害，伤害会逐渐提高。"
D.SharedStrings[3814]="剑圣朱倍尔索斯"
D.SharedStrings[3815]="剑圣随身携带的重要物品不只有长剑而已。$B$B在剑圣洞穴里通过最终试炼后，剑圣就会获得携带火刃旗帜的荣耀。$B$B当我请求恢复我在氏族中应有的地位时，那些懦夫装聋作哑地无视了我，还把我的这份荣耀也一并剥夺了。$B$B我的旗帜肯定被放在了哈瓦洛的某个地方。如果他们没在第一时间烧毁它的话，就会把它交给其它志向高远的剑圣。"
D.SharedStrings[3816]="剥来4张柔软的虎皮和4张光滑的猎豹皮。"
D.SharedStrings[3817]="剥皮训练师"
D.SharedStrings[3818]="剧毒倾泻水晶"
D.SharedStrings[3819]="剧毒小蜘蛛"
D.SharedStrings[3820]="剧毒领主的图腾魔杖"
D.SharedStrings[3821]="剧毒风暴便鞋"
D.SharedStrings[3822]="剧烈爆破胸甲"
D.SharedStrings[3823]="剧烈的疼痛使得该食人魔的移动速度降低60%"
D.SharedStrings[3824]="剩下的兄弟们已经杀到最后一个房间，他们就在前面。\n\n通往地窟出口的障碍就只剩下这次恶魔入侵的领导者，巴斯提拉克斯。\n\n消灭他并夺取他的力量，为我们争取自由。"
D.SharedStrings[3825]="剩下的兄弟们已经杀到最后一个房间，他们就在前面。\n\n通往地窟出口的障碍就只剩下这次恶魔入侵的领导者，巴斯提拉克斯。\n\n消灭他并夺取他的力量，为我们博得自由。"
