D.SharedStrings[3960]="勇猛的战斗机械陆行鸟"
D.SharedStrings[3961]="勇者牛奶的斗篷"
D.SharedStrings[3962]="動作快，$c！這些海巨人的食慾是無底洞！"
D.SharedStrings[3963]="勘查员塔雷·石镐"
D.SharedStrings[3964]="匆忙中，德莱尼人离开阿古斯过程中只带走了少许几件神器。这本书籍是保存至今日的少数遗物之一。"
D.SharedStrings[3965]="北伐军之峰的提里奥·弗丁要你想办法获取一件诅咒教徒的兜帽，穿上它，然后前往冰冠堡垒西北方的黑暗大教堂入口处与他汇合。"
D.SharedStrings[3966]="北伐军战士乔纳森"
D.SharedStrings[3967]="北伐军战士乔纳森的血流尽之后就会死亡。"
D.SharedStrings[3968]="北伐军战士布雷登布莱德"
D.SharedStrings[3969]="北伐军战士拉莫夫的血流尽之后就会死亡。"
D.SharedStrings[3970]="北伐军战士欧尔拉金·萨利斯"
D.SharedStrings[3971]="北伐军战士瓦鲁斯"
D.SharedStrings[3972]="北伐军战士约瑟芬的血流尽之后就会死亡。"
D.SharedStrings[3973]="北伐军战士莱达拉"
D.SharedStrings[3974]="北伐军战士萨伯恩"
D.SharedStrings[3975]="北伐军战士马克拉尔"
D.SharedStrings[3976]="北伐军技师斯比帕提克"
D.SharedStrings[3977]="北伐军指挥官恩塔里"
D.SharedStrings[3978]="北伐军领主兰迪加"
D.SharedStrings[3979]="北伐军领主达尔弗斯"
D.SharedStrings[3980]="北卫军远征部队"
D.SharedStrings[3981]="北地鹰喙猫头鹰"
D.SharedStrings[3982]="北方天神雪怒正在寻找这片土地上最伟大的勇士。$B$B今天，他在昆莱山上自己的寺庙里举办了一场武道大会。$B$B如果你想和来自潘达利亚各地的高手一较高下，请去找他，进入挑战者之环！"
D.SharedStrings[3983]="北方的巫妖王已经蠢蠢欲动。$b$b在他的指挥下，一支亡灵大军正在横扫诺森德，到处散播瘟疫。$b$b我们需要你去阻止他们，$n。"
D.SharedStrings[3984]="北裂境地面傳送門。可將玩家從米奈希爾傳送至瓦爾加德。"
D.SharedStrings[3985]="北郡骑士麦斯米兰"
D.SharedStrings[3986]="北郡骑士麦斯米兰有几率出现并，对附近所有敌人造成大量伤害。"
D.SharedStrings[3987]="匹克西尼·钱包"
D.SharedStrings[3988]="匿踪大师琪麟"
D.SharedStrings[3989]="十字军指挥官埃里戈尔·黎明使者"
D.SharedStrings[3990]="十字军的一部分成员正为锦标赛做准备工作，而另外一些十字军已经准备向敌人的冰冠堡垒发动进攻了。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的十字军战士已经在恐惧之门科雷萨以南建立了先头营地。拿起长枪，骑上战马，到营地去击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，$n不过你完全不用害怕。你的战马可以轻易地将它们踏平。"
D.SharedStrings[3991]="十字军的白色战马"
D.SharedStrings[3992]="十字军的黑色战马"
D.SharedStrings[3993]="十枚荣誉徽章"
D.SharedStrings[3994]="千钧一发：加尔鲁什·地狱咆哮（10人）"
D.SharedStrings[3995]="千钧一发：加尔鲁什·地狱咆哮（25人）"
D.SharedStrings[3996]="千钧一发：大女皇夏柯希尔"
D.SharedStrings[3997]="千钧一发：皇帝的意志"
