D.SharedStrings[3999]="午夜彗星护腕"
D.SharedStrings[4000]="午夜扬起前蹄，朝前冲锋，对前方锥形范围内的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[4001]="半兽人迦罗娜"
D.SharedStrings[4002]="半兽人迦罗娜偶尔会在战斗中帮助你，向敌人的脚下扔出毒药瓶，造成大量伤害。"
