D.SharedStrings[4004]="华丽的飞毯"
D.SharedStrings[4005]="协助大德鲁伊"
D.SharedStrings[4006]="协助奥术师瓦尔托伊放置魔网共振器。"
D.SharedStrings[4007]="协助热砂集团粉碎险恶的皇冠药剂公司的阴谋。"
D.SharedStrings[4008]="协助联盟与部落的联军突袭塔纳安丛林的钢铁前线。"
D.SharedStrings[4009]="协调员"
D.SharedStrings[4010]="卑鄙的冒险者"
D.SharedStrings[4011]="卑鄙的维尼克斯"
D.SharedStrings[4012]="卓格巴尔原来只能控制大地魔法，但是他们好像找到了什么方法，使得他们能够吸取其他来源的能量。"
D.SharedStrings[4013]="卓格巴尔向来是珠宝加工的大师。具体来说，原始部落的萨满祭司会佩戴由三颗石头制成的沉重项链，而这些项链由一代代师父传给他们的徒弟。"
D.SharedStrings[4014]="卓格巴尔将它放在显眼的位置，提醒自己死亡之翼曾经拥有的强大力量。"
D.SharedStrings[4015]="卓越征服军需官"
D.SharedStrings[4016]="单位正在准备施放极其强大的冲击波。"
D.SharedStrings[4017]="单位被烈焰之网束缚了！"
D.SharedStrings[4018]="单次前往旋云之巅即收集到5个金色宝珠（英雄难度）。"
D.SharedStrings[4019]="单简正在使用煞能扼杀你。\r\n昏迷。"
