D.SharedStrings[4026]="博学者迪布斯"
D.SharedStrings[4027]="博斯克与伦吉尔的天空战车"
D.SharedStrings[4028]="占位字符"
D.SharedStrings[4029]="占位符"
D.SharedStrings[4030]="占据油料精炼厂可以获得15%的攻城伤害加成。"
D.SharedStrings[4031]="占据采石场可以获得15%的攻城伤害加成。"
D.SharedStrings[4032]="占星师使用这个手持装置将大量星光聚焦在一小块区域。这个装置主要在节庆和拜星仪式期间使用，也会用于占星师拿不到书架顶部物品的时候。"
D.SharedStrings[4033]="占星师艾塔乌斯"
D.SharedStrings[4034]="占星者胜利!凯尔的力量很快就会粉碎。"
D.SharedStrings[4035]="占领奥特兰克山谷哨塔"
D.SharedStrings[4036]="占领瞭望台、竞赛场和碎石岭，然后向地狱火半岛上荣耀堡内的委任官翠希·普罗维尔复命。"
D.SharedStrings[4037]="占领瞭望台、竞赛场和碎石岭，然后向地狱火半岛上萨尔玛的传令官布莱肯·黑眼复命。"
D.SharedStrings[4038]="卡亚可乐！创意无穷！（注册商标）"
