D.SharedStrings[4047]="卡利姆多的糖果"
D.SharedStrings[4048]="卡加斯·刃拳"
D.SharedStrings[4049]="卡加斯·刃拳（史诗难度）"
D.SharedStrings[4050]="卡加斯远征军"
D.SharedStrings[4051]="卡尔什·断钢"
D.SharedStrings[4052]="卡尔加·刺肋"
D.SharedStrings[4053]="卡尔加在水晶操控方面的力量空前强大，使其可以号令强大的水晶体在战斗中协助她。这些水晶体无法被攻击。\r\n\r\n卡尔加同时最多控制2个水晶体。"
D.SharedStrings[4054]="卡尔德·格雷"
D.SharedStrings[4055]="卡尔烬德大公的爪牙"
D.SharedStrings[4056]="卡尔维特教授要你飞往湖边着陆场，与飞行员维克谈一谈。"
D.SharedStrings[4057]="卡尼托的海难"
D.SharedStrings[4058]="卡德加低估了上一个法术的威力。****你死了。****你的等级为100/100级，使你达到了“几近传奇”的级别。"
D.SharedStrings[4059]="卡德加的仆从"
D.SharedStrings[4060]="卡德加的召唤"
D.SharedStrings[4061]="卡德加的高级仆从"
D.SharedStrings[4062]="卡德罗斯的印记"
D.SharedStrings[4063]="卡德里斯的剧毒图腾"
D.SharedStrings[4064]="卡德里斯的节杖"
D.SharedStrings[4065]="卡拉克西只是一个传说，据说它位于长城外侧遥远的恐惧废土上。$B$B很少有人冒险进入那个地区，更没有人能活着回来讲述自己的经历。$B$B如果你已经下定决心要找到这些……卡拉克西………驻守在西南方遥远长城上的一小群影踪派成员可能知道的更多。"
D.SharedStrings[4066]="卡拉克西复苏之握"
D.SharedStrings[4067]="卡拉克西瓦·伊克"
D.SharedStrings[4068]="卡拉克西瓦在对我低语，外来者。在盐碱泥滩藏匿着一位英杰，他的位置已经暴露了。$b$b蜥蜴人包围了他，决不能让英杰落入他们手中。$b$b你得找到他，你得唤醒他。搞不定就别回来见我！$b$b如果你能办到，卡拉克西会对我们另眼相看的。"
D.SharedStrings[4069]="卡拉克西英杰"
D.SharedStrings[4070]="卡拉兹工坊旋翼机"
D.SharedStrings[4071]="卡拉对附近的钢铁部落入侵者造成神圣伤害。"
D.SharedStrings[4072]="卡拉波守备官"
D.SharedStrings[4073]="卡拉波守护者"
