D.SharedStrings[4083]="卡杜斯·阿卡迪安"
D.SharedStrings[4084]="卡格·血怒"
D.SharedStrings[4085]="卡桑利老年虎"
D.SharedStrings[4086]="卡桑德拉·卡布"
D.SharedStrings[4087]="卡桑琅强力游侠"
D.SharedStrings[4088]="卡桑琅荒原啤"
D.SharedStrings[4089]="卡洛斯要你进入旧希尔斯布莱德，击败年轻时候的卡洛斯。然后将他的帽子交给塔纳利斯的卡洛斯。"
D.SharedStrings[4090]="卡翠欧娜·沃宁迪女伯爵"
D.SharedStrings[4091]="卡苏姆的钻石印记"
D.SharedStrings[4092]="卡莱娜的奥法裹手"
D.SharedStrings[4093]="卡萊德斯覺得很難過，我們沒有救出你的朋友。但如果我們的動作夠快，他們可能還活著。\r\n\r\n雖然賈岡諾斯會拷問他們，但是他會留下囚犯一條小命…通常來說。"
D.SharedStrings[4094]="卡里杜斯"
D.SharedStrings[4095]="卡里西安碎刃者"
D.SharedStrings[4096]="卡雷苟斯"
D.SharedStrings[4097]="卡雷苟斯开始将所有精力专注于对抗死亡之翼，使他无法使用自己的气息或织法来帮助他的勇士们。"
D.SharedStrings[4098]="卡雷苟斯开始将所有精力专注于死亡之翼，使他无法使用自己的气息或织法来帮助他的勇士们。"
D.SharedStrings[4099]="卡雷迪斯镇长"
D.SharedStrings[4100]="卫兵斯里基克"
D.SharedStrings[4101]="危险灌注长靴"
D.SharedStrings[4102]="即使以游侠的标准来看，她也称得上是足智多谋、充满自信、技巧娴熟。"
D.SharedStrings[4103]="即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!"
D.SharedStrings[4104]="即使是泰坦也无法忍受他们的折磨。把破坏魔女巫会干掉吧。"
D.SharedStrings[4105]="即使是这么少量的永恒之井水也包含了不可思议的能量。\r\n\r\n我可以清楚的看到与海加尔相关的每个时空……第二个永恒之井的诞生，伊利丹的监禁，世界之树的附魔，还有……没错!海加尔山战役。\r\n\r\n我们必须加快脚步，时间线并不稳定。"
D.SharedStrings[4106]="即使死去，他的余威犹在"
D.SharedStrings[4107]="即使没有被击中，也可以周期性地获得枭兽狂怒。"
D.SharedStrings[4108]="即将发生爆炸，杀死所有敌人。"
D.SharedStrings[4109]="即将爆炸。"
