D.SharedStrings[4126]="原始雪人毛皮"
D.SharedStrings[4127]="原来卡奥辛远比我预料中的要有用的多嘛，不过他对我们已经没有什么利用价值了。是时候跟索基佐格将军谈谈了。我觉得你已经准备好了。$b$b他是统领燃烧平原地面部队的“三巨头”之一。索基佐格的据点就是西北边的黑石要塞。穿上伪装跟他谈谈。看看你能不能赢得他的信任。如果有进一步的指示，托德曼会联系你的。"
