D.SharedStrings[4743]="去阿拉希高地找落锤镇的杜拉姆法尔。"
D.SharedStrings[4744]="去阿拉希高地找落锤镇的格里高利·维克托医生。"
D.SharedStrings[4745]="去阿拉希高地找落锤镇的森古。"
