D.SharedStrings[4748]="去阿拉希高地找避难谷地的玛克里尔中士。"
D.SharedStrings[4749]="去雷神岛的[Horde Hub]找大法师罗曼斯。"
D.SharedStrings[4750]="去雷神岛的雷霆熔炉附近与拉希奥交谈。"
D.SharedStrings[4751]="去雷霆崖的长者高地找巴珊娜·符文图腾。"
D.SharedStrings[4752]="去雾纱栈道的石匠之愚与拉希奥谈一谈。"
D.SharedStrings[4753]="去雾纱栈道的迷雾酒肆二楼找拉希奥。"
D.SharedStrings[4754]="去风暴峭壁找丹尼芬雷的约库姆国王。"
D.SharedStrings[4755]="去风暴峭壁找伯尔瀑布的“诚实的”麦克斯。"
D.SharedStrings[4756]="去风暴峭壁找冰霜堡的格罗萨·硬须。"
D.SharedStrings[4757]="去风暴峭壁找冰霜堡的维罗格·冰啸。"
D.SharedStrings[4758]="去风暴烈酒酿造厂的入口处和陈·风暴烈酒碰面。"
D.SharedStrings[4759]="去黑海岸找奥伯丁的奥兰达利亚·夜歌。"
D.SharedStrings[4760]="去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。"
D.SharedStrings[4761]="去龙骨荒野找莫亚基港口的秘法师图阿鲁。"
D.SharedStrings[4762]="去龙骨荒野找阿格玛之锤的信使托弗斯。"
D.SharedStrings[4763]="去龙骨荒野找黎明河滩的欧瑞克·图哈特。"
D.SharedStrings[4764]="去龙骨荒野找龙眠神殿的克罗米。"
D.SharedStrings[4765]="去龙骨荒野找龙眠神殿的奥拉斯塔萨。"
D.SharedStrings[4766]="参与在本服务器首次击杀克尔苏加德（25人）。"
D.SharedStrings[4767]="参与在本服务器首次击杀巫妖王（英雄难度25人）。"
D.SharedStrings[4768]="参与在本服务器首次击杀玛里苟斯（25人）。"
D.SharedStrings[4769]="参与在本服务器首次击杀观察者奥尔加隆（25人）。"
D.SharedStrings[4770]="参与在本服务器首次击杀黑岩守护者萨塔里奥（25人）。"
D.SharedStrings[4771]="参与本服务器首次完成大十字军的试炼，并且尝试次数还剩50次（25人）。"
D.SharedStrings[4772]="参与熊猫人爆裂酒的酿造过程。"
D.SharedStrings[4773]="又一个可供我们研究的新发现―干得好，$N!达纳苏斯那边会对这些残骸进行仔细的研究。请收下这个作为你的回报。"
D.SharedStrings[4774]="又丑又滑溜，但煮好后却是意外地美味。只有老练的渔夫在纳特·帕格的帮助下才有可能抓到它。"
D.SharedStrings[4775]="及时押送被捕的教徒，否则他会逃走！"
D.SharedStrings[4776]="双头巨人克洛科"
D.SharedStrings[4777]="双头飞龙又重新出现在了我们对抗钢铁部落的战场上。倘若我们不从源头上遏制它们的话，很快就会失去对道路的控制权，被迫撤回哨站。\n\n这些多出来的双头飞龙很有可能是从影月谷东南部的黑潮栖木飞来的。如果我们赶快行动，应该还来得及破坏敌人的行动。"
D.SharedStrings[4778]="双头飞龙又重新出现在了我们对抗钢铁部落的战场上。倘若我们不从源头上遏制它们的话，很快就会失去对道路的控制权，被迫撤回哨站。\n\n这些多出来的双头飞龙很有可能是从影月谷东南部的黑潮栖木飞来的。如果我们赶快行动，应该还来得及解决这个麻烦。"
D.SharedStrings[4779]="双头飞龙管理员"
D.SharedStrings[4780]="双子峰战场军官"
D.SharedStrings[4781]="双子峰旗帜已夺取"
D.SharedStrings[4782]="双子峰荣誉击杀"
D.SharedStrings[4783]="双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟阿瑞苟斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$n。我会为你制作一顶具有超凡力量的头盔。"
D.SharedStrings[4784]="双持。\r\n急速提高{1}%。"
D.SharedStrings[4785]="双生相协治疗其生命值总量的{1}%。"
D.SharedStrings[4786]="双足飞龙管理员"
D.SharedStrings[4787]="双重攻击"
D.SharedStrings[4788]="反光暗影水晶"
D.SharedStrings[4789]="反光曙光猫眼石"
D.SharedStrings[4790]="反击所有近战攻击。"
D.SharedStrings[4791]="反击特定类型的攻击。"
D.SharedStrings[4792]="反制目标的动作，打断格挡，并使之进入10秒的冷却期。\r\n\r\n只能对格挡中的目标使用。"
D.SharedStrings[4793]="反复拳击一个敌人，每次打击造成物理伤害。"
D.SharedStrings[4794]="反射{1}%的所受伤害，并以自然伤害的形式反射给玩家。"
D.SharedStrings[4795]="反射{1}%的攻击和法术。\r\n近战攻击速度降低{2}%。\r\n施法时间延长{2}%。"
D.SharedStrings[4796]="反射下一个对你施放的法术。"
D.SharedStrings[4797]="反射魔法。\r\n每2秒对附近的敌人造成一次普通伤害。"
D.SharedStrings[4798]="反弹10次末日黑洞，使其远离玩家，再击败督军佐诺兹（普通或英雄难度）。"
D.SharedStrings[4799]="反魔法力场充斥在施法者周围，降低附近所有敌人的施法速度。"
D.SharedStrings[4800]="发出信号，表示你已经准备好陪同科多兽商队行进了。"
D.SharedStrings[4801]="发出信号，通知阿古斯之手的追踪者来帮助你。"
D.SharedStrings[4802]="发出刺耳尖啸，对周围的所有敌人造成物理伤害。"
D.SharedStrings[4803]="发出刺耳的哀嚎，对敌人造成暗影伤害。"
D.SharedStrings[4804]="发出尖锐的嘶叫，对附近所有的敌人造成{1}点物理伤害。"
D.SharedStrings[4805]="发出攻击信号"
D.SharedStrings[4806]="发出痛苦的哀嚎，对敌人造成暗影伤害。"
D.SharedStrings[4807]="发动一系列的攻击，对施法者前方锥形范围内的敌人造成物理伤害。"
D.SharedStrings[4808]="发动一连串的攻击，对施法者前方锥形范围内的敌人造成火焰伤害。"
D.SharedStrings[4809]="发动打击，对施法者前方锥形范围内的敌人造成暗影伤害。"
D.SharedStrings[4810]="发动旋风斩，对周围的敌人造成伤害。"
D.SharedStrings[4811]="发动旋风斩，对周围的敌人造成伤害，并将它们击退。"
D.SharedStrings[4812]="发动旋风斩，对附近的所有敌人喷射火焰，并降低他们对火焰魔法的抗性。"
D.SharedStrings[4813]="发射{1}枚猛烈的火球，每个造成{2}点火焰伤害。"
D.SharedStrings[4814]="发射一个套索，将敌人从空中击落。"
D.SharedStrings[4815]="发射一个高爆套索，将敌人从空中击落。"
D.SharedStrings[4816]="发射一支爆炸箭，对半径4码范围内的所有敌人造成{1}点伤害。"
D.SharedStrings[4817]="发射一枚小型炸药，冲击其行进路线上的第一只螳螂妖，并对附近的所有螳螂妖造成大量物理伤害。"
D.SharedStrings[4818]="发射一枚巨大的火焰投石，造成{1}点火焰伤害。"
D.SharedStrings[4819]="发射一枚抓钩，将你牵引向目标位置。"
D.SharedStrings[4820]="发射一枚梦魇能量箭矢，造成{1}点暗影伤害。"
D.SharedStrings[4821]="发射一枚梦魇能量箭矢，造成{1}点暗影伤害并造成{2}点腐蚀。"
D.SharedStrings[4822]="发射一枚火炮，对周围的单位造成{1}点伤害和{2}点攻城伤害。"
D.SharedStrings[4823]="发射一枚火球攻击目标，对其造成{1}点火焰伤害。"
D.SharedStrings[4824]="发射一枚火球，造成{1}点火焰伤害。"
D.SharedStrings[4825]="发射一枚火箭升至空中，随后分裂成若干枚小火箭，对半径内的所有目标造成伤害。"
D.SharedStrings[4826]="发射一枚热追踪导弹，它会尝试定位敌方的坦克。"
D.SharedStrings[4827]="发射一枚高爆弹药，将敌人从空中打下来。"
D.SharedStrings[4828]="发射一枚高速金属炮弹，对目标造成{1}点伤害。"
D.SharedStrings[4829]="发射一簇火焰，在其冲击区域留下一团火焰。"
D.SharedStrings[4830]="发射一阵箭雨，对施法者前方锥形范围内的敌人造成暗影伤害。"
D.SharedStrings[4831]="发射寒冰炸弹，造成冰霜伤害并冻结地面，造成持续伤害并降低区域内的敌人的移动速度。"
D.SharedStrings[4832]="发射榴霰弹，对施法者前方所有敌人造成物理伤害。"
D.SharedStrings[4833]="发射火炮。"
D.SharedStrings[4834]="发射火炮，造成火焰伤害，并对周围的建筑造成{1}点攻城伤害。"
D.SharedStrings[4835]="发射炮弹。对敌人造成最多{1}点伤害，对周围建筑造成最多{2}点攻城伤害。"
D.SharedStrings[4836]="发射炮弹攻击目标，造成周期性的伤害。"
D.SharedStrings[4837]="发射钢铁之星向前挺进，碾压所遭遇的一切。"
D.SharedStrings[4838]="发射闪电箭攻击敌人。"
D.SharedStrings[4839]="发射飞弹，攻击附近的所有双头飞龙，造成火焰伤害。"
D.SharedStrings[4840]="发射黑暗魔法箭，对附近的敌人造成暗影伤害。"
D.SharedStrings[4841]="发展进步"
D.SharedStrings[4842]="发条式火车破坏者"
D.SharedStrings[4843]="发烧的探险者"
D.SharedStrings[4844]="发烧的瓦尔莎拉难民"
D.SharedStrings[4845]="发现下列神器。"
D.SharedStrings[4846]="发现并追踪克罗姆加刺客的热成像。在他们找到你之前找到他们！"
D.SharedStrings[4847]="发现并追踪达纳苏斯斥候的热成像。在他们找到你之前找到他们！"
D.SharedStrings[4848]="发现深埋在黑海岸虚空深渊之下的秘密。"
D.SharedStrings[4849]="发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B“太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!”"
D.SharedStrings[4850]="发生故障！激活惯性变形模组！"
D.SharedStrings[4851]="发疯似地抽你的敌人。"
D.SharedStrings[4852]="发臭的土山头的幸运符"
D.SharedStrings[4853]="发起一次大规模的岩石冲击波，打击施法者面前的所有敌人，造成{1}点自然伤害。"
D.SharedStrings[4854]="取下他的首……呃，等等"
D.SharedStrings[4855]="取回7块攻城坦克废料。在不眠前线使用磁性废料收集器寻找废料。不眠前线位于此地正西方，穿过第二座桥梁就到。"
D.SharedStrings[4856]="取回一件可以将祖尔格拉布巨魔驱逐出藏宝海湾的神器。"
D.SharedStrings[4857]="取回一把沉睡之砂、一壶魔能泻药以及一颗澄澈的玻璃球。"
D.SharedStrings[4858]="取回破损的圣杯、满是尘土的花瓶、土灵符文碑刻和穴居人工具。"
D.SharedStrings[4859]="取回黑曜石能量核心和泰坦能量核心。"
D.SharedStrings[4860]="取得一只获救的红色雏龙、一只获救的绿色雏龙、一只获救的蓝色雏龙和一只获救的青铜雏龙。"
D.SharedStrings[4861]="取胜次数最多的评级战场"
D.SharedStrings[4862]="取胜过的评级战场"
D.SharedStrings[4863]="受伤的冒险者"
D.SharedStrings[4864]="受伤的利爪德鲁伊"
D.SharedStrings[4865]="受伤的哨兵"
D.SharedStrings[4866]="受伤的士兵"
D.SharedStrings[4867]="受伤的大地之环萨满"
D.SharedStrings[4868]="受伤的德鲁伊"
D.SharedStrings[4869]="受伤的抗魔联军防御者"
D.SharedStrings[4870]="受伤的梦境守护者"
D.SharedStrings[4871]="受伤的步兵"
D.SharedStrings[4872]="受伤的猎人"
D.SharedStrings[4873]="受伤的矿工"
D.SharedStrings[4874]="受伤的红色幼龙"
D.SharedStrings[4875]="受伤的船员"
D.SharedStrings[4876]="受伤的防御者"
D.SharedStrings[4877]="受到{1}点奥术伤害。"
D.SharedStrings[4878]="受到{1}点火焰伤害。"
D.SharedStrings[4879]="受到一名恐惧魔王控制。"
D.SharedStrings[4880]="受到了海拉之影的伤害。"
D.SharedStrings[4881]="受到任何攻击时承受的伤害减少{1}%。"
D.SharedStrings[4882]="受到伤害会导致脆骨，使受到的伤害提高。"
D.SharedStrings[4883]="受到伤害会生成法力值。\r\n\r\n法力值满时效果取消。"
D.SharedStrings[4884]="受到伤害提高{1}%。\r\n生长催化剂受到压制。"
D.SharedStrings[4885]="受到伤害时有一定几率触发魔刃之击效果，对玛诺洛斯造成大量额外伤害。"
D.SharedStrings[4886]="受到伤害时有几率召唤预言者努波顿协助你。努波顿会治疗你，并攻击你周围的所有敌人。"
D.SharedStrings[4887]="受到伤害时造成的伤害提高{1}%。本效果每2秒内只能触发一次并且最多可以叠加5次。"
D.SharedStrings[4888]="受到伤害时阿隆索斯·法奥有一定几率出现，对你施放灼热之光，治疗你并攻击你周围的所有敌人。"
D.SharedStrings[4889]="受到伤害时，攻击者受到的治疗效果降低{1}%。"
D.SharedStrings[4890]="受到先知维伦的保护。"
D.SharedStrings[4891]="受到创世之柱的庇护。每30分钟只能触发一次。"
D.SharedStrings[4892]="受到另一个食人魔的攻击！\r\n攻击和施法速度降低{1}%。"
D.SharedStrings[4893]="受到大地守护者萨尔的祝福，获得艾泽拉斯远古巨石坚不可摧的力量。防御技能的冷却时间缩短{1}%。防御技能的持续时间延长{2}%。"
D.SharedStrings[4894]="受到尘染和风的祝福。攻击速度提高{1}%。"
D.SharedStrings[4895]="受到巫妖王的保护。每10分钟只会生效一次。"
