D.SharedStrings[5107]="古尔戈索克"
D.SharedStrings[5108]="古拉巴什剧毒祭司"
D.SharedStrings[5109]="古拉巴什巨魔已经召集起他们最强大的盟友，重新建起祖尔格拉布，占据了荆棘谷。$B$B他们的头领是两个巨大恐怖的巨魔：搬运者伽乌里马和撕裂者莫尔雷克，以及一个被称为莫尔塔克斯的强大窃魂者。$B$B虽然他们并不是祖尔格拉布的统治者，但打败这些强大的巨魔爪牙能够有力地帮助我们阻止古拉巴什崛起。"
D.SharedStrings[5110]="古拉巴什狂暴者"
D.SharedStrings[5111]="古拉巴什猎头者"
D.SharedStrings[5112]="古拉巴什竞技场挑战者"
D.SharedStrings[5113]="古拉巴什血领主"
D.SharedStrings[5114]="古拉巴什调药师"
D.SharedStrings[5115]="古方自由行动药水"
