D.SharedStrings[5165]="古朴的花粉采集器"
D.SharedStrings[5166]="古朴的英杰残骸"
D.SharedStrings[5167]="古朴的螳螂塑像"
D.SharedStrings[5168]="古朴的螳螂妖帝国旗帜"
D.SharedStrings[5169]="古朴的螳螂妖灯笼"
D.SharedStrings[5170]="古朴的角斗士盾牌"
D.SharedStrings[5171]="古朴的象形石刻"
D.SharedStrings[5172]="古朴的贵族拆信刀"
D.SharedStrings[5173]="古朴的鎏金瓷俑"
D.SharedStrings[5174]="古朴的铁制护符"
D.SharedStrings[5175]="古朴的陶俑手臂"
D.SharedStrings[5176]="古朴的雕花铜镜"
D.SharedStrings[5177]="古朴的雷电之王勋章"
D.SharedStrings[5178]="古朴的雷电之王的法典"
D.SharedStrings[5179]="古朴的霜狼先祖牙雕"
D.SharedStrings[5180]="古朴的食人魔雕像"
D.SharedStrings[5181]="古朴的魔古符文石"
D.SharedStrings[5182]="古朴的魔古钱币"
D.SharedStrings[5183]="古朴的鸦爪祭司面具"
D.SharedStrings[5184]="古朴的鸩酒酒瓶"
D.SharedStrings[5185]="古朴的鹿骨鱼钩"
D.SharedStrings[5186]="古朴的黑石剃刀"
D.SharedStrings[5187]="古朴的齿痕霜狼战斧"
D.SharedStrings[5188]="古爾丹說過，有力量的人都可以加入。如果朋友加入呢？然後靠近時把權杖搶走，然後跑！\r\n\r\n沒錯！這行得通，可是要讓他們信任。古爾丹需要眼睛。朋友可以幫忙拿眼睛，就可以有信任。"
D.SharedStrings[5189]="古特里克的杀生刀：灵魂熔炉"
D.SharedStrings[5190]="古老的仇恨 - 卡利姆多的开拓"
D.SharedStrings[5191]="古老的结界保卫着古墓的最深处，防止动荡的灵魂在爆炸时影响其他盟友。"
D.SharedStrings[5192]="古老的艾格文力量残片。"
D.SharedStrings[5193]="古老而强大的魔法影响着这个生物。必须要由一位强大的德鲁伊用月神镰刀才能驱散这效果。"
D.SharedStrings[5194]="古赤的蚕宝宝"
D.SharedStrings[5195]="古鲁尔克"
D.SharedStrings[5196]="古鲁金打手"
D.SharedStrings[5197]="古鲁金敲打者"
D.SharedStrings[5198]="只有宠物可以预防森林火灾"
D.SharedStrings[5199]="只有玛里苟斯拥有魔法之心。这也是他最大的力量来源。"
D.SharedStrings[5200]="只有那些进入深渊的冒险者才能迎接这个挑战，$n。$B$B黑铁矮人已经掌握了制造强大的作战傀儡的方法。$B$B来自间谍的报告显示，那些矮人使用某种独特的能量源为他们所创造的傀儡提供无与伦比的杀戮能力。$B$B如果我们能得到这种元素精华的话，我们的憎恶怪就可以得到极大的加强！把那座城市翻个底朝天也在所不惜，找不到精华你就别回来！我们给予的报酬值得你去冒这个险。"
D.SharedStrings[5201]="只能在水下使用。在你快要喘不过气来的时候可以帮你的大忙。"
D.SharedStrings[5202]="只能在破碎群岛以及控制飞碟的场景战役中使用。"
D.SharedStrings[5203]="只能被减速30%。\r\n近战攻击会造成乱舞。"
D.SharedStrings[5204]="只能镶嵌在多彩宝石插槽中。"
D.SharedStrings[5205]="只能镶嵌在齿轮插槽中。"
D.SharedStrings[5206]="只要不受到战斗的妨碍，纳兹夏尔女武士就能将自己的速度提升到难以想象的程度。"
D.SharedStrings[5207]="只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$B$B如果你能给我弄些裂片来，我就可以给你几份植物药膏。"
D.SharedStrings[5208]="只要你距离浮标不是太远，就可以在水下呼吸。"
D.SharedStrings[5209]="只要有合适的材料，赞札就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官:金度和血领主那里夺来1个原始哈卡莱塑像。$B$B接下来是打孔的巫毒人偶。你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔!"
D.SharedStrings[5210]="召唤1个被奴役的收割者。"
D.SharedStrings[5211]="召唤1只寒噬幼雏。"
D.SharedStrings[5212]="召唤1只蝎子。"
D.SharedStrings[5213]="召唤{1}个强大的水元素协助施法者。"
D.SharedStrings[5214]="召唤一个上古之神的触须为你作战。"
D.SharedStrings[5215]="召唤一个传送门，从扭曲虚空中调遣恶魔。"
D.SharedStrings[5216]="召唤一个具有强大力量的恶魔。"
D.SharedStrings[5217]="召唤一个图腾，在这个世界与灵魂世界之间提供一条管道。"
D.SharedStrings[5218]="召唤一个太阳宝珠。"
D.SharedStrings[5219]="召唤一个奥术仆从来保卫施法者。"
D.SharedStrings[5220]="召唤一个女妖，让她抓住一名受伤的军情七处密探。目标生命值不能高于35%。"
D.SharedStrings[5221]="召唤一个小鬼为施法者作战。"
D.SharedStrings[5222]="召唤一个小鬼为施法者作战，直到被解散。"
D.SharedStrings[5223]="召唤一个小鬼为施法者战斗，直到被解散。"
D.SharedStrings[5224]="召唤一个小鬼为术士作战。"
D.SharedStrings[5225]="召唤一个幻象为施法者作战。"
D.SharedStrings[5226]="召唤一个恶魔卫士为施法者作战。"
D.SharedStrings[5227]="召唤一个战利品，使你获得凶暴打击，对附近的雷神兽人造成强力压制。"
D.SharedStrings[5228]="召唤一个战利品，使你获得紧急回避，向后跳离，避开附近的雷神兽人。"
D.SharedStrings[5229]="召唤一个暗影陷阱，触发时造成暗影伤害，并将敌人击退。"
D.SharedStrings[5230]="召唤一个月亮井。"
D.SharedStrings[5231]="召唤一个束缚灵魂仆从来保护施法者。"
D.SharedStrings[5232]="召唤一个梦魇。"
D.SharedStrings[5233]="召唤一个次级恶魔协助施法者作战。"
D.SharedStrings[5234]="召唤一个治疗之潮图腾，为周围的盟友恢复生命。"
D.SharedStrings[5235]="召唤一个泡沫之盾，受到的伤害降低{1}%。"
D.SharedStrings[5236]="召唤一个灵体之球协助施法者战斗。"
D.SharedStrings[5237]="召唤一个爬行地狱火，在战场上追踪敌人。"
D.SharedStrings[5238]="召唤一个犀牛之魂冲锋目标，造成{1}点伤害并将其抛至空中。"
D.SharedStrings[5239]="召唤一个碧蓝鳞卫摧毁附近的邪焰传送门。"
D.SharedStrings[5240]="召唤一个结界，该结界可以周期性地治疗其周围的盟友。"
D.SharedStrings[5241]="召唤一个虚空领域，对站在里面的敌人造成暗影伤害。"
D.SharedStrings[5242]="召唤一个虚空领域，并对其站在其范围内的所有敌人造成暗影伤害"
D.SharedStrings[5243]="召唤一个虫语者为施法者作战。"
D.SharedStrings[5244]="召唤一个邪能传送门，造成邪能爆破。"
D.SharedStrings[5245]="召唤一个邪能散播器，在其下方制造出一片燃烧魔藤。站在魔藤上的玩家每秒受到一次火焰伤害。"
D.SharedStrings[5246]="召唤一个野性防御者来帮助欧尔莉亚。"
D.SharedStrings[5247]="召唤一个魅魔为你作战，魅魔能魅惑人形生物，阻止其发动攻击。"
D.SharedStrings[5248]="召唤一只云端翔龙来治疗她的盟友，并攻击她的敌人。"
D.SharedStrings[5249]="召唤一只地狱犬为施法者作战，直到被解散。"
D.SharedStrings[5250]="召唤一只地狱猎犬为你作战，地狱猎犬能够扰乱敌人施法。"
D.SharedStrings[5251]="召唤一只恶魔生物。"
D.SharedStrings[5252]="召唤一只折磨之眼，周期性迷惑玩家，除非玩家面朝折磨之眼。"
D.SharedStrings[5253]="召唤一只自爆绵羊冲向附近的敌人并自爆，造成{1}点伤害，绵羊自召唤出来后最多存在3分钟。"
D.SharedStrings[5254]="召唤一只蝎子，它会为施法者作战，直至被解散。"
D.SharedStrings[5255]="召唤一只锋刃豹陪伴施法者，直到被解散为止。"
D.SharedStrings[5256]="召唤一只食腐蝙蝠为施法者进行侦察。"
D.SharedStrings[5257]="召唤一台作战装甲，将你运输到维迪卡尔。"
D.SharedStrings[5258]="召唤一名挑战者，与你在荆棘谷海角的大竞技场中搏斗。"
D.SharedStrings[5259]="召唤一名焰生毁灭者。"
D.SharedStrings[5260]="召唤一名碧蓝魔环上尉除掉你的敌人。"
D.SharedStrings[5261]="召唤一团军团烈焰。"
D.SharedStrings[5262]="召唤一团翻卷的雷云吸引玩家，当他们抵达中央时对其造成伤害。"
D.SharedStrings[5263]="召唤一头大主教的雷象。"
D.SharedStrings[5264]="召唤一头天灾狮鹫，将你载回死亡裂口。"
D.SharedStrings[5265]="召唤一头恶魔野兽。"
D.SharedStrings[5266]="召唤一头魔犬协助施法者作战。"
D.SharedStrings[5267]="召唤一座会向周围敌人射击的哨卫炮台。"
D.SharedStrings[5268]="召唤一座喷发的火山来攻击附近的敌人。"
D.SharedStrings[5269]="召唤一座圣光熔炉，让你可以使用锻造技能。\r\n\r\n锻造技能提高{1}点。"
D.SharedStrings[5270]="召唤一座炮台协助你作战。"
D.SharedStrings[5271]="召唤一排邪能瓦格里，冲过战场。路线上的玩家将会受到暗影伤害。"
D.SharedStrings[5272]="召唤一排邪能瓦格里，冲过战场。路线上的玩家将会受到物理伤害。"
D.SharedStrings[5273]="召唤一支僵尸军团为你作战。僵尸会在你附近的区域横冲直撞，攻击一切它们可以攻击的目标。在引导僵尸大军技能时，死亡骑士受到的伤害降低{1}%。"
D.SharedStrings[5274]="召唤一支由初生奥术歼灭者组成的军团协助萨格雷作战。歼灭者会席卷该区域，并扫除一切障碍。"
D.SharedStrings[5275]="召唤一条被征服的尤格-萨隆触须协助你作战。"
D.SharedStrings[5276]="召唤一枚冰冻之球协助施法者。"
D.SharedStrings[5277]="召唤一枚冰雪宝珠来保护施法者。"
D.SharedStrings[5278]="召唤一枚动力炸弹。炸弹飞向地面并在接触后爆炸。直接伤害被炸弹吸收并转换为能量，使炸弹每一击都能飞的更高。"
D.SharedStrings[5279]="召唤一枚闪光的符文，在4秒后对邻近敌人造成{2}点火焰伤害。"
D.SharedStrings[5280]="召唤一根冰锥。"
D.SharedStrings[5281]="召唤一根树苗。"
D.SharedStrings[5282]="召唤一根火柱，灼烧指定区域内的所有敌人，并对它们造成额外伤害。"
D.SharedStrings[5283]="召唤一根逆流图腾，将45码范围内的敌人牵引过来。"
D.SharedStrings[5284]="召唤一次空中打击，对一名敌方目标造成火焰伤害。"
D.SharedStrings[5285]="召唤一片奥能区域，使区域内所有单位的急速提高{1}%。"
D.SharedStrings[5286]="召唤一系列以施法者为中心向外快速辐射的音波之环。音波之环对行进路线上的所有玩家造成{1}点物理伤害。"
D.SharedStrings[5287]="召唤一群乌鸦，在随后的{1}秒内攻击你的目标。如果用于生命值低于20%的目标，冷却时间将会被降低至60秒。"
D.SharedStrings[5288]="召唤一股寒风冲击目标区域，使目标受到的所有冰霜伤害提高{1}%。"
D.SharedStrings[5289]="召唤一股治愈性的熏香云雾，如果敌人在范围内则每1.5秒治疗施法者最大生命值的{1}%。"
D.SharedStrings[5290]="召唤一连串的奥术宝珠，这些宝珠会随机选择地点。在到达目标位置后，宝珠会发生爆炸，造成奥术伤害。"
D.SharedStrings[5291]="召唤一道光芒。"
D.SharedStrings[5292]="召唤一道冰霜攻击其行进路线上的敌人。"
D.SharedStrings[5293]="召唤一道旋转气流。"
D.SharedStrings[5294]="召唤一道火焰波攻击其行进路线上的敌人。"
D.SharedStrings[5295]="召唤一道闪电冲击，使地面带上电荷，在10秒内对此区域内的所有生物造成大量自然伤害。"
D.SharedStrings[5296]="召唤一道随机移动的飓风，靠近飓风的敌人会被卷上天空。"
D.SharedStrings[5297]="召唤一队天角拦截者对一个区域进行扫射，造成物理伤害。"
D.SharedStrings[5298]="召唤一阵冰雨，对冲击区域造成冰霜伤害。"
D.SharedStrings[5299]="召唤一阵旋风，撕裂行进路线上的所有敌人。"
D.SharedStrings[5300]="召唤一阵邪能火雨，对冲击区域造成火焰伤害。"
D.SharedStrings[5301]="召唤一阵邪能火雨，对击中的区域造成火焰伤害。"
D.SharedStrings[5302]="召唤一颗异界孢子。"
D.SharedStrings[5303]="召唤一颗深渊巨石从天而降，造成火焰伤害。"
D.SharedStrings[5304]="召唤一颗熔火流星，对附近的敌人造成毁灭性的伤害。"
D.SharedStrings[5305]="召唤不稳定的地狱火，对冲击点的敌人造成火焰伤害，并将其击退。"
D.SharedStrings[5306]="召唤两枚冰冻之球协助施法者。"
D.SharedStrings[5307]="召唤亡者的悲惨骸骨。"
D.SharedStrings[5308]="召唤伊芙琳之怒，对区域内的所有敌人造成{1}点自然伤害。 "
D.SharedStrings[5309]="召唤佩佩趴在你头上，陪你一起冒险。"
D.SharedStrings[5310]="召唤其他逝去的野兽之灵来践踏敌人。"
D.SharedStrings[5311]="召唤几只地穴甲虫来攻击施法者的目标。"
D.SharedStrings[5312]="召唤几只墓穴甲虫攻击施法者的目标。"
D.SharedStrings[5313]="召唤几只邪能魔仆协助末日使徒塔拉尔。"
D.SharedStrings[5314]="召唤凯希尔的雷象来帮助你！"
D.SharedStrings[5315]="召唤凶猛的洪水，对附近敌人造成冰霜伤害。"
D.SharedStrings[5316]="召唤出一个幻影协助施法者。"
D.SharedStrings[5317]="召唤出一个影魔。影魔会使一个目标昏迷，并追逐该目标直到死亡。"
D.SharedStrings[5318]="召唤出一个治疗结界，治疗任何站在其中的盟友。"
D.SharedStrings[5319]="召唤出一只洞穴蜘蛛协助施法者。"
D.SharedStrings[5320]="召唤出一只鬼影般的幽灵狼协助施法者。"
D.SharedStrings[5321]="召唤出一只鬼影般的虚空狼协助施法者。"
D.SharedStrings[5322]="召唤出一群各式各样的生物并将施法者传送到安全的敌方。"
D.SharedStrings[5323]="召唤出一道会向随机方向延伸的烈焰火柱，烧尽沿途的一切。"
D.SharedStrings[5324]="召唤双子与你并肩作战，可以在萨洛拉丝女王和高阶术士奥蕾塞丝之间切换。"
D.SharedStrings[5325]="召唤地狱战马"
D.SharedStrings[5326]="召唤地狱犬协助施法者。"
D.SharedStrings[5327]="召唤墓穴甲虫群攻击所有邻近的敌方目标。"
D.SharedStrings[5328]="召唤天角拦截者对选中的区域进行扫射，造成物理伤害。"
D.SharedStrings[5329]="召唤宠物。"
D.SharedStrings[5330]="召唤审判官之眼并通过它来观察世界。审判官之眼处于潜行状态，且移动迅速，但是非常脆弱。"
D.SharedStrings[5331]="召唤小鬼协助施法者，直到被解散。"
D.SharedStrings[5332]="召唤小鬼最害怕的一副景象。"
D.SharedStrings[5333]="召唤巴罗夫家族的3个仆人为你战斗、做饭和打扫。"
D.SharedStrings[5334]="召唤帕米拉·雷德帕斯的灵魂来陪伴你穿越东瘟疫之地。"
D.SharedStrings[5335]="召唤幽灵狼群。"
D.SharedStrings[5336]="召唤弗蕾亚的盟友为保卫奥杜尔而战。"
D.SharedStrings[5337]="召唤很多奶牛为你而战。"
D.SharedStrings[5338]="召唤或取消一只可供骑乘的魔法公鸡。不是开玩笑。"
D.SharedStrings[5339]="召唤或解散一只可供骑乘的熊猫人风筝。这是一种飞行坐骑。"
D.SharedStrings[5340]="召唤或解散一只可供骑乘的白色迅猛龙。"
D.SharedStrings[5341]="召唤或解散一只可供骑乘的绿色机械陆行鸟。"
D.SharedStrings[5342]="召唤或解散一只可供骑乘的蓝色机械陆行鸟。"
D.SharedStrings[5343]="召唤或解散一只可供骑乘的血牙寡妇蜘蛛。"
D.SharedStrings[5344]="召唤或解散一只可供骑乘的陆行鸟。"
D.SharedStrings[5345]="召唤或解散一只可供骑乘的黑锋骸骨狮鹫。只能在外域和诺森德召唤这种坐骑。这种坐骑的速度会根据你的骑术技能的等级改变。"
D.SharedStrings[5346]="召唤或解散一头可供骑乘的其拉作战坦克。"
D.SharedStrings[5347]="召唤或解散一头可供骑乘的冰雪猛犸象。"
D.SharedStrings[5348]="召唤或解散一头可供骑乘的出租狮鹫。只能在风暴峭壁、冰冠冰川和索拉查盆地召唤这种坐骑。"
D.SharedStrings[5349]="召唤或解散一头可供骑乘的出租驭风者。只能在风暴峭壁、冰冠冰川和索拉查盆地召唤这种坐骑。"
D.SharedStrings[5350]="召唤或解散一头可供骑乘的炽焰角鹰兽。"
D.SharedStrings[5351]="召唤或解散一头可供骑乘的红色龙鹰。这是一种飞行坐骑。"
D.SharedStrings[5352]="召唤或解散一头可供骑乘的美酒节科多兽。"
D.SharedStrings[5353]="召唤或解散一头可供骑乘的虚空幼龙坐骑。"
D.SharedStrings[5354]="召唤或解散一头可供骑乘的装甲棕熊。"
D.SharedStrings[5355]="召唤或解散一头可供骑乘的迅捷晨刃豹。"
D.SharedStrings[5356]="召唤或解散一头可供骑乘的迅捷棕马。"
D.SharedStrings[5357]="召唤或解散一头可供骑乘的重型冰雪猛犸象。可以运载3名乘员。"
D.SharedStrings[5358]="召唤或解散一头可供骑乘的重型旅行猛犸象。可以运载3名乘员。"
D.SharedStrings[5359]="召唤或解散一头可供骑乘的长毛猛犸象。"
D.SharedStrings[5360]="召唤或解散一头可供骑乘的阿曼尼战熊。"
D.SharedStrings[5361]="召唤或解散一头可供骑乘的驯鹿。"
D.SharedStrings[5362]="召唤或解散一头可供骑乘的黑色夜刃豹。"
D.SharedStrings[5363]="召唤或解散一头可供骑乘的黑色战熊。"
D.SharedStrings[5364]="召唤或解散一条可供骑乘的冰霜巨龙坐骑。"
D.SharedStrings[5365]="召唤或解散一条可供骑乘的黑色猛犸战象。"
D.SharedStrings[5366]="召唤或解散你同意在儿童周中抚养的孤儿。"
D.SharedStrings[5367]="召唤或解散你的伙伴班禄。这是一种飞行坐骑。"
D.SharedStrings[5368]="召唤或解散你的先知的狂怒风暴。这是一种飞行坐骑。"
D.SharedStrings[5369]="召唤或解散你的大法师的棱光飞碟。这是一种飞行坐骑。"
D.SharedStrings[5370]="召唤或解散你的大祭司的光誓寻觅者。这是一种飞行坐骑。"
D.SharedStrings[5371]="召唤或解散你的大领主的金辉战马。这是一种飞行坐骑。"
D.SharedStrings[5372]="召唤或解散你的屠魔者的破邪尖啸者。这是一种飞行坐骑。"
D.SharedStrings[5373]="召唤或解散你的战争领主的嗜血战龙。这是一种飞行坐骑。"
D.SharedStrings[5374]="召唤或解散你的暗影之刃的谋杀预兆。这是一种飞行坐骑。"
D.SharedStrings[5375]="召唤或解散你的暴雪巨熊。"
D.SharedStrings[5376]="召唤或解散你的死亡领主的邪嗣征服者。这是一种飞行坐骑。"
D.SharedStrings[5377]="召唤或解散你的气球。"
D.SharedStrings[5378]="召唤或解散你的虚空领主的混沌愤怒战马。这是一种飞行坐骑。"
D.SharedStrings[5379]="召唤攻城地狱火！"
D.SharedStrings[5380]="召唤旅行者的苔原猛犸象，还有两名伙伴随行！这是一种速度非常快的坐骑！"
D.SharedStrings[5381]="召唤无头骑士"
D.SharedStrings[5382]="召唤无常烈焰，在竞技场中四处游荡，任何被触碰到的玩家都会受到{1}点火焰伤害。若无常烈焰触碰到瓦安，则会提高其伤害和施法速度。"
D.SharedStrings[5383]="召唤来自阿古斯的礼物，命中时对区域范围造成火焰伤害。"
D.SharedStrings[5384]="召唤欠欠来到施法者身边，直到被解散。"
D.SharedStrings[5385]="召唤水元素保护施法者。"
D.SharedStrings[5386]="召唤河鬃萨满。"
D.SharedStrings[5387]="召唤泽拉，揭示远古的记忆。"
D.SharedStrings[5388]="召唤流星从天而降。"
D.SharedStrings[5389]="召唤流星雨，在冲击点造成火焰伤害。"
D.SharedStrings[5390]="召唤深渊魔的仪式非常复杂，而且经常失败。当仪式失败的时候，经常会留下一小块恶魔的碎片，恶魔的怒火及它对自己无能的绝望在碎片中翻腾着。古代的战场上到处都散布着这样的石头。"
D.SharedStrings[5391]="召唤混乱之雨，烧灼指定区域内的所有敌人，造成混乱伤害。"
D.SharedStrings[5392]="召唤火焰之雨，每秒对指定区域中的敌人造成火焰伤害。"
D.SharedStrings[5393]="召唤猛烈的台风，对其触碰到的敌人造成{1}点自然伤害。"
D.SharedStrings[5394]="召唤球状闪电"
D.SharedStrings[5395]="召唤盟友到吉安娜身旁。"
D.SharedStrings[5396]="召唤砾石佩波。"
D.SharedStrings[5397]="召唤神圣魔法的能量治疗附近所有的队友。"
D.SharedStrings[5398]="召唤离子球"
D.SharedStrings[5399]="召唤美酒女郎，她的出现可以提高队伍的士气。向她招手就可获得美酒节的佳酿！"
D.SharedStrings[5400]="召唤群星攻击所有目标，每次造成{1}点奥术伤害。"
D.SharedStrings[5401]="召唤群星攻击所有目标，每颗星星都会造成奥术伤害。"
D.SharedStrings[5402]="召唤群星攻击所有目标，造成奥术伤害。"
D.SharedStrings[5403]="召唤者诺沃斯"
D.SharedStrings[5404]="召唤者阿拉基在一次莫名其妙的胜利之后占据了安多哈尔。我们知道他以前曾是通灵学院的领导者，为了完成钥匙，我们就必须拿到他的那个被称作圣甲虫的图章，用它来制作钥匙的头部。$B$B攻入他的要塞，把他干掉。$B$B杀掉召唤者阿拉基之后，就把他的圣甲虫给我拿回来！$B$B通灵学院的钥匙在等着你，$n！"
D.SharedStrings[5405]="召唤自然之力治疗盟友。"
D.SharedStrings[5406]="召唤自然魔法治疗一名盟友。"
D.SharedStrings[5407]="召唤自然魔法，治疗目标盟友，数值相当于其生命值的{1}%。"
D.SharedStrings[5408]="召唤艾露恩的双眼，沉默附近的敌人并对其造成奥术伤害。"
D.SharedStrings[5409]="召唤虚空领域，对站在里面的敌人造成暗影伤害。"
D.SharedStrings[5410]="召唤虚空领域，对站在领域中的敌人造成暗影伤害。"
D.SharedStrings[5411]="召唤蜂拥的虫群，对站在虫群中的目标造成{1}点自然伤害。\r\n并使他们攻击命中的几率降低{2}%。"
D.SharedStrings[5412]="召唤要塞的部队突袭某个区域。"
D.SharedStrings[5413]="召唤要塞里的部队协助你对抗巫师领主莫库克。"
D.SharedStrings[5414]="召唤赞达拉远古之神的帮助。解锁额外的技能。"
D.SharedStrings[5415]="召唤达库鲁的灵魂精华，持续一小段时间。"
D.SharedStrings[5416]="召唤重型冰雪猛犸象！这是一头速度非常快的猛犸象！可以搭载两名乘客（必须与驾驶员在同一支队伍中）。"
D.SharedStrings[5417]="召唤重型黑色猛犸战象！这是一头速度非常快的猛犸象！可以搭载两名乘客（必须与驾驶员在同一支队伍中）。"
D.SharedStrings[5418]="召唤铲齿鹿的野性之魂来激励召唤者的灵魂。"
D.SharedStrings[5419]="召唤闪电，将其附魔在施法者的箭矢上。附魔后的基础远程攻击将造成额外的{1}点自然伤害。"
D.SharedStrings[5420]="召唤阵风，每1秒对12码范围内的所有敌人造成{1}点自然伤害。"
D.SharedStrings[5421]="召唤阿维亚什听从你的命令。"
D.SharedStrings[5422]="召唤音波之环。"
D.SharedStrings[5423]="召唤食人魔角斗士搏命厮杀供人娱乐。"
D.SharedStrings[5424]="召唤食尸鬼攻击敌人，为阿彻鲁斯之眼争取时间。"
D.SharedStrings[5425]="召唤食尸鬼攻击敌人，使你有时间控制阿彻鲁斯之眼逃到安全地带。"
D.SharedStrings[5426]="召唤黑暗魔法从天而降，对冲击区域造成暗影伤害。"
D.SharedStrings[5427]="召唤黑曜石先知附近的不灭烈焰。"
D.SharedStrings[5428]="召唤黑铁美酒女郎，她会用你的空酒杯去揍你的敌人。向她招手就可获得美酒节的佳酿！"
D.SharedStrings[5429]="召唤黯石援兵。"
D.SharedStrings[5430]="召回阿彻鲁斯之眼。"
D.SharedStrings[5431]="召火者洛顿"
D.SharedStrings[5432]="召焰者维兹拉"
D.SharedStrings[5433]="可从怪物身上获取额外宝物，由安古斯·铁拳友情赞助。"
D.SharedStrings[5434]="可代替任何较低等级的附魔棒。"
D.SharedStrings[5435]="可以凭此证明在赛羊会学徒处购买美酒节赛羊。"
D.SharedStrings[5436]="可以卖给某些德拉诺商人换取货物和金币。"
D.SharedStrings[5437]="可以召唤阿格拉玛之怒。"
D.SharedStrings[5438]="可以和主人一起飞翔。"
D.SharedStrings[5439]="可以在副手上装备单手和副手武器。"
D.SharedStrings[5440]="可以在副手装备所有武器。"
D.SharedStrings[5441]="可以在拍卖行购买和出售。"
D.SharedStrings[5442]="可以在水上行走。"
D.SharedStrings[5443]="可以在水上行走。任何伤害都会取消这个效果。"
D.SharedStrings[5444]="可以在水下呼吸。"
D.SharedStrings[5445]="可以在水下呼吸，并且在瓦尔莎拉时海床移动速度提高{1}%。"
D.SharedStrings[5446]="可以在水面上行走。"
D.SharedStrings[5447]="可以在游泳时施放法术和技能。"
D.SharedStrings[5448]="可以在破碎群岛中治疗发烧的探险者。"
D.SharedStrings[5449]="可以在破碎群岛中治疗受伤的冒险者。"
D.SharedStrings[5450]="可以在邪能页岩矿脉中找到更多的材料。"
D.SharedStrings[5451]="可以在野兽身上找到，或由拥有剥皮技能的玩家收集。可以在拍卖行购买和出售。"
D.SharedStrings[5452]="可以在骑乘状态下与目标互动。"
D.SharedStrings[5453]="可以在魔石矿脉中找到更多的材料。"
D.SharedStrings[5454]="可以对其它魔蝎造成一定伤害的攻击。"
D.SharedStrings[5455]="可以将管子连接到漂浮于水面上的浮筒，用以在水下呼吸。如果管子破裂，则必须重新装备头盔。"
D.SharedStrings[5456]="可以打开很复杂的锁，需消耗万能钥匙。"
D.SharedStrings[5457]="可以打开需求开锁技能{1}点的锁。需消耗万能钥匙。"
D.SharedStrings[5458]="可以放置烟花炸药桶。烟花炸药桶被引爆时会对附近的敌人造成{1}点火焰伤害。"
D.SharedStrings[5459]="可以现场调整天赋。"
D.SharedStrings[5460]="可以看到隐形与潜行的敌人。\r\n可以穿过实体障碍物看到敌人和宝藏。"
D.SharedStrings[5461]="可以蒙骗血色先锋军。必须留在新壁炉谷中，不然幻象就会消失！"
D.SharedStrings[5462]="可作为剥皮刀使用。"
D.SharedStrings[5463]="可作为矿工锄使用。"
D.SharedStrings[5464]="可口可乐使者"
D.SharedStrings[5465]="可在你的要塞专业技能建筑里或阿什兰处换取配方。"
D.SharedStrings[5466]="可在元素转化时代替点金石使用。"
D.SharedStrings[5467]="可在达拉然的抑魔金熔炉摧毁制造物品时获得。"
D.SharedStrings[5468]="可将8码外憎恨的目标拖拽过来。"
D.SharedStrings[5469]="可怕的嗜魔者"
D.SharedStrings[5470]="可怕的恶魔伊莫拉斯带领着一支燃烧军团的部队，征服并统治了一个遥远的枢纽世界。\n\n守望者们费尽艰辛才把他制服，并关在了左边的密室里。虽然他被控制住了，但这种情况持续不了太久。\n\n如果有恶魔猎手能够打败他，那么他的恶魔力量就会成为一份宝贵的战利品，让胜利者获得难以想象的力量。\n\n我相信你可以做到，$n。"
D.SharedStrings[5471]="可怕的纪念品"
D.SharedStrings[5472]="可怕的萨尼法克斯"
D.SharedStrings[5473]="可恨的斯麦斯帕"
D.SharedStrings[5474]="可恨的斯麦斯帕将他的视线锁定在一个目标身上。\r\n\r\n怨恨凝视结束后，斯麦斯帕会向受到影响玩家的方向发动一次怨恨冲锋。"
D.SharedStrings[5475]="可恨的斯麦斯帕将他的视线锁定在你的身上！"
