D.SharedStrings[5586]="同盟种族：虚空精灵"
D.SharedStrings[5587]="同罗克·维普杉克交谈，然后随同莫尔杉商队向北进发。"
D.SharedStrings[5588]="同龙喉哨站的欧纳克交谈。霍尔佐格可以为你提供通往岸边的快速交通。"
D.SharedStrings[5589]="后备亡灵卫兵"
D.SharedStrings[5590]="后方已经安全"
D.SharedStrings[5591]="吐出带有疾病的亡灵秽物，造成自然伤害。"
D.SharedStrings[5592]="吐出酸液，对施法者前方的敌人造成{1}点自然伤害。"
D.SharedStrings[5593]="向10码范围内的入侵者射出一道光束，触碰时造成伤害。"
D.SharedStrings[5594]="向20-45码范围之间的所有敌人发射暗影箭。"
D.SharedStrings[5595]="向一个友方玩家扔出纸飞艇，如果目标的背包中有空位，就可以接住飞艇！"
D.SharedStrings[5596]="向一个敌人冲锋，将其击退并造成物理伤害。"
D.SharedStrings[5597]="向一个敌人冲锋，造成普通伤害外加额外伤害，并击退对手。"
D.SharedStrings[5598]="向一个敌人发射一支扭曲魔法之箭，造成暮光伤害。"
D.SharedStrings[5599]="向一个敌人发射一支闪电箭，造成自然伤害。"
D.SharedStrings[5600]="向一个敌人发射水箭，造成{1}点冰霜伤害。"
D.SharedStrings[5601]="向一个敌人发射水箭，造成中等的冰霜伤害。"
D.SharedStrings[5602]="向一个敌人发射炮弹，造成大量伤害并使其昏迷。"
D.SharedStrings[5603]="向一个敌人发射烈焰之箭，造成武器伤害再加上{1}点伤害。所有伤害都算作火焰伤害。"
D.SharedStrings[5604]="向一个敌人发射魔法飞弹，造成奥术伤害。"
D.SharedStrings[5605]="向一个敌人射出一支水箭，造成自然伤害。"
D.SharedStrings[5606]="向一个敌人射击，造成物理伤害。"
D.SharedStrings[5607]="向一个敌人射击，造成物理伤害并产生很高的威胁值。"
D.SharedStrings[5608]="向一个敌人投掷一把风暴之锤。"
D.SharedStrings[5609]="向一个敌人投掷斧头，造成物理伤害，并将其击退。"
D.SharedStrings[5610]="向一个敌人投掷武器，造成物理伤害。"
D.SharedStrings[5611]="向一个敌人投掷武器，造成物理伤害，并使其移动速度减慢{1}%。"
D.SharedStrings[5612]="向一个敌人投掷毒药。"
D.SharedStrings[5613]="向一个敌人投掷石块，造成物理伤害。"
D.SharedStrings[5614]="向一个敌人投掷荆棘，造成{1}点自然伤害。"
D.SharedStrings[5615]="向一个敌人投掷药剂，造成自然伤害并使其中毒，受到持续性伤害。"
D.SharedStrings[5616]="向一个敌人投掷重型水晶，击中后对周围区域造成物理伤害。"
D.SharedStrings[5617]="向一个欧卡里隆的武器箱掷出一颗巴顿威洛的手榴弹。"
D.SharedStrings[5618]="向一个目标发动冲锋，造成{1}点物理伤害，并将其击退。"
D.SharedStrings[5619]="向一个目标发射等离子电球，造成{1}点法术火焰伤害。"
D.SharedStrings[5620]="向一个目标投掷邪焰，造成火焰伤害。"
D.SharedStrings[5621]="向一个目标抛掷熔岩，造成{1}点火焰伤害。"
D.SharedStrings[5622]="向一个目标注射蜘蛛卵，在短时间内孵化出小蜘蛛。"
D.SharedStrings[5623]="向一个随机友方目标召唤出一股平和的轻风。轻风扫过区域中的全部盟友每秒受到{1}点治疗。区域中的任何敌人都会进入沉默和平静状态，直到他们离开此区域。此效果可持续30秒。"
D.SharedStrings[5624]="向一个随机目标发射一道邪能火焰冲击，造成{1}点火焰伤害。"
D.SharedStrings[5625]="向一个随机目标发射化学炸弹，使该区域形成一片化学云雾。"
D.SharedStrings[5626]="向一个随机目标发射能量脉冲，对面向目标的一个锥形区域内的敌人造成{1}点法术火焰伤害。"
D.SharedStrings[5627]="向一位潜在客户招手示意。或许他们会来尝尝你的汤面？"
D.SharedStrings[5628]="向一只恐魔蝙蝠发射一枚受到艾露恩祝福的箭矢。"
D.SharedStrings[5629]="向一只邪翼游荡者投掷并将它拉回地面。"
D.SharedStrings[5630]="向一名卫兵敬礼，获得其外观。"
D.SharedStrings[5631]="向一名搏击俱乐部代表出示此卡牌以挑战奥里斯。你同一时间内只能拥有一张挑战卡牌。"
D.SharedStrings[5632]="向一名敌人冲锋。"
D.SharedStrings[5633]="向一名敌人冲锋，对所有敌人造成{1}点物理伤害并将其击退。"
D.SharedStrings[5634]="向一名敌人冲锋，造成物理伤害。"
D.SharedStrings[5635]="向一名敌人发射一束能量箭，造成奥术伤害。"
D.SharedStrings[5636]="向一名敌人发射魔法飞弹，对其造成奥术伤害。"
D.SharedStrings[5637]="向一名敌人射出一支熔岩箭，造成火焰伤害。"
D.SharedStrings[5638]="向一名敌人射出一支闪电箭，这支闪电箭在击中目标后会跳跃攻击在其周围的所有敌人。该法术会对每一名目标造成{1}点自然伤害。"
D.SharedStrings[5639]="向一名敌人射出一支闪电箭，这支闪电箭在击中目标后会跳跃攻击在其周围的所有敌人。该法术会对每一名目标造成自然伤害。"
D.SharedStrings[5640]="向一名敌人射出一股水柱，造成{1}点冰霜伤害，并将敌人击退。"
D.SharedStrings[5641]="向一名敌人射出烈焰之箭，使其脚下的地面熊熊燃烧。"
D.SharedStrings[5642]="向一名敌人射出藤蔓，使目标被定身并对所有被困住的敌人造成自然伤害。"
D.SharedStrings[5643]="向一名敌人射击，对其造成物理伤害。"
D.SharedStrings[5644]="向一名敌人扔出火球，造成火焰伤害。"
D.SharedStrings[5645]="向一名敌人投出一罐蜘蛛，造成暗影伤害，并召唤小蜘蛛来协助你达到邪恶的目的！"
D.SharedStrings[5646]="向一名敌人投掷尖刺，造成物理伤害。"
D.SharedStrings[5647]="向一名敌人投掷武器，造成持续的物理伤害。"
D.SharedStrings[5648]="向一名敌人投掷毒药，造成自然伤害。"
D.SharedStrings[5649]="向一名敌人投掷熔火邪能，造成火焰伤害。"
D.SharedStrings[5650]="向一名敌人掷出一块岩石，造成物理伤害。"
D.SharedStrings[5651]="向一名敌人释放恶魔能量冲击，对其造成混乱伤害。"
D.SharedStrings[5652]="向一名盟友发射绷带。可能造成脑震荡。"
D.SharedStrings[5653]="向一名随机敌方目标喷吐毒液。毒液喷吐的飞行速度会受到风向的影响。"
D.SharedStrings[5654]="向一名随机目标冲锋，对目的地附近的所有敌人造成暗影伤害。"
D.SharedStrings[5655]="向一小块地面喷射蛛网，经过这里的任何人都会被定身。"
D.SharedStrings[5656]="向一队敌人射出一大团炽烈的火焰，造成{1}点火焰伤害，并将他们击退。"
D.SharedStrings[5657]="向上高飞。\r\n不可攻击。"
D.SharedStrings[5658]="向两个随机敌人滚出熔岩巨石，撕裂大地并喷发，造成{1}点火焰伤害。"
D.SharedStrings[5659]="向你显示后续还有几波僵尸会攻过来。"
D.SharedStrings[5660]="向你的当前敌方目标投出一发暗影箭，造成暗影伤害。"
D.SharedStrings[5661]="向你的目标掷出三叉戟，把他们向你拖过来，造成{1}点物理伤害，并对目标造成嘲讽。"
D.SharedStrings[5662]="向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效施法。请把徽记之戒给我，我来灌注能量。"
D.SharedStrings[5663]="向你致敬，强大的$C!你有没有带来我要的银色黎明勇气勋章?当你把它们交给我之后，我就会把炫彩黎明披肩给你。"
D.SharedStrings[5664]="向军械库岗哨发信号，对目标区域进行火炮轰击。"
D.SharedStrings[5665]="向前冲锋20码，对附近的敌人造成伤害并使其短暂昏迷。"
D.SharedStrings[5666]="向前冲锋，伤害并击退其行径路线上的所有单位。"
D.SharedStrings[5667]="向前冲锋，对施法者行进路线上的所有敌人造成物理伤害，并将其击退。"
D.SharedStrings[5668]="向前冲锋，造成物理伤害并将敌人击退。"
D.SharedStrings[5669]="向前冲锋，造成物理伤害并将敌人击飞到空中。"
D.SharedStrings[5670]="向前发射一颗奥术之球，对其经过的敌人造成奥术伤害。"
D.SharedStrings[5671]="向前方一条直线上射出大量炮弹，造成物理伤害。"
D.SharedStrings[5672]="向前方发射一支烈焰箭矢，对其路径上的所有敌人造成火焰伤害。"
D.SharedStrings[5673]="向前方的敌人喷出闪电。"
D.SharedStrings[5674]="向前方锥形区域喷射强劲气流，造成持续增长的暗影伤害。"
D.SharedStrings[5675]="向前突进，击退前方锥形区域内的单位，并造成物理伤害。"
D.SharedStrings[5676]="向北荆棘谷的奈辛瓦里远征队的艾耶克·罗欧克复命。"
D.SharedStrings[5677]="向北贫瘠之地，十字路口的索克报告。"
D.SharedStrings[5678]="向卓格巴尔喷洒吸引虫子的迷雾。"
D.SharedStrings[5679]="向南贫瘠之地北方城堡的海军司令奥布里报到。"
D.SharedStrings[5680]="向南贫瘠之地缇甘远征军营地的缇甘下士报到。"
D.SharedStrings[5681]="向卡拉赞东南方废墟内的扎佐·耀指复命。"
D.SharedStrings[5682]="向各个方向喷发暗影，在附近随机生成暗影之池。暗影之池击中目标后造成暗影伤害。"
D.SharedStrings[5683]="向各个方向喷射火焰，形成一团团烈焰以产生太阳赐福之魂。"
D.SharedStrings[5684]="向各个方向射出水流，对附近的敌人造成冰霜伤害，并将它们击退。"
D.SharedStrings[5685]="向后短距离翻滚。"
D.SharedStrings[5686]="向后翻滚一小段距离。"
D.SharedStrings[5687]="向周围的敌人发射弧形的燃烧琥珀之箭。"
D.SharedStrings[5688]="向周围的敌人射击。"
D.SharedStrings[5689]="向周围释放闪电弧。"
D.SharedStrings[5690]="向商人出售物品所得金币"
D.SharedStrings[5691]="向四面八方射出充满神圣能量的箭矢，对目标和其身旁的敌人目标造成{1}点神圣伤害，每次跳跃强化50%。"
D.SharedStrings[5692]="向四面八方投掷炸弹。"
D.SharedStrings[5693]="向地上喷吐熔岩寄生虫，对熔岩巨虫前的敌人造成{1}点火焰伤害。"
D.SharedStrings[5694]="向地上扔一个烟雾弹，造成{1}点伤害，并使站在其中的玩家命中几率降低{2}%。"
D.SharedStrings[5695]="向地精小队发出信号，让他们空降过来援助你。"
D.SharedStrings[5696]="向地面位置投掷邪火炸弹，使其爆燃。邪火炸弹会对命中目标每秒造成一次火焰伤害。"
D.SharedStrings[5697]="向地面投掷一枚烟雾弹，造成伤害并使站在其中的玩家命中几率降低。"
D.SharedStrings[5698]="向塞西莉亚的栖地的下列NPC打招呼（使用/wave指令）。"
D.SharedStrings[5699]="向多个敌人施放烈焰之刺，造成火焰伤害。"
D.SharedStrings[5700]="向多个目标投射煞能量，造成暗影伤害并增加其仇恨。"
D.SharedStrings[5701]="向天空中射出一个焰火，让它绽放出千颗紫色的星星。"
D.SharedStrings[5702]="向天空中射出一个焰火，让它绽放出千颗红色的星星。"
D.SharedStrings[5703]="向天空中射出一个焰火，让它绽放出许多红色条纹。"
D.SharedStrings[5704]="向天空中射出一个焰火，让它绽放出黄色玫瑰图案。"
D.SharedStrings[5705]="向安戈洛环形山入口处的加尔·暴风爪报到。"
D.SharedStrings[5706]="向尖啸反舌鸟发射一团邪能能量，在命中时将其蒸发。"
D.SharedStrings[5707]="向当前目标释放一波火焰，造成{1}点火焰伤害。"
D.SharedStrings[5708]="向影牙城堡的调查员费岑·布莱斯塔克报告。"
D.SharedStrings[5709]="向心塌缩护肩"
