D.SharedStrings[5711]="向战歌要塞南方小屋里的拉兹格尔大王报到。"
D.SharedStrings[5712]="向所有敌人射出毒箭，造成{1}点自然伤害。"
D.SharedStrings[5713]="向所有玩家射出暗影能量箭雨，造成{1}点暗影伤害。"
D.SharedStrings[5714]="向指定区域发射一枚高爆炸弹，对6码范围内的敌人造成火焰伤害，并将其击退。"
D.SharedStrings[5715]="向攻击者发射充满神圣能量的光束。"
