D.SharedStrings[5719]="向敌人位置投掷燃烧的液体。"
D.SharedStrings[5720]="向敌人冲锋，对其造成相当于{1}%武器伤害的火焰伤害，并将目标击倒。"
D.SharedStrings[5721]="向敌人冲锋，对目标和它周围的盟友造成{1}点伤害，并将它们击退。"
D.SharedStrings[5722]="向敌人冲锋，将其击退并造成{1}点伤害。"
D.SharedStrings[5723]="向敌人冲锋，将其击退并造成{1}点物理伤害。"
D.SharedStrings[5724]="向敌人冲锋，将其击退并造成普通伤害加上{1}点伤害。"
D.SharedStrings[5725]="向敌人冲锋，造成奥术伤害。"
