D.SharedStrings[5792]="向施法者前方的敌人投出数枚邪能箭，造成{1}点火焰伤害。"
D.SharedStrings[5793]="向施法者前方锥形范围内的敌人喷洒剧毒，对被击中的敌人造成自然伤害。"
D.SharedStrings[5794]="向施法者的武器注入暗影能量，攻击命中后有一定几率激发一次能够造成暗影伤害的额外近战攻击。"
D.SharedStrings[5795]="向施法者身前的敌人喷射毒药，对其造成{1}点自然伤害。"
D.SharedStrings[5796]="向暗月马戏团的亚布·尼比盖尔复命。"
D.SharedStrings[5797]="向暗矛要塞中的沃金报到。"
D.SharedStrings[5798]="向暮光高地暮光海滩的海军上尉埃姆利报到。"
D.SharedStrings[5799]="向暮光高地溅血谷地的纳克拉尔·掠爪报到。"
D.SharedStrings[5800]="向暮光高地爬蛇海湾的格拉洛克报到。"
D.SharedStrings[5801]="向更多的艾泽拉斯小动物展示你的爱心（使用/love命令）。"
D.SharedStrings[5802]="向正前方发射一枚爆炸火箭，在命中飞行目标后爆炸。"
D.SharedStrings[5803]="向正前方发射爆炸性的导弹，在其飞行100码之后爆炸，攻击周围半径10码范围内的所有敌人。"
