D.SharedStrings[5809]="向目标丢掷一片随机食物，造成物理伤害。"
D.SharedStrings[5810]="向目标位置发射一枚火箭，造成{1}点火焰伤害，并将敌人从冲击点击退。"
D.SharedStrings[5811]="向目标位置发射一组烟火，让它绽放出黄色的火花。"
