D.SharedStrings[5818]="向目标位置投掷一跟魔力香蕉，绊倒第一个踩中它的人。"
D.SharedStrings[5819]="向目标位置释放痛苦的灵魂，造成暗影伤害，并在该处留下一个痛苦灵魂之井。"
