D.SharedStrings[5822]="向目标区域倾泄岩石碎片。"
D.SharedStrings[5823]="向目标区域发射跳跃机器人身上装载的爆炸火箭弹，将敌人的跳跃机器人击退，并对其造成{1}%的伤害！"
