D.SharedStrings[5848]="向目标射出一股碎石，造成{1}点物理伤害并将其击入空中。"
D.SharedStrings[5849]="向目标射出火焰箭，对其造成火焰伤害。"
D.SharedStrings[5850]="向目标射出砂石箭，造成物理伤害。"
D.SharedStrings[5851]="向目标射出闪电箭，对其造成{1}点自然伤害。"
D.SharedStrings[5852]="向目标射出闪电箭，对其造成{1}点自然伤害，并产生{2}点漩涡值。"
D.SharedStrings[5853]="向目标射出闪电，造成自然伤害。"
D.SharedStrings[5854]="向目标射出魔法箭，对其造成奥术伤害。"
D.SharedStrings[5855]="向目标尖叫，发出强有力的音波冲击。"
D.SharedStrings[5856]="向目标投出一团烈火，造成火焰伤害。"
D.SharedStrings[5857]="向目标投出虚空能量球，造成{1}点暗影伤害。"
D.SharedStrings[5858]="向目标投掷一把鱼叉，造成{1}点伤害。"
D.SharedStrings[5859]="向目标投掷强化后的盾牌，对目标及其周围的所有敌人造成神圣伤害。"
D.SharedStrings[5860]="向目标投掷暮光闪电箭，造成自然伤害。"
D.SharedStrings[5861]="向目标投掷武器，造成物理伤害。"
D.SharedStrings[5862]="向目标投掷熔岩，造成{1}点火焰伤害。"
D.SharedStrings[5863]="向目标投掷熔岩，造成{1}点火焰伤害。如果目标身上有烈焰震击效果，熔岩爆裂会消耗烈焰震击，并造成双倍伤害。"
D.SharedStrings[5864]="向目标投掷熔岩，造成{1}点火焰伤害。如果目标身上有烈焰震击效果，熔岩爆裂会消耗烈焰震击，并造成爆击。"
D.SharedStrings[5865]="向目标投掷熔岩，造成火焰伤害。"
D.SharedStrings[5866]="向目标投掷闪电之球，造成{1}点伤害。"
D.SharedStrings[5867]="向目标掷出一把扳手，对其造成物理伤害。"
D.SharedStrings[5868]="向目标掷出一把武器，对其造成物理伤害。"
D.SharedStrings[5869]="向目标敌人冲锋，对5码内所有敌人造成物理伤害。"
D.SharedStrings[5870]="向目标敌人射出一支黑暗魔法箭，造成暗影伤害。"
D.SharedStrings[5871]="向目标敌人投掷芜菁，造成物理伤害。"
D.SharedStrings[5872]="向目标敌方单位发射声波攻击，对你和目标之间的敌人造成伤害。"
D.SharedStrings[5873]="向目标的腿脚抛出套索，一旦套住便降低其移动速度。\r\n\r\n如果目标在跳跃则会失效。"
D.SharedStrings[5874]="向空中发射一支可以绽放出无数紫色星星的焰火。"
D.SharedStrings[5875]="向空中发射一支可以绽放出无数红色、白色和蓝色星星的焰火。"
D.SharedStrings[5876]="向空中发射一支可以绽放出无数红色星星的焰火。"
D.SharedStrings[5877]="向空中发射烟花。"
D.SharedStrings[5878]="向空中发射烟花，让它绽放出五彩缤纷的图案。"
D.SharedStrings[5879]="向空中发射烟花，让它绽放出绿色的火花。"
D.SharedStrings[5880]="向空中发射烟花，让它绽放成旋转光球的形态。"
D.SharedStrings[5881]="向空中发射烟花，让它绽放成青龙的形态。"
D.SharedStrings[5882]="向空中发射魔法飞弹集束，魔法飞弹会选择一个邻近的随机敌人目标并倾泻而下，造成{1}点奥术伤害。"
D.SharedStrings[5883]="向索隆迪爾致敬。願你的靈魂在英靈殿中尋得一席之地。"
D.SharedStrings[5884]="向能够导电的敌人射出一道闪电，造成{1}点自然伤害，随后闪电会跃向附近的其他目标，继续造成伤害。"
D.SharedStrings[5885]="向至高岭的罗诺斯·铁角报告你的遭遇。"
D.SharedStrings[5886]="向艾尔文森林北郡修道院前的治安官玛克布莱德报到。"
D.SharedStrings[5887]="向艾尔文森林北郡修道院后的维里副队长报到。"
D.SharedStrings[5888]="向艾泽拉斯的小动物展示你的爱心（使用/love命令）。"
D.SharedStrings[5889]="向落日酒坊的居民询问风暴烈酒族人的下落。"
D.SharedStrings[5890]="向螳螂妖女皇传播信息。\r\n无敌。\r\n捣毁扎尼提克共鸣水晶会移除这个效果。"
D.SharedStrings[5891]="向螳螂攻击者投掷一捆粘性炸药，造成{1}点火焰伤害，将其从目标区域击退，并在3秒后将所有炸药一一引爆，造成{2}点火焰伤害。"
D.SharedStrings[5892]="向西瘟疫之地北山伐木场的纳萨尼尔·杜马报告。"
D.SharedStrings[5893]="向西瘟疫之地壁炉谷的大领主提里奥·弗丁报告。"
D.SharedStrings[5894]="向西瘟疫之地安多哈尔城的希尔瓦娜斯·风行者复命。"
D.SharedStrings[5895]="向西瘟疫之地安多哈尔城的库尔迪拉·织亡者报告。"
D.SharedStrings[5896]="向西瘟疫之地安多哈尔城的萨萨里安报告。"
D.SharedStrings[5897]="向西瘟疫之地安多哈尔城里的库尔迪拉·织亡者报告。"
D.SharedStrings[5898]="向西瘟疫之地寒风营地的指挥官阿什拉姆·瓦罗菲斯特报告。"
D.SharedStrings[5899]="向西瘟疫之地治愈者营地的战地特工卡尔缇舍报告。"
D.SharedStrings[5900]="向西瘟疫之地被烧毁的前哨站的琳塞·鸦日报告"
D.SharedStrings[5901]="向远处投掷一个不稳定的木桶。"
D.SharedStrings[5902]="向远处的一名敌人冲锋，造成{1}%的武器伤害。"
D.SharedStrings[5903]="向远方投掷一只瘟疫桶。"
D.SharedStrings[5904]="向远方用力掷出一个巨石。"
D.SharedStrings[5905]="向选定的区域掷出一枚窒息毒气炸弹。"
D.SharedStrings[5906]="向逐日者之岛的太阳之塔里的寻路者卡雷尔汇报。"
D.SharedStrings[5907]="向锥形范围内吐息，造成火焰和自然伤害。"
D.SharedStrings[5908]="向附近一个敌人投掷炸弹。几秒后炸弹会爆炸，造成大量的火焰伤害。"
D.SharedStrings[5909]="向附近一名敌人掷出地雷。触发地雷会将其引爆，造成大量的火焰伤害。"
D.SharedStrings[5910]="向附近一名敌人脚下投掷一个陷阱，在数秒后发生爆炸。"
D.SharedStrings[5911]="向附近敌人射出多支黑暗魔法箭，造成{1}点暗影伤害。"
D.SharedStrings[5912]="向附近的一个敌对空中单位发射一枚强大的追踪导弹。"
D.SharedStrings[5913]="向附近的敌人发射一枚飞弹，摧毁他们的武器系统。"
D.SharedStrings[5914]="向附近的敌人发射暗影箭雨，对它们造成{1}点暗影伤害。"
D.SharedStrings[5915]="向附近的敌人发射暗影箭雨，对它们造成暗影伤害。"
D.SharedStrings[5916]="向附近的敌人发射魔法箭，对其造成奥术伤害。"
D.SharedStrings[5917]="向附近的敌人发射魔法箭，造成奥术伤害。"
D.SharedStrings[5918]="向附近的敌人发射黑暗的魔法箭，对其造成暗影伤害，并将其击退。"
D.SharedStrings[5919]="向附近的敌人射出利刺。"
D.SharedStrings[5920]="向附近的敌人射出利刺，造成物理伤害并使其流血。"
D.SharedStrings[5921]="向附近的敌人射出多支暗影箭，对它们造成{1}点暗影伤害。"
D.SharedStrings[5922]="向附近的敌人射出多支暗影箭，对它们造成暗影伤害。"
D.SharedStrings[5923]="向附近的敌人射出闪电箭，造成自然伤害。"
D.SharedStrings[5924]="向附近的玩家发射一道利刃弹幕，造成{1}点物理伤害。"
D.SharedStrings[5925]="向马绍尔哨站的霍莱伊·马绍尔复命。"
D.SharedStrings[5926]="向魔网能量注入远古魔力。"
D.SharedStrings[5927]="向黑尾拾骨者发射烈焰之箭。"
D.SharedStrings[5928]="吞咽者拉姆斯登"
D.SharedStrings[5929]="吞噬一个低阶野兽会为该单位恢复相当于其最大生命值{1}%的生命值。"
D.SharedStrings[5930]="吞噬一个低阶野兽会使该单位恢复{1}%的最大生命值。"
D.SharedStrings[5931]="吞噬一个低阶野兽可以使该单位恢复{1}%的最大生命值。"
D.SharedStrings[5932]="吞噬一个低阶野兽，使单位造成的伤害提高{1}%，移动速度提高{2}%，并为目标恢复相当于其最大生命值{3}%的生命值。"
D.SharedStrings[5933]="吞噬元素，令施法者获得不稳定的能量。"
D.SharedStrings[5934]="吞噬者之牙"
D.SharedStrings[5935]="吞噬者卡加克斯的鳞片，闪闪发光并且几乎刀枪不入。"
D.SharedStrings[5936]="吞噬者穆坦努斯"
D.SharedStrings[5937]="吞噬附近一个阵亡敌人的部分灵魂，使伤害提高{1}%。"
D.SharedStrings[5938]="吞噬附近所有生物的生命能量。\r\n\r\n注意！使用这项技能会消耗一块充能的聚焦水晶。"
D.SharedStrings[5939]="吞天之喉头盔"
D.SharedStrings[5940]="吞天之喉战盔"
D.SharedStrings[5941]="吞天之喉战铠"
D.SharedStrings[5942]="吞天之喉手甲"
D.SharedStrings[5943]="吞天之喉护手"
D.SharedStrings[5944]="吞天之喉护肩"
D.SharedStrings[5945]="吞天之喉护胸"
D.SharedStrings[5946]="吞天之喉护腿"
D.SharedStrings[5947]="吞天之喉肩胄"
D.SharedStrings[5948]="吞天之喉腿铠"
D.SharedStrings[5949]="吟游诗人的传说是真的吗?你拿到剑了没?"
D.SharedStrings[5950]="听夏琪亚的报告。"
D.SharedStrings[5951]="听着……我不想破坏了节日的美好气氛，但是烟林牧场需要帮助——需要你这样的冒险家。$B$B我们弄丢了节日所需的重要礼品，现在连我们派去寻找礼品的烟林牧场密探也不见了！请帮帮忙——礼品是在希尔斯布莱德丘陵区域的奥特兰克山脉附近丢失的，我们派出的密探也在那儿。$B$B去看看礼品和密探是否都安然无恙吧！"
D.SharedStrings[5952]="听着……我本不该告诉你这些，不过既然你是个大英雄……$B$B今年到处都有新鲜的冬青树茁壮成长，不过它们很快就会枯萎。我们弄了一台机器，可以储藏冬青树，然后在夏天拿出来热卖！$B$B我可以让你使用我们储藏的冬青树，不过你必须得是个够资格的大厨！给我带来一些石中盐，还有两个，不，三个，我是说五个金币。你觉得怎么样？够划算吧？"
D.SharedStrings[5953]="听着，$g小伙子:小姑娘;，艾泽拉斯的命运危在旦夕。$B$B我们唯一的机会是到天文台去，找到奥尔加隆，阻止他向他的泰坦主人发送信息。$B$B赶快找到天文台。如果你发现了任何有价值的信息，就立即回来向我报告。奥尔加隆抵达之前，我们还有一些时间可以准备。"
D.SharedStrings[5954]="听着，$n，至此你已经帮了很大的忙了，但那还远远不够。我们必须阻止这些疯狂的巨魔，至少成功把他们挡在藏宝海湾的大门外。$b$b我会派人去指挥整个行动，但我需要你进入祖尔格拉布，帮我做些事情。$b$b就是说，我需要你为我找来一个可以将这些巨魔赶出藏宝海湾的物件。$b$b你要是能做到的话，我们不会亏待你的。"
D.SharedStrings[5955]="听说联盟的冠军都在为他们的战士寻找古代的兵器，我们可不能让他们占这个便宜。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。"
D.SharedStrings[5956]="启动传送板，把凡瑟尔的礼物交给塔莉萨。"
D.SharedStrings[5957]="启动喷射跳跃装置，向前方跳跃。"
D.SharedStrings[5958]="启动跳跃机器人的跳跃喷射器，从空中跃向你的目标地点。"
D.SharedStrings[5959]="启动邪能之槌号的控制台，完成“入侵尼斯卡拉”场景战役。"
D.SharedStrings[5960]="启动邪能之槌号，召集你的伊利达雷部队。"
D.SharedStrings[5961]="吸取一名敌人的生命值，并转移给施法者。"
D.SharedStrings[5962]="吸取所有邻近敌人的力量，使其造成的伤害降低{1}%并使你造成的伤害提高{2}%。"
D.SharedStrings[5963]="吸取敌人{1}点生命值并转移给施法者。"
D.SharedStrings[5964]="吸取敌人{1}点生命值，并将其转移给施法者。"
D.SharedStrings[5965]="吸取生命"
D.SharedStrings[5966]="吸取生命和能量。"
D.SharedStrings[5967]="吸取生命和能量，使施法者获得生命能量。"
D.SharedStrings[5968]="吸取生命和能量，给予施法者生命能量。"
D.SharedStrings[5969]="吸取目标的意志，暂时使审判官无敌。"
D.SharedStrings[5970]="吸收{1}点伤害。"
D.SharedStrings[5971]="吸收{1}点伤害。\r\n免疫打断效果。"
D.SharedStrings[5972]="吸收{1}点伤害。\r\n因受到伤害而结束效果时，制造伤害的能力提高{2}%。"
D.SharedStrings[5973]="吸收{1}点冰霜伤害。"
D.SharedStrings[5974]="吸收{1}点奥术伤害。"
D.SharedStrings[5975]="吸收{1}点暗影伤害。"
D.SharedStrings[5976]="吸收{1}点火焰伤害。"
D.SharedStrings[5977]="吸收{1}点物理伤害。"
D.SharedStrings[5978]="吸收{1}点神圣伤害。"
D.SharedStrings[5979]="吸收{1}点自然伤害。"
D.SharedStrings[5980]="吸收伤害。"
D.SharedStrings[5981]="吸收伤害。\r\n对近战和远程攻击者造成{1}点伤害。\r\n对施法者造成{1}点伤害。"
D.SharedStrings[5982]="吸收战斗中的伤害 - 可躲避伤害标签。"
D.SharedStrings[5983]="吸收来自前方的伤害。"
D.SharedStrings[5984]="吸收物理和魔法伤害。"
D.SharedStrings[5985]="吸收神圣魔法，爆炸后造成神圣伤害。"
D.SharedStrings[5986]="吸收纯粹的暮光精华，从而得到强化。\r\n造成伤害提高{1}%。\r\n生命值提高{2}%。"
D.SharedStrings[5987]="吸收邻近敌人的力量和耐力并加强施法者的力量。"
D.SharedStrings[5988]="吸收野火，将野火的能量注入目标的武器，使其近战攻击对所有敌人额外造成50000点火焰伤害。"
D.SharedStrings[5989]="吸收野火，将野火的能量注入目标的武器，使其近战攻击对所有敌人额外造成{1}点火焰伤害。"
D.SharedStrings[5990]="吸收风暴幼龙的闪电攻击为发报机充能。"
D.SharedStrings[5991]="吸血提高{1}%，灵界打击造成的伤害提高{2}%。"
D.SharedStrings[5992]="吸血暴行之握"
D.SharedStrings[5993]="吸血蜘蛛为蛛王沃拉斯恢复{1}点生命值。"
D.SharedStrings[5994]="吸血蝙蝠宝宝"
D.SharedStrings[5995]="吸血蝠皮护腕"
D.SharedStrings[5996]="吸血鬼之血会使你的最大生命值额外提高{1}%，并使你受到的治疗量和吸收量额外提高{2}%。"
D.SharedStrings[5997]="吸血鬼的拥抱"
D.SharedStrings[5998]="吸食敌人的血肉，造成的伤害提高{1}%，\r\n攻击速度提高{2}%。\r\n施法速度提高{3}%。该效果可以叠加。"
D.SharedStrings[5999]="吹出一个足够大的气泡来拯救溺水者。"
D.SharedStrings[6000]="吼板是一种一臂长的坚硬木板，它被固定在一根长绳末端，只要持有者将它甩过头顶不断旋转，它就会发出低沉的嗡嗡声，并传到很远的地方。这个样品上带有战歌氏族特有的凹槽，可发出高亢的声响，有别于其他大部分氏族制品低沉的嗡鸣声。"
D.SharedStrings[6001]="呀，也许我应该亲自去手刃那些该死的纳迦!显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至于太清闲。"
D.SharedStrings[6002]="告诉我，$N。你从前线带来了什么消息?"
D.SharedStrings[6003]="呕吐的沼泽碾压者"
D.SharedStrings[6004]="周期性从敌人身上吸取生命。"
D.SharedStrings[6005]="周期性使爆裂熔炉的热能层级提高{1}。"
D.SharedStrings[6006]="周期性召唤炽烈的烈焰之柱灼烧敌人。"
D.SharedStrings[6007]="周期性向10码范围外的敌人投掷香蕉。"
D.SharedStrings[6008]="周期性地使弓箭手向飞翔的螳螂妖射箭。"
D.SharedStrings[6009]="周期性地发射暗影箭，对一片区域造成暗影伤害。"
D.SharedStrings[6010]="周期性地发射虚空之箭，当其撞击地面后造成伤害。"
D.SharedStrings[6011]="周期性地发射虚空之箭，当其撞击地面后造成暗影伤害。"
D.SharedStrings[6012]="周期性地吸取周围施法者的法力值。"
D.SharedStrings[6013]="周期性地在邪能风暴下方施放闪电。 "
D.SharedStrings[6014]="周期性地对一个附近的目标释放奥术能量，造成{1}点伤害。"
D.SharedStrings[6015]="周期性地对位于施法者面前锥形区域内的敌人造成{1}点火焰伤害。"
D.SharedStrings[6016]="周期性地对周围的敌人造成暗影伤害。"
D.SharedStrings[6017]="周期性地对指定区域中的敌人造成暗影伤害，并使其移动速度降低。"
D.SharedStrings[6018]="周期性地对敌人造成火焰伤害。"
D.SharedStrings[6019]="周期性地对敌人造成自然伤害。"
D.SharedStrings[6020]="周期性地对选定区域中的敌人造成伤害，并使它们减速。"
D.SharedStrings[6021]="周期性地对附近敌人造成火焰伤害。"
D.SharedStrings[6022]="周期性地对附近的敌人施加伤害，并使你受到的伤害降低{1}%，移动速度提高{2}%。"
D.SharedStrings[6023]="周期性地对附近的敌人造成伤害。"
D.SharedStrings[6024]="周期性地对附近的敌人造成火焰伤害。\r\n不能移动或使用任何技能。"
D.SharedStrings[6025]="周期性地投出流星。"
D.SharedStrings[6026]="周期性地投出流星，砸在地面上时造成火焰伤害。"
D.SharedStrings[6027]="周期性地施放闪烁的水泡。"
D.SharedStrings[6028]="周期性地触发一次旋风击退效果。"
D.SharedStrings[6029]="周期性地让周围的敌人感染月羽疫病。"
D.SharedStrings[6030]="周期性地造成自然伤害。"
D.SharedStrings[6031]="周期性地降低敌方单位的生命值上限。"
D.SharedStrings[6032]="周期性对所有敌人造成{1}点火焰伤害。"
D.SharedStrings[6033]="周期性对附近的敌人造成伤害并使其移动速度、攻击速度和施法速度持续降低。移动可以打破该效果。"
D.SharedStrings[6034]="周期性对附近的敌人造成火焰伤害。"
D.SharedStrings[6035]="周期性投掷流星，在坠落地面时造成火焰伤害。"
D.SharedStrings[6036]="周期性治疗效果"
D.SharedStrings[6037]="周期性造成{1}点火焰伤害。每次辐射会使火焰伤害提高{2}%。"
D.SharedStrings[6038]="周期性造成火焰伤害。"
D.SharedStrings[6039]="呴呴，你好啊。我是冬天爷爷，作为熏木牧场的良好成员……我这里有“一应俱全的东西，包括所有熏木牧场精心为您准备的货物”，希望你度过一个愉快的冬幕节。$B$B如果你在这一年表现得很好的话，你将在冬幕节这一天收到来自于熏木牧场的礼物。哈哈。"
D.SharedStrings[6040]="呸！今天我正好缺人手，你太幸运了。不干的话，我这一整周都会让你背黑锅。$b$b官员和高阶士兵需要擦鞋服务。他们的靴子就放在营帐前。$b$b我要能从鞋面上看见我的倒影，步兵！赶紧干活去！"
D.SharedStrings[6041]="呼吸！水下呼吸！不要移除！与加快游泳速度的热电液压蛙蹼是标配！"
D.SharedStrings[6042]="呼唤她的孩子，召唤三只掠夺者协助她。"
D.SharedStrings[6043]="命中几率提高[abs(abilityStateMod(41,251))]%。\r\n爆击几率提高[abs(abilityStateMod(40,251))]%。"
D.SharedStrings[6044]="命中几率提高{1}%。\r\n敌人的躲闪几率降低{2}%。"
D.SharedStrings[6045]="命中几率降低25%。"
D.SharedStrings[6046]="命中几率降低{1}%。"
D.SharedStrings[6047]="命中后有一定几率使武器变钝，造成的伤害降低。"
D.SharedStrings[6048]="命中时有一定几率对敌人造成火焰伤害。"
D.SharedStrings[6049]="命中时造成冰霜伤害。"
D.SharedStrings[6050]="命中能量力场"
D.SharedStrings[6051]="命令你的岩石猎鹰扑向你选定的目标。在命令岩石猎鹰攻击目标之前，必须给它喂食一只峡湾虫。"
D.SharedStrings[6052]="命令你的旗手为你和你的要塞守卫插下军旗！"
D.SharedStrings[6053]="命令你的旗手为你和你的要塞守卫插下军旗！\r\n\r\n每鼓舞一个守卫可获得胜利点数。"
D.SharedStrings[6054]="命令抗魔枯法者测试他们对邪能魔法的抗性。"
D.SharedStrings[6055]="命令迦罗娜悄无声息地干掉一个敌方兽人，动作要快！"
D.SharedStrings[6056]="命运与机遇饱饮鲜血，使你获得{1}%的移动速度加成。"
D.SharedStrings[6057]="和一只沼岩蝌蚪谈一谈。"
D.SharedStrings[6058]="和先知昊梵舟一起，跟随末代皇帝的脚步。\r\n\r\n无法使用坐骑。"
D.SharedStrings[6059]="和其他骁士彼此对战训练将能磨利你的爪子，锻炼你的战斗直觉。等到竞赛开始时，你将会做好准备。"
D.SharedStrings[6060]="和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。"
D.SharedStrings[6061]="和卡桑琅丛林里的达格·自走炸弹谈一谈。"
D.SharedStrings[6062]="和吉尔吉斯部族建立良好的关系，然后和智者乌泰克谈一谈。"
D.SharedStrings[6063]="和奥格瑞玛精神谷的督军格尔库克谈一谈。"
D.SharedStrings[6064]="和奥金顿法力陵墓里的工匠莫法鲁斯谈一谈。"
D.SharedStrings[6065]="和学徒季·酒怒谈一谈。"
D.SharedStrings[6066]="和宠物小伙伴玩抛接球游戏。"
D.SharedStrings[6067]="和我在一起吧！"
D.SharedStrings[6068]="和指挥官巴格兰谈一谈。"
D.SharedStrings[6069]="和昆莱山上父子洗牛站的老麝香爪谈一谈。"
D.SharedStrings[6070]="和普通的拆信刀一样，这通常是一种毫无用处的工具，之所以将它带在身边，只是为了在一些不方便携带匕首的场合当作凶器使用。"
D.SharedStrings[6071]="和晴日峰的吉斯坦大师谈一谈，和她一起完成你的训练。"
D.SharedStrings[6072]="和晴日峰的吴大师谈一谈，和她一起完成你的训练。"
D.SharedStrings[6073]="和晴日峰的尹大师谈一谈，和他一起完成你的训练。"
D.SharedStrings[6074]="和晴日峰的曾大师谈一谈，和他一起完成你的训练。"
D.SharedStrings[6075]="和晴日峰的程大师谈一谈，和她一起完成你的训练。"
D.SharedStrings[6076]="和晴日峰的许大师谈一谈，和他一起完成你的训练。"
D.SharedStrings[6077]="和狮王之傲旅店的旅店老板法雷谈一谈。"
D.SharedStrings[6078]="和玛格拉姆部族建立良好的关系，然后和瓦鲁格谈一谈。"
D.SharedStrings[6079]="和谐者智先生"
D.SharedStrings[6080]="和铁炉堡军事区的大元帅斯诺·落雪谈一谈。"
D.SharedStrings[6081]="和锦绣谷魔古山宫殿的梦想家思南谈一谈。"
D.SharedStrings[6082]="咒术师维霍丝"
D.SharedStrings[6083]="咕噜咕噜……"
D.SharedStrings[6084]="咱们来给你找点事做吧。先从简单的开始，伙计。$B$B岛上的豹子在猎杀我们的野猪。跟它们分享食物可不成！如果你今晚还想填饱肚子的话，就得想办法保证那些野猪还活着。$B$B岛上到处都是豹子。去把它们的毛皮给我拿来。"
D.SharedStrings[6085]="哀伤尖塔"
D.SharedStrings[6086]="哀嚎之风减缓你的移动速度。"
D.SharedStrings[6087]="哀嚎的灵魂"
D.SharedStrings[6088]="品尝暗月马戏团的每一道食物及饮料。"
D.SharedStrings[6089]="品尝本月美酒俱乐部提供的12种啤酒。"
D.SharedStrings[6090]="哇!做的好，$N!这是你的糖果。$B$B万鬼节快乐!"
D.SharedStrings[6091]="哇呼!$B$B这可给了他们点教训!"
D.SharedStrings[6092]="哇啊啊啊！！"
D.SharedStrings[6093]="哇喔，你做到了!你真棒!也许明年你可以在节庆上找到一份工作!"
D.SharedStrings[6094]="哇，你全都拿来了!你真棒!$B$B谢谢你代替我去完成不给糖就捣蛋。拿着这些南瓜糖吧 – 我想你会很喜欢的!$B$B万鬼节尾声快乐，$N!"
D.SharedStrings[6095]="哇，战利品！打开我！"
D.SharedStrings[6096]="哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。"
D.SharedStrings[6097]="哈加萨·莫尔海德"
D.SharedStrings[6098]="哈尔弗斯·碎龙者"
D.SharedStrings[6099]="哈尔弗斯利用束缚魔法迫使一头龙服从他的命令。"
D.SharedStrings[6100]="哈尔格斯·黯刃"
D.SharedStrings[6101]="哈尔玛·斯塔索姆队长"
D.SharedStrings[6102]="哈德利·里卡德博士"
D.SharedStrings[6103]="哈拉夫瑟尔"
D.SharedStrings[6104]="哈杜伦·明翼"
D.SharedStrings[6105]="哈洛姆的冰封月牙斧"
D.SharedStrings[6106]="哈洛姆的恐惧之盔"
D.SharedStrings[6107]="哈洛姆的护符"
D.SharedStrings[6108]="哈瑞的轰炸机"
D.SharedStrings[6109]="哈萨尔在回到他的位置上时抵御伤害。"
D.SharedStrings[6110]="哈里森·琼斯"
D.SharedStrings[6111]="哈里森·琼斯与奥丹姆神殿"
D.SharedStrings[6112]="哈顿告诉我，阿古斯陷落后，萨格拉斯就下令在星球的核心深处建造了一座黑暗神殿。我们对这座神殿知之甚少，因为只有黑暗泰坦最忠实的亲信才能获得进入那里的印记。\n\n如果我们能得到印记，就可以把它们灌注进维迪卡尔。这样我们的部队就可以直接进攻阿古斯的腐化之心了。"
D.SharedStrings[6113]="响应先知维伦的召唤，前往阿古斯与燃烧军团战斗。"
D.SharedStrings[6114]="哎呀很好，$C。我一直都在等待你。$B$B我这有几个任务特别的适合你。$B"
D.SharedStrings[6115]="哦！是我！你是$n，对吧？我记得这里！$b$b我好像被困在部落和联盟的战斗之中，一般来说，这不是什么大事，只不过每当我想飞走，那台大炮似乎就瞄准我不放。$b$b你能帮我解决掉它吗？"
D.SharedStrings[6116]="哦！欢迎你，游学者周卓的朋友。我有一个消息要告诉你。$b$b<这个古怪的小家伙交给你一个破旧的卷轴盒子。>$b$b游学者阁下正在昆莱山等着你。通往那里的道路非常危险，是的，非常非常危险。$b$b你可以寻找沿路的向导来为你指路。"
D.SharedStrings[6117]="哦，差点忘了，有人拜托我交给你这个东西。我觉得这封信应该来自你的某个同伴。$b$b有人设法使我相信你的出现是当务之急，因此我擅自安排了你的行程。$b$b当你做好准备后，请和南边的金莎·箭眼谈一谈。她的风筝正在等着你。"
D.SharedStrings[6118]="哦，终于找回我的东西了……谢谢你。$B$B有些矮人可能喜欢亮闪闪的金属或是华丽的宝石……不过没有这只杯子，我就什么都没有啦!"
D.SharedStrings[6119]="哨兵指挥官"
D.SharedStrings[6120]="哨兵的夜刃豹"
D.SharedStrings[6121]="哨兵艾莉萨·星风的灵魂"
D.SharedStrings[6122]="哨兵部队的将军"
D.SharedStrings[6123]="唉。既然你在幫我做事，我想必應該要問問你的名字。\r\n\r\n<泰德里斯把手伸進書中，拉出一株陌生的乾枯植物。>\r\n\r\n謝謝你幫我取得下一種材料。我對你的協助…感念在心，$n。"
D.SharedStrings[6124]="唐恩的残忍掌控解除了!因为你，英雄，纳格兰有了更明亮的明天。做的好!"
D.SharedStrings[6125]="唤下一道雷霆闪电，对施法者附近的所有敌人造成自然伤害。"
D.SharedStrings[6126]="唤地者托伦斯卡"
D.SharedStrings[6127]="唤地者耶法"
D.SharedStrings[6128]="唤地者萨满"
D.SharedStrings[6129]="唤潮者泰德鲁斯"
D.SharedStrings[6130]="唤起往昔的回忆。"
D.SharedStrings[6131]="唤醒亡者，使其成为被遗忘者。"
D.SharedStrings[6132]="唤醒目标体内的生命火花。"
D.SharedStrings[6133]="唤雷者布隆迪尔"
D.SharedStrings[6134]="唤风者卡尔东"
D.SharedStrings[6135]="唤风者耶萨德拉"
D.SharedStrings[6136]="唱出一首振奋人心的歌曲，为所有同伴回复[StandardHealing(1,1)]点生命值。"
D.SharedStrings[6137]="啄击一个敌人，造成物理伤害。"
D.SharedStrings[6138]="商人出售：“掮客”马库斯·布朗\n地区：西部荒野"
D.SharedStrings[6139]="商人出售：格丽萨·日露\n地区：暗月岛"
D.SharedStrings[6140]="商人出售：缇菲·机簧、吉雅达·金索\n地区：要塞"
D.SharedStrings[6141]="商人波塔努斯"
D.SharedStrings[6142]="商人波塔努斯要求你前往沙塔斯城，与圣光广场上的主教纳苏恩谈一谈。"
D.SharedStrings[6143]="商人约瑟夫"
D.SharedStrings[6144]="商队科多兽驭手"
D.SharedStrings[6145]="啊……$N……我很高兴你来到了这里。$B$B让你的身体与精神接受土地的洗礼吧，你将会发现山丘就是你的力量，平原就是你的宽容，而世界本身就是你的精髓所在。$B$B在这个祭仪中你唯一所要做的事情，就是谦卑地站在土元素面前。当你以后遇到其它元素的时候，会发现它们也许并没有土元素这么平静。或许它们是混乱而暴戾的，但这是元素自身的天性。它们相互之间总是存在着对立，而你必须对这一点非常了解才行。"
D.SharedStrings[6146]="啊……是你啊，$n。玛乌提……他死了？我终于活到了为我兄弟报仇的这一刻。我对你只有一个请求……这头小豹崽在这里挠我的脚很久了。作为一个矮人，我不该光着脚去死。$b$b求求你，让我穿着靴子下葬。"
D.SharedStrings[6147]="啊……痛！我的肚子……"
D.SharedStrings[6148]="啊……这是怎么回事！？$b$b我的肚子……痛得厉害。$b$b痛……啊……他们肯定下了毒！$b$b他们在要塞里种植了奇怪的海草，强迫我们吃下……$b$b如果不继续服食，恐怕疼痛会加剧的……$b$b求求你了，$r。快给我找些海草来！"
D.SharedStrings[6149]="啊哈!梅维基闹了一个笑话!$B$B<梅维基大笑。>$B$B这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗?这值得奖励!$B$B梅维基会磨亮你的宝珠的。把宝珠放在这儿，$N。"
D.SharedStrings[6150]="啊啊啊啊啊啊啊啊啊啊啊！啊啊啊啊啊啊啊啊啊！！！"
D.SharedStrings[6151]="啊啊啊啊！！！"
D.SharedStrings[6152]="啊！到处都是蜘蛛！烬网幼蛛持续造成伤害并会降低目标的移动速度。"
D.SharedStrings[6153]="啊！它们到处都是！烬网幼蛛持续造成伤害并会降低目标的移动速度。"
D.SharedStrings[6154]="啊，$N!什么事让你这样一个重要的$g男人:女人;来到这么肮脏的地方呢?$B$B当然，我已经准备好你的宝石了。最好的东西就要给我们最喜欢的$r。"
D.SharedStrings[6155]="啊，$N!能为像你这样伟大的英雄提供奖励真让我感到荣幸。请允许我继续。$B$B<高阶执行官清了清喉咙，又开始大声咆哮。>$B$B请所有在场者见证:由于对被遗忘者和部落作出了杰出的贡献，而且是在面对极端强大的敌人和令人难以置信的危险的情况下做出这样的贡献，我将这个给予$N，并对这位部落的英雄表示最崇高的敬意!"
D.SharedStrings[6156]="啊，$n。\r\n\r\n很高興能與你重逢。相信你已經準備好助我一臂之力。"
D.SharedStrings[6157]="啊，$n，很高興看到你安然無恙！六法議會的成員正從施法後的虛弱逐漸恢復。\r\n\r\n高強度的傳送法術可能會使人頭暈目眩，你剛剛雖然暫時失去意識，但至少醒來的時候沒發現自己卡在牆壁裡！\r\n\r\n達拉然已經移動到破碎群島。從現在開始，我們會傾全力取得創世之柱，將燃燒軍團永遠逐出艾澤拉斯！"
D.SharedStrings[6158]="啊，一个追寻工程学真谛的年轻工程师，一个探求地精工程学奥秘的求知者!好吧，我的朋友，请原谅我的敏感和激动。我们现在的情况仍然十分糟糕，但是有你这样对工程学的真知孜孜以求的技师加入我们的行列，这仍然是让我很高兴的!"
D.SharedStrings[6159]="啊，你就是那個鼎鼎大名的$c。很好。\r\n\r\n我們應該看看你是不是名副其實。"
D.SharedStrings[6160]="啊，你希望我来考验你的勇气，非常好。$B$B这座城市的内部和外部有着无数的机遇与挑战正在等着一位乐于接受挑战并有能力接受挑战的$G男人:女人;。$B$B这项试炼可不容易，$N。它正如我们在修行之路上遇到的许多其它的试炼一样，有可能会夺走我们的生命。教会总是想提高自己的地位，但它也知道，必须通过圣骑士的牺牲才能彰显出教会的价值。$B$B你准备好了吗?"
D.SharedStrings[6161]="啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。"
D.SharedStrings[6162]="啊，你收到了我的信?很好。"
D.SharedStrings[6163]="啊，你的确是在寻找更为……实际的东西。如果你已经准备就绪了，那么我可以帮你。$B$B我很高兴看到我们的同行寻求更多的力量，而不仅仅是知识，这很好。$B$B那么，你准备好了吗，$N?"
D.SharedStrings[6164]="啊，你真是很准时，$N。我先前还在怀疑是不是所有的信差都成功地完成了他们的使命呢。幸运的是他们都做到了，否则我敢打赌你现在仍在到处旅行，在世界各地了解我们的人民所面对的威胁。$B$B你准备好了吗?我是说准备接受更多的试炼。你的能力提高得很快，我想你已经做好对我们的信仰加深了解的准备了。"
D.SharedStrings[6165]="啊，又见面了，$N。我正在像往常一样观察海洋的波涛。什么风把你吹到这里来了?"
D.SharedStrings[6166]="啊，太好了……这件披氅非常完美。$B$B拿着这个披氅，$N。愿它保护你对抗其拉虫人的邪恶魔法。"
D.SharedStrings[6167]="啊，太好了。这颗腐烂头颅的疾病虽然致命，但我们绝对不能惧怕危险或恶心。$N，某天你会了解，这该死的东西是救赎的唯一途径…"
D.SharedStrings[6168]="啊，好极了，又来了一个。时间对我来说不成问题，但是对你而言就至关重要了。你要学习的东西还很多，而我想传授给你的也很多。你必须证明自己的价值，以此来赢得丰厚的回报。"
D.SharedStrings[6169]="啊，很好。这些材料的品质都很棒。谢谢你，$N。"
D.SharedStrings[6170]="啊，快看！我就說它不會失去光采。現在沒有線索能從那傻瓜身上追查到我這了…\r\n\r\n你說什麼？弱化他地位的計謀？無論如何，傷害已經造成。安全總比遺憾好。"
D.SharedStrings[6171]="啊，我想刚才经历了那场小遭遇战也可以被称为完成了一项“战地任务”吧。把这些带回塞纳里奥城堡去，我相信他们一定会有重要任务给你的。$B$B快出发!"
D.SharedStrings[6172]="啊，我相信你发现的是以前被探险者协会检查过的那具尸体。他们来过这里，还提到了在研究一具尸体的时候被一群鱼人追击的事情。看来你成功地完成了我们都没能完成的事情。请你收下这个，月神殿感谢你。"
D.SharedStrings[6173]="啊，找全了!我们现在就来用这些上好的光铸铁打造些有用的东西吧，怎么样?"
D.SharedStrings[6174]="啊，是的。莫克斯一定会对这个感到非常满意。$B$B那护腕以前是大型护甲装备的一部份。如果你能再帮我忙的话，我这里还有更多可以跟你护腕搭配的装备。"
D.SharedStrings[6175]="啊，没错，可以替我节省下许多时间了。$B$B收下这个，当作我麻烦你的回报，朋友。帮我多找一些元素115来，你找到多少我收多少。"
D.SharedStrings[6176]="啊，泽弗洛斯特让你来的。很好。看来我的话传到了如此之远的地方，为我找到了新的学生，这让我感到非常高兴。$B$B我们这些$C必须联合在一起，$N，无论自己属于哪个种族。这一点很重要，因为跟我们打交道的家伙都十分疯狂―如果我们没能安抚它们或者正确地控制它们的话。$B$B我觉得你已经学会了很多东西，如果你愿意的话，我会帮你继续提高你的能力。"
D.SharedStrings[6177]="啊，说实话，光靠锋利的钢剑是不足以获得胜利的。其他参赛者用的都是附有魔法的武器，这对我非常不利，不过这也不是什么大问题。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。"
D.SharedStrings[6178]="啊，谢谢你的讯息。或许你不介意帮忙大地之环?元素不断变迁。我们可以使用所有能获得的协助。"
D.SharedStrings[6179]="啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！$B$B召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。$B$B消灭巫妖，$n，从它的护符匣里拿出一块碎片来，作为你获胜的证据！"
D.SharedStrings[6180]="啊，這樣感覺好多了。謝謝你！\r\n\r\n開始上工吧。"
D.SharedStrings[6181]="啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。"
D.SharedStrings[6182]="啥都没有"
D.SharedStrings[6183]="啧啧！你的冲锋被目标躲开了！你也太菜了吧？"
D.SharedStrings[6184]="啸天者托瓦拉"
D.SharedStrings[6185]="啸天者欧穆隆"
D.SharedStrings[6186]="啸风双头飞龙"
D.SharedStrings[6187]="喂给你的非战斗宠物……如果你够胆的话。"
D.SharedStrings[6188]="喂食你的宠物小伙伴，使其被邪能腐蚀。"
D.SharedStrings[6189]="善良的欧莉萨拉"
D.SharedStrings[6190]="喋喋不休的恶魔"
D.SharedStrings[6191]="喔，感謝博學者！我曾怕永遠找不到它了。\r\n\r\n我知道這枚戒指有些…用途。我的確希望它不屬於任何重要人士。或是…會說話之人。"
D.SharedStrings[6192]="喔，我要怎么报答这个忙呢?"
D.SharedStrings[6193]="喔，我親愛的小可琳！感謝你，感謝你！"
D.SharedStrings[6194]="喔，更多美味的亡者面包，感谢你!$B$B请收下这个当作回报…一点节日的小娱乐。"
D.SharedStrings[6195]="喔，这是什么?多么令人开心的芳香!我肯定这一定会让火焰烧得更加纯净与明亮!$B$B收下这些花朵，$N。收下它并且让我独自一人…我一定好好感受这珍贵的香气…"
D.SharedStrings[6196]="喜出望外"
D.SharedStrings[6197]="喝下庄严静夜合剂，急速提高{1}%，造成的伤害提高{2}%。"
D.SharedStrings[6198]="喝下，使用蚁酸变形。"
D.SharedStrings[6199]="喝个烂醉如泥，洒上最好的香水，向斯拉兹扔一把玫瑰花瓣，然后亲吻他。到了早上你就会后悔的。"
D.SharedStrings[6200]="喝个烂醉如泥，洒上最好的香水，向杰雷米亚·派森扔一把玫瑰花瓣，然后亲吻他。到了早上你就会后悔的。"
D.SharedStrings[6201]="喧闹恶鬼的噪音实在是太烦人了！将你的音量提高{1}。"
D.SharedStrings[6202]="喷出一团闪电，在冲击区域制造出一个闪电云团。"
D.SharedStrings[6203]="喷出岩石吐息，对前方的敌人造成自然伤害。"
D.SharedStrings[6204]="喷出邪能污秽。"
D.SharedStrings[6205]="喷吐一团邪能火球，对附近的敌人造成火焰伤害。"
D.SharedStrings[6206]="喷吐令人反胃的油漆造成{1}点物理伤害。"
D.SharedStrings[6207]="喷吐烈焰，对施法者前方锥形区域造成{1}点火焰伤害。"
D.SharedStrings[6208]="喷吐熔岩，留下一个熔岩池，每秒造成一次伤害。"
D.SharedStrings[6209]="喷射出一股毒性树脂，造成相当于武器伤害的自然伤害。"
D.SharedStrings[6210]="喷射出粘稠的蛛网，造成{1}点伤害并束缚敌人，同时将他们拖至到施法者身前。"
D.SharedStrings[6211]="喷射柔和的蒸汽水雾。"
D.SharedStrings[6212]="喷涌岩浆，在蠕虫面前的锥形范围内造成火焰伤害。"
D.SharedStrings[6213]="喷溅出黏液，对格罗布鲁斯身前的敌人造成{1}点自然伤害。被黏液击中的敌人将召唤出一个辐射软泥怪。"
D.SharedStrings[6214]="嗜血者的精致小瓶"
D.SharedStrings[6215]="嗜骨如命的艾苏克"
D.SharedStrings[6216]="嗨，$C！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。$B$B要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通套装的手腕部分。$B$B我需要大量生活在希利苏斯地区的蝎子和蜘蛛的毒液。把毒液样本带给我，再支付一些金币，我就跟你交换。"
D.SharedStrings[6217]="嗨，$g先生:女士;，这个榆木脑袋不放我进去。想要赚些外快吗？$B$B我的老板在给试炼竞技场的角斗比赛做宣传。$B$B你瞧着挺耐揍的，何不去参加比赛呢？"
D.SharedStrings[6218]="嗨，$r，对宝藏感兴趣嘛？我这里有点猛料。$b$b最近我听到了一些消息，是关于风险投资公司在淤泥沼泽东北的石矿洞的。有个矿工挖出了一枚足有拳头大小的翡翠石。$B$B我知道有一些买主肯掏钱买那么大的一块宝石，如果你帮我搞到那块宝石的话，那么我愿意和你五五分成，你看怎么样？"
D.SharedStrings[6219]="嗨，玩火炬的！挺开心的嘛？瞧你那副乐在其中的模样！怎么样，扔火炬游戏玩得炉火纯青了吧？接下来，你要面对新的挑战啦……$B$B你知道游戏规则的：将火炬扔向带标记的火盆。这次呢，时限有所延长，但火盆的数量就多得多了。$B$B准备好了吗？"
D.SharedStrings[6220]="嗯!我喜欢草莓冰淇淋!提古勒和弗洛尔的草莓冰淇淋是最棒的!$B$B非常感谢你，$N―这是我所得到的最好的礼物!"
D.SharedStrings[6221]="嗯……$N?你有什么特别的东西要给我吗?"
D.SharedStrings[6222]="嗯……这条虫子的皮可以制成非常好的保护层。和安其拉的其它材料配合起来，我们就可以制作一件完美的护甲。希望它可以帮助你对抗那些潜伏在神殿中的恐怖力量!"
D.SharedStrings[6223]="嗯。从你告诉我的事情，法阵里的声音……它们一定是被用来做为某种沟通的工具。我一想到那些邪恶的脑袋会透过这样的魔法联系就不寒而栗。无论如何，你看起来还是很健全很清醒。银色黎明感谢你的努力。"
D.SharedStrings[6224]="嗯。从你告诉我的事情，法阵里的声音……它们一定是被用来做为某种沟通的工具。我一想到那些邪恶的脑袋会通过这样的魔法联系就不寒而栗。无论如何，你看起来还是很健全很清醒。银色黎明感谢你的努力。"
D.SharedStrings[6225]="嗯哼?你是不是被联盟打败，馀烬被抢走了，只能蹲在路边哭?"
D.SharedStrings[6226]="嗯哼?你是不是被部落打败，馀烬被抢走了，只能蹲在路边哭?"
D.SharedStrings[6227]="嗯哼！撤退。$B$B我要我的猫咪，不然我就不走。他是一只黄色的虎斑猫，非常可爱。$B$B这里的东北边有一棵大树，树下有一辆破损的货车，小运最喜欢在那里玩耍了。$B$B你去把他找回来，然后我们就可以动身了。"
D.SharedStrings[6228]="嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。"
D.SharedStrings[6229]="嗯，$N?你做出选择了吗?你选择了炼狱火还是恶魔犬?$B$B这取决于你，你的选择将反映出你的优势和弱点。对术士来说，强化自己的优势而不弥补自己的弱点是很常见的。有时候，制服敌人靠的是出色的策略，而不是一个样样兼顾的施法者。"
D.SharedStrings[6230]="嗯，$N，至少你活着回来了。我想这值得一些奖励……"
D.SharedStrings[6231]="嗯，你完成你的任务了吗?"
D.SharedStrings[6232]="嗯，又一个成功完成湖中试炼的德鲁伊!做得好，我年轻的朋友。$B$B我是塔加里，月光林地及这座神殿的守护者，这是我的责任，也是我所拥有的特权。守护者雷姆洛斯指引着塞纳里奥议会努力保持着自然的平衡，并且他的神殿正在为此做出巨大的贡献。在这里使用灵珠，即表示你认同这个地方在议会中的重要性。"
D.SharedStrings[6233]="嗯，我知道你是谁，我也知道你来这里干什么。阿尔比顿在你来之前就跟我说过了。让我们长话短说吧，怎么样?$B$B我确实有可以用来制作骷髅钥匙的模具，但是它非常贵―15个金币，现货，不二价。我会把骷髅碎片放进模具里交给你，我也会教你如何铸造钥匙，即使你连一点锻造的相关知识都没有……这些都是免费的。$B$B谁说商人都是唯利是图的!"
D.SharedStrings[6234]="嗯，我知道是格拉希娜派你来的。你与这些小动物的作战经验是非常宝贵的，据我所知没几个人曾经对付过这类生物。至于格拉希娜所持的安戈洛环形山是异种蝎发源地的观点……可能确实如此。安戈洛环形山是西边的一个神秘而危险的丛林。也许我们可以在那里搞清楚异种蝎的来龙去脉。"
D.SharedStrings[6235]="嗯，是希尔恩让你来找我的吧?$B$B他是值得信赖的朋友，也就是说，你已经准备好要创建下一个灵契了―火焰灵契。$B$B我已经看到了熊熊燃烧的火焰和欲望。你已经拥有了一些力量，现在你已经准备好掌握更多了。耐心点，$N。记住大地所教会你的那些。力量和毁灭随手可得，不过你必须首先知道什么时候应该收手。"
D.SharedStrings[6236]="嗯，是时候了……$c。"
D.SharedStrings[6237]="嗯，沉没的神庙，我可是亲眼见过它的。也许你想要知道更多有关它的消息?$B$B你看起来就是那种爱冒险的类型 -- 我想，你也许会对我所知道的东西感兴趣……"
D.SharedStrings[6238]="嗯，現在我們可以專心解救還在城裡受苦的居民了。"
D.SharedStrings[6239]="嗯，这张优惠券值二十份种子。要是你把种子用完了，我们仍可以为你提供更多的种子。不幸的是，大量生产萨伦迪斯种子所需的费用可不小，这正是我们要收取成本费以解决资金问题的原因。$B$B那些带着晨光麦回来的冒险者们会发现大德鲁伊给予的回报要远远大于他们所付出的代价。"
D.SharedStrings[6240]="嘲讽此生物会使其向你的位置移动。\r\n打断此生物或其生命值低于90%时，它会开始攻击所有敌人。"
D.SharedStrings[6241]="嘲讽生物，增加其攻击施法者的几率。"
D.SharedStrings[6242]="嘲讽目标，使其向你发起攻击，但是对已经在攻击你的目标无效。"
D.SharedStrings[6243]="嘲讽目标，使其攻击你，但是对已经在攻击你的目标无效。"
D.SharedStrings[6244]="嘲讽目标，吸引他来攻击你。但对于已经在攻击你的目标无效。"
D.SharedStrings[6245]="嘲颅割颅者"
D.SharedStrings[6246]="嘿!我认识你。人们讨论你在血色竞技场的胜利讨论了好几个月!因为没有出场打卫冕赛而输掉你的勇士头衔真是太可惜了!来的快，去的也快，嗯?至少你还活着。"
D.SharedStrings[6247]="嘿...你現在可沒有那麼大了!擊殺獎勵兔子"
D.SharedStrings[6248]="嘿，你好。你在寻找这片地方的主人吗？那就去见见楼梯上面的那位熊猫人吧。跟你一样，我也是访客。$b$b不好意思，我跟我朋友现在要商量点事情。我们稍后再聊。"
D.SharedStrings[6249]="嘿，你好啊！你是这要塞的指挥官对吧？我是代表热砂保护协会来的。$b$b我们想在纳格兰开展一项极其重要的挖掘项目。可惜当地的食人魔给我们添了不少麻烦。$b$b就在不久前，我们团队中一位最优秀的保护者在当地勘探时失踪了。他已经是我们协会这星期失去的第三位成员了！$b$b我们的设备还真执行不了救援任务……那你怎么想？我们非常需要你的帮助。"
D.SharedStrings[6250]="嘿，你有时间吗？我这有点事情想交给你办。"
D.SharedStrings[6251]="嘿，朋友，想找刺激吗？冒险呢？金钱呢？暴力呢？$B$B好吧，你最好喜欢暴力，因为他们刚刚在加基森重新开放了雷霆斗技场。看着它长期荒废真叫人伤心，什么伤害诉讼啊，敲诈起诉啊，版权侵犯啊……但现在它回来了，就等着像你一样野蛮强壮的人进去，把最肮脏的对手放倒！$B$B到加基森去，找狄奥维奥博士报名。别忘了告诉你的朋友们！"
D.SharedStrings[6252]="噢。它还在滴水耶。你就不能先把它弄干吗?"
D.SharedStrings[6253]="噢对！这正是我们需要的！我刚想给那些动物来个大轰炸。"
D.SharedStrings[6254]="噢，只是张酒杯兑换券…说不定你还花了一番力气才弄来。好吧，这是你今年的酒杯。$B$B不过我猜我应该还会常常再看到你。无论如何，要是想兑换啤酒节奖章，你找我就对了…$B$B或他找我…$B$B噢噢喔…或是他…"
D.SharedStrings[6255]="噢，感谢你!愿圣光祝福你的善举，仁慈的$g先生:女士;。黑暗骑士的阴影依旧在逼近，但起码现在，村子不受他的火焰威胁了。"
D.SharedStrings[6256]="噢，我可怜又无辜的洒弹器！看看它们把你怎么了。$B$B不过至少它们完成了发射任务，我要的就是这个效果。$B$B这是洒弹器的结构图。你可以把它们装在你不喜欢的东西旁边！"
