D.SharedStrings[6319]="因为不想使用鸦人的传统武器，泰罗克将这把大槌作为他失去王位，沦为被流放的异端的象征。数百年来，一直有传言称，泰罗克从不使用鸦人传统的折翅之刑，而是砸断那些敢于违逆他的鸦人的喙作为惩罚。"
D.SharedStrings[6320]="因为你与水晶的共鸣，你的移动速度降低了。"
D.SharedStrings[6321]="因为受到伤害而损失的施法时间减少{1}%。"
