D.SharedStrings[6336]="国王陛下?!我是说……国王陛下?真正的国王陛下?你不会是在开玩笑吧?你可没说你在找的是绑架国王的绑匪啊，我甚至没听说他失踪了啊－－这多少也能解释他儿子继位的理由。$B$B我马上和伊林联络，他一定会想知道你的进展的。$B$B我可从没想过贾恩会为了一点肮脏的钱就把暴风城给出卖了。须知盗亦有道啊!$B$B现在最重要的是要找到亨德尔。我想我应该能帮上忙。"
