D.SharedStrings[6394]="圣光军团保护着你不受帕拉克希斯号的伤害。"
D.SharedStrings[6395]="圣光对我微笑了，我还没死在这个人间地狱中。但是如果我再不逃走的话，天灾军团就会杀了我，把我撕成碎片，用来制作它们的“产品”。$B$B我一个人是没办法逃走的，$c。不过如果有你的帮助，或许我还可以活下来，继续与天灾军团作战。$B$B趁着天灾军团的屠夫还没来杀我，你能帮我逃出去吗？"
D.SharedStrings[6396]="圣光对我微笑了，我还没死在这个人间地狱中。但是如果我再不逃走的话，天灾军团就会杀了我，把我撕成碎片，用来制作它们的“产品”。$B$B我一个人是没办法逃走的，孩子。不过如果有你的帮助，或许我还可以活下来，继续与天灾军团作战。$B$B趁着天灾军团的屠夫还没来杀我，你能帮我逃出去吗？"
