D.SharedStrings[6584]="在仔细查看了地图之后，你意识到刺背野猪人的酋长正计划着对纳拉其营地展开进一步攻击。$b$b鹰风酋长必须马上得知这个消息。"
D.SharedStrings[6585]="在任何团员都不被下列攻击命中的情况下，击败火焰之地的奥利瑟拉佐尔。"
D.SharedStrings[6586]="在任何团队成员都没有带有超过8秒的穿刺效果的情况下，击败玛洛加尔领主（10人）。"
D.SharedStrings[6587]="在任何团队成员都没有带有超过8秒的穿刺效果的情况下，击败玛洛加尔领主（25人）。"
D.SharedStrings[6588]="在任意战场的一场战斗中造成300000点伤害或者治疗，并且这些伤害或治疗的目标必须是玩家。"
D.SharedStrings[6589]="在任意战场的一场战斗中，亲手杀死20名敌人，并且自己不死亡。"
D.SharedStrings[6590]="在任意战场的一场战斗中，获得30个荣誉击杀。"
D.SharedStrings[6591]="在伊利达雷哨所与恶魔猎手的首领谈一谈。"
D.SharedStrings[6592]="在伐木场下达100份产品订单。"
D.SharedStrings[6593]="在你前往凿握据点的途中杀死任意15名黑石大军的成员。"
D.SharedStrings[6594]="在你和那些假人训练时，牢记大师的教导。"
D.SharedStrings[6595]="在你回到德迪利特面前的时候，他在自己面前的空气中画了一个无形的符记。一股力量光环笼罩着这位微笑着的德鲁伊。$B$B“我感受到了你的智慧，年轻的$r，在我们第一次见面的时候它并没有体现出来。你的眼神体现出了你的力量和求知欲―虽然这种意愿还没有集中起来。现在你要学会如何集中你的力量，并适应熊的天性，让它为你所用。”"
D.SharedStrings[6596]="在你外出时有位士兵来找过你。好像跟前往纳格兰的车队有关。\n\n不管是什么事情，车队的安危都值得担忧。那可是战歌氏族的领地。"
D.SharedStrings[6597]="在你寻找宗师的过程中，你刚刚与一名驯宠大师战斗过。你必须在再次战斗前恢复你的宠物。"
D.SharedStrings[6598]="在你所属阵营的任意主城中杀死50个敌对阵营的玩家。"
D.SharedStrings[6599]="在你手上的是『荣誉酿酒者』手印吗?"
D.SharedStrings[6600]="在你找出诅咒教派的间谍以后，大领主提里奥·弗丁安排了双倍的卫兵。弗丁大人认为诅咒教派不会仅仅因为失去一个黑骑士就善罢甘休。$B$B根据天爪龙斥候的报告，有一支诅咒教派的部队正准备袭击我们，他们的首领是一条名叫冰喉的冰霜巨龙。如果不阻止他们的话，赛场就会受到攻击。斥候们说，冰喉就盘旋在我们的西南方向，铁墙大坝和奥尔杜萨交界的地方。"
D.SharedStrings[6601]="在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。"
D.SharedStrings[6602]="在你点燃引线的时候，你发现它的燃烧速度比你想象中的要快了许多。$B$B炸弹就要爆炸了，只有马上跳进深坑，并且不被炸下来的杂物砸到，你才有可能活下来。"
D.SharedStrings[6603]="在你痛下杀手之前，将敌人玩弄于股掌之间总让人乐此不疲。"
D.SharedStrings[6604]="在你的位置制造一滩剧毒泥浆！剧毒泥浆每1秒会造成{1}点自然伤害。"
D.SharedStrings[6605]="在你的小队中无人使用琥珀幼龙的情况下，击败魔环中的魔网守护者埃雷苟斯（英雄难度）。"
D.SharedStrings[6606]="在你的小队中无人使用红玉幼龙的情况下，击败魔环中的魔网守护者埃雷苟斯（英雄难度）。"
D.SharedStrings[6607]="在你的小队中无人使用翡翠幼龙的情况下，击败魔环中的魔网守护者埃雷苟斯（英雄难度）。"
D.SharedStrings[6608]="在你的手掌上划一刀，与达库鲁定下契约。"
D.SharedStrings[6609]="在你的职业大厅的指挥地图上选择下一个突击点。"
D.SharedStrings[6610]="在你的脚边放置一个陷阱符文。陷阱符文会持续5分钟。"
D.SharedStrings[6611]="在你的舰船上安装高能炉并完成海军封锁行动。"
D.SharedStrings[6612]="在你的舰船周围放出烟幕，干扰敌方视野以避免受到先发打击。"
D.SharedStrings[6613]="在你的船坞建造一艘驱逐舰，并派它去执行海军行动。"
D.SharedStrings[6614]="在你的要塞与初级勘测员多恩谈一谈。"
D.SharedStrings[6615]="在你的队伍占领采石场和油料精炼厂的情况下获取征服之岛的胜利。"
D.SharedStrings[6616]="在你要塞的矿井附近找到奇怪的石头。"
D.SharedStrings[6617]="在你选择的区域制造一个诱饵目标。半径30码范围内的任何兽人都会前来调查。"
D.SharedStrings[6618]="在你面前的敌方玩家尸体上放置一面旗帜。"
D.SharedStrings[6619]="在使四个导管先分别失效的情况下击败雷电王座的雷神（普通或英雄难度）。"
D.SharedStrings[6620]="在保证古达克的莫拉比没有一次成功变身为猛犸象的情况下击败他（英雄难度）。"
D.SharedStrings[6621]="在保证着魔的植株存活的情况下赢得烛龙之战的胜利。"
D.SharedStrings[6622]="在假日活动期间完成军团的史诗地下城！"
D.SharedStrings[6623]="在假日活动期间重温大地的裂变时空漫游地下城！"
D.SharedStrings[6624]="在假日活动期间重温巫妖王之怒时空漫游地下城！"
D.SharedStrings[6625]="在假日活动期间重温熊猫人之谜时空漫游地下城！"
D.SharedStrings[6626]="在假日活动期间重温燃烧的远征时空漫游地下城！"
D.SharedStrings[6627]="在先后倒下的10秒内将两条幼龙杀死，然后击败哈尔弗斯·碎龙者。绿龙宝宝可被视作一条幼龙。"
D.SharedStrings[6628]="在光复诺莫瑞根地上部分中协助过大工匠梅卡托克和诺莫瑞根流亡者。"
D.SharedStrings[6629]="在光芒之柱的顶部召唤弗蕾亚的力量。"
D.SharedStrings[6630]="在光辉中进行朗诵祈祷文。无法在战斗中使用。"
D.SharedStrings[6631]="在克尔苏加德的大厅中杀死至少18个憎恶的情况下，击败纳克萨玛斯的克尔苏加德（10人）。"
D.SharedStrings[6632]="在克尔苏加德的大厅中杀死至少18个憎恶的情况下，击败纳克萨玛斯的克尔苏加德（25人）。"
