D.SharedStrings[6738]="在公会队伍中，在占领全部5面旗帜的情况下获取100次阿拉希盆地评级战场的胜利。"
D.SharedStrings[6739]="在公会队伍中，成为本服务器首个在英雄难度的巨龙之魂中击杀死亡之翼的公会。"
D.SharedStrings[6740]="在公会队伍中，成为本服务器首个在英雄难度的恐惧之心中成功击杀大女皇夏柯希尔的公会。"
D.SharedStrings[6741]="在公会队伍中，成为本服务器首个在英雄难度的暮光堡垒中成功击杀希奈丝特拉的公会。"
D.SharedStrings[6742]="在公会队伍中，成为本服务器首个在英雄难度的永春台中成功击杀惧之煞的公会。"
D.SharedStrings[6743]="在公会队伍中，成为本服务器首个在英雄难度的火焰之地中成功击杀拉格纳罗斯的公会。"
D.SharedStrings[6744]="在公会队伍中，成为本服务器首个在英雄难度的风神王座中成功击杀奥拉基尔的公会。"
D.SharedStrings[6745]="在公会队伍中，成为本服务器首个在英雄难度的黑翼血环中成功击杀奈法利安的公会。"
D.SharedStrings[6746]="在公会队伍中，获得1000次评级战场的胜利。"
D.SharedStrings[6747]="在公会队伍中，获得1次评级战场的胜利。"
D.SharedStrings[6748]="在公会队伍中，获得2000次评级战场的胜利。"
D.SharedStrings[6749]="在公会队伍中，获得5000次评级战场的胜利。"
D.SharedStrings[6750]="在其获得的“生锈”效果不高于5层的情况下击败通灵学院的血骨傀儡（英雄难度）。"
D.SharedStrings[6751]="在兽人氏族中，学会与德拉诺的元素之灵交流是一项极为重要的成就。许多氏族都宣称神秘的“第一萨满”来自他们的氏族，但事实是没人能确保他或者她的忠诚度。"
D.SharedStrings[6752]="在兽栏中，你可能会遇到赞达拉部队中最老练的驯兽师。他们懂得用斧子、野兽和爪子进行攻击。他们就是在这里建立起自己的骑兵部队的。$b$b在他们骑着那些怪物出现在战场上之前，我们要你先去兽栏击败那里的赞达拉巨魔。"
D.SharedStrings[6753]="在兽栏杀死5只迅猛龙和10只训练有素的掠食龙。"
D.SharedStrings[6754]="在内线米查尔被处死之前将他救出来。"
D.SharedStrings[6755]="在再次坐下就餐前将你的食物摆放好。"
D.SharedStrings[6756]="在军官身边一定范围内时，每秒钟恢复12点生命值和15点法力值。"
D.SharedStrings[6757]="在军官身边一定范围内时，每秒钟恢复8点生命值和10点法力值。"
D.SharedStrings[6758]="在冠军的试炼中使用纯洁者耶德瑞克的锤子将其击败（英雄难度）。"
D.SharedStrings[6759]="在冠军的试炼中击败所有首领（英雄难度）。"
D.SharedStrings[6760]="在冠军的试炼中击败黑骑士，并且任何队员不能被引爆食尸鬼击中（英雄难度）。"
D.SharedStrings[6761]="在冬幕节期间的达拉然城中，使用你的冬幕伪装包变成雪人，并且与另一个雪人跳舞。"
D.SharedStrings[6762]="在冬幕节期间穿上华丽的冬幕毛衣，到敌对阵营的主城中歌唱。"
D.SharedStrings[6763]="在冬幕节期间，使用你的打架赛车获得25次胜利。"
D.SharedStrings[6764]="在冬幕节期间，向穆拉丁·铜须投掷一枚雪球。"
D.SharedStrings[6765]="在冬幕节期间，向贝恩·血蹄投掷一枚雪球。"
D.SharedStrings[6766]="在冬幕节期间，对下列种族/职业组合各使用一捧雪花。"
D.SharedStrings[6767]="在冬幕节期间，对联盟的“兄弟”使用槲寄生。"
D.SharedStrings[6768]="在冬幕节期间，对部落的“兄弟”使用槲寄生。"
D.SharedStrings[6769]="在冬幕节期间，打开树下的一件礼物。"
D.SharedStrings[6770]="在冬幕节期间，穿着3件冬季服饰，然后吃下格拉库的肉松蛋糕。"
D.SharedStrings[6771]="在冬幕节期间，运用你的烹饪技巧制作一份小姜饼、一份冬幕节蛋奶酒和一份热苹果酒。"
D.SharedStrings[6772]="在冬幕节期间，骑在飞行驯鹿身上完成“继续轰炸！”任务。"
D.SharedStrings[6773]="在冬拥湖使用载具或火炮杀死100名玩家。"
D.SharedStrings[6774]="在冬拥湖的下列区域各杀死10名玩家。"
D.SharedStrings[6775]="在冰冠堡垒中击败巫妖王（普通难度10人）。"
D.SharedStrings[6776]="在冰冠堡垒中击败巫妖王（普通难度25人）。"
D.SharedStrings[6777]="在冰冠堡垒中击败巫妖王（英雄难度10人）。"
D.SharedStrings[6778]="在冰冠堡垒中击败巫妖王（英雄难度25人）。"
D.SharedStrings[6779]="在冰冠堡垒中，从阿尔萨斯身上获得骸骨战马－－无敌。"
D.SharedStrings[6780]="在冰封水域打通一条航路。"
D.SharedStrings[6781]="在冰锥甜筒购买冰激凌，并与你的孤儿一同分享。"
D.SharedStrings[6782]="在决战奥格瑞玛中与游学者周卓谈一谈。"
D.SharedStrings[6783]="在决战奥格瑞玛中使用时光之眼。"
D.SharedStrings[6784]="在净化斯坦索姆事件中击败永恒腐蚀者（英雄难度）。"
D.SharedStrings[6785]="在净化斯坦索姆战役中，1分钟内杀死100个复活的僵尸（英雄难度）。"
D.SharedStrings[6786]="在凋零野猪的表演期间可要好好表现，以提高你的粉丝得分。"
D.SharedStrings[6787]="在凋零野猪的表演期间好好表现，以提高你的粉丝得分。"
D.SharedStrings[6788]="在击败巫妖王前让死疽效果堆叠至30层（10人）"
D.SharedStrings[6789]="在击败欧尔莉亚的同时击败野性防御者（10人）。"
D.SharedStrings[6790]="在击败欧尔莉亚的同时击败野性防御者（25人）。"
D.SharedStrings[6791]="在刀塔堡垒里找到洛戈什"
D.SharedStrings[6792]="在刀锋山、纳格兰、达拉然下水道、洛丹伦废墟、托维尔隆和虎踞峰各赢得一场竞技场排位赛的胜利。"
D.SharedStrings[6793]="在创世者的图书馆中，从数据库下载米米尔的秘密数据。"
D.SharedStrings[6794]="在制革厂开始你的第一份制皮订单，并收集产品。"
D.SharedStrings[6795]="在刺芒小径从琥珀采集器上收集7个装满琥珀的罐子。"
D.SharedStrings[6796]="在前往库斯海文的路上守卫信使和他携带的珍贵物品。"
D.SharedStrings[6797]="在前线基地医护所中放下你营救出来的银色北伐军战士。"
D.SharedStrings[6798]="在力量谷的拍卖行外、荣誉谷、智慧谷以及精神谷的旗帜下高声叫喊，宣传美酒节。"
D.SharedStrings[6799]="在勇士的训练中，你将有机会和来自其它城市的各位勇士较量，以检验自己的作战技术。虽然勇士之间的战斗并非比赛的正式内容，但仍然可以从中学到许多有价值的东西——比如对手的战斗风格，还有他们的弱点。$B$B斗志高昂的勇士经常互相比试，为了荣耀和名望而战。$B$B多参加一些勇士的训练吧。等到你有足够的自信成为勇士中的佼佼者之后，就把你所获得的徽记拿来给我。"
D.SharedStrings[6800]="在化学云雾的作用下，被云团席卷的所有目标所受到的伤害都提高{1}%。"
D.SharedStrings[6801]="在北伐军军需官卡普萨里斯夫人那里购买一匹银色马驹，并使用它。"
D.SharedStrings[6802]="在北贫瘠之地风险投资公司研究基地里找到控制台。"
D.SharedStrings[6803]="在区域内时每秒造成火焰伤害。"
D.SharedStrings[6804]="在南港与威勒姆中尉对话。"
D.SharedStrings[6805]="在占星者和奥尔多阵营中达到崇拜声望。"
D.SharedStrings[6806]="在占星者阵营或奥尔多阵营中达到崇拜声望。"
D.SharedStrings[6807]="在占领4座基地的情况下获取10次风暴之眼的胜利。"
D.SharedStrings[6808]="在占领全部3面旗帜的情况下获取10次吉尔尼斯之战的胜利。"
D.SharedStrings[6809]="在占领全部5面旗帜的情况下获取10次阿拉希盆地的胜利。"
D.SharedStrings[6810]="在占领采石场、油料精炼厂、船坞、攻城车间和飞艇基地的情况下获得征服之岛战斗的胜利。"
D.SharedStrings[6811]="在卡拉赞墓穴打败黑暗骑士并取得乌萨勒斯。"
D.SharedStrings[6812]="在卡拉赞墓穴打败黑暗骑士并取得天启。"
D.SharedStrings[6813]="在卡桑琅河最南端的朱鹤寺附近找到科洛·迷雾行者。"
D.SharedStrings[6814]="在卡桑琅海湾使用信号弹发射器给联盟舰队发信号。"
D.SharedStrings[6815]="在危急关头，我们会把最强大的力量汇聚成一种纯粹的毁灭性武器。而眼下就是这样的非常时刻。\n\n一旦收到指示，我们会把力量导入一个物品之中，然后把它交给你。释放它的力量，完成一项意义非凡的任务。"
D.SharedStrings[6816]="在双子峰中以3比0获胜，且完成至少1次击杀。"
D.SharedStrings[6817]="在双子峰中死亡"
D.SharedStrings[6818]="在双子峰杀死100个携带旗帜者。"
D.SharedStrings[6819]="在取得死亡之翼背脊之战的胜利前，先诱使他按顺序做出以下翻滚动作：左翻，右翻，左翻，右翻（普通或英雄难度）。"
D.SharedStrings[6820]="在受到伊克之渣效果影响的状态下，击败古达克的迦尔达拉（英雄难度）。"
D.SharedStrings[6821]="在受到伤害时造成{1}点暗影伤害。这个效果会跳跃到附近的其他团队成员身上。"
D.SharedStrings[6822]="在受到治疗时有一定几率治疗敌方目标。"
D.SharedStrings[6823]="在受害者脚下制造一团侵蚀之影，并会向外生长。如果影子的源头被艾露恩之光所覆盖，这些影子将会回到地下。\r\n站在影子中会使受害者每秒受到{1}点暗影伤害。"
D.SharedStrings[6824]="在古克罗克的洞穴可以进行水下呼吸，并且海底移动速度提高{1}%。"
D.SharedStrings[6825]="在古尔达要塞里击败巫师领主莫库克并取得奥术枢纽。"
D.SharedStrings[6826]="在召唤出你的孤儿的情况下，击败乌特加德之巅的伊米隆国王。"
D.SharedStrings[6827]="在召唤出你的孤儿的情况下，完成五个日常任务。"
D.SharedStrings[6828]="在吉尔尼斯之战中死亡"
D.SharedStrings[6829]="在吉尔尼斯之战中，于双虹下做出/喘气的表情。"
D.SharedStrings[6830]="在吉尔尼斯之战中，通过夺回旗帜保卫10次基地。"
D.SharedStrings[6831]="在吉尔尼斯之战资源落后500点的情况下反超并获胜。"
D.SharedStrings[6832]="在吉尔尼斯城保卫战的指挥官身边作战极大地提升了你的士气。"
D.SharedStrings[6833]="在吉尔尼斯的吉尔尼斯城废墟附近找到扎佐·耀指。"
D.SharedStrings[6834]="在同一个角色上获得蛋蛋的蛋、贪睡的威利和小象项圈。"
D.SharedStrings[6835]="在同时受到加速与狂暴效果影响的情况下，持旗作出咆哮的表情。"
D.SharedStrings[6836]="在吞噬效果叠加到10层之前，击败达克萨隆要塞的托尔戈（英雄难度）。"
D.SharedStrings[6837]="在吞完异种虫蛋大餐后，你的小暴掠龙舔了舔它的嘴唇。有一瞬间，你觉得它似乎对已经结束的用餐时间感到失望。"
D.SharedStrings[6838]="在吸血鬼形态下击败鲜血女王兰娜瑟尔，然后再在未变为吸血鬼的情况下击败她一次（10人）。"
D.SharedStrings[6839]="在吸血鬼形态下击败鲜血女王兰娜瑟尔，然后再在未变为吸血鬼的情况下击败她一次（25人）。"
