D.SharedStrings[6861]="在团队中的所有成员冰霜抗性都不超过100点的情况下，击败纳克萨玛斯的萨菲隆（10人）。"
D.SharedStrings[6862]="在团队中的所有成员冰霜抗性都不超过100点的情况下，击败纳克萨玛斯的萨菲隆（25人）。"
D.SharedStrings[6863]="在团队副本中死亡的总次数"
D.SharedStrings[6864]="在围攻砮皂寺中，让将军帕瓦拉克获得20层“引爆”效果并将其击败（英雄难度）。"
D.SharedStrings[6865]="在地上放置一个假人，吸引附近的怪物攻击它。假人可持续存在15秒或直至被杀死。"
D.SharedStrings[6866]="在地上放置一个假人，吸引附近的怪物攻击它。持续3分钟。"
D.SharedStrings[6867]="在地上放置一个酒杯，吸引附近的刀塔食人魔。"
D.SharedStrings[6868]="在地上放置一道爆炸陷阱。当敌人靠近时，陷阱会猛烈地爆炸，造成巨大的伤害，并将附近的所有敌人击退。"
D.SharedStrings[6869]="在地下城和团队副本中死亡的总次数"
D.SharedStrings[6870]="在地图上添加宝藏位置。"
D.SharedStrings[6871]="在地狱咆哮近卫军阵营中达到崇拜声望。"
D.SharedStrings[6872]="在地狱火半岛和地狱火堡垒中，通过杀死怪物而获得的荣耀堡声望提高{1}%。"
D.SharedStrings[6873]="在地狱火半岛和地狱火堡垒中，通过杀死怪物而获得的萨尔玛声望提高{1}%。"
D.SharedStrings[6874]="在地狱火堡垒中，他们正使用玛诺洛斯熔池的恶魔能量腐化一只玛戈隆。\n\n你要是去那地方侦察的话，可要小心。"
D.SharedStrings[6875]="在地狱火堡垒击败阿克蒙德。"
D.SharedStrings[6876]="在地面上喷吐闪电，对敌人造成持续的自然伤害。"
D.SharedStrings[6877]="在地面上放置神圣能量之环，治疗附近的盟友。"
D.SharedStrings[6878]="在地面上放置银色黎明的旗帜，净化附近的土地。"
D.SharedStrings[6879]="在场景的最后增加{1}秒的持续时间。"
D.SharedStrings[6880]="在埃索达阵营中达到崇拜声望，并获得在银色锦标赛中代表埃索达出战的资格。"
D.SharedStrings[6881]="在城里打听莱维娅·劳伦斯的情报。"
D.SharedStrings[6882]="在堕夜精灵中的声望提高{1}点。"
D.SharedStrings[6883]="在堕夜精灵中的声望提高{1}点，最高可达到崇拜。"
D.SharedStrings[6884]="在堕夜精灵的声望提高{1}点，最高可达到崇拜。"
D.SharedStrings[6885]="在塔拉多北部刃怒的指挥部外面与大法师卡德加谈一谈。"
D.SharedStrings[6886]="在塔拉多的尤鲁恩矿场与安吉拉谈一谈。"
D.SharedStrings[6887]="在塔拉多的暮秋岛与先知玛露妮谈一谈。"
D.SharedStrings[6888]="在塔拉多的阿鲁纳附近找到塑晶者巴伦。"
D.SharedStrings[6889]="在塔纳安丛林完成2项区域奖励目标。"
D.SharedStrings[6890]="在塔纳安丛林的所有三个阵营中达到崇敬声望。"
D.SharedStrings[6891]="在塔纳安丛林的钢铁前线击败一只钢铁战争戈隆，并收集战争戈隆挽具。"
D.SharedStrings[6892]="在塔纳安丛林腐化的避难所与欧鲁诺克谈谈。"
D.SharedStrings[6893]="在塔纳安丛林骑乘时移动速度提高{1}%。"
D.SharedStrings[6894]="在塞纳里奥议会和塞纳里奥远征队阵营中达到崇拜声望。"
D.SharedStrings[6895]="在塞西莉亚的栖地找到并击败下列拉格纳罗斯的爪牙。"
D.SharedStrings[6896]="在壁炉的火焰旁度过的时光提升了你对抗即将到来的黑暗的能力。受到的暗影伤害降低20%。最多可叠加5次。"
D.SharedStrings[6897]="在复活节期间吃下100块复活节巧克力。"
D.SharedStrings[6898]="在复活节期间吃下25块复活节巧克力。"
D.SharedStrings[6899]="在复活节期间，装扮成一只兔子并前往安戈洛环形山的葛拉卡温泉，在那里产一枚卵。"
D.SharedStrings[6900]="在复活节期间，通过打开鲜艳的彩蛋获得一件端庄的裙子。"
D.SharedStrings[6901]="在复活节期间，通过打开鲜艳的彩蛋获得白色礼服衬衣和黑色礼服短裤。"
D.SharedStrings[6902]="在外域边境的影月谷见证真正的背叛。"
D.SharedStrings[6903]="在大十字军的试炼中，在击杀任何首领时不死一人，并且在尝试次数剩下50次时获得嘉奖宝箱（25人）。"
D.SharedStrings[6904]="在大厅里，有一本书对我很有价值。$B$B可惜，它在织焰者孔格勒手中。我曾经试着去接近他，但都没有得手。$B$B你也许会比我幸运。不过要小心，我听说他确实丧失理智且变得很疯狂。织焰者打算把图书馆里所有的书籍都烧掉。$B$B他可能也会把血色大厅一起烧掉。"
D.SharedStrings[6905]="在大地之中，我的兄弟能把他们自己赠与给新的生命。你从比死亡更糟糕的命运中拯救了他们。$B$B我不知道在你的语言之中有没有一个字能够表达这对吾族而言有多么意义重大。感谢你，$r。"
D.SharedStrings[6906]="在大地治愈者达鲁尝试与奈瑟匹拉交谈时，在一旁观察。"
D.SharedStrings[6907]="在大漩涡将潮汐领主耐普图隆召唤至艾泽拉斯之心。"
D.SharedStrings[6908]="在大锅上使用时，为熊猫人陷阱的完成度提供一次性的加成。"
D.SharedStrings[6909]="在大锅中的酒不被偷走的情况下完成盎迦猴岛的第二阶段。"
D.SharedStrings[6910]="在天火号不受到暮光弹幕伤害的情况下，击败战争大师黑角（普通或英雄难度）。"
D.SharedStrings[6911]="在天空中翱翔……"
D.SharedStrings[6912]="在夺日者先锋军中的声望提高{1}点。"
D.SharedStrings[6913]="在夺日者阵营中达到崇拜声望，并获得在银色锦标赛中代表一座主城出战的资格。"
D.SharedStrings[6914]="在奈瑟匹拉体内，使用达鲁的网捕捉一只深渊猎手蟹。"
D.SharedStrings[6915]="在奈瑟匹拉的体腔内的墙上攻击7处奈瑟匹拉脓肿。"
D.SharedStrings[6916]="在奈萨里奥的宝库与布莱恩·铜须谈一谈。"
D.SharedStrings[6917]="在奎尔丹纳斯岛，太阳之井高地入口处同哈杜伦·明翼交谈。"
D.SharedStrings[6918]="在奎尔多米尔神殿某处使用女武士的断剑来目睹她最后的经历。"
D.SharedStrings[6919]="在奥丹姆完成应许约柜任务，包括哈里森·琼斯与奥丹姆神殿。"
D.SharedStrings[6920]="在奥丹姆的天降弹雨日常任务中，用1发炮弹杀死10个司克诺兹步兵。"
D.SharedStrings[6921]="在奥丹姆获得一头骆驼坐骑（单驼峰）。"
D.SharedStrings[6922]="在奥尔杜萨，从被奴役的爪牙的尸体上吸取黑暗物质。"
D.SharedStrings[6923]="在奥格瑞玛的一幢住宅里领取你的伪造的文件。"
D.SharedStrings[6924]="在奥格瑞玛的精神谷与历史学家吉帕见面。"
D.SharedStrings[6925]="在奥格瑞玛银行搜索斯内维尔·拉斯罗凯特。"
D.SharedStrings[6926]="在奥格瑞玛阵营中达到崇拜声望，并获得在银色锦标赛中代表奥格瑞玛出战的资格。"
D.SharedStrings[6927]="在奥特兰克山谷中拾取提古勒和弗洛尔的合影。"
D.SharedStrings[6928]="在奥特兰克山谷中死亡"
D.SharedStrings[6929]="在奥特兰克山谷战场中获得一场胜利，然后向任意联盟主城、达拉然、冬拥湖或沙塔斯城中的联盟准将复命。"
D.SharedStrings[6930]="在奥特兰克山谷战场中获得一场胜利，然后向任意部落主城、达拉然、冬拥湖或沙塔斯城中的部落战争使者复命。"
D.SharedStrings[6931]="在奥特兰克山谷的征战平原上，抢在一名敌人下马之前将其杀死。"
D.SharedStrings[6932]="在奥特兰克山谷的雷矛大厅中杀死50名敌对玩家。"
D.SharedStrings[6933]="在奥特兰克山谷的霜狼大厅中杀死50名敌方玩家。"
D.SharedStrings[6934]="在奥金顿击败塔隆戈尔。"
D.SharedStrings[6935]="在守望者中的声望提高{1}点，最高可达到崇拜。"
D.SharedStrings[6936]="在安其拉的住所里，可怕的克苏恩在睡眠中等待着。"
D.SharedStrings[6937]="在完成一个古老的仪式后，鸦爪祭司伊沙尔全身心地用自己的黑暗法术来效忠于泰罗克的化身。"
D.SharedStrings[6938]="在完成净化仪式之前，这副躯体将不断产生怨恨之灵。"
D.SharedStrings[6939]="在宠物战斗中击败叛徒格鲁克、杰出的高雷兹勒、科拉·恐怖图腾、佐尔坦和艾琳娜·振翼。"
D.SharedStrings[6940]="在宠物战斗中击败圣地的俞娜、农夫倪石、莫鲁克、勇敢的尹勇、探索者祖什和废土行者苏游。"
D.SharedStrings[6941]="在宠物战斗中击败大卫·寇斯、德扎·疫角、科塔兹·黑锤、伊芙瑞莎和杜林·黑锤。"
D.SharedStrings[6942]="在宠物战斗中击败尼基·微技、拉斯安、纳洛克和莫勒鲁长老。"
D.SharedStrings[6943]="在宠物战斗中击败布洛克、鲍丁·固拳和高兹·怨怒。"
D.SharedStrings[6944]="在宠物战斗中击败毕格·爆索、差点没头的雅各布、奥克鲁特·荒龙和格特瑞奇。"
D.SharedStrings[6945]="在宠物战斗中击败茱莉亚·史蒂文斯。"
D.SharedStrings[6946]="在宠物战斗中击败莉迪亚·埃考斯特。"
D.SharedStrings[6947]="在寇塔峰上标出10处山羊咔啡“沉积物”。"
D.SharedStrings[6948]="在寇魔古寺中央持有一颗能量球并坚持90秒。"
D.SharedStrings[6949]="在寇魔古寺中死亡"
D.SharedStrings[6950]="在寇魔古寺为你的队伍获得8,000点胜利点数。"
D.SharedStrings[6951]="在对一根奥术之柱引导完成以后，对所有敌人造成{1}点奥术伤害。"
D.SharedStrings[6952]="在将下列物品喂给萨鲁克后击败萨格拉斯之墓的主母萨丝琳（普通或更高难度）。"
