D.SharedStrings[6954]="在小地图上显示附近所有野兽的位置。"
D.SharedStrings[6955]="在尼芬雷先祖或永不疲倦的霜脉矮人的尸体上吹响霍迪尔的号角。"
D.SharedStrings[6956]="在岩石大厅的远古法庭事件中获胜，并且保证布莱恩·铜须不受到任何伤害（英雄难度）。"
D.SharedStrings[6957]="在工坊开始你的第一份工程学订单，并收集产品。"
D.SharedStrings[6958]="在巨石之核与高阶女祭司艾苏尔的战斗中，于10秒内击败60个信徒（英雄难度）。"
