D.SharedStrings[6969]="在巨龙之魂团队副本中击败莫卓克（英雄难度）。"
D.SharedStrings[6970]="在巨龙之魂团队副本中取得死亡之翼背脊之战的胜利（英雄难度）。"
D.SharedStrings[6971]="在巨龙之魂团队副本中完成致使死亡之翼陨落的所有战斗。"
D.SharedStrings[6972]="在巴拉丁典狱官阵营中达到崇拜声望。"
D.SharedStrings[6973]="在布林顿回路教程小游戏中达到20级。"
D.SharedStrings[6974]="在带有铁靴烈酒效果的情况下击败钢铁议会（10人）。"
D.SharedStrings[6975]="在带有铁靴烈酒效果的情况下击败钢铁议会（25人）。"
D.SharedStrings[6976]="在干船坞与索洛格碰头。"
D.SharedStrings[6977]="在并不甘愿合作的莫尔葛工程师的指引下，恶魔猎手创造出了许多这样的传送门前往马顿。不幸的是，他们对这些传送门疏于管范，致使从传送门中前来的恶魔比过去的多得多。"
D.SharedStrings[6978]="在幽暗城阵营中达到崇拜声望，并获得在银色锦标赛中代表幽暗城出战的资格。"
D.SharedStrings[6979]="在废品站的焚化炉附近使用一小袋回收的物资。"
D.SharedStrings[6980]="在废品站，你可以查看你的追随者们从战场上带回来的额外材料，并把所有有用的东西保留下来。\n\n我手头有一包我们的人带回来的额外材料，但还没仔细分拣过。要不你就把它带到焚化炉那边去，看看里面还有没有什么能用的东西。"
D.SharedStrings[6981]="在弓或枪械上加装永久性的瞄准镜，使其伤害提高{1}点。\r\n\r\n加装瞄准镜后的远程武器会变成灵魂绑定物品。不能对物品等级高于600的物品使用。"
D.SharedStrings[6982]="在弓或枪械上加装永久性的瞄准镜，使其攻击伤害提高{1}点。\r\n\r\n加装瞄准镜后的远程武器会变成灵魂绑定物品。不能对物品等级高于600的物品使用。"
D.SharedStrings[6983]="在弓或枪械上加装永久性的瞄准镜，使其攻击伤害提高{1}点。不能对物品等级高于600的物品使用。"
D.SharedStrings[6984]="在弓或枪械上加装永久性的瞄准镜，使其远程命中提高{1}点。\r\n\r\n加装瞄准镜后的远程武器会变成灵魂绑定物品。不能对物品等级高于600的物品使用。"
D.SharedStrings[6985]="在引爆4朵初生的花朵后击败永夜大教堂的阿格洛诺克斯（史诗难度）。"
D.SharedStrings[6986]="在弗蕾亚受到25层自然协调效果影响的情况下击败她（10人）。"
D.SharedStrings[6987]="在当时，鹿骨是最常用来制作鱼钩的材料：足够坚固，可以刻出倒刺；同时又有足够的韧性，不会在巨大的鲑鱼嘴里被折断。许多渔民会在他们的“幸运鱼钩”上雕刻精心设计的图案。"
D.SharedStrings[6988]="在影月谷的沙塔尔祭坛与大主教玛拉达尔谈一谈。"
D.SharedStrings[6989]="在影月谷黯影沼泽北部的塔纳安海峡里消灭逆流。"
D.SharedStrings[6990]="在影牙城堡中击败高弗雷勋爵（英雄难度）。"
D.SharedStrings[6991]="在影牙城堡中，于指挥官斯普林瓦尔没能受到邪恶增强效果影响的情况下将其击败（英雄难度）。"
D.SharedStrings[6992]="在影牙城堡中，于灰葬男爵没能成功施放怜悯治疗的情况下将其击败（英雄难度）。"
D.SharedStrings[6993]="在影牙城堡中，用弹幕击败12个嗜血食尸鬼，并将高弗雷勋爵击败（英雄难度）。"
D.SharedStrings[6994]="在征服之岛中，使用一辆投刃车杀死10名玩家，并且自己不死亡。"
D.SharedStrings[6995]="在征服之岛中，使用炮台摧毁10辆载具并轰杀100名玩家。"
D.SharedStrings[6996]="在征服之岛中，在敌方大门没有被攻破前冲入他们的庭院。"
D.SharedStrings[6997]="在很久很久以前，某人可真是啰嗦啊。不过你很幸运——你一个字也看不懂。"
D.SharedStrings[6998]="在微缩地图上显示附近所有矿脉的位置。"
D.SharedStrings[6999]="在微缩地图上显示附近所有药草的位置。"
D.SharedStrings[7000]="在德拉诺战役期间击败下列搏击俱乐部首领。"
D.SharedStrings[7001]="在德拉诺战役期间击败以下稀有搏击首领。"
D.SharedStrings[7002]="在德拉诺战役期间获得购买下列搏击俱乐部首领挑战卡牌的权利。"
D.SharedStrings[7003]="在德拉诺的PVP战斗中消灭500名熊猫人玩家。"
D.SharedStrings[7004]="在德拉诺达到5000个荣誉击杀。"
D.SharedStrings[7005]="在德拉诺野外时，锻炉卫士会时刻注视着你并来协助你战斗。"
D.SharedStrings[7006]="在德莱尼到来之前，这块石碑的碎片已经在塔拉多躺了几百年。上面记载了食人魔皇室发布的捣毁数个兽人定居点的命令，以报复一些叛军突袭高里亚奴隶贸易车队的行为。这些命令应该得到了执行，因为那些城镇已经不复存在了，只有这块石碑静静诉说着那段黑暗的历史。"
D.SharedStrings[7007]="在恐惧中昏迷，受到周期性伤害。"
D.SharedStrings[7008]="在恐轨车站击败啸天者托瓦拉。"
D.SharedStrings[7009]="在悟道者红色烟雾弹的庇护下，受到伤害降低20%。"
D.SharedStrings[7010]="在悬槌角斗场中干掉100名角斗士。$B$B你可以通过与悬槌堡的卡格对话或在你的角斗士圣殿中与骨渣对话来进入角斗场。"
D.SharedStrings[7011]="在悼念日与卡特琳娜跳舞来变成一只骷髅。"
D.SharedStrings[7012]="在情人节期间的达拉然城中与别人共进浪漫午餐，并品尝快乐奶油。"
D.SharedStrings[7013]="在情人节期间获得一束红玫瑰或一束黑玫瑰。"
D.SharedStrings[7014]="在情人节期间，从影牙城堡的药剂师汉摩尔处取得爱情火箭。"
D.SharedStrings[7015]="在憎恶不使用回流软泥的情况下，击败普崔塞德教授（10人）。"
D.SharedStrings[7016]="在憎恶不使用回流软泥的情况下，击败普崔塞德教授（25人）。"
D.SharedStrings[7017]="在懒惰的苦工睡觉时，用工头的木棒敲醒4个苦工。"
D.SharedStrings[7018]="在戈尔隆德与杜隆坦碰头。"
D.SharedStrings[7019]="在戈尔隆德使用强化钢铁陷阱捕捉一只野猪或淡水兽，然后在你的畜棚里下达一份产品订单。"
D.SharedStrings[7020]="在戈尔隆德的天海岭与希萨莉·黑鸦谈一谈。"
D.SharedStrings[7021]="在戈尔隆德的战斗燃油仓库里与杜隆坦交谈。"
D.SharedStrings[7022]="在戈尔隆德的石槌竞技场附近找到卡什德拉克。"
D.SharedStrings[7023]="在戈尔隆德的石槌竞技场附近找到角斗士阿卡尼。"
D.SharedStrings[7024]="在戈尔隆德的蛮兽岗哨与杜隆坦谈一谈。"
D.SharedStrings[7025]="在戈尔隆德的迪奥诺之劫与贝楚斯谈一谈。"
D.SharedStrings[7026]="在戈尔隆德的高山走廊与守备官玛尔拉德谈一谈。"
D.SharedStrings[7027]="在戈尔隆德被遗忘的洞穴附近阅读希尔加的日记。"
D.SharedStrings[7028]="在戈尔隆德高格里克之陨西部消灭泰摩尔，并取得一堆消化了一半的龙虾人肉。"
D.SharedStrings[7029]="在成功的任务中使用，可搜索周围水域，带回一箱有用的残骸。"
D.SharedStrings[7030]="在我们准备锦标赛的同时，银色北伐军也在准备对敌人的冰冠堡垒发动攻击。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的北伐军战士已经在恐惧之门科雷萨以南建立了先头营地。拿上你的长枪到营地去，骑上军马，击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，不过你完全不用害怕。你的战马可以轻易地将它们踏平。"
D.SharedStrings[7031]="在我们商队往来荒野都很安全时回来找我。"
D.SharedStrings[7032]="在我们封印墓穴时，我将禁锢萨格拉斯的最后一块封印残片交给了戒卫侍女。如果你能得到它，就能在墓穴中随意穿行了。但我不知道那位守护者怎么样了，你得做好最坏的打算。"
D.SharedStrings[7033]="在我们把所有的注意力都放在坚守暮冬要塞、处理天谴之门一带的状况时，月溪旅正在努力穿越茂密的森林，与灰熊丘陵的那些不友好的居民进行战斗。他们希望能找到另一条通往冰冠冰川的道路。$B$B驻扎在琥珀松木营地的杜蒙特中尉正在征募无畏的强壮冒险者去探索未知的野外。你愿意去接受这份挑战吗？"
D.SharedStrings[7034]="在我们潜在的新盟友之中，似乎有些人还对我们的能力有所质疑。如果他们发觉我们连自己家门口的问题都不能摆平，又怎么会觉得我们能对他们有所帮助呢？$B$B你做的事情将会改变这个状况。我们的能力很快就不再会受到任何质疑。我们将很快以与新盟友们对等的身份加入部落。$B$B将这封信交给被遗忘者的领袖，希尔瓦娜斯女王。她一直站在我们这一边，达尔坎的死讯对她来说无疑将会是最美妙的音乐。做好长途旅行的准备吧，$n。如果一切顺利，她可能会派你去奥格瑞玛。"
D.SharedStrings[7035]="在我们的故乡肆虐的所有地狱火堡垒邪兽人都必须要消灭干净！但要想攻击地狱火堡垒，我们必须首先占领堡垒外围的几处战略要地。$B$B巡逻队发现有三处工事正好适合我们的目的。但联盟竟与我们不谋而合，现在已经派出部队占领了那里！$B$B我要求你立刻阻止联盟的行动，并占领这些工事。协助我军占领工事之后，立刻回来向我报告。$B$B为了部落！"
D.SharedStrings[7036]="在我的面前站着的是联盟所尊崇的英雄。$B$B<哈格丁中尉向你敬礼。>$B$B很少人能够在雷矛部族赢得这样的称号。我看到敌人向你蜂拥而来，旋即全部倒下。$B$B你踏入战场，就成了我们部队的明灯!$B$B这是你的新徽记。"
D.SharedStrings[7037]="在战场上击败你的对手，你会得到嘉奖的。"
D.SharedStrings[7038]="在战斗中使用滚地翻，将对目标4码范围内的所有敌人造成{1}点物理伤害并将其击退。"
D.SharedStrings[7039]="在战斗区域内击败宠物。"
D.SharedStrings[7040]="在战斗的间隙，不同类型的恶魔会表现出不同的行为。比如说，魅魔喜欢详细地记下她们每天的作所作为。她们的描述总是耸人听闻，有时甚至荒诞不经。这些记载通常会写在用她们的敌人或俘虏的皮肤做成的“纸”上。"
D.SharedStrings[7041]="在战斗过程中周期性地受到自然伤害。"
D.SharedStrings[7042]="在战歌峡谷、阿拉希盆地和奥特兰克山谷中达到崇拜声望。"
D.SharedStrings[7043]="在战歌峡谷中死亡"
D.SharedStrings[7044]="在战歌峡谷中，杀死一名获得了加速增效的玩家。"
D.SharedStrings[7045]="在战歌峡谷战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。"
D.SharedStrings[7046]="在战歌峡谷战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。"
D.SharedStrings[7047]="在战歌峡谷杀死100个携带旗帜者。"
D.SharedStrings[7048]="在戴着感恩者礼帽，穿着感恩者的裙子、长袍或是外衣中的任意一件时，击败利爪之王艾吉斯。"
D.SharedStrings[7049]="在所有《燃烧的远征》副本相关势力中达到崇拜声望。"
D.SharedStrings[7050]="在所有专业与辅助专业中，都获得525点技能点数。"
D.SharedStrings[7051]="在所有专业与辅助专业中，都获得600点技能点数。"
D.SharedStrings[7052]="在所有宴会客人都具有偏执狂效果的情况下击败重返卡拉赞的麦迪文之影（史诗难度）。"
D.SharedStrings[7053]="在所有的友方主城中燃放暗月烟花。"
D.SharedStrings[7054]="在所有联盟种族阵营中达到崇拜声望，并获得在银色锦标赛中代表所有联盟种族出战的资格。"
D.SharedStrings[7055]="在所有部落种族阵营中达到崇拜声望，并获得在银色锦标赛中代表所有部落种族出战的资格。"
D.SharedStrings[7056]="在扎尼维斯的琥珀采掘场找到被挖出的英杰。"
D.SharedStrings[7057]="在扎赫纳尔魔网废墟附近寻找巴瑞克·疾风。"
D.SharedStrings[7058]="在托维尔失落之城与锁喉的战斗中，于10秒内击败20条狂乱的鳄鱼（英雄难度）。"
D.SharedStrings[7059]="在托维尔失落之城与高阶预言者巴林姆的战斗中，击败3个正在燃烧的灵魂（英雄难度）。"
D.SharedStrings[7060]="在托维尔失落之城中击败南风之主希亚玛特。"
D.SharedStrings[7061]="在托维尔失落之城中击败南风之主希亚玛特（英雄难度）。"
D.SharedStrings[7062]="在托维尔失落之城中，在受到3层闪电充能效果影响的情况下击败南风之主希亚玛特（英雄难度）。"
D.SharedStrings[7063]="在拉格纳罗斯的领域击败下列烈焰副官，并且不被他们的特殊攻击命中。"
D.SharedStrings[7064]="在拉穆卡恒托维尔阵营中达到崇拜声望。"
D.SharedStrings[7065]="在拍卖行出售物品"
D.SharedStrings[7066]="在拍卖行出售物品的最高价格"
D.SharedStrings[7067]="在拍卖行搜索斯内维尔·拉斯罗凯特。"
D.SharedStrings[7068]="在拍卖行购买物品"
D.SharedStrings[7069]="在拍卖行购买物品的最高价格"
D.SharedStrings[7070]="在拥有敏锐光环效果的情况下击败托里姆（10人）。"
D.SharedStrings[7071]="在拥有敏锐光环效果的情况下击败托里姆（25人）。"
D.SharedStrings[7072]="在指定位置召唤1个会在原地旋转的奥术哨兵。哨兵的射线会对触碰到的玩家造成奥术伤害。"
D.SharedStrings[7073]="在指定位置投下巨型邪能炸弹，对炸弹直接碾压的目标造成{1}点火焰伤害，对其他所有目标造成{2}点火焰伤害。"
D.SharedStrings[7074]="在接下来的3秒内每秒燃烧总生命值的3%。"
D.SharedStrings[7075]="在控制了荣耀之路所有岗哨的情况下击败敌对阵营的指挥官。"
D.SharedStrings[7076]="在控制全部4颗能量球的情况下获得寇魔古寺的胜利。"
D.SharedStrings[7077]="在掷贪婪骰子决定物品等级高于185的精良或更高品质物品归属时，以100点获胜。"
D.SharedStrings[7078]="在掷需求骰子决定物品等级高于185的精良或更高品质物品归属时，以100点获胜。"
D.SharedStrings[7079]="在携带塞泰的黑暗之爪的情况下击败纳格兰的所有训练中的坐骑目标。"
D.SharedStrings[7080]="在携带铁颚狼齿项链的情况下击败纳格兰的所有训练中的坐骑目标。"
D.SharedStrings[7081]="在收集3块原生真铁矿石之后击败黑石铸造厂的格鲁尔（普通或更高难度）。"
D.SharedStrings[7082]="在攻击敌人时有一定几率为佩戴者恢复{1}点生命值。"
D.SharedStrings[7083]="在攻击敌人时有可能为使用者回复{1}点生命值。"
D.SharedStrings[7084]="在放置了三个或更少的邪能护盾发生器的情况下击败安托鲁斯，燃烧王座的安托兰统帅议会。"
D.SharedStrings[7085]="在效果结束时立即杀死处于暮光领域的目标，并将正常领域中的目标拖入暮光领域。"
D.SharedStrings[7086]="在敌人位置制造一道冰冻之水的喷泉，造成冰霜伤害，并将其击飞。"
D.SharedStrings[7087]="在敌人周围生成一片孢子云，持续造成自然伤害并降低其造成的伤害。"
D.SharedStrings[7088]="在敌人脚下制造一个疯狂之井，一小段时间之后造成暗影伤害。"
D.SharedStrings[7089]="在敌人脚下形成一道急流，造成冰霜伤害并将其击飞到空中。"
D.SharedStrings[7090]="在敌人面前掷出施法者的盾牌，在攻击范围内造成{1}点暗影伤害，击退敌人。"
D.SharedStrings[7091]="在敌方玩家释放灵魂之前，对他们使用/hug表情命令。"
D.SharedStrings[7092]="在敌方目标身上种下一连串火种，在4秒后或对目标造成重大打击时因爆炸而造成{1}点火焰伤害。"
D.SharedStrings[7093]="在斯巴索克雷区连续被10枚地雷炸到，期间不落地。"
D.SharedStrings[7094]="在斯考德-艾希尔检查6面雕饰维库盾牌。"
D.SharedStrings[7095]="在斯考德-艾希尔神殿的四座祭坛获得祝福，然后与雕像沟通。"
D.SharedStrings[7096]="在新工匠镇里，向大工匠梅卡托克进行自我介绍。"
D.SharedStrings[7097]="在施法者与目标之间传输生命。"
D.SharedStrings[7098]="在施法者周围召唤一团风暴雷云，当施法者被攻击时会造成自然伤害。"
D.SharedStrings[7099]="在施法者周围召唤出大量黑曜石尖刺，对附近目标造成{1}点物理伤害，并将其击退。"
D.SharedStrings[7100]="在施法者所在位置召唤一个泡沫之池。"
D.SharedStrings[7101]="在施法者所在的地點召喚玩家角色尺寸的隱形碰撞物件。這可使玩家角色站在NPC身上。"
D.SharedStrings[7102]="在施法者脚下召唤一组符文，提高所有站在其中的目标的爆击几率。"
D.SharedStrings[7103]="在施法者身周笼罩上一层保护性的护盾，吸收最多{1}点伤害，被护盾吸收的伤害会让施法者失去法力值，而不是生命值。还会反射{2}%的法术伤害。"
D.SharedStrings[7104]="在施法者身边制造幻象以暂时迷惑对手。"
D.SharedStrings[7105]="在施法者身边召唤一个强大的暗影化身，将敌人拉向它，并向它脚下的地面下毒。"
D.SharedStrings[7106]="在施法者身边召唤一个恶臭的死亡猎手。"
D.SharedStrings[7107]="在施法者身边召唤一个闪电新星图腾。"
D.SharedStrings[7108]="在施法者附近召唤一股潮水，对所有敌人造成冰霜伤害。"
D.SharedStrings[7109]="在施法者面前一个锥形区域内造成{1}点物理伤害。"
D.SharedStrings[7110]="在施法者面前制造一个不断扩大的锥形土块。受到该效果影响范围内的生物将被击飞，并在着陆时受到坠落伤害。"
D.SharedStrings[7111]="在施法者面前锥形区域内造成{1}点奥术伤害。"
D.SharedStrings[7112]="在施法者面前锥形区域内造成奥术伤害。"
D.SharedStrings[7113]="在施法者面前锥形区域射出水泡，造成冰霜伤害。"
D.SharedStrings[7114]="在旅行形态下，希萨莉使你的移动速度提高。"
D.SharedStrings[7115]="在旋云之巅与阿萨德的战斗中完全避开静电缠握效果（英雄难度）。"
D.SharedStrings[7116]="在旋云之巅中击败阿萨德（英雄难度）。"
D.SharedStrings[7117]="在无人受到深呼吸伤害的情况下击败奥妮克希亚（10人）。"
D.SharedStrings[7118]="在无人受到深呼吸伤害的情况下击败奥妮克希亚（25人）。"
D.SharedStrings[7119]="在无人触发正负极接触放电的情况下，击败纳克萨玛斯的塔迪乌斯（10人）。"
D.SharedStrings[7120]="在无人触发正负极接触放电的情况下，击败纳克萨玛斯的塔迪乌斯（25人）。"
D.SharedStrings[7121]="在时光之末中与泰兰德的残影开战前，于暗影围攻阶段生存下来，并保护队伍中的治疗者不受任何伤害（英雄难度）。"
D.SharedStrings[7122]="在时光之末中击败姆诺兹多（英雄难度）。"
D.SharedStrings[7123]="在时光之末中，当希尔瓦娜斯的残影使用上层精灵的召唤时击败两个复活的食尸鬼，再击败希尔瓦娜斯的残影（英雄难度）。"
D.SharedStrings[7124]="在时空漫游地下城中获得，可以在主城的时空漫游商人处换取货物。"
D.SharedStrings[7125]="在时间结束前找出队友并将其标记，就会获胜！"
D.SharedStrings[7126]="在昆莱山中不息山的山坡上找到先知昊梵舟。"
D.SharedStrings[7127]="在星歌避难所与泰兰德·语风谈一谈。"
D.SharedStrings[7128]="在星辰坠落的范围内时可以在移动中施法。"
D.SharedStrings[7129]="在暗夜要塞杀死崔利艾克斯。"
D.SharedStrings[7130]="在暗夜要塞消灭古尔丹。"
D.SharedStrings[7131]="在暗夜要塞消灭艾利桑德。"
D.SharedStrings[7132]="在暗夜要塞消灭高级植物学家特尔安。"
D.SharedStrings[7133]="在暗影大厅中消灭10个影月兽人或虚空狼。"
D.SharedStrings[7134]="在暗月马戏团完成至少6个专业技能任务。"
D.SharedStrings[7135]="在暮光之门杀死10个食人魔和双头魔。"
D.SharedStrings[7136]="在暮光堡垒中击败升腾者议会（英雄难度）。"
D.SharedStrings[7137]="在暮光堡垒中击败哈尔弗斯·碎龙者（英雄难度）。"
D.SharedStrings[7138]="在暮光堡垒中击败希奈丝特拉（英雄难度）。"
D.SharedStrings[7139]="在暮光堡垒中击败瓦里昂娜和瑟纳利昂（英雄难度）。"
D.SharedStrings[7140]="在暮光堡垒中，于任何团队成员获得超过30%的堕落之血前，击败古加尔。"
D.SharedStrings[7141]="在暮光堡垒中，于初次尝试且没有任何团队成员倒下的情况下，击败希奈丝特拉（英雄难度）。"
D.SharedStrings[7142]="在暮光堡垒中，于只有一片液冰的情况下击败源质畸体。"
D.SharedStrings[7143]="在暮光堡垒中，于暮光世界杀死6个暮光恶魔，然后击败瓦里昂娜和瑟纳利昂。"
D.SharedStrings[7144]="在暮光堡垒击败古加尔（英雄难度）。"
D.SharedStrings[7145]="在暮光审判中击败大主教本尼迪塔斯（英雄难度）。"
D.SharedStrings[7146]="在暮光审判中，消灭10个暮光火花之后再击败大主教本尼迪塔斯（英雄难度）。"
D.SharedStrings[7147]="在暮光烈焰中燃烧。"
D.SharedStrings[7148]="在暮光高地完成暮光之锤系列任务，包括碎颅者魔山。"
D.SharedStrings[7149]="在暮光高地完成杀戮熔炉竞技场任务，包括暮光的恐惧！"
D.SharedStrings[7150]="在暮光高地的暮光堡垒中找到马迪亚斯·肖尔。"
D.SharedStrings[7151]="在暮光高地的暮光海滩上寻找坠地的蛮锤狮鹫骑士索尔顿·锤击。"
D.SharedStrings[7152]="在暴风城的一幢住宅里领取你的伪造的文件。"
D.SharedStrings[7153]="在暴风城的皇家图书馆与历史学家勒洛尔见面。"
D.SharedStrings[7154]="在暴风城银行搜索斯内维尔·拉斯罗凯特。"
D.SharedStrings[7155]="在暴风城阵营中达到崇拜声望，并获得在银色锦标赛中代表暴风城出战的资格。"
