D.SharedStrings[7242]="在波加尔开始使用磨魂者之前，他曾使用图腾束缚灵魂，驱使它们为他效力。$b$b如果我们能拿到几个那样的图腾，我或许可以利用他与它们之间的灵魂联系来强行建立连结。那他就会被迫现身在我们眼前！$b$b去帮我找几个图腾来，我也许就能实现我的计划，我想有5个应该就够了。"
