D.SharedStrings[7246]="在浮华宝库里存满了雷神最难对付的武器和最珍贵的饰物——不必惊讶，这些通常总是千篇一律，毫无新意。$B$B但其中有一样神器很特别，那是一件名叫风暴项圈的护符，能帮我们弄清驾驭闪电的奥秘。$B$B进入宝库，消灭宝藏看守者。拿走他的钥匙，用它从宝库后面的储物箱里找回护符。"
