D.SharedStrings[7299]="在熔火前线的进攻行动中与下列角色对话。"
D.SharedStrings[7300]="在熔火前线的进攻行动中完成以下目标。"
D.SharedStrings[7301]="在熔炉处开始你的第一份锻造订单，并收集产品。"
D.SharedStrings[7302]="在猎豹、熊、巨熊和枭兽形态下的攻击强度提高{1}点。"
D.SharedStrings[7303]="在猎豹形态下移动速度提高{1}%。"
D.SharedStrings[7304]="在猎豹形态下，希萨莉使你的精通提高{1}。"
D.SharedStrings[7305]="在王子成为国王之前，他经历过很多战斗……但其中只有一场战斗使他差点丢掉性命。$B$B那场战斗就发生在这里。等你看过我向你展示的场景以后，你就都明白了。$B$B从地上拣起一块染血的石头，然后你就可以看到当时的情景了。"
D.SharedStrings[7306]="在玛拉顿的深处居住着一个邪恶的混乱生物——瑟莱德丝公主，她是一个和上古之神相关的地元素。很早以前，她和塞纳留斯的长子扎尔塔结合，他们的后代……被称为半人马。那些半人马杀掉了扎尔塔，并保留了他的遗体。我的任务是征召足够强大的冒险者去杀死瑟莱德丝，这样我们就可以在回到石爪山之前找到扎尔塔的遗体了。"
D.SharedStrings[7307]="在玛祖海床和寒须海湾中可以进行水下呼吸，并且海底移动速度提高{1}%。"
D.SharedStrings[7308]="在玛祖海床和荒寂海湾中可以进行水下呼吸，并且海底移动速度提高{1}%。"
D.SharedStrings[7309]="在环中受到治疗，每秒造成的治疗量提高。"
D.SharedStrings[7310]="在玳刃右侧进行攻击将无法命中。"
D.SharedStrings[7311]="在珠宝店开始你的第一份珠宝加工订单，并收集产品。"
D.SharedStrings[7312]="在理发店搜索斯内维尔·拉斯罗凯特。"
D.SharedStrings[7313]="在瑟拉维斯岛上受到悟道者保护时，你会获得隐形帷幕的保护。一些行动，包括进入战斗、受到伤害、放置炸弹和骑乘都会解除你的潜行状态。"
D.SharedStrings[7314]="在瑟芬崔斯克重新出现后被召唤到它附近。"
D.SharedStrings[7315]="在瓦丝琪尔中击败鲸鲨（尽管或可能是由于他不会掉落任何物品）。"
D.SharedStrings[7316]="在瓦丝琪尔可以进行水下呼吸，且移动速度提高{1}%。"
D.SharedStrings[7317]="在瓦丝琪尔完成耐普图隆任务，包括保卫深渊裂口。"
D.SharedStrings[7318]="在瓦丝琪尔的梦魇深渊中找到波涛语者瓦罗伦。"
D.SharedStrings[7319]="在瓦丝琪尔目睹纳兹夏尔女武士的3个视象。"
D.SharedStrings[7320]="在瓦尔莎拉的洛拉希尔与玛法里奥·怒风谈一谈。"
D.SharedStrings[7321]="在瓦尔莎拉钓鱼时，可能会吸引稀有鱼类。"
D.SharedStrings[7322]="在瓦拉加尔中的声望提高{1}点，最高可达到崇拜。"
D.SharedStrings[7323]="在生命之树形态下，希萨莉使你的急速提高{1}%。"
D.SharedStrings[7324]="在用碎裂星辰摧毁30个地狱火尖刺之后击败萨格拉斯之墓的格罗斯（普通或更高难度）。"
D.SharedStrings[7325]="在白骨庭院中，雷电之王麾下的巫师们正在举行黑暗的仪式。$B$B为扩充军力，山泽夺魂者们将从生者身上偷取的灵魂，注入古老的石头雕像里。$B$B当这些岩石征服者被赋予生命后，他们就会成为战场上可怕的敌手。$B$B我们必须在这些雕像被复活前，阻止他们的仪式。"
D.SharedStrings[7326]="在盛宴餐桌旁将每一种食物都吃过五份，以此获得分享之魂。"
D.SharedStrings[7327]="在盛宴餐桌旁将食物丢在一名食客的头上。"
D.SharedStrings[7328]="在目标位置丢下大量石块，造成自然伤害。"
D.SharedStrings[7329]="在目标位置制造一个火焰喷泉。"
D.SharedStrings[7330]="在目标位置制造一个烈焰之球，追踪生成时离它最近的玩家。\r\n\r\n当烈焰之球与一名玩家接触时，会触发烈焰爆破。"
D.SharedStrings[7331]="在目标位置制造一片充满日光能量的区域。滞留在此区域内的盟友每秒会恢复{1}%的最大生命值。试图闯进该区域的敌人将被击退。"
D.SharedStrings[7332]="在目标位置召唤一个闪电力场，在其持续期间对附近敌人造成自然伤害。"
D.SharedStrings[7333]="在目标位置召唤一只食尸鬼，慢慢向观众群中的任意乐队成员移动。"
D.SharedStrings[7334]="在目标位置召唤一场彗星风暴。"
D.SharedStrings[7335]="在目标位置处撕裂大地。3秒后，一股熔岩之柱从裂口喷涌而出，造成火焰伤害。"
D.SharedStrings[7336]="在目标位置形成一滩邪能之水。目标站在邪能之水中会受到暗影伤害。"
D.SharedStrings[7337]="在目标位置生成一处魂泉。"
D.SharedStrings[7338]="在目标位置部署一颗地雷。地雷会对任何踩着的敌人造成伤害，并使其周围的所有敌人暂时昏迷。"
D.SharedStrings[7339]="在目标区域制造一片水藻，对敌人造成自然伤害并使其减速。"
D.SharedStrings[7340]="在目标区域召唤一根大地之刺，造成{1}点自然伤害。"
D.SharedStrings[7341]="在目标区域附近召唤一个飓风元素。"
D.SharedStrings[7342]="在目标区域降下陨石。对桥梁造成额外伤害。"
D.SharedStrings[7343]="在目标周围召唤三个乌尔的触须，慢慢吸干目标的生命能量。"
D.SharedStrings[7344]="在目标地点制造一个祥和之池，净化受煞影响的目标。"
D.SharedStrings[7345]="在目标地点制造一个祥和之池，提高附近盟友的施法和攻击速度。"
D.SharedStrings[7346]="在目标地点持续造成烈焰喷射。"
D.SharedStrings[7347]="在目标地点生成一个间歇性的暗影能量喷泉。"
D.SharedStrings[7348]="在目标地点生成一个间歇性的火焰喷泉。"
D.SharedStrings[7349]="在目标地点生成一个间歇性的蒸汽喷泉。"
D.SharedStrings[7350]="在目标完全被治愈之前使其受到的治疗量降低{1}%。"
D.SharedStrings[7351]="在目标脚下召唤一股强大的水柱，对其造成冰霜伤害并将其击向空中。"
D.SharedStrings[7352]="在目标脚下召唤一股强大的煞能喷涌，对其造成暗影伤害并将其击向空中。"
D.SharedStrings[7353]="在目标身上叠加剧毒造成持续自然伤害，叠加10层后目标死亡。"
D.SharedStrings[7354]="在目标身上施放野兽的印记，每当野兽对其造成伤害时，目标即会受到{1}点伤害。"
D.SharedStrings[7355]="在看守者加什拉、看守者纳尔伊和看守者希尔希克仍然存活的情况下，击败艾卓-尼鲁布的看门者克里克希尔（英雄难度）。"
D.SharedStrings[7356]="在眠月花园内的任意位置启动，传送到湍流之针上。如果你已经在湍流指针上面，则可以使用它传送回地面。"
D.SharedStrings[7357]="在石槌角斗士竞技场历经千锤百炼，布鲁托俨然已成为一个近身肉搏战的行家里手。"
D.SharedStrings[7358]="在石槌角斗士竞技场历经千锤百炼，角斗士瓦安达姆俨然已成为一个近身肉搏战的行家里手。"
D.SharedStrings[7359]="在破碎群岛上采集任何一种草药后上坐骑的速度加快。"
D.SharedStrings[7360]="在破碎群岛海域钓鱼时，可能会吸引稀有鱼类。"
D.SharedStrings[7361]="在破碎群岛的地面骑乘速度提高{1}%。"
D.SharedStrings[7362]="在破碎群岛的骑乘速度提高{1}%。"
D.SharedStrings[7363]="在破碎群岛采集草药时会出现额外的草药。"
D.SharedStrings[7364]="在碎银矿脉中同时获得“狂暴”和“恢复”效果。"
D.SharedStrings[7365]="在碎银矿脉中死亡"
D.SharedStrings[7366]="在碧蓝巨龙圣地寻找与魔枢现状有关的线索。"
D.SharedStrings[7367]="在祖尔格拉布与金度的战斗中于15秒内击败20个扭曲之魂（英雄难度）。"
D.SharedStrings[7368]="在祖尔格拉布击败伽布、莫尔塔克斯、伽乌里马、莫尔雷克、花翼巢穴女王、加兹兰卡的失落后裔、托尔图恩和古拉巴什厨师长（英雄难度）。"
D.SharedStrings[7369]="在神谕林地月亮井中使用紫水晶瓶装水。"
D.SharedStrings[7370]="在神谕者和狂心氏族阵营中达到崇拜声望。"
D.SharedStrings[7371]="在空中前冲。穿过能量力场可立即为此技能充能。负能量场和负能量位面则会使你昏迷。"
D.SharedStrings[7372]="在空午餐篮里装入你烹制的4份犀牛热狗，外加你在达拉然草地上找到的4片野芥菜。$B$B将芥菜热狗篮交给达拉然城克拉苏斯平台的大法师伯塔鲁斯。"
D.SharedStrings[7373]="在竞技场向多个随机目标发射火箭弹幕，造成火焰伤害并将其击飞至空中。"
D.SharedStrings[7374]="在竞技场和战场中获得荣誉点数以解锁PvP专用天赋和奖励。"
D.SharedStrings[7375]="在竞技场赛季中获得“决斗者”头衔。"
D.SharedStrings[7376]="在竞技场赛季中获得“挑战者”头衔。"
D.SharedStrings[7377]="在竞技场赛季中获得“竞争者”头衔。"
D.SharedStrings[7378]="在竞技场赛季中获得“角斗士”头衔。"
D.SharedStrings[7379]="在第14赛季赢得100场竞技场（3v3）战斗或40场评级战场战斗"
D.SharedStrings[7380]="在第15赛季赢得100场竞技场（3v3）战斗或40场评级战场战斗"
D.SharedStrings[7381]="在索克雷萨高地击败圣光吞噬者戴米多斯。"
D.SharedStrings[7382]="在索克雷萨高地摧毁5个德拉诺黑暗之石。"
D.SharedStrings[7383]="在索克雷萨高地摧毁萨格雷补给，并将由此获得的增益效果保持10分钟。"
D.SharedStrings[7384]="在紧急情况下启动快速反应模式，伤害和生命值提高{1}%。"
D.SharedStrings[7385]="在紫罗兰城堡中举起你的武器，接受六人议会的礼物。"
D.SharedStrings[7386]="在紫罗兰监狱中，不使用防御控制水晶，保持监狱封印完整度100%，并击败塞安妮苟萨（英雄难度）。"
D.SharedStrings[7387]="在紫罗兰监狱中，击败谢沃兹、拉文索尔、艾库隆、湮灭者祖拉玛特、埃雷克姆和摩拉格（英雄难度）。"
D.SharedStrings[7388]="在纳扎纳克：遗忘深渊里调查这个声音的来源。"
D.SharedStrings[7389]="在纳格兰古尔戈索克的秘巢与古尔戈索克谈一谈。"
D.SharedStrings[7390]="在纳格兰完成包括“终极挑战”在内的所有赫米特·奈辛瓦里任务。"
D.SharedStrings[7391]="在纳格兰居住着德拉诺最强大的野兽，而且那里的食人魔使用一种非常残忍的手段驯养他们。$B$B其中，又数那个叫高里亚驱兽者的尤为凶残。他浑身充满了血腥和恐惧的气息。让我们瞧瞧你的坐骑面对他是否还能面不改色。"
D.SharedStrings[7392]="在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。$B$B如果它能让附近的野狼都不得不退避三舍，这对你的塔布羊来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。"
D.SharedStrings[7393]="在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。$B$B如果它能让附近的野狼都不得不退避三舍，这对你的座狼来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。"
D.SharedStrings[7394]="在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。$B$B如果它能让附近的野狼都不得不退避三舍，这对你的淡水兽来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。"
D.SharedStrings[7395]="在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。$B$B如果它能让附近的野狼都不得不退避三舍，这对你的裂蹄牛来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。"
D.SharedStrings[7396]="在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。$B$B如果它能让附近的野狼都不得不退避三舍，这对你的野猪来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。"
D.SharedStrings[7397]="在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。$B$B如果它能让附近的野狼都不得不退避三舍，这对你的雷象来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。"
D.SharedStrings[7398]="在纳格兰的破碎悬崖与格莱布林·迅爆谈一谈。"
D.SharedStrings[7399]="在纳格兰的试炼竞技场北边与卡德加会面。"
D.SharedStrings[7400]="在纳格兰的鲜血竞技场与古尔戈索克交谈，并在特别表演赛中获胜。"
D.SharedStrings[7401]="在织梦者中的声望提高{1}点，最高可达到崇拜。"
D.SharedStrings[7402]="在结构薄弱点放置奥术炸弹。"
D.SharedStrings[7403]="在维迪卡尔的矩阵核心中解锁技能，可在阿古斯使用。 "
D.SharedStrings[7404]="在美酒节期间，戴着合成酿酒护目镜从65码的高度掉落下来，但是不摔死。"
D.SharedStrings[7405]="在美酒节营地的贝尔比处兑换礼品券。"
D.SharedStrings[7406]="在美酒节营地背后的布利克斯·菲克维特处兑换礼品券。"
D.SharedStrings[7407]="在联盟任意主城中杀死2500个敌对阵营的玩家。"
D.SharedStrings[7408]="在聚光灯下！\r\n你所造成的所有伤害提高{1}%。"
D.SharedStrings[7409]="在肯瑞托远征军中的声望提高{1}点。"
D.SharedStrings[7410]="在肯瑞瓦村东部的农场中使用以召唤奶牛贝希。"
D.SharedStrings[7411]="在腐烂森林里杀死5个末日守卫毁灭者、5个恐惧魔王污染者、5个堕落的黑木树人和3个邪孢沼泽领主。"
D.SharedStrings[7412]="在腐烂森林里杀死腐烂的黑熊、腐烂的夜行蜘蛛和腐烂的尖啸蝙蝠，并将它们的肢体组合成魔能容器。"
D.SharedStrings[7413]="在至尊殿使用古拉的咒语，然后击败重生的古拉。"
D.SharedStrings[7414]="在至少1个轨道防御系统被激活的情况下击败烈焰巨兽（10人）。"
D.SharedStrings[7415]="在至少2个轨道防御系统被激活的情况下击败烈焰巨兽（10人）。"
D.SharedStrings[7416]="在至少3个轨道防御系统被激活的情况下击败烈焰巨兽（10人）。"
D.SharedStrings[7417]="在至少一条暮光幼龙存活的情况下与黑岩守护者萨塔里奥交战并将其击败（10人）。"
D.SharedStrings[7418]="在至少一条暮光幼龙存活的情况下与黑岩守护者萨塔里奥交战并将其击败（25人）。"
D.SharedStrings[7419]="在至少两条暮光幼龙存活的情况下与黑岩守护者萨塔里奥交战并将其击败（10人）。"
D.SharedStrings[7420]="在至少两条暮光幼龙存活的情况下与黑岩守护者萨塔里奥交战并将其击败（25人）。"
D.SharedStrings[7421]="在至少出现25个碎石的情况下击败科隆加恩（10人）。"
D.SharedStrings[7422]="在至少出现25个碎石的情况下击败科隆加恩（25人）。"
D.SharedStrings[7423]="在至少有1位长者存活的情况下击败弗蕾亚（10人）。"
D.SharedStrings[7424]="在至少有1位长者存活的情况下击败弗蕾亚（25人）。"
D.SharedStrings[7425]="在至少有2位长者存活的情况下击败弗蕾亚（10人）。"
D.SharedStrings[7426]="在至少有2位长者存活的情况下击败弗蕾亚（25人）。"
D.SharedStrings[7427]="在至少还有2名狗头人奴隶存活的情况下击败冰吼（10人）。"
D.SharedStrings[7428]="在至少还有4名狗头人奴隶存活的情况下击败冰吼（25人）。"
D.SharedStrings[7429]="在至少还有两名痛苦女王存活的情况下击败加拉克苏斯大王（10人）。"
D.SharedStrings[7430]="在至少还有两名痛苦女王存活的情况下击败加拉克苏斯大王（25人）。"
D.SharedStrings[7431]="在至高岭与莱莎见面。"
D.SharedStrings[7432]="在至高岭钓鱼时，可能会吸引稀有鱼类。"
D.SharedStrings[7433]="在與過去的事件調和的過程中..."
D.SharedStrings[7434]="在艾卓-尼鲁布的哈多诺克斯用蛛网封住顶部入口、阻止更多怪物进入之前将其击败（英雄难度）。"
D.SharedStrings[7435]="在艾泽拉斯之心与元素师佳奈谈一谈。"
D.SharedStrings[7436]="在艾萨拉克希雷姆大师的冰霜试炼中，确保在不受到伤害的情况下获得20层冰之精华。"
D.SharedStrings[7437]="在艾萨拉克希雷姆大师的暗影试炼中，确保在不受到伤害的情况下困住20个泣灵。"
D.SharedStrings[7438]="在艾萨拉克希雷姆大师的火焰试炼中，确保在不受到伤害的情况下获得10层火焰之舞。"
D.SharedStrings[7439]="在艾萨拉女王与恶魔勾结之前，那个时代出品的挂毯上经常会展现出独特的“回针”绣法，这种技法在战后已经销声匿迹。"
D.SharedStrings[7440]="在艾萨拉找到位于奥格瑞玛火箭车换乘站的霍扎克·齐格尼伯。"
D.SharedStrings[7441]="在艾萨拉的秘密实验室附近找到九号实验品。"
D.SharedStrings[7442]="在花园东南部尽头的战斗现场使用纳兹夏尔女武士之刃。"
D.SharedStrings[7443]="在苏拉玛购买的魔法食物及法师法术制造的食物与饮料的效果提高{1}%。不包括玩家制造的食品。"
D.SharedStrings[7444]="在苏拉玛钓鱼时，可能会吸引稀有鱼类。"
D.SharedStrings[7445]="在英灵殿时，战士的移动速度提高{1}%。"
D.SharedStrings[7446]="在荆棘谷完成包括“王牌猎人”在内的所有赫米特·奈辛瓦里任务。"
D.SharedStrings[7447]="在荒芜之地的观察者陵墓中，找到哨兵的棋卒的用途。"
D.SharedStrings[7448]="在荒芜之地的观察者陵墓中，找到戒卫的棋卒的用途。"
D.SharedStrings[7449]="在莎拉达希尔的枝干底下，萨维斯不断施压，扭曲并折磨着曾经圣洁的德鲁伊林地。\n\n不仅如此，萨维斯还俘虏了许多德鲁伊，以缓慢又痛苦的方式折磨他们。我们必须前往黑心林地，阻止他的邪恶计划。"
D.SharedStrings[7450]="在萨格拉斯之墓的深处，基尔加丹似乎终于走投无路了。但这是真的吗？还是我们落入了欺诈者的陷阱？"
D.SharedStrings[7451]="在萨隆矿坑副本中，在任何玩家获得11层永冻效果前击败熔炉领主加弗斯特（英雄难度）。"
D.SharedStrings[7452]="在萨隆矿坑副本中，在首次挑战天灾领主泰兰努斯之前，清理通道时无人受到冰锥的伤害（英雄难度）。"
D.SharedStrings[7453]="在虚空之光神殿与贝蒂尔德·深砧谈一谈。"
D.SharedStrings[7454]="在螳螂妖身上涂抹易燃的油，准备将其活活烧死。"
D.SharedStrings[7455]="在血槌炉渣矿井击败戈洛克。"
D.SharedStrings[7456]="在血槌要塞找到伯德里克·格雷散落的日志书页。"
D.SharedStrings[7457]="在血槌要塞找到暗影猎手布加散落的日志书页。"
D.SharedStrings[7458]="在血色大厅击败50个血色十字军的成员。"
D.SharedStrings[7459]="在血骑士大厅底部从生病的血精灵魔导师身上吸取剩余的光明能量。"
D.SharedStrings[7460]="在被击中之后对攻击者造成{1}点奥术伤害。"
D.SharedStrings[7461]="在被击中时对攻击者造成{1}点火焰伤害，使你的法术爆击几率提高{3}%，并使你受到爆击的几率降低{2}%。"
D.SharedStrings[7462]="在被击中时对攻击者造成火焰伤害，使你的法术爆击几率提高{2}%，并使你受到爆击的几率降低{1}%。"
D.SharedStrings[7463]="在被发配到戈尔隆德之前，我就驻扎在纳格兰的破碎悬崖，管理那片乱糟糟的挖掘场。达古德宰相不肯让我带上我喜爱的佩剑。他跟我说，我要去的地方用不上它。$B$B我想把它拿回来，指挥官。我想我们的实力足以打倒达古德，并从他血淋淋的尸体上拿回我的剑了。$B$B它对我意义重大。没有佩剑的食人魔根本算不上食人魔。"
D.SharedStrings[7464]="在被格林托克斥候发现后5分钟内击败魔古山宫殿的杰翰及其格林托克随从（英雄难度）。"
D.SharedStrings[7465]="在被火化之前，这具尸体上整齐地摆放着武器。"
D.SharedStrings[7466]="在被遗弃的营地放出你的冰霜猎犬，追踪布莱恩的气息。"
D.SharedStrings[7467]="在裁缝店开始你的第一份裁缝订单，并收集产品。"
D.SharedStrings[7468]="在裂鞭海岸的水下对正在休眠的利维洛斯投掷，将其穿刺。"
D.SharedStrings[7469]="在装有维库人液体的大锅旁盛满此容器。"
D.SharedStrings[7470]="在西南部平台下收集8颗胀大的海藻球。"
D.SharedStrings[7471]="在西瘟疫之地的四口天灾之锅中，费尔斯通农场里的那一口可能是最容易进入的了。亡灵天灾在那边驻扎的都是新兵，尽管他们也不是轻易可以击败的对手，但相对来说毕竟容易一些。$B$B到费尔斯通农场去，它就在这里的正东方，安多哈尔的西北方，并与那里的护锅者交战。它身上有一把可以打开天灾之锅的钥匙。当你开启那口锅之后，用这个瓶子装满锅里的毒药样品，我们要对它进行研究以制造出一种解药。"
D.SharedStrings[7472]="在西瘟疫之地的墓穴深处找到武器箱。"
D.SharedStrings[7473]="在西芙没有离开的情况下击败托里姆（10人）。"
D.SharedStrings[7474]="在西芙没有离开的情况下击败托里姆（25人）。"
D.SharedStrings[7475]="在西芙还没有离开的时候，迫使托里姆进入竞技场（10人）。"
D.SharedStrings[7476]="在西芙还没有离开的时候，迫使托里姆进入竞技场（25人）。"
D.SharedStrings[7477]="在西部凹地放置信号灯，不要让它受到攻击！"
D.SharedStrings[7478]="在西风避难营内找到特使艾米萨·闪蹄。"
D.SharedStrings[7479]="在要塞中击败所有可召唤的团队首领。"
D.SharedStrings[7480]="在要塞建造一座船坞，使你能建造船只并执行海军行动。"
D.SharedStrings[7481]="在訓練初期，你的第一項任務很簡單:去跟尚羲大師談話。"
D.SharedStrings[7482]="在让锋鳞飞到空中的次数不多于一次的情况下击败它（10人）。"
D.SharedStrings[7483]="在让锋鳞飞到空中的次数不多于一次的情况下击败它（25人）。"
D.SharedStrings[7484]="在诅咒之地的玛尔卓斯杀死玛尔·虫棘。你可以使用魔能容器打断他的沉睡。"
D.SharedStrings[7485]="在诅咒之地的盘蛇谷获得奥利斯塔的护符。"
D.SharedStrings[7486]="在诅咒之地的破碎海滩获得戈洛尔的护符。"
D.SharedStrings[7487]="在试炼场中成功完成基础伤害（白银）的试炼。"
D.SharedStrings[7488]="在试炼场中成功完成基础伤害（青铜）的试炼。"
D.SharedStrings[7489]="在试炼场中成功完成基础伤害（黄金）的试炼。"
D.SharedStrings[7490]="在试炼场中成功完成基础坦克（白银）的试炼。"
D.SharedStrings[7491]="在试炼场中成功完成基础坦克（青铜）的试炼。"
D.SharedStrings[7492]="在试炼场中成功完成基础坦克（黄金）的试炼。"
D.SharedStrings[7493]="在试炼场中成功完成基础治疗（白银）的试炼。"
D.SharedStrings[7494]="在试炼场中成功完成基础治疗（青铜）的试炼。"
D.SharedStrings[7495]="在试炼场中成功完成基础治疗（黄金）的试炼。"
D.SharedStrings[7496]="在试炼场的基础伤害（无限）的试炼中成功顶过10波攻击。"
D.SharedStrings[7497]="在试炼场的基础伤害（无限）的试炼中成功顶过20波攻击。"
D.SharedStrings[7498]="在试炼场的基础伤害（无限）的试炼中成功顶过30波攻击。"
D.SharedStrings[7499]="在试炼场的基础伤害（无限）的试炼中获得最高分。"
D.SharedStrings[7500]="在试炼场的基础伤害（无限）的试炼中获得最高分（90级）。"
D.SharedStrings[7501]="在试炼场的基础坦克（无限）的试炼中成功顶过10波攻击。"
