D.SharedStrings[7509]="在试炼场的基础治疗（无限）的试炼中成功顶过30波攻击。"
D.SharedStrings[7510]="在试炼场的基础治疗（无限）的试炼中获得最高分。"
D.SharedStrings[7511]="在试炼场的基础治疗（无限）的试炼中获得最高分（90级）。"
D.SharedStrings[7512]="在诺兹多姆的子嗣阵营中达到崇拜声望。"
D.SharedStrings[7513]="在诺森德完成包括“母龙之怒”在内的所有赫米特·奈辛瓦里任务。"
D.SharedStrings[7514]="在诺莫瑞根流亡者阵营中达到崇拜声望，并获得在银色锦标赛中代表诺莫瑞根流亡者出战的资格。"
D.SharedStrings[7515]="在赞加拉的卡德加的法师塔与大法师卡德加谈一谈。"
D.SharedStrings[7516]="在赞吉尔复活他之前消灭高阶祭司耶克里克。$b$b假如你迷路了或者需要回到祖尔格拉布，去跟探险者协会挖掘场的梅维克交谈。"
D.SharedStrings[7517]="在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要转至漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。"
D.SharedStrings[7518]="在赫达沙尔找到登山鞋、浸油斗篷，以及魔化磁石。"
D.SharedStrings[7519]="在起源大厅中击败拉夏（英雄难度）。"
D.SharedStrings[7520]="在起源大厅中，于拉夏完成整个充能阶段之前将他击败（英雄难度）。"
D.SharedStrings[7521]="在起源大厅中，于神殿守护者安努尔施放圣歌回响的15秒内将其打断，然后击败他（英雄难度）。"
D.SharedStrings[7522]="在踏梦者瓦莉瑟瑞娅被治疗至满血以前，进入每个由她生成的传送门（10人）。"
D.SharedStrings[7523]="在踏梦者瓦莉瑟瑞娅被治疗至满血以前，进入每个由她生成的传送门（25人）。"
D.SharedStrings[7524]="在身上的每一个装备栏中都装备一件物品等级不低于187级的精良品质物品。"
D.SharedStrings[7525]="在身上的每一个装备栏中都装备一件物品等级不低于213级的史诗品质物品。"
D.SharedStrings[7526]="在身上的每一个装备栏中都装备一件物品等级不低于333级的精良品质物品。"
D.SharedStrings[7527]="在身上的每一个装备栏中都装备一件物品等级不低于359级的史诗品质物品。"
D.SharedStrings[7528]="在身上的每一个装备栏中都装备一件物品等级不低于450级的精良品质物品。"
D.SharedStrings[7529]="在身上的每一个装备栏中都装备一件物品等级不低于476级的史诗品质物品。"
D.SharedStrings[7530]="在身上的每一个装备栏中都装备一件物品等级不低于608级的精良品质物品。"
D.SharedStrings[7531]="在辛萨罗杀死5名邪枝巫医和5名邪枝猎头者。"
D.SharedStrings[7532]="在辛萨罗杀死5名邪枝狂战士和5名邪枝暗影法师。"
D.SharedStrings[7533]="在辛萨罗杀死5名邪枝饮血者和5名邪枝噬魂者。"
D.SharedStrings[7534]="在辛萨罗用蒂基之炬点燃8张蒂基面具。"
D.SharedStrings[7535]="在达克萨隆要塞中挑战暴龙之王爵德，并且在战斗中杀死6名达卡莱裂肠者或达卡莱镰爪龙（英雄难度）。"
D.SharedStrings[7536]="在达拉然与诺米见面。"
D.SharedStrings[7537]="在达拉然喷泉中钓鱼时，有更高的几率可以钓到某些硬币。"
D.SharedStrings[7538]="在达拉然城中阅读《奥术魔法的学派》中的下列章节。"
D.SharedStrings[7539]="在达拉然城中，15秒内进行40次扔火炬杂耍。"
D.SharedStrings[7540]="在达拉然的克拉苏斯平台与大法师卡德加谈一谈。"
D.SharedStrings[7541]="在达拉然的紫罗兰城堡与空军上将罗杰斯谈一谈。"
D.SharedStrings[7542]="在达拉然街道上找到考瓦斯·血棘。"
D.SharedStrings[7543]="在达拉然购买一枚肯瑞托徽记、肯瑞托指环、肯瑞托指箍或肯瑞托戒指。"
D.SharedStrings[7544]="在达纳苏斯阵营中达到崇拜声望，并获得在银色锦标赛中代表达纳苏斯出战的资格。"
D.SharedStrings[7545]="在过去的几天里，我看到过一个女血精灵出入邪兽人的要塞，与邪兽人的首领进行会谈。从她的肢体语言中，我可以看出她是在发布命令。但这到底是怎么回事？她是在传达谁的命令？$B$B我对此充满好奇，所以我在她离开邪兽人营地时跟踪她，结果发现她往北边的火翼岗哨去了。我在火翼岗哨边界停止了跟踪。$B$B在她下一次离开邪兽人营地前杀掉她。"
D.SharedStrings[7546]="在这个世界和灵魂世界之间打开一道裂隙。"
D.SharedStrings[7547]="在这个生物面前摆放一个箱子。"
D.SharedStrings[7548]="在这个通道的另一端，你会看到一片战火纷飞的土地，年轻的$c。部落不断侵入我们神圣的森林，锯断这里的苍天古树来建造他们的战争机器。$B$B进入战歌峡谷，帮助银翼要塞击败入侵的部落势力吧。"
D.SharedStrings[7549]="在这些宴席桌上摆满美食实在是一个能累死人的工作！我在制作酸果蔓酱的时候还在盯着那些甜味土豆，又要保证那些馅饼不被烤糊。$B$B看样子，我已经把所有东西都准备好了。不，等等，我还忘了一样东西。玉米馅料！哦，不。我已经没有时间再去准备玉米馅料了。你愿意帮我一个忙吗？这并不难，你只需要在这里购买一些原料，就能制作出香喷喷的玉米馅料了。"
D.SharedStrings[7550]="在这件物品中注入{1}块埃匹希斯碎片的能量，以激活它真正的力量。"
D.SharedStrings[7551]="在这座岛屿上布满了伺机而动的敌对力量，主要来自三个强大的组织，时刻准备朝我们发起攻击。他们分别是驾驭雷电的大师，古老而强大的幽灵，以及原始赞达拉畸体。$B$B要是你能找到一些散落在这岛屿四处的山泽仪式石，你应该就能让这些强大的敌人现身，一举击败他们。$B$B找到并消灭每个组织的成员，让他们阵脚大乱，我不会让你白忙的。"
D.SharedStrings[7552]="在这样的地方，补给是很不容易找到的，$c。自从占领了这座岛，我们就开始了侦察，但前景不太妙。$B$B幸运的是，我们刚刚收到了一份侦察报告，说是在这座基地西边有一处沼泽，里面有许多鳄鱼。那些鳄鱼的皮对我们的制皮匠来说是很有用的材料。去给我尽量弄一些回来。"
D.SharedStrings[7553]="在这里进入决斗会重置你所有的冷却时间。"
D.SharedStrings[7554]="在进入起源大厅的5分钟之内，结束光明穹顶的战斗（英雄难度）。"
D.SharedStrings[7555]="在远古海滩中死亡"
D.SharedStrings[7556]="在逆风小径上空的达拉然和卡德加会面。"
D.SharedStrings[7557]="在通灵学院中，让卡斯迪诺夫的切肉者获得99层“沸腾嗜血”效果并将其击败（英雄难度）。"
D.SharedStrings[7558]="在通道事件触发后的3分钟内击败乌特加德之巅的残忍的斯卡迪（英雄难度）。"
D.SharedStrings[7559]="在逝网之谷里消灭污染者埃克萨纳托斯并取回沙塔尔。"
D.SharedStrings[7560]="在遗忘山丘找到并杀死康纳中尉。遗忘山丘位于岛屿的极西侧。"
D.SharedStrings[7561]="在遥远南方的阿兰卡峰林，生长在水下的蘑菇正在不断地侵蚀着陆地，古怪的真菌生物四处横行。$B$B其中有一个真菌巨人叫布巴波尔，正好让你的坐骑见识一下它不曾见过的捕食者。"
D.SharedStrings[7562]="在邪能之槌号与战争领主加尔顿谈一谈。"
D.SharedStrings[7563]="在部落任意主城中杀死2500个敌对阵营的玩家。"
D.SharedStrings[7564]="在重新加入战斗前，施法者需要休息。"
D.SharedStrings[7565]="在金莲教阵营达到崇敬声望。"
D.SharedStrings[7566]="在钢铁码头击败斯古洛克。"
D.SharedStrings[7567]="在铁炉堡图书馆的探险者大厅内，将你所抓到的东西展示在空的展台上。"
D.SharedStrings[7568]="在铁炉堡外的美酒节会场找到美酒节组织者，领取免费的啤酒。"
D.SharedStrings[7569]="在铁炉堡阵营中达到崇拜声望，并获得在银色锦标赛中代表铁炉堡出战的资格。"
D.SharedStrings[7570]="在铁甲兵营、典狱官岗哨和熔渣车间达成10次荣誉击杀。"
D.SharedStrings[7571]="在铭文师之家开始你的第一份铭文订单，并收集产品。"
D.SharedStrings[7572]="在银月城阵营中达到崇拜声望，并获得在银色锦标赛中代表银月城出战的资格。"
D.SharedStrings[7573]="在银色北伐军、龙眠联军、肯瑞托和黑锋骑士团阵营中达到崇拜声望。"
D.SharedStrings[7574]="在银色盟约阵营中达到崇拜声望，并获得在银色锦标赛中代表一座主城出战的资格。"
D.SharedStrings[7575]="在银色锦标赛中接受训练，作为你的种族阵营中的候选者出场比赛。"
D.SharedStrings[7576]="在银色锦标赛中接受训练，作为你的种族阵营中的勇士出场比赛。"
D.SharedStrings[7577]="在银色锦标赛中揭穿黑骑士的阴谋，并且击败他。"
D.SharedStrings[7578]="在银色锦标赛中，分别击败所有种族阵营的骑士。"
D.SharedStrings[7579]="在银色锦标赛的场地中，不能攻击敌对阵营的成员。"
D.SharedStrings[7580]="在银色锦标赛的骑乘决斗中击败另一名玩家。"
D.SharedStrings[7581]="在银色黎明和银色北伐军阵营中达到崇拜声望。"
D.SharedStrings[7582]="在银行外、军事区、探险者大厅以及秘法区的旗帜下高声叫喊，宣传美酒节。"
D.SharedStrings[7583]="在锥形范围内吐出闪电，造成自然伤害。"
D.SharedStrings[7584]="在锦标赛上，你可以和你的战友们一起练习技术，但是时刻都不要忘记，我们真正的敌人——天灾军团绝不会坐等灭亡。你不但要和队友切磋，还要在与敌人的战斗中磨砺自己的刀锋。$B$B到位于陨落英雄之谷西南和恐惧之门科雷萨以北的那个地区去。天灾军团正在那里复活死亡的英雄们，并将他们变成我们的敌人。击败那些天灾军团的爪牙，让我们的勇士得到安息，并在那里磨砺你的战斗技艺。"
D.SharedStrings[7585]="在锦标赛上，你可以和你的战友们一起练习技术，但是时刻都不要忘记，我们真正的敌人——天灾军团绝不会坐等灭亡。虽然你已经学会了骑乘作战的要领，也不要把这么多年来积累的战斗技巧都给抛到脑后去。我们需要你用实际行动证明，你可以充满荣誉与勇气地面对天灾军团，这样你才有资格参加我们的锦标赛。$B$B到冰冠冰川去，把你在那里遇到的所有天灾军团成员都给干掉。不过你要离轰炸场远一些，那里的敌人实在是太多了。"
D.SharedStrings[7586]="在锦标赛兽栏旁使用以召唤你的坐骑。"
D.SharedStrings[7587]="在锦标赛兽栏附近使用，召唤你的坐骑。"
D.SharedStrings[7588]="在锦绣谷的闻道之座与游学者周卓谈一谈。"
D.SharedStrings[7589]="在锦绣谷的闻道之座外面与克罗米交谈。"
D.SharedStrings[7590]="在闪电大厅的比亚格里将军携带临时电荷的状态下将其击败（英雄难度）。"
D.SharedStrings[7591]="在队伍中无人触发灾祸效果的情况下，击败乌特加德之巅的伊米隆国王（英雄难度）。"
D.SharedStrings[7592]="在阴影中穿行，在10码范围内的敌人之间穿梭，每0.5秒使用两把武器攻击一个敌人，总共进行5次攻击。可以多次攻击同一个目标。"
D.SharedStrings[7593]="在阴影中穿行，攻击随机敌人。"
D.SharedStrings[7594]="在阴惨泥沼中存在着某种黑暗法术，就连我们的魔法之光都能扑灭，我们的斥候只得艰难的辨识方向。$B$B当你在泥沼中穿行时，重新将你所找到的所有火炬点燃，从而为我们的兄弟们照亮道路。或许它们还能帮你找到回来的路。"
D.SharedStrings[7595]="在阵亡勇士的印记施放3次之前，击败死亡使者（10人）。"
D.SharedStrings[7596]="在阵亡勇士的印记施放5次之前，击败死亡使者（25人）。"
D.SharedStrings[7597]="在阿什兰的事件地点击败敌方阵营，并在其基地内击杀对方首领。"
D.SharedStrings[7598]="在阿佐朗死後，燃燒軍團的元氣大傷，一時之間難以復原。\r\n\r\n你贏得我的尊敬，$n。"
D.SharedStrings[7599]="在阿兰卡峰林的血鬃领地里消灭戈图尔。"
D.SharedStrings[7600]="在阿彻鲁斯中，死亡骑士的移动速度提高{1}%。"
D.SharedStrings[7601]="在阿拉希盆地中死亡"
D.SharedStrings[7602]="在阿拉希盆地中，通过夺回旗帜保卫50次基地。"
D.SharedStrings[7603]="在阿拉希盆地战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。"
D.SharedStrings[7604]="在阿拉希盆地战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。"
D.SharedStrings[7605]="在阿拉希盆地资源落后500点的情况下反超并获胜。"
D.SharedStrings[7606]="在阿拉希高地上散布着4块禁锢之石，这些石头将我牢牢地钉在地下。$B$B要想解除它们，你就必须解除最坚固的那块：内禁锢之石。首先，你必须搜集到其它三块石头的钥匙。$B$B这些石头都有守护者在看守，但是如果你足够聪明或者足够幸运的话，就能找到消灭这些守卫的办法。"
D.SharedStrings[7607]="在阿格拉玛的宝库附近与哈维谈一谈。"
D.SharedStrings[7608]="在阿苏纳的伊利达雷哨所饮下后可以开始追踪宝藏。"
D.SharedStrings[7609]="在阿苏纳的某个地方，肯定会有人知道有关创世之柱的消息。"
D.SharedStrings[7610]="在阿苏纳的蓝翼栖地与大法师卡雷见面。"
D.SharedStrings[7611]="在阿苏纳钓鱼时，可能会吸引稀有鱼类。"
D.SharedStrings[7612]="在阿鲁纳西北方的十字路口处与塑晶者巴伦姆交谈。"
D.SharedStrings[7613]="在附近一个位置召唤科斯拉佐的渗透之眼。"
D.SharedStrings[7614]="在附近一个玩家脚下召唤火焰喷射，在3秒后喷发火焰，造成{1}点火焰伤害。"
D.SharedStrings[7615]="在附近一个目标脚下召唤火焰喷射，在3秒后喷发火焰，造成{1} 点火焰伤害。"
D.SharedStrings[7616]="在附近一个目标脚下召唤火焰喷射，在3秒后喷发火焰，造成{1}点火焰伤害。"
D.SharedStrings[7617]="在附近一名玩家附近召唤闪电，3秒后造成{1}点自然伤害。"
D.SharedStrings[7618]="在附近位置召唤3颗爆裂宝珠。"
D.SharedStrings[7619]="在附近制造施法者的数个镜像，使其施放法术并攻击敌方目标。"
D.SharedStrings[7620]="在附近召唤{1}个会在原地旋转的奥术哨兵。哨兵的射线会对触碰到的玩家造成奥术伤害。"
D.SharedStrings[7621]="在附近形成风暴雷云，每秒造成一次自然伤害，持续15秒。"
D.SharedStrings[7622]="在附近敌人脚下召唤出熔岩喷注。"
D.SharedStrings[7623]="在附魔研究室开始你的第一份附魔订单，并收集产品。"
D.SharedStrings[7624]="在降落到涌泉海滩后的30秒内击杀一名敌人。"
D.SharedStrings[7625]="在随机一名敌人的位置召唤眼球炸弹，稍后爆炸。"
D.SharedStrings[7626]="在雪球中畅游。"
D.SharedStrings[7627]="在雪落墓地放置信号灯，不要让它受到攻击！"
D.SharedStrings[7628]="在雷神岛上消灭锻造大师，然后从魔古看门人身上找到一块法典碎片。"
D.SharedStrings[7629]="在雷神岛时声望值奖励提高{1}%。"
D.SharedStrings[7630]="在雷神岛的各个位置使用山泽仪式石举行闪电仪式、灵魂仪式和原始仪式，然后击败被召唤出的强大对手。"
D.SharedStrings[7631]="在雷耶克的剑上涂抹蓝玉虫巢巨蜂、硬皮冲锋者或雾语氏族的成员的血。"
D.SharedStrings[7632]="在雷霆图腾与梅拉·高岭谈一谈。"
D.SharedStrings[7633]="在雷霆图腾南边的峭壁与灵魂行者黑角见面。"
D.SharedStrings[7634]="在雷霆崖阵营中达到崇拜声望，并获得在银色锦标赛中代表雷霆崖出战的资格。"
D.SharedStrings[7635]="在雾纱栈道的迷雾酒肆二楼与拉希奥会面。"
D.SharedStrings[7636]="在雾纱栈道的迷雾酒肆找到拉希奥。"
D.SharedStrings[7637]="在震地峡谷里找到灵魂熔炉，并重铸古特里克的杀生刀。"
D.SharedStrings[7638]="在霍迪尔打碎他的珍贵宝箱之前击败他（10人）。"
D.SharedStrings[7639]="在霍迪尔打碎他的珍贵宝箱之前击败他（25人）。"
D.SharedStrings[7640]="在霜之哀伤洞穴深处激活瑟里格的占卜宝珠。"
D.SharedStrings[7641]="在霜火岭的肃霜丘陵附近加入乌鲁卡格。"
D.SharedStrings[7642]="在霜狼兽人氏族的帮助下，部落正前往刀塔堡垒。"
D.SharedStrings[7643]="在非战斗状态下，恢复精灵对你进行持续治疗，并使法力回复提高。"
D.SharedStrings[7644]="在靠近教派祭坛的位置阅读传送门仪式咒语。"
D.SharedStrings[7645]="在风暴之眼中死亡"
D.SharedStrings[7646]="在风暴之眼中，杀死一名获得了狂暴增效的玩家。"
D.SharedStrings[7647]="在风暴之眼战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。"
D.SharedStrings[7648]="在风暴之眼战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。"
D.SharedStrings[7649]="在风暴之眼的战斗中，携带狂暴效果并杀死一名敌人。"
D.SharedStrings[7650]="在风暴峡湾钓鱼时，可能会吸引稀有鱼类。"
D.SharedStrings[7651]="在风暴烈酒酿造厂中挥舞锤子并一次性击杀100只兔妖（英雄难度）。"
D.SharedStrings[7652]="在风暴烈酒酿造厂中让乌克乌克被20个滚动的酒桶击中后再将其击败（英雄难度）。"
D.SharedStrings[7653]="在风暴要塞：生态船、能源舰和禁魔监狱中，通过杀死怪物获得的沙塔尔声望提高{1}%。伤害和治疗效果提高{2}%。"
D.SharedStrings[7654]="在风神王座中击败奥拉基尔（英雄难度）。"
D.SharedStrings[7655]="在风神王座中击败风之议会（英雄难度）。"
D.SharedStrings[7656]="在风神王座中，于团队所有成员都受到至少7层严寒之风效果影响时，击败风神议会。"
D.SharedStrings[7657]="在风神王座中，于奥拉基尔受到回馈效果影响的情况下将其击败。"
D.SharedStrings[7658]="在风险投资公司研究基地里找到控制台。"
D.SharedStrings[7659]="在风险海湾被感染的地精身上测试一下血清。"
D.SharedStrings[7660]="在风鳞洞穴中从任何来源受到闪电伤害都会为发报机充能。"
D.SharedStrings[7661]="在骆驼背上击败起源大厅中的地怒者塔赫（英雄难度）。"
D.SharedStrings[7662]="在高岭部族中的声望提高{1}点，最高可达到崇拜。"
D.SharedStrings[7663]="在高贾拉的命令下，这些潜行单位将从随机目标身后的阴影中现身，疯狂背刺。任何在其攻击范围内的玩家都会受到大量物理伤害。"
D.SharedStrings[7664]="在魔兽世界七周年庆典期间登录游戏。"
D.SharedStrings[7665]="在魔兽世界九周年庆典期间登录游戏。"
D.SharedStrings[7666]="在魔兽世界五周年庆典期间登录游戏。"
D.SharedStrings[7667]="在魔兽世界八周年庆典期间登录游戏。"
D.SharedStrings[7668]="在魔兽世界六周年庆典期间登录游戏。"
D.SharedStrings[7669]="在魔兽世界十一周年庆典期间登录游戏。"
D.SharedStrings[7670]="在魔兽世界十三周年庆典期间登录游戏。"
D.SharedStrings[7671]="在魔兽世界十二周年庆典期间登录游戏。"
D.SharedStrings[7672]="在魔兽世界十周年庆典期间登录游戏。"
D.SharedStrings[7673]="在魔兽世界四周年庆典期间登录游戏。"
D.SharedStrings[7674]="在魔枢的大魔导师泰蕾丝塔两次分身时，相隔5秒之内击杀她的每个分身，然后击败她（英雄难度）。"
D.SharedStrings[7675]="在鲜血竞技场有挑战在等着你。\n\n带上朋友一同前往，证明你的勇士称号是当之无愧的。"
D.SharedStrings[7676]="在麝香爪牧场击败9个伯里尔基抢劫者。"
D.SharedStrings[7677]="在黑潮栖木驾驶着双头飞龙终结者3000型在3分钟内击败10个暗翼幼龙。"
D.SharedStrings[7678]="在黑石塔上层击败督军扎伊拉。"
D.SharedStrings[7679]="在黑石岩窟中击败升腾者领主奥西迪斯。"
D.SharedStrings[7680]="在黑石岩窟中，于卡尔什·断钢累积达到15层过热水银护甲后将其击败（英雄难度）。"
D.SharedStrings[7681]="在黑石岩窟中，于没有任何队伍成员获得4层微光之雾的情况下击败升腾者领主奥西迪斯（英雄难度）。"
D.SharedStrings[7682]="在黑石岩窟中，允许柯尔拉的3个狂热者进化，并在消灭进化的狂热者后将柯尔拉击败（英雄难度）。"
D.SharedStrings[7683]="在黑石岩窟中，让摧骨者罗姆欧格用碎颅技能杀死10个愤怒之土元素，然后将他击败（英雄难度）。"
D.SharedStrings[7684]="在黑石深渊杀死6名火焰驱逐者，并从西区兵营的怒炉将军身上缴获将军的进攻计划书。"
D.SharedStrings[7685]="在黑石矿坑使用钢铁军用发射器，让自己在3分钟内飞过4个环。"
D.SharedStrings[7686]="在黑石铸造厂中，让兽王达玛克首先骑上下列所有野兽之后将其击败（普通或更高难度）："
D.SharedStrings[7687]="在黑翼血环中击败全能金刚防御系统（英雄难度）。"
D.SharedStrings[7688]="在黑翼血环中击败全能金刚防御系统，并不会被下列攻击击中。"
D.SharedStrings[7689]="在黑翼血环中击败奇美隆（英雄难度）。"
D.SharedStrings[7690]="在黑翼血环中击败奇美隆，并最多只有2名团队成员在战斗中倒下。"
D.SharedStrings[7691]="在黑翼血环中击败奈法利安（英雄难度）。"
D.SharedStrings[7692]="在黑翼血环中击败熔喉（英雄难度）。"
D.SharedStrings[7693]="在黑翼血环中击败艾卓曼德斯（英雄难度）。"
D.SharedStrings[7694]="在黑翼血环中击败艾卓曼德斯，并保证没有任何团队成员的音量高过50%。"
D.SharedStrings[7695]="在黑翼血环中击败马洛拉克（英雄难度）。"
D.SharedStrings[7696]="在黑翼血环中，于团队任何成员受到寄生虫感染前，击败熔喉。"
D.SharedStrings[7697]="在黑翼血环中，于奈法利安生命值低于50%的情况下开始最终阶段的战斗，并将其击败。"
D.SharedStrings[7698]="在黑翼血环对马洛拉克的战斗中，于10秒内消灭12个畸变怪，然后将马洛拉克击败。"
D.SharedStrings[7699]="在黑色裂口寻找暮光之眼。"
D.SharedStrings[7700]="在黑铁矮人进攻时保卫美酒节营地，并完成任务“那次，我喝醉了之后……”。"
D.SharedStrings[7701]="在龙骨荒野的龙眠神殿寻找阿莱克丝塔萨，生命的缚誓者。"
D.SharedStrings[7702]="地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。$b$b锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。"
D.SharedStrings[7703]="地下城世界事件 - 汉摩尔"
D.SharedStrings[7704]="地下城建筑师的地图加快你的移动速度。\r\n\r\n只有当你处于起源大厅的时候才会生效。"
D.SharedStrings[7705]="地下城管理者"
D.SharedStrings[7706]="地下城训练假人"
D.SharedStrings[7707]="地下墓穴？我从没听说过这种地方。难道他指的是那里……\n\n河流边上有一扇下水道格栅，它可以通向卡拉赞的地下墓穴。我以前从没留意过它，不过那里可能就是幽灵所说的地方。\n\n想一想，黑暗骑士可能一直都在我们眼皮子底下！走吧，我们去看看里面会有什么。"
D.SharedStrings[7708]="地平线吹来的风轻拂着你，脚下的大地是如此坚实，火焰温暖了你的灵魂，而现在我想让你体味水的纯洁。$B$B你已经达到了一定的境界，你的精神将赐予你走得更远的力量。不过，你先得迈出至关重要的第一步。"
D.SharedStrings[7709]="地底之王达古尔"
D.SharedStrings[7710]="地狱咆哮的先锋战士"
D.SharedStrings[7711]="地狱咆哮的勇士"
D.SharedStrings[7712]="地狱咆哮的战弓"
D.SharedStrings[7713]="地狱咆哮的战歌使你倍受鼓舞，你的生命总值、治疗效果、伤害吸收和伤害效果提高{1}%。"
D.SharedStrings[7714]="地狱咆哮的铁军先锋部队设法抵达了黑石山，并与龙喉氏族的督军扎伊拉结盟了。眼下，钢铁部落正在准备入侵艾泽拉斯，而扎伊拉则在黑石山的腹地组装一架灭世武器，要将所有挡路者尽数消灭。$B$B你必须彻底粉碎扎伊拉的阴谋，指挥官。她已经威胁我们太久了。"
D.SharedStrings[7715]="地狱咆哮近卫军"
D.SharedStrings[7716]="地狱咆哮近卫军战旗"
D.SharedStrings[7717]="地狱火"
D.SharedStrings[7718]="地狱火入侵者"
D.SharedStrings[7719]="地狱火半岛的工事"
D.SharedStrings[7720]="地狱火堡垒"
D.SharedStrings[7721]="地狱火堡垒与我们的军队一直有着小规模的冲突与交战。目前，我们自己的领地大多守备稳固，但一直没能对他们发动真正的进攻。为了筹备进攻，我们要首先占领地狱火堡垒外围的战略要地。$B$B我们的斥候目前确定了三处互成犄角之势的工事，希望你能协助这三处的防守。占领所有工事之后回来向我报告。$B$B愿你能在接下来的战斗中有好运气，$n，毫无疑问，你得面对部落的威胁，他们也同样想占领这三处重要的工事。"
D.SharedStrings[7722]="地狱火堡垒的轮廓被刻在这个模具的背面。"
D.SharedStrings[7723]="地狱火末日使者"
D.SharedStrings[7724]="地狱火着陆的冲击力对附近的敌人造成伤害，并将其击退。"
D.SharedStrings[7725]="地狱犬"
D.SharedStrings[7726]="地狱猎犬"
D.SharedStrings[7727]="地穴追猎者护手"
D.SharedStrings[7728]="地窟守护者"
D.SharedStrings[7729]="地精三轮摩托"
D.SharedStrings[7730]="地精三轮摩托涡轮增压型"
D.SharedStrings[7731]="地精小队"
D.SharedStrings[7732]="地精工程学"
D.SharedStrings[7733]="地精工程学训练师"
D.SharedStrings[7734]="地精工程师"
D.SharedStrings[7735]="地精挖掘者"
D.SharedStrings[7736]="地精火箭背包"
D.SharedStrings[7737]="地精袖珍核弹"
D.SharedStrings[7738]="地精轰炸机"
D.SharedStrings[7739]="地质学家拉克斯班的研究对于我们在希利苏斯的行动很有帮助，她最近需要一些特别的材料，以进行更多的研究。$B$B请收集这些材料，把它们交给拉克斯班。"
D.SharedStrings[7740]="地面上一座活火山突然爆发，对所有邻近敌人造成火焰伤害。"
D.SharedStrings[7741]="地面移动速度提高60%。只能在暗月马戏团、暗月小径和暗月滨海步道骑乘。"
D.SharedStrings[7742]="地面移动速度提高{1}%。"
D.SharedStrings[7743]="地龙特攻队"
D.SharedStrings[7744]="场景战役大满贯"
D.SharedStrings[7745]="场景的持续时间延长{1}秒。"
D.SharedStrings[7746]="坍塌的暮光传送门能够让你离开暮光领域。"
D.SharedStrings[7747]="坎雷萨德·埃伯洛克"
D.SharedStrings[7748]="坎雷萨德·埃伯洛克有几率出现，对附近的所有敌人造成大量伤害。"
D.SharedStrings[7749]="坏松鼠5000型"
D.SharedStrings[7750]="坐骑速度提高{1}%。"
D.SharedStrings[7751]="坐骑速度提高{1}%。对70级以上的玩家不起作用。"
D.SharedStrings[7752]="坚定的范克里夫复仇者"
D.SharedStrings[7753]="坚定的裁决"
D.SharedStrings[7754]="坚定者特尔拉斯"
D.SharedStrings[7755]="坚强的利戈拉"
D.SharedStrings[7756]="坚硬的纳迦鳞片"
D.SharedStrings[7757]="坚韧的丝束包裹住不幸的人。"
D.SharedStrings[7758]="坠月守卫"
D.SharedStrings[7759]="坠落的残骸造成物理伤害，并将目标从撞击点击退。"
D.SharedStrings[7760]="坠落速度减缓。"
D.SharedStrings[7761]="坠落速度降低。"
D.SharedStrings[7762]="垂涎的嗜血者"
D.SharedStrings[7763]="埃克顿·布拉斯塔"
D.SharedStrings[7764]="埃利奥特·范·鲁克"
D.SharedStrings[7765]="埃匹希斯卫士"
D.SharedStrings[7766]="埃匹希斯卫士制造于失落的鸦人文明时代，他们是坚不可摧的构造体，被完好无损地保存在古老密室内。"
D.SharedStrings[7767]="埃匹希斯宝石切割机"
D.SharedStrings[7768]="埃匹希斯水晶"
D.SharedStrings[7769]="埃希拉·黎明克星"
D.SharedStrings[7770]="埃希拉施展出眼花缭乱的武器技艺。受到的所有低于{1}点的伤害都降至1点。当施法者受到的伤害超过这一上限时，效果结束。"
D.SharedStrings[7771]="埃提耶什，守护者的传说之杖"
D.SharedStrings[7772]="埃提耶什，被玷污的传说之杖"
D.SharedStrings[7773]="埃斯图兰的学徒"
D.SharedStrings[7774]="埃林·提亚斯"
D.SharedStrings[7775]="埃沃隆的解药"
D.SharedStrings[7776]="埃洛杜斯将军"
D.SharedStrings[7777]="埃洛瑟尔信徒"
D.SharedStrings[7778]="埃洛瑟尔助祭"
D.SharedStrings[7779]="埃洛瑟尔居住在古老的萨斯塔拉林地，他在那里与自然进行交流，并将治疗之术与知识的传承教导给他的信徒。$b$b去找到他，并告诉他这里非常需要他的帮助。"
D.SharedStrings[7780]="埃索达守备官"
D.SharedStrings[7781]="埃索达平民"
D.SharedStrings[7782]="埃蕾希·晨歌"
D.SharedStrings[7783]="埃辛诺斯之焰"
D.SharedStrings[7784]="埃辛诺斯壁垒"
D.SharedStrings[7785]="埃辛诺斯战刃"
D.SharedStrings[7786]="埃辛诺斯的灰烬"
D.SharedStrings[7787]="埃达尔拉"
D.SharedStrings[7788]="埃达尔拉的骆驼"
D.SharedStrings[7789]="埃里克·戴维森"
D.SharedStrings[7790]="埃隆巴克保护者"
D.SharedStrings[7791]="埃雷萨拉斯皇家徽记"
D.SharedStrings[7792]="埃霍恩的冰霜之镰"
D.SharedStrings[7793]="埃鲁纳克的限制图腾"
D.SharedStrings[7794]="城市到處流傳著非常有趣的八卦，$n。勝利就在眼前了。"
D.SharedStrings[7795]="基姆兹·宾奇维斯"
D.SharedStrings[7796]="基姆兹也许很无礼且毒舌，但对她的朋友和家人绝对忠诚。"
D.SharedStrings[7797]="基姆兹的改装车"
D.SharedStrings[7798]="基尔加丹"
D.SharedStrings[7799]="基尔加丹切断玩家的灵魂，生成他们的复制品。"
D.SharedStrings[7800]="基尔罗格·死眼"
D.SharedStrings[7801]="基尔罗格·死眼（史诗难度）"
D.SharedStrings[7802]="基尔罗格之眼"
