D.SharedStrings[7806]="基础攻击"
D.SharedStrings[7807]="基础教程：攻击目标"
D.SharedStrings[7808]="基础移动速度无法提升。你受到的伤害提高35%。无法潜行和隐形。"
D.SharedStrings[7809]="基维·Q·匹德菲特"
D.SharedStrings[7810]="基鲁鼓舞着你，耐力提高{1}点，智力提高{2}点。"
D.SharedStrings[7811]="堂弟兔子脚"
D.SharedStrings[7812]="堕夜精灵徽章"
