D.SharedStrings[7823]="堕落者之火"
D.SharedStrings[7824]="堕落者之颅"
D.SharedStrings[7825]="堕落者瑞萨扎尔"
D.SharedStrings[7826]="堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的!$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N - 你要面对的绝非一般的敌人。"
D.SharedStrings[7827]="堕落苦难胸甲"
D.SharedStrings[7828]="堕落议会护手"
D.SharedStrings[7829]="堡垒外的战斗"
