D.SharedStrings[7842]="塔兹利尔的镐"
D.SharedStrings[7843]="塔卡里的巫毒酒蕴含着你不想去了解的魔法力量。"
D.SharedStrings[7844]="塔尔伦·海毕肯"
D.SharedStrings[7845]="塔布羊训练：兽人猎手"
