D.SharedStrings[7855]="塔拉迪特精通水晶"
D.SharedStrings[7856]="塔拉迪特耐力水晶"
D.SharedStrings[7857]="塔纳利斯时光之穴的阿纳克洛斯要你前往斯坦索姆，在神圣之地上使用埃提耶什，守护者的传说之杖。击败被驱赶出法杖的生物，然后回到阿纳克洛斯那里去。"
D.SharedStrings[7858]="塔纳安外交家"
D.SharedStrings[7859]="塔胡·慧风"
D.SharedStrings[7860]="塔诺恩·红羽"
D.SharedStrings[7861]="塔达拉姆王子"
D.SharedStrings[7862]="塔隆·血魔"
D.SharedStrings[7863]="塔隆戈尔"
D.SharedStrings[7864]="塔雷斯要求你使用魔导师平台内的阳台上的宝珠。"
D.SharedStrings[7865]="塞伦娜派你来的？太好了……她还活着。"
D.SharedStrings[7866]="塞尔赞的护命匣"
D.SharedStrings[7867]="塞希娅·黎明玫瑰"
