D.SharedStrings[7870]="塞拉赞恩"
D.SharedStrings[7871]="塞拉赞恩的仆从"
D.SharedStrings[7872]="塞林·暗砧"
D.SharedStrings[7873]="塞林·灰月"
D.SharedStrings[7874]="塞林的应急工具"
D.SharedStrings[7875]="塞林的直升机"
D.SharedStrings[7876]="塞林需要这玩意儿让他的直升机飞起来。"
D.SharedStrings[7877]="塞泰克神谕者"
D.SharedStrings[7878]="塞泰的暗影能量向四周发出光束。被光束击中的玩家将每秒受到一次暗影伤害。"
D.SharedStrings[7879]="塞纳留斯"
D.SharedStrings[7880]="塞纳留斯之枝号"
D.SharedStrings[7881]="塞纳留斯在目标位置召唤了一道冰障！"
D.SharedStrings[7882]="塞纳留斯的卫士"
D.SharedStrings[7883]="塞纳留斯的女儿"
D.SharedStrings[7884]="塞纳留斯的树枝"
D.SharedStrings[7885]="塞纳留斯的腐蚀会召唤蠕行梦魇，造成{1}点暗影伤害，并使蠕行梦魇对其的伤害提高{2}%。此效果可叠加。"
D.SharedStrings[7886]="塞纳苟斯"
D.SharedStrings[7887]="塞纳苟斯画像"
D.SharedStrings[7888]="塞纳苟斯的投影"
D.SharedStrings[7889]="塞纳里奥作战角鹰兽"
D.SharedStrings[7890]="塞纳里奥树林出事了？"
D.SharedStrings[7891]="塞纳里奥要塞的卫兵急需磨刀石。去收集足够的磨刀石，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。"
D.SharedStrings[7892]="塞纳里奥角鹰兽宝宝"
D.SharedStrings[7893]="塞纳里奥议会"
D.SharedStrings[7894]="塞纳里奥议会派驻外域的主要远征军组织被称为塞纳里奥远征队。尽管它最早是由塞纳里奥议会直接领导的探险队，但现在已经发展成了一支人数众多、完全独立的军队。$B$B远征队的首领伊谢尔·风歌希望我们能派些自愿者去她的哨站。前往赞加沼泽东部的塞纳里奥庇护所向她报告。沿着西边的大道一直往前走就到了。"
D.SharedStrings[7895]="塞纳里奥远征队"
D.SharedStrings[7896]="塞纳里奥防御者"
D.SharedStrings[7897]="塞西莉亚栖地的火焰领主"
D.SharedStrings[7898]="塞露布拉的暗影使你受到的伤害降低{1}%，移动速度提高{2}%。"
D.SharedStrings[7899]="墓穴中的灵魂被一个可怕的引擎所扭曲。毁掉它，让灵魂从折磨中获得解脱。"
D.SharedStrings[7900]="墓草之花"
D.SharedStrings[7901]="增强哈格拉的能力。"
D.SharedStrings[7902]="墨格瑞拉之头"
D.SharedStrings[7903]="墨格瑞拉的毒牙"
D.SharedStrings[7904]="墨格瑞拉的闪光之眼"
D.SharedStrings[7905]="墨格瑞拉（英雄难度）"
D.SharedStrings[7906]="墨菲斯托斯从扭曲虚空中召唤援军。"
D.SharedStrings[7907]="士兵们，苏醒过来，战斗吧！"
D.SharedStrings[7908]="壮硕的牦牛"
D.SharedStrings[7909]="声纳脉冲已侦测到一名敌人，使盲眼巨龙轻易就能找到他！"
D.SharedStrings[7910]="处于静滞状态。"
D.SharedStrings[7911]="处于静滞状态，免疫伤害。"
D.SharedStrings[7912]="复仇的愤怒卫士"
D.SharedStrings[7913]="复仇的灵魂"
D.SharedStrings[7914]="复仇角斗士的虚空幼龙"
D.SharedStrings[7915]="复制一名敌人的武器，装备在自己身上。"
D.SharedStrings[7916]="复制影像"
D.SharedStrings[7917]="复制敌人的副手武器并挥舞它。"
D.SharedStrings[7918]="复制的奥术畸兽"
D.SharedStrings[7919]="复数打击护腕"
D.SharedStrings[7920]="复活一个死去的盟友，复活后该盟友拥有{1}%的生命值和法力值。无法在战斗中施放。"
D.SharedStrings[7921]="复活的刃豹"
D.SharedStrings[7922]="复活的刃豹幼崽"
D.SharedStrings[7923]="复活的圣殿骑士"
D.SharedStrings[7924]="复活的奥术师"
D.SharedStrings[7925]="复活的托林尼尔幼龙"
D.SharedStrings[7926]="复活的暗影法师"
D.SharedStrings[7927]="复活的食尸鬼"
D.SharedStrings[7928]="复活盟友现在将使其恢复最大生命值和法力值。死亡骑士死去时可以复活本人。"
D.SharedStrings[7929]="复活节兔宝宝"
D.SharedStrings[7930]="复活节，赞美生命和春天的庆典！朋友，我希望你喜欢找彩蛋这项娱乐活动，这样你就可以帮上我的忙了。$b$b我不知道那些德鲁伊在制造彩蛋时到底使用了哪些魔法，他们也不打算给我解释。你在收集彩蛋的时候能不能帮我保留一些蛋壳的碎片？蛋里面的东西你可以自己拿去，那些蛋才是我需要的研究样本。"
D.SharedStrings[7931]="复生的坚骨战士"
D.SharedStrings[7932]="复生的希尔斯布莱德农民"
D.SharedStrings[7933]="复生的白骨"
D.SharedStrings[7934]="复生的达卡莱勇士"
D.SharedStrings[7935]="复生的魔古石像"
D.SharedStrings[7936]="复生：冰霜印记"
D.SharedStrings[7937]="复生：奥术宝珠"
D.SharedStrings[7938]="复生：灼热烙印"
D.SharedStrings[7939]="夏克里尔的攻击会令受害者的肉体变得脆弱，使其更容易受到掠风者克尔鲁克攻击的影响。"
D.SharedStrings[7940]="夏多雷平民"
D.SharedStrings[7941]="夏尔兹·斯莫德普"
D.SharedStrings[7942]="夏斯卡格草丛"
D.SharedStrings[7943]="夏柯希尔之手"
D.SharedStrings[7944]="夏柯希尔女皇的仆从能够操纵恐怖的煞能量。"
D.SharedStrings[7945]="夏柯希尔誓刃者"
D.SharedStrings[7946]="夏琪亚"
D.SharedStrings[7947]="夙涡，落日之杖"
D.SharedStrings[7948]="多亏了塔贝萨派你来找我。我想向她商借一些粮食直到飞艇残骸的问题解决为止，但是我知道当前她也没有多馀的粮食可以援助我。假如你想参与刺激的冒险，可以参考我布告某只凶猛的迅猛龙悬赏令。"
D.SharedStrings[7949]="多尔穆斯最爱的骆驼喷吐目标，使区域内的敌人受到自然伤害。"
D.SharedStrings[7950]="多彩九头蛇兜帽"
D.SharedStrings[7951]="多彩九头蛇手套"
D.SharedStrings[7952]="多彩九头蛇护肩"
D.SharedStrings[7953]="多彩九头蛇护腿"
D.SharedStrings[7954]="多彩九头蛇长袍"
D.SharedStrings[7955]="多彩黎明衬肩"
D.SharedStrings[7956]="多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。"
D.SharedStrings[7957]="多棒的一顿飨宴，嗯?$B$B我很高兴你能和我们一起庆祝旅人丰年祭的精神。"
D.SharedStrings[7958]="多次进入冠军的试炼，在驱散5个不同的昔日回忆后击败银色神官帕尔崔丝（英雄难度）。"
D.SharedStrings[7959]="多汁的鞭笞者"
D.SharedStrings[7960]="多玛塔克斯"
D.SharedStrings[7961]="多萨拉克，折剑者"
D.SharedStrings[7962]="多重射击"
D.SharedStrings[7963]="夜之子反叛者"
D.SharedStrings[7964]="夜之子复国者"
D.SharedStrings[7965]="夜之子所擅长的魔法可不止一种。我们很有可能在暗夜要塞内遭遇强大的敌人。如果我们想要打倒古尔丹，我们就必须先消灭暗夜要塞中强大的法师和战士。"
D.SharedStrings[7966]="夜之子根除者"
D.SharedStrings[7967]="夜之子渗透者"
D.SharedStrings[7968]="夜之子灵魂石"
D.SharedStrings[7969]="夜之子补给品"
D.SharedStrings[7970]="夜刃豹幼崽"
D.SharedStrings[7971]="夜精灵和他们的盟友听到你的名字就会吓得发抖!为部落而战!"
D.SharedStrings[7972]="夜落精靈堅持要參與這場戰鬥。我們的人手應付不了所有的工作。"
D.SharedStrings[7973]="大主教伊瑞尔"
D.SharedStrings[7974]="大主教图拉扬"
D.SharedStrings[7975]="大主教奈丽"
D.SharedStrings[7976]="大主教本尼迪塔斯"
D.SharedStrings[7977]="大主教本尼迪塔斯正在释放暮光之力。"
D.SharedStrings[7978]="大主教玛拉达尔"
D.SharedStrings[7979]="大主教的雷象"
D.SharedStrings[7980]="大主教阿卡玛"
D.SharedStrings[7981]="大地之刺造成{1}点自然伤害，并将敌人抛上空中。"
D.SharedStrings[7982]="大地之怒"
D.SharedStrings[7983]="大地之环"
D.SharedStrings[7984]="大地之环使者"
D.SharedStrings[7985]="大地之环卫兵"
D.SharedStrings[7986]="大地之环地卜师"
D.SharedStrings[7987]="大地之环狮鹫"
D.SharedStrings[7988]="大地之环的一名成员，波涛语者瓦罗伦，已经游到东北边的梦魇深渊里去了。我们有段时间没有收到她的消息了。$B$B游到那边去，看看你能不能找到她。"
D.SharedStrings[7989]="大地之环萨满"
D.SharedStrings[7990]="大地之环防御者"
D.SharedStrings[7991]="大地图腾"
D.SharedStrings[7992]="大地在我们脚下震颤，指挥官。我们的斥候还没回来复命。我能感觉到一场攻击迫在眉睫，可是敌人会从哪里袭来呢？"
D.SharedStrings[7993]="大地守护者之鳞"
D.SharedStrings[7994]="大地封印就在这儿，三个凹陷的壁龛分别对应着紫水晶符石、蛋白符石和星钻符石。"
D.SharedStrings[7995]="大地治愈者诺莎拉"
D.SharedStrings[7996]="大地治愈者达鲁"
D.SharedStrings[7997]="大地的力量包围着你，造成的伤害提高{1}%。"
D.SharedStrings[7998]="大地的召唤"
D.SharedStrings[7999]="大地的碎片从埃鲁纳克之手中迸出，对附近的敌人造成大量伤害。"
D.SharedStrings[8000]="大地观察者萨满祭司"
D.SharedStrings[8001]="大地迸发出邪火，召唤一个烈火生物并造成火焰伤害。"
D.SharedStrings[8002]="大地震击"
D.SharedStrings[8003]="大地震颤"
D.SharedStrings[8004]="大型什锦汤面餐车"
D.SharedStrings[8005]="大型侵入点：主母芙努娜"
D.SharedStrings[8006]="大型侵入点：奥库拉鲁斯"
D.SharedStrings[8007]="大型侵入点：妖女奥露拉黛儿"
D.SharedStrings[8008]="大型侵入点：审判官梅托"
D.SharedStrings[8009]="大型侵入点：深渊领主维尔姆斯"
D.SharedStrings[8010]="大型侵入点：索塔纳索尔"
