D.SharedStrings[8014]="大型熊猫人八宝汤面餐车"
D.SharedStrings[8015]="大型爆盐炸弹"
D.SharedStrings[8016]="大型白色科多兽"
D.SharedStrings[8017]="大型美酒节科多兽"
D.SharedStrings[8018]="大型裂隙守护者"
D.SharedStrings[8019]="大型金色科多兽"
D.SharedStrings[8020]="大型防御构装体"
D.SharedStrings[8021]="大女皇夏柯希尔"
D.SharedStrings[8022]="大女皇夏柯希尔（英雄难度）"
D.SharedStrings[8023]="大妖术师奥霍多"
D.SharedStrings[8024]="大守备官索沃斯"
D.SharedStrings[8025]="大宰相的红玉玺戒"
D.SharedStrings[8026]="大家总有一天会学到教训。活要见人，死要见尸，否则绝不能断定你的敌人已经死了。<洛休斯咧嘴一笑。>"
D.SharedStrings[8027]="大家都听着！大家都听着！所有的英雄都应该聆听这号召的声音！$B$B暴风城已经发出了备战的号召！所有勇士都应该拿起武器，一同面对来自东部王国北部地区亡灵天灾的威胁！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，联盟的安全岌岌可危！$B$B联盟的英雄们——去向指挥官阿什拉姆·瓦罗菲斯特报到吧，他的大本营就在奥特兰克山脉北边的冰风岗！"
D.SharedStrings[8028]="大工匠梅卡托克"
D.SharedStrings[8029]="大工匠梅卡托克正在远方通过该装置进行广播。"
D.SharedStrings[8030]="大工匠，侏儒之王"
D.SharedStrings[8031]="大布道者艾娜拉"
D.SharedStrings[8032]="大师级渔夫"
D.SharedStrings[8033]="大师级考古学"
D.SharedStrings[8034]="大师级遗物猎人"
D.SharedStrings[8035]="大幅度减少制造凡图斯符文：古尔丹所需要的材料。"
D.SharedStrings[8036]="大幅度提高玩家的经验值。"
D.SharedStrings[8037]="大德鲁伊哈缪尔·符文图腾"
D.SharedStrings[8038]="大德鲁伊格兰达里斯"
D.SharedStrings[8039]="大德鲁伊范达尔·鹿盔"
D.SharedStrings[8040]="大打出手（第1赛季）"
D.SharedStrings[8041]="大技师罗姆尔"
D.SharedStrings[8042]="大技师罗姆尔的影像"
D.SharedStrings[8043]="大星术师索兰莉安"
D.SharedStrings[8044]="大机械师瑟玛普拉格"
D.SharedStrings[8045]="大检察官怀特迈恩"
D.SharedStrings[8046]="大检察官法尔班克斯"
D.SharedStrings[8047]="大法师克希雷姆"
D.SharedStrings[8048]="大法师克希雷姆的影像"
D.SharedStrings[8049]="大法师克萨伦"
D.SharedStrings[8050]="大法师兰达洛克"
D.SharedStrings[8051]="大法师卡德加"
D.SharedStrings[8052]="大法师卡德加制造的三大狂野指环之一。"
D.SharedStrings[8053]="大法师卡德加已经制定了对抗暗影议会的下一步行动计划。到他的法师塔和他会面吧，就在塔拉多东边的赞加拉沼泽里。"
D.SharedStrings[8054]="大法师卡德加已经制定了对抗暗影议会的下一步行动计划，他需要你的帮助。"
D.SharedStrings[8055]="大法师卡德加已经计划好了对暗影议会展开下一步行动。到他的法师塔和他会面吧，就在塔拉多东边的赞加拉沼泽里。$b$b应该不会花费你太长时间的。"
D.SharedStrings[8056]="大法师卡德加的影像"
D.SharedStrings[8057]="大法师卡德加，二次大战的英雄，正在召集艾泽拉斯最强大的勇士们组成联军，共同突入黑暗之门。"
D.SharedStrings[8058]="大法师卡莱"
D.SharedStrings[8059]="大法师卡雷"
D.SharedStrings[8060]="大法师埃兰希尔·星歌"
D.SharedStrings[8061]="大法师埃兰德拉"
D.SharedStrings[8062]="大法师塞琳德拉"
D.SharedStrings[8063]="大法师奥图鲁斯"
D.SharedStrings[8064]="大法师安吉拉·杜萨图斯"
D.SharedStrings[8065]="大法师安斯雷姆·鲁因"
D.SharedStrings[8066]="大法师欧妮娅拉"
D.SharedStrings[8067]="大法师沃迪恩·伍德格莱尔"
D.SharedStrings[8068]="大法师瓦格斯"
D.SharedStrings[8069]="大法师瓦格斯派其影像回到过去协助你，并研究德拉诺的历史。"
D.SharedStrings[8070]="大法师瓦格斯的影像"
D.SharedStrings[8071]="大法师瓦格斯的法杖"
D.SharedStrings[8072]="大法师索尔"
D.SharedStrings[8073]="大法师罗曼斯"
D.SharedStrings[8074]="大法师艾萨斯·夺日者"
D.SharedStrings[8075]="大法师范尔希·古德宾格"
D.SharedStrings[8076]="大法师茉德拉"
D.SharedStrings[8077]="大法师阿塔瑞克"
D.SharedStrings[8078]="大海的庇佑，一去不返"
D.SharedStrings[8079]="大督军霍恩·重拳一直在寻找愿意采用自杀式攻击方法对付燃烧军团的人。你一定有勇气去接受其中一个任务。$B$B当你准备好流血牺牲的时候去跟他谈一谈。他正在那边庆祝干掉了一台魔能机甲。他和他的护卫队几个小时前摧毁了那台魔能机甲，要不是他的凶猛和战斗技巧，我们可能都死在这里了。"
D.SharedStrings[8080]="大肆碾压，对施法者面前的所有敌人造成物理伤害。"
D.SharedStrings[8081]="大胆的科尔塔"
D.SharedStrings[8082]="大药剂师普特雷斯"
D.SharedStrings[8083]="大药剂师普特雷斯要求你将双天灾脑质交给奥格瑞玛的药剂师卡尔洛夫。"
D.SharedStrings[8084]="大部分我能看懂，足以明白主要写的什么了。且不论谁下的命令——他夸奖了卢埃加的“成果”并且鼓励他继续审讯他的”客人“。$B$B同时，它写道，“斯克提斯已按计划正在部署中。”"
D.SharedStrings[8085]="大酋长"
D.SharedStrings[8086]="大酋长的命令：希尔斯布莱德丘陵！"
D.SharedStrings[8087]="大酋长的命令：纳格兰！"
D.SharedStrings[8088]="大酋长的命令：阿拉希高地！"
D.SharedStrings[8089]="大领主亚历山德罗斯·莫格莱尼"
D.SharedStrings[8090]="大领主提里奥·弗丁"
D.SharedStrings[8091]="大领主的指令"
D.SharedStrings[8092]="大领主达里安·莫格莱尼"
D.SharedStrings[8093]="大魔导师泰蕾丝塔"
D.SharedStrings[8094]="大魔导师泽瑞尔"
D.SharedStrings[8095]="大魔导师艾利桑德"
D.SharedStrings[8096]="大魔导师艾利桑德使用暗夜井的力量塑造时间。她在生命值低到濒临死亡时会回溯时间，让玩家回到刚开始与她交战的时间点。战斗从这个时间点重新开始，但是艾利桑德会在她过去的回响中混入新的技能。她可以回溯两次时间，之后就连时间也无法拯救她了。"
D.SharedStrings[8097]="大魔导师薇莉瑟拉"
D.SharedStrings[8098]="天呐！激光、磁体和钻头！"
D.SharedStrings[8099]="天堂，在他们数不尽的星星中有着世间神秘事物的答案，$N。强大，有智慧，幸运的人，能够仰望天空找到答案?"
D.SharedStrings[8100]="天堂，在他们数不尽的星星中有着世间神秘事物的答案，$N。强大，有智慧，幸运的人，能够抬头仰望天空找到答案?"
D.SharedStrings[8101]="天定亡者勇士"
D.SharedStrings[8102]="天怒预言者苏克拉底"
D.SharedStrings[8103]="天海游荡者"
D.SharedStrings[8104]="天火号士兵"
D.SharedStrings[8105]="天火号旋翼机"
D.SharedStrings[8106]="天火号旋翼机飞行员"
D.SharedStrings[8107]="天火号狮鹫骑士"
D.SharedStrings[8108]="天火号甲板炮"
D.SharedStrings[8109]="天灾僵尸"
D.SharedStrings[8110]="天灾军团的瘟疫大锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅领主并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。"
D.SharedStrings[8111]="天灾领主泰兰努斯"
D.SharedStrings[8112]="天然的排泄物，凑巧砸向了某个不幸的兽人。"
D.SharedStrings[8113]="天界河马幼崽"
D.SharedStrings[8114]="天神比武大会"
D.SharedStrings[8115]="天禅院弟子将就位，并向入侵的野牛人施放超级真气冲击，对她面前的敌人造成{1}点火焰伤害。"
D.SharedStrings[8116]="天空卫士卡提要你用牧绳捕捉5只以太鳐。"
D.SharedStrings[8117]="天罚使者奈兹玛"
D.SharedStrings[8118]="天舞者之靴"
D.SharedStrings[8119]="天角拦截者"
D.SharedStrings[8120]="天角酋长"
D.SharedStrings[8121]="天铸之锤的近战攻击可造成{1}点自然伤害。"
D.SharedStrings[8122]="太好了!你对银色黎明做出的贡献必将永载史册，$N。你完成了我的要求，现在我很高兴能为你提供我们的披肩。只要你一直保持在银色黎明中的声望，你就可以从任何银色黎明军需官那里购买到这些披肩。$B$B我的$g兄弟:姐妹;，为了银色黎明而战!"
D.SharedStrings[8123]="太好了!如果那些营火真的如你们所说的那样炽热的燃烧着，看来我们今年指派的火焰管理器都很尽责。谢谢你帮我去调查;来，收下这个做为我一点小意思。"
D.SharedStrings[8124]="太好了!我们感谢你慷慨的捐赠，$N!"
D.SharedStrings[8125]="太好了!收下这个。我用你取得的物品准备了这个包裹。它们会让你召唤泰洛克。$B$B小心，$N。他是世界上最强大的阿拉卡。别小看他!"
D.SharedStrings[8126]="太好了。我該把這些熔掉並鑄成錠，供下一批委託用。"
D.SharedStrings[8127]="太好了。有了這個，把你們所有人傳送到海底的機率就會大大降低！"
D.SharedStrings[8128]="太好了！这正是我上周钓鱼时弄丢的图纸。这些图纸与我的原型设备完全对应。拿上这个高能炉，把它安装在我们的其中一艘舰船上。这可以让我们突破海上封锁，扩大我们的德拉诺海域的控制范围。"
D.SharedStrings[8129]="太好了，你终于回家了，$N。每当泰兰德和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?艾露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。"
D.SharedStrings[8130]="太好了，你终于回来了!嗯嗯，你发现了什么?他们是谁?"
D.SharedStrings[8131]="太好了，太好了!这些绝对能派上大用场―只要经过适当的工艺处理，它们就会变得更加厚实。$B$B再次感谢你的帮助，$N。拿着这个―这是我的最新产品。"
D.SharedStrings[8132]="太好了，太好了，谢谢你!我大概会需要更多的样本才能得到最终的结果，但你今天已经做得够好了。"
D.SharedStrings[8133]="太好了，有新的成员响应号召，加入对抗异种虫类的军队。欢迎来到塞纳里奥城堡，$C。我很高兴看到我们的特使能说服你发挥才干。在这里你会发现有很多帮助我们的机会，我也希望你能快点证明自己对我们的事业是很有价值的。"
D.SharedStrings[8134]="太好了，那個老糊塗總算得到報應了。\r\n\r\n看來漫步宏園現在需要一名新的珠寶匠，而我覺得我已經學會前任師傅的所有知識了。\r\n\r\n這是體恤你的辛勞的一點小心意。"
D.SharedStrings[8135]="太有趣了!做的好，$N!这是你的糖果。$B$B万鬼节快乐!"
D.SharedStrings[8136]="太棒了!你在战歌峡谷保卫战中表现很出色!愿你的英雄事迹在我们的土地上流传开来。"
D.SharedStrings[8137]="太棒了!现在我只希望，能看到达拉然破坏者队赢球!"
D.SharedStrings[8138]="太棒了!这将能协助我们的部队对抗严寒。"
D.SharedStrings[8139]="太棒了!这样就可以让凯尔萨斯知道不要低估我们的力量。"
D.SharedStrings[8140]="太棒了!那就来交易吧。要能和这件护甲搭配，还真不是件容易的事。可是我怕我马上就用不到这件了。$B$B若你还想帮我忙，我就再给你其它装备。"
D.SharedStrings[8141]="太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!"
D.SharedStrings[8142]="太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。"
D.SharedStrings[8143]="太美了！我从没见过这么美的东西！$B$B是的，是的，我确定，把它扔到喷泉里吧。圣光在上，人们总是把各种垃圾扔到里面。$B$B<珍珠现在更加明亮了，它移动到了水面上方。>"
D.SharedStrings[8144]="太阳之井 - 奎尔萨拉斯的陷落"
D.SharedStrings[8145]="太阳之井高地"
D.SharedStrings[8146]="太阳之核爆炸，自毁并击退所有附近的敌人。"
D.SharedStrings[8147]="失敗，拒絕。從那一天起，伊利丹就被這兩種心魔糾纏。但他依然無所畏懼，持續尋找自己的宿命，他找到了另一條道路。"
