D.SharedStrings[8171]="夺取风暴之眼旗帜"
D.SharedStrings[8172]="夺回拉尔戈的瞭望台"
D.SharedStrings[8173]="夺回海加尔山的戈德林圣殿，然后向伊安·杜兰复命。"
D.SharedStrings[8174]="夺心者卡什"
