D.SharedStrings[8182]="夺日者龙鹰"
D.SharedStrings[8183]="夺目的红羽雀"
D.SharedStrings[8184]="夺走他们的一切"
D.SharedStrings[8185]="奇娅娜·月影"
D.SharedStrings[8186]="奇怪的发动机零件"
D.SharedStrings[8187]="奇怪的美酒"
D.SharedStrings[8188]="奇怪，黑騎兵竟然沒跟過來。不過沒關係，這是一件好事。\r\n\r\n我相信找到黑騎兵的關鍵就在這附近。讓我們開始搜索吧。"
D.SharedStrings[8189]="奇拉·艾索尔"
D.SharedStrings[8190]="奇美隆的下次攻击将会连续打击两次。"
D.SharedStrings[8191]="奇袭地狱火"
D.SharedStrings[8192]="奇袭地狱火（史诗难度）"
D.SharedStrings[8193]="奈丝伍德夫人"
D.SharedStrings[8194]="奈古拉什总是一副随时准备把一切都吞下去充饥的样子。$B$B那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其他巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！$B$B如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！"
D.SharedStrings[8195]="奈法利安"
D.SharedStrings[8196]="奈法利安和奥妮克希亚在一起的时候，他们的攻击速度提高了{1}%。"
D.SharedStrings[8197]="奈法利安和奥妮克希亚在一起的时候，他们的攻击速度提高了。"
