D.SharedStrings[8420]="奥丁亲自发来了一则消息。他和他的战士们正在英灵殿里等待有资格的挑战者出现。\n\n击败英灵殿的勇士，夺得荣耀。"
D.SharedStrings[8421]="奥丁亲自邀请艾泽拉斯最强大的勇士进入他的圣殿，迎战他的诸位战将。"
D.SharedStrings[8422]="奥丁的力量在这里涌动着，使他手下强大的瓦拉加尔可以跃向天空，在苍穹要塞着陆。"
D.SharedStrings[8423]="奥丁的瓦格里"
D.SharedStrings[8424]="奥丹姆马车挽具"
D.SharedStrings[8425]="奥伯妮·亮鬃"
D.SharedStrings[8426]="奥克泰尔·龙血"
D.SharedStrings[8427]="奥克鲁特·荒龙"
D.SharedStrings[8428]="奥利斯塔的护符"
D.SharedStrings[8429]="奥利瑟拉之锋"
D.SharedStrings[8430]="奥利瑟拉佐尔"
D.SharedStrings[8431]="奥利瑟拉佐尔完全飞了起来，对敌人造成火焰伤害并将其击退。"
D.SharedStrings[8432]="奥利瑟拉佐尔扑打着她灼热之翼，使敌人受到火焰伤害。"
D.SharedStrings[8433]="奥利瑟拉佐尔燃起了熊熊烈火！对附近的敌人造成火焰伤害。"
D.SharedStrings[8434]="奥利瑟拉佐尔的烈焰之爪"
D.SharedStrings[8435]="奥卓克希昂"
D.SharedStrings[8436]="奥卓克希昂的敌人将被他抓入暮光领域，并受到他的暮光攻击。"
D.SharedStrings[8437]="奥古斯图斯的收据册"
D.SharedStrings[8438]="奥古斯特公爵"
D.SharedStrings[8439]="奥古雷启迪者"
D.SharedStrings[8440]="奥古雷执政官"
D.SharedStrings[8441]="奥妮克希亚"
D.SharedStrings[8442]="奥妮克希亚幼龙"
D.SharedStrings[8443]="奥妮克希亚的火焰吐息对所有地面上的敌人造成{1}点火焰伤害。"
D.SharedStrings[8444]="奥妮克希亚的烈焰吐息攻击所有地面上的敌人，造成{1}点火焰伤害。"
D.SharedStrings[8445]="奥妮克希亚的血脉"
D.SharedStrings[8446]="奥妮克希亚的雏龙"
D.SharedStrings[8447]="奥妮克希亚龙宝宝"
