D.SharedStrings[8449]="奥尔多遗产保卫者"
D.SharedStrings[8450]="奥尔巴兹·血毒"
D.SharedStrings[8451]="奥尔高格（史诗难度）"
D.SharedStrings[8452]="奥尼尔上尉"
D.SharedStrings[8453]="奥拉尔德·施米尔"
D.SharedStrings[8454]="奥斯伯恩·奥布诺提斯"
D.SharedStrings[8455]="奥术伤害提高{1}%。\r\n施法时间减少{2}%。"
