D.SharedStrings[8468]="奥术斩造成相当于{1}%武器伤害的奥术伤害。"
D.SharedStrings[8469]="奥术歼灭者"
D.SharedStrings[8470]="奥术法术强度提高{1}点。"
D.SharedStrings[8471]="奥术法杖"
D.SharedStrings[8472]="奥术炸弹"
D.SharedStrings[8473]="奥术结界"
D.SharedStrings[8474]="奥术能量席卷目标区域，对区域内的敌人造成{1}到{2}点奥术伤害。"
D.SharedStrings[8475]="奥术重铸师"
D.SharedStrings[8476]="奥术震击"
D.SharedStrings[8477]="奥术魔宠"
D.SharedStrings[8478]="奥术魔灵会引导末日决战。引导结束后，它们会对所有敌人造成{1}点奥术伤害，并将其击退。 "
D.SharedStrings[8479]="奥杜尔的守护者"
D.SharedStrings[8480]="奥格瑞姆·毁灭之锤"
D.SharedStrings[8481]="奥格瑞姆之锤"
D.SharedStrings[8482]="奥格瑞姆之锤的库尔迪拉·织亡者要你使用憎恶复活工具包制造一名复活的憎恶，然后利用它杀死15只冰寒食尸鬼、15只残忍的恶鬼和15名复活的联盟士兵。"
D.SharedStrings[8483]="奥格瑞姆之锤的库尔迪拉希望你从奥尔杜萨的苦痛新兵身上夺取幻象宝珠，然后对那里的3名黑暗压制者使用。"
D.SharedStrings[8484]="奥格瑞姆之锤的库尔迪拉希望你去收集5份黑暗物质，然后在奥尔杜萨召唤出一名黑暗信使。"
D.SharedStrings[8485]="奥格瑞姆之锤的库尔迪拉希望前往奥尔杜萨，杀死升腾者奥鲁麦斯。"
D.SharedStrings[8486]="奥格瑞姆之锤的首席技师考伯克拉希望你把沸腾的魔质扔进奥尔杜萨的天灾之锅里。"
D.SharedStrings[8487]="奥格瑞拉，铃儿响叮当"
D.SharedStrings[8488]="奥格瑞玛冠军"
D.SharedStrings[8489]="奥格瑞玛勇士"
D.SharedStrings[8490]="奥格瑞玛平民"
D.SharedStrings[8491]="奥格瑞玛战狼"
D.SharedStrings[8492]="奥格瑞玛步兵"
D.SharedStrings[8493]="奥格瑞玛死忠份子"
D.SharedStrings[8494]="奥格瑞玛的怒焰裂谷已经被燃刃氏族占领了，$n，我们不能听之任之，让他们接着觊觎雷霆崖。$B$B去跟裂谷里的石头守卫库尔加克谈一谈。尽你所能帮助他，毕竟雷霆崖与奥格瑞玛唇齿相依。"
D.SharedStrings[8495]="奥格瑞玛破城者的荣耀"
D.SharedStrings[8496]="奥格瑞玛苦工"
D.SharedStrings[8497]="奥格瑞玛驭风者"
D.SharedStrings[8498]="奥格索普的飞弹分离器"
D.SharedStrings[8499]="奥法地牢从你身上吸取了一部分生命来强化它自己。"
D.SharedStrings[8500]="奥特兰克山谷传送门"
D.SharedStrings[8501]="奥特兰克山谷军官"
D.SharedStrings[8502]="奥特兰克山谷击杀"
D.SharedStrings[8503]="奥特兰克山谷的全能明星"
D.SharedStrings[8504]="奥特兰克山谷胜利"
D.SharedStrings[8505]="奥特兰克山谷荣誉奖章"
D.SharedStrings[8506]="奥特兰克山谷荣誉杀敌"
D.SharedStrings[8507]="奥特兰克负酒犬"
D.SharedStrings[8508]="奥舍尔开始狂乱盛宴，必须受到相当于最大生命值{1}%的伤害才会放开受害者。"
D.SharedStrings[8509]="奥舍尔跃向一个兽笼，放出关在里面的野兽！"
D.SharedStrings[8510]="奥苏尔入侵者"
D.SharedStrings[8511]="奥莉丝塔夫人"
D.SharedStrings[8512]="奥萨拉克斯之塔"
D.SharedStrings[8513]="奥萨拉，黑夜之母"
D.SharedStrings[8514]="奥蕾莉亚·风行者"
D.SharedStrings[8515]="奥西迪斯之影"
D.SharedStrings[8516]="奥西迪斯支配他的一个影子。"
D.SharedStrings[8517]="奥赛特的刑罚护腿"
D.SharedStrings[8518]="奥达奇战刃"
D.SharedStrings[8519]="奥里克斯·瑞文戴尔领主"
D.SharedStrings[8520]="奥金尼仲裁者"
D.SharedStrings[8521]="奥金尼占星者"
D.SharedStrings[8522]="奥金尼守护者"
