D.SharedStrings[8524]="奥金尼狂热者"
D.SharedStrings[8525]="奥金尼警戒者"
D.SharedStrings[8526]="奥金尼重装步兵"
D.SharedStrings[8527]="奥金尼防御者"
D.SharedStrings[8528]="奥金顿之心的三块碎片之一。"
D.SharedStrings[8529]="奥雷迪尔的药剂"
D.SharedStrings[8530]="奥马纳克瓦举起盾牌并冲向前方的目标地点。路径上的所有人都将被盾牌冲击并受到物理伤害。"
D.SharedStrings[8531]="奥鲁凯的法杖"
D.SharedStrings[8532]="奥鲁凯的节杖"
D.SharedStrings[8533]="奥鲁瑞尔使用灼热烙印标记随机的目标。接下来她会点燃自己的盔甲并向被标记的目标发起冲锋。阻挡她的所有敌人会被击退并燃烧，受到{1}点火焰伤害。该效果可叠加。 \r\n\r\n受到灼热烙印影响的玩家死亡时会立即爆炸。"
D.SharedStrings[8534]="奥黛丽·伯恩赫普"
D.SharedStrings[8535]="奧丹姆看守者－受到召喚 00－哈里遜騎乘"
D.SharedStrings[8536]="女伯爵莉亚德琳"
D.SharedStrings[8537]="女伯爵莉娅德琳是第一个血精灵圣骑士。是她最早从纳鲁穆鲁那里偷来了圣光的力量，也是她最早开始为自己的人民寻求宽恕与救赎。一直以来，莉娅德琳凭借着她的力量与信念领导着她的组织。在她看来，血骑士真正的目标只有一个，而且不可动摇——确保彻底消灭燃烧军团。"
D.SharedStrings[8538]="女公爵布劳缪克丝"
D.SharedStrings[8539]="女妖之王"
D.SharedStrings[8540]="女妖希奥克丝"
D.SharedStrings[8541]="女性暗夜精灵"
D.SharedStrings[8542]="女性维库人幻象"
D.SharedStrings[8543]="女招待"
D.SharedStrings[8544]="女猎人库扎莉"
D.SharedStrings[8545]="女猎手卡丝帕莲"
D.SharedStrings[8546]="女猎手艾丝蒂德"
D.SharedStrings[8547]="女王护卫"
D.SharedStrings[8548]="女王的皇家守卫"
D.SharedStrings[8549]="女祭司德莉希亚"
D.SharedStrings[8550]="女祭司月葬"
D.SharedStrings[8551]="女祭司萨阿莉亚"
D.SharedStrings[8552]="奴役者基兹鲁尔"
D.SharedStrings[8553]="奴隶主奥克默克"
D.SharedStrings[8554]="她不只是一个园丁。"
D.SharedStrings[8555]="她看起來不錯。奧肯多爾果實對我們的同胞來說確實是奇蹟。\r\n\r\n在接下來的戰鬥中，她會是不錯的盟友。西爾格臨會好好照顧她的。"
D.SharedStrings[8556]="好了……我制作了一种伪装，它可以把你变成天灾军团的成员，而且不易被发现。$b$b只要伪装还没有失效，你就可以在天灾军团中自由行动。只有荒芜卫士能看穿我制造的这种幻象，你要小心它们！$b$b你要注意的另一个问题就是，这个伪装不太稳定，随时可能失效，所以你一定要保持警惕。$b$b现在让我们来测试一下效果吧。你使用项圈激活伪装，到东边去找天灾军团的商人，给我买一瓶苦痛浆液回来。"
D.SharedStrings[8557]="好了，伙计，我们先从简单的开始。首先我得确认你知道如何使用手里的武器。$B$B去拿那些蒂基面具假人练练手，慢点来，自然一点。我会观察你的表现，然后决定下一步要怎么做。"
D.SharedStrings[8558]="好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。"
D.SharedStrings[8559]="好像你还打算还似的。"
D.SharedStrings[8560]="好吧，$C……你被告知是我独自负责这项研究，所以显然你尽快赶来了。$B$B现在既然你已经到了这儿，那么当我告诉你详细情况时，你可要集中精神听仔细了，我可没耐心再说一次。"
D.SharedStrings[8561]="好吧，$N，你选择这条道路真是明智之极!随便什么蠢货都可以成为初级工程学的专家―那些地精跟他们那满是辐射的老窝就是铁一样的证据。要成为出色的哥布尔工程学专家，你必须有坚强的意志和稳固的双手―在这里我不得不强调稳固二字。$B$B竖起你的耳朵来好好听着，$N，你会学到许多东西的。"
D.SharedStrings[8562]="好吧，$N，我很高兴你能当我的学徒。你做出了一个明智的选择。当你掌握制作蛮皮护甲的秘诀之后，那些使用皮质装备的买主就会蜂拥而至。$B$B让我们开始吧―你想从哪部分开始?"
D.SharedStrings[8563]="好吧，$g朋友:女士;，是时候给他们装个窃听器了。$B$B放松一点，我并不说要真的去装一个窃听器，不过大概也就是那么回事。$B$B在奥尔杜萨的北部区域，有许多诅咒教派的虚空召唤师带着恶魔爪牙游来荡去。用这根魔棒从那些被奴役的爪牙的尸体上吸取一些黑暗物质，然后使用诅咒教派的召唤水晶，召唤出我们的小间谍。$B$B除非它被发现，否则信使将一直作为我们的耳目，小心地观察敌人的行动。"
D.SharedStrings[8564]="好吧，在面对失败的时候你没有选择逃跑。你坚守阵地，$N，当你继续坚持的时候，一名真正的英雄就这样出现了。无疑你将在下一次中获胜……但是我们一样要对你表示感谢。"
D.SharedStrings[8565]="好吧，我有一项合法并且重要的任务要交代你。我们要唤回南面草场上的科多兽。索基佐格将军很快就要带领军队前往赤脊山。要是没有科多兽载我，我会掉队的。$b$b靠近科多兽并吹响这支号角，它就会主动返回营地了。$b$b你得仔细点。科多兽的脾气有时候会不太好，揍它们一顿就会听话了。"
D.SharedStrings[8566]="好吧，这事可能不怎么有趣，但总要有人去做。$b$b我的部队已经在没膝的死水里连续激战数天了。这样对身体可不好。$b$b他们需要的一堆温暖的篝火，不但能把他们自己烤干，还可以鼓舞士气。$b$b这座城市整天都湿漉漉的，但这些荆木树的枯根却有抗潮的能力。$b$b请帮我们收集一些点火的燃料来，我们会非常感谢你的。"
D.SharedStrings[8567]="好奇的小狼獾人"
D.SharedStrings[8568]="好奇的小神谕者"
D.SharedStrings[8569]="好好使用它吧，$C，不要对那些哈卡的信徒心存任何怜悯!"
