D.SharedStrings[8643]="好战角斗士的龙皮长袍"
D.SharedStrings[8644]="好战角斗士：《德拉诺之王》第3赛季"
D.SharedStrings[8645]="好极了，$C。你在为黑暗女王效力的过程中表现得很出色。你的坚定不移和雄心壮志将极大地帮助黑暗女王实现她的目标。下次再来我这儿吧，也许我会布置其它的任务给你，帮助黑暗女王取代巫妖王，并彻底瓦解天灾军团。"
D.SharedStrings[8646]="好極了。這些書籍裡的知識對我們之後的作戰應該大有幫助。"
D.SharedStrings[8647]="好消息，$C!如果我们的战术持续运作成功，那么部落要不了多久就得全面撤退了。"
D.SharedStrings[8648]="好耶！你要学会如何制作一个索引任务！现在想想下面该做什么。"
D.SharedStrings[8649]="好运的蓝麻绳"
D.SharedStrings[8650]="如何在德拉诺从不同的树木上收集木材。"
D.SharedStrings[8651]="如何，$C?$B$B世界又少了一个诅咒教徒吗?"
D.SharedStrings[8652]="如何，$r?$B$B你那些憎恶朋友们好用吗?"
D.SharedStrings[8653]="如何，朋友?你击败雅路麦斯了吗?"
D.SharedStrings[8654]="如你所见，$C?聪明才智有时可以在看似势不可挡的敌军前反败为胜。"
D.SharedStrings[8655]="如你所见，我身后是一只巨大的黑色爪子，它是我们在出门寻找新的受训野兽时发现的。动物们似乎都非常惧怕这玩意儿，或许这爪子的主人曾经捕杀过它们。"
D.SharedStrings[8656]="如果不在盛宴餐桌旁吃个痛快，就绝对不算是庆祝过感恩节。$B$B请坐下来尽情享用这里的美食吧！如果想品尝不同的菜肴，你可以从一个座位上移动到另一个座位上，或者请求宴会桌旁的其他人将他们面前的菜式传递给你。$B$B当你吃过桌上的所有美食之后，你的体内就会充满分享之魂。"
D.SharedStrings[8657]="如果你决心成为龙鳞制皮师，那么我就收下你这个学生。把我要的东西交给我，我就可以开始向你传授技能了。"
D.SharedStrings[8658]="如果你只有一枚荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用一枚荣誉徽章来换取声望的话，我随时在这里等着你。"
D.SharedStrings[8659]="如果你可以治疗那些植物，它们就可以再次生长了。我们必须尽力而为，$N……"
D.SharedStrings[8660]="如果你实在不喜欢你的礼物，可以去跟烟林牧场的商人谈谈，把它换成钱。$b$b一经兑换，概不负责。"
D.SharedStrings[8661]="如果你已经准备好了要制作一些真正精彩的设备，那么你就来对地方了。看得出来，你是个熟练的技师，的那我还想看到一些你的作品。我要对你的工作进行分析，帮助你在侏儒工程学的光明大道上更快地前进。我需要以下物品：6根秘银管、1只精确瞄准镜和2个高级假人！$B$B把这些东西交给我，你就能成为一名官方认可的侏儒技师，能够使用我们的全部设计图表了！"
D.SharedStrings[8662]="如果你想与燃烧军团作战，就到纳格兰西部去找到受难者奥图里斯。"
D.SharedStrings[8663]="如果你想学习如何烹饪旅人丰年祭的食物，我可以帮你。如果你还不是位厨师，去找训练师后你立刻就可以烹制食物了!"
D.SharedStrings[8664]="如果你想要对侏儒工程学有更多了解，就把工程学教材交给藏宝海湾的奥格索普·奥布诺提斯。"
D.SharedStrings[8665]="如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。"
D.SharedStrings[8666]="如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。"
D.SharedStrings[8667]="如果你想要探索深海的所有秘密并捕几条大鱼，请到卡桑琅丛林的渔人码头去和海涛谈一谈。$B$B我敢肯定，他很乐意教你几手钓鱼技巧！"
D.SharedStrings[8668]="如果你成功了，那你也许可以就此赢得我的尊敬，$C。"
D.SharedStrings[8669]="如果你把原本供你骑乘的高速座狼给我带来，我就可以让你从新的狼中选择一头。新的狼将和你原来的狼拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅捷座狼就可以知道它们大概是什么样子了。"
D.SharedStrings[8670]="如果你把原本供你骑乘的高速科多兽给我带来，我就可以让你从新的科多兽中选择一头。新的科多兽将和你原来的科多兽拥有同样的速度，但是其外观将会有所不同，看看周围的这些科多兽就可以知道它们大概是什么样子了。"
D.SharedStrings[8671]="如果你把原本供你骑乘的高速迅猛龙给我带来，我就可以让你从新的迅猛龙中选择一头。新的迅猛龙将和你原来的迅猛龙拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅猛龙就可以知道它们大概是什么样子了。"
D.SharedStrings[8672]="如果你把它放在耳边摇晃，就能听到内部液体晃动的声音。"
D.SharedStrings[8673]="如果你是我的朋友，就按照我的要求去做!"
D.SharedStrings[8674]="如果你的尸体被敌方玩家进行了拾取，或是你在死亡后对灵魂进行了释放，都会掉落神器碎片。"
D.SharedStrings[8675]="如果你继续停留在这一地区，将进入PvP状态！"
D.SharedStrings[8676]="如果你要我帮你制作护甲就一定要将我说的东西带来。"
D.SharedStrings[8677]="如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。"
D.SharedStrings[8678]="如果受到直接治疗，就对施法者造成{1}点暗影伤害。"
D.SharedStrings[8679]="如果和带有同种电荷的单位在一起，所造成的伤害提高100%；如果和带有异种电荷的单位在一起，则对其造成自然伤害。"
D.SharedStrings[8680]="如果在我战斗的时候，你读到了这个……"
D.SharedStrings[8681]="如果奥拉基尔的当前目标不在他的近战范围内，他就会对其引导一束闪电的能量，造成越来越高的自然伤害，直至目标回到奥拉基尔的近战范围。"
D.SharedStrings[8682]="如果奥鲁瑞尔的邪能之魂与其自身间距离超过45码，两者所造成的伤害和急速都会提高。"
D.SharedStrings[8683]="如果得不到治疗，这条龙恐怕就不行了。"
D.SharedStrings[8684]="如果怒痕雪人的毛皮的品质可以和那些深痕谷中的雪人相媲美，那么它们一定像瑟银一样具有韧性!$B$B想象一下吧!"
D.SharedStrings[8685]="如果我们能够直接传送到堡垒的顶端，到达古尔丹研习黑暗魔法的地方，事情就会变得简单很多了，不是吗？但这些大厅中仍然充斥着恶魔的力量，我的魔法无法穿透它们，达到那样的高度。$b$b如果能够利用强大的邪能精华，我就可以让我的魔法和他们的防御力量相容，绕过他们的防线。但只有在堡垒顶部才能够找到高度浓缩的邪能能量。这还真是个难题……"
D.SharedStrings[8686]="如果我想要在被遗忘的海岸这里开一家可以正常经营的工程学商店，那我就必须先解决这些讨厌的元素生物——它们简直是无法无天！$B$B幸运的是，我发现这些元素生物身上有一种可以给我的超级压缩器提供动力的理想材料——我希望你可以好好地教训它们，拿到我要的东西！把它们身上的水元素核心给我拿来！"
D.SharedStrings[8687]="如果我是你，我會先洗手，再吃東西。"
D.SharedStrings[8688]="如果我的拱道地圖正確無誤，那些應該就是我們需要注意的所有出口。"
D.SharedStrings[8689]="如果有任何盟友瘫痪，则驱散所有群体控制效果。"
D.SharedStrings[8690]="如果有四名敌人没有被脱水践踏击中，梦魇古树会恢复能量。"
D.SharedStrings[8691]="如果没有被践踏，源生完成后就会发芽。"
D.SharedStrings[8692]="如果瘫痪的盟友超过2个，则驱散所有群体控制效果。"
D.SharedStrings[8693]="如果瘫痪的盟友超过{1}个，则驱散所有的群体控制效果。"
D.SharedStrings[8694]="如果目标手中握有啤酒，则将其击晕。"
D.SharedStrings[8695]="如果目标生命值全满，则造成相当于最大生命值{1}%的火焰伤害。"
D.SharedStrings[8696]="如果真的成功了，說不定圖拉揚和聖光軍團還有希望。"
D.SharedStrings[8697]="如果被任何魔血碰触，恐惧卫士就会复活。"
D.SharedStrings[8698]="如果被伤害、挑衅或嘲讽，则会改变初始行为。"
D.SharedStrings[8699]="如果要開一個傳送網路到薩莉瑟拉那邊，就非拿到這些器材不可。"
D.SharedStrings[8700]="如果说他们之前还没发火的话，现在一定是怒不可遏了。我们在这辆坦克上连一分钟都活不下去！$b$b赶快去跟其他人会合，离开这儿！！"
D.SharedStrings[8701]="如果说你在逐日岛学到的最重要一课是什么，那无疑就是如何控制你对魔法的渴求了。血精灵对魔法的渴求是一种无止境的渴求，$n，你所吸收的能量必须完全处于你的掌控之中，并且通过奥术洪流将能量释放出去。如果你失败了的话，就将变成一个失心者……变成一个在绝望与疯狂中苟活的瘾君子。$B$B去岛上寻找一条法力浮龙，对它使用奥术洪流技能吧。学会掌握欲望所生成的力量。当你学会如何释放这种力量之后，回来找我。"
D.SharedStrings[8702]="如果附近没有其他玩家，将触发毁灭之惧。"
D.SharedStrings[8703]="如此多的勇士献出了生命，鲜血染红了整个战场。然而，你活下来了……你还坚定地站在这里。你带领我们的部队取得了无数胜利，你做出了杰出的贡献，这为你赢得了更高的声望和军阶。$B$B这就是你的新徽记。"
D.SharedStrings[8704]="如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B请将你的徽记之戒交给我，这样我才能强化它的能量。"
D.SharedStrings[8705]="如此强大的武器是不会毁于战火的。"
D.SharedStrings[8706]="妖女伊森黛拉"
