D.SharedStrings[8709]="妥善保存的魔杖"
D.SharedStrings[8710]="妮可茜可能会非常担心本次调查行动潜在的利润损失。$b$b如果你见到她，能告诉她一声我们马上就回去了吗？"
D.SharedStrings[8711]="姐妹相互分担伤害！"
D.SharedStrings[8712]="委托大法师纽哈斯制作的副本。不用担心还书的问题，它会自己跑回来的。"
