D.SharedStrings[8726]="孟菲斯托斯之影出现在伊利丹周围，并试图打断他施放驱逐暗影。击中敌人的暗影冲击会对其造成{1}点暗影伤害。"
D.SharedStrings[8727]="孢子镜像"
D.SharedStrings[8728]="季·火掌"
D.SharedStrings[8729]="季鹍的传说之羽"
D.SharedStrings[8730]="季鹍的复苏之风"
D.SharedStrings[8731]="孤儿们一直都很期待能有像你这样的朋友，$n。我非常高兴你能答应照顾他们其中的一个。$B$B带上这只哨子。有了它，你随时都能召唤受你照顾的孤儿。你不需要照顾他太久——大概也就是儿童周这段时间。$B$B好了，$n，请召唤你的孤儿吧。他一定会非常喜欢你的。你们一定会在诺森德各处渡过不少愉快的旅程。"
D.SharedStrings[8732]="孤单的翡翠雏龙"
D.SharedStrings[8733]="学习两种主要专业技能"
D.SharedStrings[8734]="学习工程学结构图"
