D.SharedStrings[8737]="学习珠宝加工配方"
D.SharedStrings[8738]="学习骑乘"
D.SharedStrings[8739]="学会变身成为一条龙，将一名盟友背在自己身上。"
D.SharedStrings[8740]="孩子，干的不错啊，这是你应得的。嗯，你明天要是有空还来啊，我这还有别的活儿给你~"
D.SharedStrings[8741]="孪生绝望之盾"
D.SharedStrings[8742]="孵化大师召唤幼嗣，攻击附近的敌人。"
D.SharedStrings[8743]="它们从不靠近海面一英里以内，所以是钓不到的。这种鱿鱼只能通过……其它方法获取。"
D.SharedStrings[8744]="它似乎是所有能量核心中最硬最重的。"
D.SharedStrings[8745]="它們所受的痛苦讓我感同身受。它們終將回歸，但現在它們將暫時獲得安息。"
D.SharedStrings[8746]="它太笨重了。很难相信它不会影响剑圣的战斗力。"
D.SharedStrings[8747]="它居然没有来攻击你，这让我感到很惊讶。但是不要紧，我有个计划可以让那头野兽出来。$B$B作为这块区域的领袖，拉克维有权与任何雌性暴掠龙交配——而且它确实这么做了。你可以在这里的西边找到许多暴掠龙蛋，靠近它们，这时就会有雌性暴掠龙跑出来攻击你。这些雌性暴掠龙头上有一种腺体，它所散发出的味道可以告诉雄性暴掠龙：它准备进行交配了。给我带两个这样的腺体回来。"
D.SharedStrings[8748]="它的表面闪动着火光，躺在你的手心里时依然散发着热量。"
D.SharedStrings[8749]="它看起来很奇怪，并且很显然蕴含着魔法力量。"
