D.SharedStrings[8785]="守望者地窟里的状况比我们想象的还要糟糕。原来的囚犯摇身一变成为了狱卒，全面占领了地窟。不过，我们情报显示，科达娜·邪歌可能就在那里。\n\n进入守望者地窟，净化那里的邪恶。"
