D.SharedStrings[8806]="安妮莉亚把手放在你的肩头上，慢慢地把你拉近她的身边。她艰难地喘着气，抬手指向北方的拱门。在她的气息渐渐变得微弱，眼睛慢慢地闭上之前，安妮莉亚留下了最后一句话：“被他夺走了……加萨里斯……”她临终时还在想着要让塞纳留斯的树枝回到树妖的手中。"
