D.SharedStrings[8868]="完成了。我已能感到腐敗的存在逐漸被驅淨。\r\n\r\n感謝你，$n，你幫了這地方大忙。"
D.SharedStrings[8869]="完成了。沙亞蘭以後再也不缺法力了。"
D.SharedStrings[8870]="完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。"
