D.SharedStrings[9120]="对一小块区域内的敌人造成{1}点火焰伤害。"
D.SharedStrings[9121]="对一条敌对的龙造成{1}点奥术伤害，并引爆其身上的所有震击能量。每引爆一层震击能量，伤害就提高{2}点。"
D.SharedStrings[9122]="对一条法力浮龙使用种族特长技能“奥术洪流”，然后向奥术师赫里恩复命。"
D.SharedStrings[9123]="对一条直线上的所有敌人造成{1}点物理伤害，并将其击退。"
D.SharedStrings[9124]="对一株植物造成剧烈影响，使其生长速度提高三倍。"
D.SharedStrings[9125]="对上层平台的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[9126]="对下列种族/职业组合使用一把玫瑰花瓣。"
D.SharedStrings[9127]="对下方的目标投掷一枚重磅炸弹。"
D.SharedStrings[9128]="对与之接触到的敌人造成{1}点伤害。"
D.SharedStrings[9129]="对亚煞极之境内的所有敌人造成{1}点暗影伤害。"
D.SharedStrings[9130]="对亡灵所造成的近战、远程和法术伤害提高{1}%。"
D.SharedStrings[9131]="对亡灵生物造成的伤害提高{1}%。"
D.SharedStrings[9132]="对亡灵的攻击强度提高{1}点。"
D.SharedStrings[9133]="对亡灵的法术强度提高{1}点。"
D.SharedStrings[9134]="对亡灵造成的伤害提高{1}%。"
D.SharedStrings[9135]="对付流亡者赞吉尔和高阶祭司温诺希斯。$b$b假如你迷路了或者需要回到祖尔格拉布，去跟探险者协会挖掘场的梅维克交谈。"
D.SharedStrings[9136]="对任何攻击附近小队成员的怪物造成神圣伤害。每个圣骑士在同一时间内只能开启一种光环。光环会一直持续，直到被取消。"
D.SharedStrings[9137]="对任何用近战武器攻击施法者的怪物造成神圣伤害。"
D.SharedStrings[9138]="对伤患进行人工呼吸，救治溺水的伤患。"
D.SharedStrings[9139]="对位于施法者正面锥形区域内的敌人造成{1}点火焰伤害。"
D.SharedStrings[9140]="对位于施法者身后锥形区域内的敌人造成{1}点伤害，并将其击退。"
D.SharedStrings[9141]="对你和附近未相连的盟友造成持续加剧的暗影伤害。当所有相连的目标都相互位于各自5码范围内时，该效果将消失。"
D.SharedStrings[9142]="对你护送牛头人车队的谢礼。"
D.SharedStrings[9143]="对你的当前目标召唤一道闪电打击，造成{1}点自然伤害。"
D.SharedStrings[9144]="对你的目标造成{1}点火焰伤害。"
D.SharedStrings[9145]="对你的目标造成火焰伤害。"
D.SharedStrings[9146]="对使用近战武器攻击你的敌人造成{1}点火焰伤害。"
D.SharedStrings[9147]="对元素生物造成的伤害提高{1}%。"
D.SharedStrings[9148]="对其路径上的敌方玩家造成{1}点物理伤害。"
D.SharedStrings[9149]="对冲击位置周围一定半径内的目标造成{1}点伤害。"
D.SharedStrings[9150]="对冲击位置周围一定半径内的目标造成大量的火焰伤害。"
D.SharedStrings[9151]="对冲击位置附近大范围内的目标造成{1}点伤害。"
D.SharedStrings[9152]="对冲击位置附近小范围内的所有目标造成{1}点伤害。能以极快的速度发射。"
D.SharedStrings[9153]="对冲击区域内的所有敌人造成暗影伤害。"
D.SharedStrings[9154]="对冲击波内的敌人造成伤害。"
D.SharedStrings[9155]="对冲击点附近的所有敌人造成{1}点冰霜伤害。"
D.SharedStrings[9156]="对前方的敌人造成{1}点自然伤害。"
D.SharedStrings[9157]="对前方锥形区域里的敌人造成神圣伤害。"
D.SharedStrings[9158]="对前方锥形范围内的敌人造成神圣伤害。"
D.SharedStrings[9159]="对区域内所有敌人造成{1}点冰霜伤害。"
D.SharedStrings[9160]="对区域内的任意目标造成物理伤害，并将其击退。"
D.SharedStrings[9161]="对区域内的所有敌人造成{1}点物理伤害，并使其受到尖啸和飞羽的伤害提高{2}%。"
D.SharedStrings[9162]="对区域内的敌人造成{1}点火焰伤害。"
D.SharedStrings[9163]="对区域内的玩家造成越来越高的暗影伤害，使其获得的治疗效果降低{1}%。该效果仅在移动范围内没有有效目标时可以施放。"
D.SharedStrings[9164]="对半径15码范围内的所有单位造成{1}点物理伤害。"
D.SharedStrings[9165]="对半径5码范围内的所有敌人造成{1}点伤害。"
D.SharedStrings[9166]="对半径5码范围内的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[9167]="对半径5码范围内的目标造成{1}点火焰伤害。"
D.SharedStrings[9168]="对单一目标造成{1}点冰霜伤害。"
D.SharedStrings[9169]="对单个目标造成暗影伤害。"
D.SharedStrings[9170]="对受到喷涌火焰灼烧的敌人造成伤害。"
D.SharedStrings[9171]="对受害者放射出暮光能量的冲击波。"
D.SharedStrings[9172]="对受害者造成{1}点物理伤害。"
D.SharedStrings[9173]="对受害者造成中等的自然伤害。"
D.SharedStrings[9174]="对周围全部敌人每秒造成{1}点冰霜伤害。"
D.SharedStrings[9175]="对周围的所有敌人造成{1}点冰霜伤害，并使它们受到的冰霜伤害提高{2}%。"
D.SharedStrings[9176]="对周围的所有敌人造成伤害。"
D.SharedStrings[9177]="对周围的敌人每秒造成{1}点伤害，但是移动速度降低{2}%。"
D.SharedStrings[9178]="对周围的敌人造成{1}点火焰伤害。"
D.SharedStrings[9179]="对周围的敌人造成火焰伤害。"
D.SharedStrings[9180]="对噬魂者造成的部分伤害将会反弹给灵魂倒映的目标。"
D.SharedStrings[9181]="对地同步世界旋转器"
D.SharedStrings[9182]="对地面上的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[9183]="对坠落伤害免疫。\r\n不能使用喷气。"
D.SharedStrings[9184]="对坦克前方锥形区域内的敌人造成{1}点物理伤害，并将其击退。"
D.SharedStrings[9185]="对墨菲斯托斯前方的敌人造成大量火焰伤害。"
D.SharedStrings[9186]="对多头蛇的头造成伤害的同时也会对瑟芬崔斯克造成伤害！"
D.SharedStrings[9187]="对多种群体控制免疫，并使造成的伤害提高{1}%。"
D.SharedStrings[9188]="对大面积区域内的所有敌人造成伤害。"
D.SharedStrings[9189]="对夺日者监视结界周围的敌人造成自然伤害。"
D.SharedStrings[9190]="对奥妮克希亚身旁的敌人造成{1}点自然伤害。"
D.SharedStrings[9191]="对奥术、火焰、冰霜、自然和暗影法术的抗性提高{1}点。"
D.SharedStrings[9192]="对岩石巨人造成额外伤害。"
D.SharedStrings[9193]="对巨人造成的伤害提高{1}%。"
D.SharedStrings[9194]="对巨型灰烬座狼的尸体使用座狼锯肉刀，收集40块座狼肉排。"
D.SharedStrings[9195]="对应任意插槽。"
D.SharedStrings[9196]="对应任意插槽。最多可以在你的装备中镶嵌一枚。"
D.SharedStrings[9197]="对应任意插槽。镶嵌此宝石将使其变为绑定物品。"
D.SharedStrings[9198]="对当前敌方目标造成{1}点到{2}点伤害。"
D.SharedStrings[9199]="对当前目标造成{1}点火焰伤害。"
D.SharedStrings[9200]="对影响区域内的所有目标造成物理伤害。"
D.SharedStrings[9201]="对影响范围内的敌人造成{1}点暗影伤害。"
D.SharedStrings[9202]="对恶魔的攻击强度提高{1}点。"
D.SharedStrings[9203]="对恶魔造成的伤害提高{1}%。"
D.SharedStrings[9204]="对愤怒领主勒考斯前方的敌人造成火焰伤害并击退。"
D.SharedStrings[9205]="对愤怒领主盾卫前方的敌人造成{1}点火焰伤害，并将其击退。"
