D.SharedStrings[9281]="对敌人造成伤害时有一定几率召唤一头古拉巴什迅猛幼龙来帮助你。\r\n\r\n只能在祖尔格拉布才能激活。"
D.SharedStrings[9282]="对敌人造成伤害时有一定几率召唤一头阿曼尼熊崽来帮助你。\r\n\r\n只能在祖阿曼才能激活。"
D.SharedStrings[9283]="对敌人造成伤害时，有一定几率为格利基克恢复{1}点生命值。"
